INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-gios-vua-don-xong-can-ga-di-a-2026-01-10', '1 em GIOS vừa dọn xong cần gả đi ạ', '2026-01-10', 'tin-tuc', '1 em GIOS vừa dọn xong cần gả đi ạ. Xe khung nhôm Bộ chuyển động Shimano 3x8 Xe phù hợp cho các bác từ 1m55-1m68 Các Bác quan tâm Ib em tư vấn nhé 0902003145', '/sites/yenthoa/logo.png', '<p>1 em GIOS vừa dọn xong cần gả đi ạ.</p><p>Xe khung nhôm</p><p>Bộ chuyển động Shimano 3x8</p><p>Xe phù hợp cho các bác từ 1m55-1m68</p><p>Các Bác quan tâm Ib em tư vấn nhé</p><p>0902003145</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-sk-20-ban-voi-cho-anh-chi-dong-thai-2026-01-25', '1 em SK 20 bán vội cho anh chị Đồng Thái', '2026-01-25', 'tin-tuc', '1 em SK 20 bán vội cho anh chị Đồng Thái . Xe size 20 phim nhỏ nên các bé từ 5 tuổi cũng đã đi được rồi ạ.', '/sites/yenthoa/logo.png', '<p>1 em SK 20 bán vội cho anh chị Đồng Thái .</p><p>Xe size 20 phim nhỏ nên các bé từ 5 tuổi cũng đã đi được rồi ạ.</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-xe-dap-the-thao-lap-nhanh-con-di-ship-cho-anh-khach-thi-2026-01-18', '1 em xe đạp Thể thao lắp nhanh còn đi ship cho anh khách Thị trấn mua tặng Bố…', '2026-01-18', 'tin-tuc', '1 em xe đạp Thể thao lắp nhanh còn đi ship cho anh khách Thị trấn mua tặng Bố nhân dịp Tết đến Xuân về! Các anh chị ở xa muốn tặng quà bố mẹ cứ ib hoặc Alo em nhé, em sẽ gửi tận tay các Bác món quà…', '/sites/yenthoa/logo.png', '<p>1 em xe đạp Thể thao lắp nhanh còn đi ship cho anh khách Thị trấn mua tặng Bố nhân dịp Tết đến Xuân về!</p><p>Các anh chị ở xa muốn tặng quà bố mẹ cứ ib hoặc Alo em nhé, em sẽ gửi tận tay các Bác món quà của các anh chị ạ!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-xe-dap-the-thao-laux-ve-boi-bac-khach-2026-10-23', '1 em xe đạp thể thao Laux về bới Bác khách', '2026-10-23', 'tin-tuc', '1 em xe đạp thể thao Laux về bới Bác khách. Chúc Bác thật nhiều sức khoẻ. Cảm ơn Bác đã tin tưởng và ủng hộ xe đạp Yên Thoa', '/sites/yenthoa/logo.png', '<p>1 em xe đạp thể thao Laux về bới Bác khách. Chúc Bác thật nhiều sức khoẻ. Cảm ơn Bác đã tin tưởng và ủng hộ xe đạp Yên Thoa</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('1-em-xe-dap-the-thao-ve-voi-bac-khach-yen-hoa-2026-02-02', '1 em xe đạp thể thao về với Bác Khách Yên Hoà', '2026-02-02', 'tin-tuc', '1 em xe đạp thể thao về với Bác Khách Yên Hoà. Bác bảo 12 năm trước mua xe cho con gái đi học cấp 3 xe đi chắc chắn, bền lắm nên hôm nay quay lại mua thêm cái xe đạp 2 ông bà đạp thể dục buổi sáng.…', '/sites/yenthoa/logo.png', '<p>1 em xe đạp thể thao về với Bác Khách Yên Hoà. Bác bảo 12 năm trước mua xe cho con gái đi học cấp 3 xe đi chắc chắn, bền lắm nên hôm nay quay lại mua thêm cái xe đạp 2 ông bà đạp thể dục buổi sáng.</p><p>Cháu cám ơn Bác đã tin tưởng và ủng hộ Siêu Thị Yên Thoa. Chúc hai Bác thật nhiều sức khoẻ.</p><p>Các Bác cần tư vấn mẫu xe đạp thể thao, xe đạp phổ thông, xe trẻ em Ib em nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('133-binh-to-cho-ban-hoc-sinh-lop-10-kim-son-2026-02-02', '133 bình to cho bạn học sinh lớp 10 Kim Sơn', '2026-02-02', 'tin-tuc', '133 bình to cho bạn học sinh lớp 10 Kim Sơn. Hàng sẵn nhiều các Bác cứ qua chọn thoải mái ạ!', '/sites/yenthoa/logo.png', '<p>133 bình to cho bạn học sinh lớp 10 Kim Sơn. Hàng sẵn nhiều các Bác cứ qua chọn thoải mái ạ!</p>', 1);
