INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('supper-24-thong-nhat-2026-01-17', 'Supper 24 Thống Nhất', '2026-01-17', 'tin-tuc', 'Supper 24 Thống Nhất Chiếc xe đạp thể thao mà bé trai nào cũng mơ ước có. Xe có size 24 phù hợp cho các bé từ 9 tuổi ( cao tầm 1m4 trở lên) Các Bác quan tâm Ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Supper 24 Thống Nhất</p><p>Chiếc xe đạp thể thao mà bé trai nào cũng mơ ước có.</p><p>Xe có size 24 phù hợp cho các bé từ 9 tuổi ( cao tầm 1m4 trở lên)</p><p>Các Bác quan tâm Ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('tam-biet-nam-at-ty-chao-don-nam-binh-ngo-2026-02-16', 'Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ', '2026-02-16', 'tin-tuc', 'Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ Xe đạp Yên Thoa xin gửi lời cám ơn tới tất cả Quý Khách Hàng, Quý Đối tác đã luôn tin tưởng , ủng hộ và đồng hành cùng xe đạp Yên Thoa Năm Bính Ngọ xắp sang…', '/sites/yenthoa/logo.png', '<p>Tạm biệt năm Ất Tỵ chào đón năm Bính Ngọ</p><p>Xe đạp Yên Thoa xin gửi lời cám ơn tới tất cả Quý Khách Hàng, Quý Đối tác đã luôn tin tưởng , ủng hộ và đồng hành cùng xe đạp Yên Thoa</p><p>Năm Bính Ngọ xắp sang Xe đạp Yên Thoa xin kính chúc mọi người, mọi nhà thật nhiều sức khỏe, hạnh phúc, Vạn Sự Như Ý!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('thanh-nien-nho-thoi-ma-rat-co-mat-nhin-nhe-2026-02-15', 'Thanh niên nhỏ thôi mà rất có mắt nhìn nhé', '2026-02-15', 'tin-tuc', 'Thanh niên nhỏ thôi mà rất có mắt nhìn nhé. Đã chọn là phải chọn chiếc xe đắt nhất , xịn nhất mới chịu cơ', '/sites/yenthoa/logo.png', '<p>Thanh niên nhỏ thôi mà rất có mắt nhìn nhé. Đã chọn là phải chọn chiếc xe đắt nhất , xịn nhất mới chịu cơ</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('toi-nay-lai-co-be-mac-man-cho-xe-dap-2026-08-23', 'Tối nay lại có bé mắc màn cho xe đạp', '2026-08-23', 'tin-tuc', 'Tối nay lại có bé mắc màn cho xe đạp Khách bảo mưa mới có thời gian đi mua hàng', '/sites/yenthoa/logo.png', '<p>Tối nay lại có bé mắc màn cho xe đạp</p><p>Khách bảo mưa mới có thời gian đi mua hàng</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('trong-buc-anh-nay-la-3-em-xe-dap-chuan-bi-len-duong-2026-10-26', 'Trong bức ảnh này là 3 em xe đạp chuẩn bị lên đường', '2026-10-26', 'tin-tuc', 'Trong bức ảnh này là 3 em xe đạp chuẩn bị lên đường ! Các Bác quan tâm các mẫu xe đạp trẻ em, xe đạp phổ thông, xe 3 bánh, xe điện ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Trong bức ảnh này là 3 em xe đạp chuẩn bị lên đường !</p><p>Các Bác quan tâm các mẫu xe đạp trẻ em, xe đạp phổ thông, xe 3 bánh, xe điện ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('van-la-em-y-133-nho-gon-cac-chi-lua-chon-ve-dua-don-con-chau-2026-01-06', 'Vẫn là em ý 133 nhỏ gọn các chị lựa chọn về đưa đón con cháu đi học, đi chợ', '2026-01-06', 'tin-tuc', 'Vẫn là em ý 133 nhỏ gọn các chị lựa chọn về đưa đón con cháu đi học, đi chợ', '/sites/yenthoa/logo.png', '<p>Vẫn là em ý 133 nhỏ gọn các chị lựa chọn về đưa đón con cháu đi học, đi chợ</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('van-la-em-y-133-nho-gon-gia-mem-nhu-bun-2026-01-07', 'Vẫn là em ý 133 nhỏ gọn, giá mềm như bún', '2026-01-07', 'tin-tuc', 'Vẫn là em ý 133 nhỏ gọn, giá mềm như bún . Các Bác quan tâm Ib em tư vấn nhé.', '/sites/yenthoa/logo.png', '<p>Vẫn là em ý 133 nhỏ gọn, giá mềm như bún</p><p>. Các Bác quan tâm Ib em tư vấn nhé.</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('van-la-xe-dap-thong-nhat-nhung-nhe-suc-hon-linh-hoat-hon-va-2026-09-02', 'Vẫn là xe đạp Thống Nhất nhưng nhẹ sức hơn, linh hoạt hơn và sẵn sàng đi xa hơn', '2026-09-02', 'tin-tuc', 'Vẫn là xe đạp Thống Nhất nhưng nhẹ sức hơn, linh hoạt hơn và sẵn sàng đi xa hơn. Sau 66 năm gắn bó cùng những vòng xe đạp bằng sức người, Thống Nhất xin giới thiệu một người bạn đồng hành mới - vẫn…', '/sites/yenthoa/logo.png', '<p>Vẫn là xe đạp Thống Nhất nhưng nhẹ sức hơn, linh hoạt hơn và sẵn sàng đi xa hơn.</p><p>Sau 66 năm gắn bó cùng những vòng xe đạp bằng sức người, Thống Nhất xin giới thiệu một người bạn đồng hành mới - vẫn chất \"Thống Nhất\" quen thuộc, nhưng giờ đây nhẹ nhàng hơn trên mỗi hành trình.</p><p>THỐNG NHẤT CHÍNH THỨC RA MẮT XE ĐẠP TRỢ LỰC ĐIỆN!</p><p>Sản phẩm mới, diện mạo mới ==&gt; Không phải để thay đổi những giá trị đã làm nên Thống Nhất, mà để những giá trị ấy tiếp tục được nâng tầm và đi cùng thời đại.</p><p>Không cần thay đổi thói quen, chỉ cần thêm chút \"trợ lực\" cho mỗi chặng đường - đi làm, đi chợ, hay dạo phố cũng nhẹ tênh hơn hẳn.</p><p>Sản phẩm đã có sẵn tại SIÊU THỊ YÊN THOA, mời các Bác qua cửa hàng trải nghiệm sản phẩm ạ!</p>', 1);
