INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dap-gn-20-thong-nhat-phu-hop-cho-cac-ban-6-9-tuoi-em-san-2026-03-17', 'Xe đạp GN 20 Thống Nhất phù hợp cho các bạn 6-9 tuổi em sẵn đủ màu ạ', '2026-03-17', 'tin-tuc', 'Xe đạp GN 20 Thống Nhất phù hợp cho các bạn 6-9 tuổi em sẵn đủ màu ạ!', '/sites/yenthoa/logo.png', '<p>Xe đạp GN 20 Thống Nhất phù hợp cho các bạn 6-9 tuổi em sẵn đủ màu ạ!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dap-thong-nhat-ms-27-5-la-mau-xe-the-thao-danh-cho-nguoi-2026-10-24', 'Xe đạp Thống Nhất MS 27,5″ là mẫu xe thể thao dành cho người dùng yêu thích sự…', '2026-10-24', 'tin-tuc', 'Xe đạp Thống Nhất MS 27,5″ là mẫu xe thể thao dành cho người dùng yêu thích sự khỏe khoắn, dễ đi và bền bỉ. Xe Sở hữu khung thép chắc chắn, phuộc thép bền bỉ, bộ truyền động Shimano 7 tốc độ, phanh…', '/sites/yenthoa/logo.png', '<p>Xe đạp Thống Nhất MS 27,5″ là mẫu xe thể thao dành cho người dùng yêu thích sự khỏe khoắn, dễ đi và bền bỉ.</p><p>Xe Sở hữu khung thép chắc chắn, phuộc thép bền bỉ, bộ truyền động Shimano 7 tốc độ, phanh đĩa trước sau cùng bánh 27,5″ sử dụng lốp Kenda 27,5×1.75.</p><p>MS 27,5″ mang đến cảm giác đạp êm ái, ổn định và linh hoạt từ những cung đường đô thị đến ngoại ô.</p><p>Xe sẵn 3 màu tại xe đạp Yên Thoa</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dap-tre-em-thong-nhat-puppy-so-huu-dien-mao-vo-cung-ngot-2026-08-23', 'Xe đạp trẻ em Thống Nhất Puppy sở hữu diện mạo vô cùng ngọt ngào, tươi xắn cùng…', '2026-08-23', 'tin-tuc', 'Xe đạp trẻ em Thống Nhất Puppy sở hữu diện mạo vô cùng ngọt ngào, tươi xắn cùng kiểu dáng nhỏ gọn, được thiết kế chuyên biệt dành cho các bạn nhỏ lứa tuổi tiểu học (chiều cao từ 120cm – 140cm). Khung…', '/sites/yenthoa/logo.png', '<p>Xe đạp trẻ em Thống Nhất Puppy sở hữu diện mạo vô cùng ngọt ngào, tươi xắn cùng kiểu dáng nhỏ gọn, được thiết kế chuyên biệt dành cho các bạn nhỏ lứa tuổi tiểu học (chiều cao từ 120cm – 140cm).</p><p>Khung và phuộc thép chịu lực siêu bền, đáp ứng tần suất sử dụng hằng ngày.</p><p>Bảng màu đa dạng (Hồng, Kem, Trắng, Xanh neon) rực rỡ hợp gu trẻ nhỏ.</p><p>Vận hành êm ái, dễ làm chủ tốc độ và an toàn tuyệt đối.</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dep-nha-em-lai-len-duong-ve-voi-khach-a-2026-08-18', 'Xe đẹp nhà em lại lên đường về với khách ạ', '2026-08-18', 'tin-tuc', 'Xe đẹp nhà em lại lên đường về với khách ạ. Các con xắp đi học rồi ba mẹ cần tư vấn mẫu xe đạp, xe thể thao, xe điện ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Xe đẹp nhà em lại lên đường về với khách ạ. Các con xắp đi học rồi ba mẹ cần tư vấn mẫu xe đạp, xe thể thao, xe điện ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dep-nha-em-len-duong-ve-voi-khach-yeu-a-2026-10-26', 'Xe đẹp nhà em lên đường về với khách yêu ạ', '2026-10-26', 'tin-tuc', 'Xe đẹp nhà em lên đường về với khách yêu ạ. Mẫu xe đạp Batwheel 16 nhà em được lòng ba mẹ và các bạn nhỏ lắm ạ. Các Bác quan tâm ib em tư vấn nhé!', '/sites/yenthoa/logo.png', '<p>Xe đẹp nhà em lên đường về với khách yêu ạ. Mẫu xe đạp Batwheel 16 nhà em được lòng ba mẹ và các bạn nhỏ lắm ạ.</p><p>Các Bác quan tâm ib em tư vấn nhé!</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-dien-3-banh-cu-ong-mua-ve-de-di-lai-khong-phu-thuoc-con-c-2026-02-27', 'Xe điện 3 bánh cụ ông mua về để đi lại không phụ thuộc con cháu', '2026-02-27', 'tin-tuc', 'Xe điện 3 bánh cụ ông mua về để đi lại không phụ thuộc con cháu', '/sites/yenthoa/logo.png', '<p>Xe điện 3 bánh cụ ông mua về để đi lại không phụ thuộc con cháu</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-tro-luc-dien-sallway-2026-01-03', 'Xe trợ lực điện Sallway', '2026-01-03', 'tin-tuc', 'Xe trợ lực điện Sallway Là loại xe đạp có gắn động cơ điện và pin, giúp người lái đạp nhẹ nhàng hơn bằng cách cung cấp lực hỗ trợ Xe có thể chạy thuần điện, đạp thuần cơ, hoặc kết hợp cả hai. phù hợp…', '/sites/yenthoa/logo.png', '<p>Xe trợ lực điện Sallway</p><p>Là loại xe đạp có gắn động cơ điện và pin, giúp người lái đạp nhẹ nhàng hơn bằng cách cung cấp lực hỗ trợ</p><p>Xe có thể chạy thuần điện, đạp thuần cơ, hoặc kết hợp cả hai.</p><p>phù hợp cho các bạn học sinh và các Bác lớn tuổi.</p>', 1);
INSERT IGNORE INTO posts (slug, title, date, section, excerpt, img, html, published) VALUES ('xe-xin-mang-ten-espero-billy-2026-06-10', 'Xế xịn mang tên : Espero BILLY', '2026-06-10', 'tin-tuc', 'Xế xịn mang tên : Espero BILLY Thiết kế gọn gàng, dễ dàng len lỏi từng khúc phố Động cơ lên tới 1600W, tốc độ 50km/h, vận hành êm ái Quản lý xe dễ dàng bằng thẻ từ NFC và ứng dụng FunnyRide Cốp rộng…', '/sites/yenthoa/logo.png', '<p>Xế xịn mang tên : Espero BILLY</p><p>Thiết kế gọn gàng, dễ dàng len lỏi từng khúc phố</p><p>Động cơ lên tới 1600W, tốc độ 50km/h, vận hành êm ái</p><p>Quản lý xe dễ dàng bằng thẻ từ NFC và ứng dụng FunnyRide</p><p>Cốp rộng thoải mái chứa gọn mũ bảo hiểm, đồ cá nhân</p><p>Quãng đường : 80-90km/ 1lần sạc</p><p>0902003145</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-133-aima-orla', 'Xe Đạp Điện 133 Aima Orla', 'khac', '[\"xe-dap-dien\"]', 10500000, 10500000, '/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-6.webp\"]', '[]', '[]', '[]', '<p>Không phải mẫu xe nào cũng cần thiết kế cầu kỳ hay thông số “khủng” để tạo ấn tượng. Với nhiều người, một chiếc xe dễ lái, bền bỉ và phù hợp với nhu cầu di chuyển hằng ngày mới là lựa chọn đáng giá. Xe Đạp Điện 133 Aima Orla G5 là đại diện tiêu biểu cho nhóm xe như vậy khi tập trung vào trải nghiệm thực tế thay vì chạy theo hình thức.</p>\n<p>Xe Đạp Điện 133 Aima Orla G5 kế thừa kiểu dáng 133 quen thuộc – một form xe đã quá phổ biến trên đường phố Việt Nam. Tuy nhiên, điểm khác biệt nằm ở cách mẫu xe này được tinh chỉnh lại về tỷ lệ tổng thể để mang đến cảm giác cân đối và “đầm xe” hơn khi sử dụng.</p>', '<p>Không phải mẫu xe nào cũng cần thiết kế cầu kỳ hay thông số “khủng” để tạo ấn tượng. Với nhiều người, một chiếc xe dễ lái, bền bỉ và phù hợp với nhu cầu di chuyển hằng ngày mới là lựa chọn đáng giá. Xe Đạp Điện 133 Aima Orla G5 là đại diện tiêu biểu cho nhóm xe như vậy khi tập trung vào trải nghiệm thực tế thay vì chạy theo hình thức.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-7.webp\" alt=\"Xe Đạp Điện 133 Aima Orla G5\" loading=\"lazy\"></p>\n<h2><strong>Dáng xe nhỏ gọn nhưng mang lại cảm giác chắc chắn</strong></h2>\n<p><strong>Xe Đạp Điện</strong> 133 Aima Orla G5 kế thừa kiểu dáng 133 quen thuộc – một form xe đã quá phổ biến trên đường phố Việt Nam. Tuy nhiên, điểm khác biệt nằm ở cách mẫu xe này được tinh chỉnh lại về tỷ lệ tổng thể để mang đến cảm giác cân đối và “đầm xe” hơn khi sử dụng.</p>\n<p>Kích thước xe được tối ưu để vừa đảm bảo sự nhỏ gọn, vừa giữ được độ ổn định khi di chuyển. Khi đi trong ngõ nhỏ, bãi xe trường học hoặc khu dân cư đông đúc, người dùng có thể dễ dàng xoay trở mà không gặp nhiều khó khăn. Đồng thời, khi chạy trên đường lớn, xe vẫn giữ được sự vững vàng, không tạo cảm giác chao đảo như một số mẫu xe điện giá rẻ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-8.webp\" alt=\"Xe Đạp Điện 133 Aima Orla G5\" loading=\"lazy\"></p>\n<p>Trọng lượng xe ở mức nhẹ vừa phải, giúp việc dắt xe, quay đầu hay dựng chống trở nên đơn giản hơn. Đây là yếu tố rất quan trọng với học sinh hoặc người lớn tuổi – những người thường ưu tiên sự tiện lợi và dễ sử dụng hơn là công suất mạnh.</p>\n<p>Chiều cao yên được thiết kế phù hợp với vóc dáng người Việt, giúp người lái chống chân dễ dàng khi dừng xe. Điều này không chỉ tăng sự tự tin khi điều khiển mà còn góp phần đảm bảo an toàn trong điều kiện giao thông đông đúc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-133-aima-orla-9.webp\" alt=\"Xe Đạp Điện 133 Aima Orla G5\" loading=\"lazy\"></p>\n<p>Khung xe làm từ thép chịu lực kết hợp với hệ thống vành đúc chắc chắn tạo nên một nền tảng ổn định. Khi di chuyển qua các đoạn đường gồ ghề hoặc gờ giảm tốc, Xe Đạp Điện 133 Aima Orla G5 vẫn giữ được độ cân bằng tốt, hạn chế rung lắc ở thân xe.</p>\n<h2><strong>Thiết kế tối giản nhưng vẫn đủ sức hút</strong></h2>\n<p>Không đi theo xu hướng thiết kế phức tạp hay quá nổi bật, Xe Đạp Điện 133 Aima Orla G5 lựa chọn phong cách đơn giản, dễ nhìn và phù hợp với nhiều đối tượng. Chính sự “vừa đủ” này lại là điểm giúp xe giữ được sức hút lâu dài.</p>\n<p>Các đường nét trên thân xe được bo tròn nhẹ nhàng, tạo cảm giác mềm mại nhưng không kém phần hiện đại. Thiết kế này giúp xe không bị “kén người dùng” – từ học sinh, sinh viên đến người đi làm đều có thể sử dụng mà không cảm thấy lạc tông.</p>\n<p>Lớp sơn tĩnh điện phủ bên ngoài mang lại độ bóng tốt và khả năng chống trầy xước nhẹ. Sau một thời gian sử dụng, xe vẫn giữ được vẻ ngoài khá mới nếu được bảo quản đúng cách. Đây là yếu tố quan trọng với những ai có ý định sử dụng xe lâu dài.</p>\n<p>Phần đầu xe được trang bị đèn LED hiện đại, cho ánh sáng rõ và tập trung. Khi di chuyển ban đêm, ánh sáng đủ mạnh để quan sát nhưng không gây chói mắt cho người đi ngược chiều. Đây là điểm cộng lớn về mặt an toàn.</p>\n<p>Bảng đồng hồ điện tử được thiết kế đơn giản, hiển thị rõ ràng các thông tin như tốc độ, mức pin và quãng đường. Người dùng có thể nắm bắt tình trạng xe nhanh chóng mà không cần mất nhiều thời gian làm quen.</p>\n<p>Sàn để chân phẳng, rộng và có các gờ chống trượt giúp tăng độ an toàn khi di chuyển trong điều kiện trời mưa. Thiết kế này cũng giúp người dùng dễ dàng mang theo đồ đạc hoặc thay đổi tư thế khi lái xe.</p>\n<h2><strong>Khả năng vận hành ổn định và dễ kiểm soát</strong></h2>\n<p>Một trong những điểm khiến Xe Đạp Điện <strong>133 Aima Orla G5</strong> được đánh giá cao nằm ở cảm giác vận hành. Xe được trang bị động cơ 500W – mức công suất đủ dùng cho nhu cầu di chuyển trong đô thị.</p>\n<p>Khi sử dụng thực tế, xe cho cảm giác tăng tốc mượt mà, không bị giật cục khi vặn ga. Điều này đặc biệt quan trọng với người mới làm quen với xe điện, giúp họ dễ dàng kiểm soát tốc độ và giữ thăng bằng. Ở dải tốc độ thấp và trung bình, xe vận hành khá êm, ít rung lắc. Khi di chuyển trong giờ cao điểm hoặc khu vực đông phương tiện, người lái vẫn cảm thấy thoải mái và dễ chịu.</p>\n<p>Khả năng chở tải của xe cũng đáp ứng tốt nhu cầu sử dụng hàng ngày. Khi chở thêm người hoặc mang theo đồ, xe vẫn giữ được sự ổn định, không bị hụt lực rõ rệt. Ngoài ra, động cơ điện hoạt động gần như không phát ra tiếng ồn lớn. Điều này mang lại trải nghiệm lái nhẹ nhàng, đồng thời góp phần giảm ô nhiễm tiếng ồn trong đô thị.</p>\n<h2><strong>Quãng đường di chuyển đáp ứng tốt nhu cầu thực tế</strong></h2>\n<p>Pin/ắc quy là yếu tố quan trọng quyết định tính tiện dụng của một chiếc xe điện. Xe Đạp Điện 133 Aima Orla G5 mang đến hai lựa chọn phù hợp với nhiều nhu cầu khác nhau.</p>\n<p>Phiên bản tiêu chuẩn cho phép xe di chuyển quãng đường khoảng 70–75 km sau mỗi lần sạc. Trong khi đó, phiên bản nâng cấp có thể đạt mức 90–100 km. Với quãng đường này, người dùng hoàn toàn có thể đi học hoặc đi làm trong nhiều ngày mà không cần sạc lại. Thời gian sạc dao động từ 8–10 giờ, phù hợp với thói quen sạc qua đêm. Bộ sạc đi kèm có khả năng tự ngắt khi đầy, giúp bảo vệ ắc quy và tăng độ an toàn trong quá trình sử dụng.</p>\n<p>Một ưu điểm lớn của Xe Đạp Điện 133 Aima Orla G5 là chi phí vận hành thấp. So với xe máy xăng, chi phí điện năng cho mỗi lần sạc chỉ ở mức rất nhỏ, giúp tiết kiệm đáng kể trong thời gian dài.</p>\n<h2><strong>Trang bị an toàn và tiện ích thực tế</strong></h2>\n<p>Xe được trang bị hệ thống phanh tang trống trước sau, mang lại lực hãm ổn định và dễ kiểm soát. Với người mới sử dụng, kiểu phanh này giúp hạn chế tình trạng bóp phanh quá mạnh gây mất cân bằng.</p>\n<p>Lốp không săm giúp tăng độ bám đường và giảm nguy cơ xì hơi đột ngột khi gặp vật nhọn. Điều này mang lại sự an tâm hơn khi di chuyển trên nhiều loại địa hình khác nhau. Hệ thống giảm xóc hoạt động hiệu quả, giúp xe vận hành êm ái hơn khi đi qua các đoạn đường xấu. Người ngồi sau cũng cảm thấy thoải mái hơn trong suốt hành trình.</p>\n<p>Cốp xe dưới yên có dung tích đủ dùng để chứa mũ bảo hiểm nửa đầu, áo mưa hoặc một số vật dụng cá nhân. Đây là chi tiết rất thực tế, giúp người dùng không cần mang theo quá nhiều đồ khi di chuyển.</p>\n<p>Xe Đạp Điện 133 <strong>Aima</strong> Orla G5 không phải là mẫu xe gây ấn tượng mạnh ngay từ cái nhìn đầu tiên, nhưng lại chinh phục người dùng bằng sự ổn định và tiện dụng trong quá trình sử dụng lâu dài. Từ thiết kế nhỏ gọn, dễ lái đến khả năng vận hành êm ái và chi phí sử dụng thấp, tất cả đều hướng đến nhu cầu thực tế của người dùng đô thị.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-bruke-pin-lithium-15ah', 'Xe Đạp Điện Bruke Pin Lithium 15Ah', 'khac', '[\"xe-dap-dien\"]', 8400000, 8400000, '/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-5.webp\"]', '[]', '[]', '[]', '<p>Xe đạp điện Bruke, với trái tim là Pin Lithium 48V-15Ah, đại diện cho một bước tiến quan trọng trong lĩnh vực di chuyển xanh, kết hợp sự tiện lợi của xe đạp và khả năng vận hành của động cơ điện. Mẫu xe nhập khẩu này được thiết kế để trở thành người bạn đồng hành tin cậy, linh hoạt trong mọi hành trình đô thị. Bruke cam kết về tính bền vững, mang lại hiệu suất vận hành ổn định, thiết thực cho học sinh, sinh viên và những người cần phương tiện gọn nhẹ, không cần đăng ký.</p>\n<p>Xe điện Bruke được trang bị động cơ điện công suất 350W. Đây là mức công suất được cân chỉnh hoàn hảo, đủ mạnh để cung cấp lực đẩy cần thiết cho việc di chuyển hàng ngày. Động cơ 350W đảm bảo xe dễ dàng tăng tốc mượt mà từ trạng thái đứng yên và duy trì vận tốc ổn định, đặc biệt hữu ích khi di chuyển trên các đoạn đường bằng phẳng.</p>', '<p><strong>Xe đạp điện Bruke</strong>, với trái tim là Pin Lithium 48V-15Ah, đại diện cho một bước tiến quan trọng trong lĩnh vực di chuyển xanh, kết hợp sự tiện lợi của xe đạp và khả năng vận hành của động cơ điện. Mẫu xe nhập khẩu này được thiết kế để trở thành người bạn đồng hành tin cậy, linh hoạt trong mọi hành trình đô thị. Bruke cam kết về tính bền vững, mang lại hiệu suất vận hành ổn định, thiết thực cho học sinh, sinh viên và những người cần phương tiện gọn nhẹ, không cần đăng ký.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-6.webp\" alt=\"Xe Đạp Điện Bruke Pin Lithium 15Ah\" loading=\"lazy\"></p>\n<h2><br><strong>Động cơ tinh chỉnh</strong></h2>\n<p><br><strong>Xe điện Bruke</strong> được trang bị động cơ điện công suất 350W. Đây là mức công suất được cân chỉnh hoàn hảo, đủ mạnh để cung cấp lực đẩy cần thiết cho việc di chuyển hàng ngày. Động cơ 350W đảm bảo xe dễ dàng tăng tốc mượt mà từ trạng thái đứng yên và duy trì vận tốc ổn định, đặc biệt hữu ích khi di chuyển trên các đoạn đường bằng phẳng.</p>\n<p><br>Loại động cơ sử dụng là loại không chổi than, giúp tối ưu hóa hiệu suất năng lượng và giảm thiểu tiếng ồn. Công nghệ này đảm bảo xe vận hành êm ái, tạo cảm giác thoải mái và thư giãn cho người lái. Sự vắng mặt của chổi than cũng loại bỏ nhu cầu bảo dưỡng thường xuyên liên quan đến mài mòn cơ học, kéo dài tuổi thọ và độ bền của động cơ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-7.webp\" alt=\"Xe Đạp Điện Bruke Pin Lithium 15Ah\" loading=\"lazy\"></p>\n<p><br>Xe điện đạt vận tốc max từ 30 đến 40km/h. Đây là dải tốc độ lý tưởng cho xe đạp điện, vừa đảm bảo tính an toàn theo quy định, vừa đủ nhanh để di chuyển hiệu quả trong thành phố. Chế độ vận hành hoàn toàn tự động chỉ cần vặn ga giúp mọi đối tượng, kể cả người mới sử dụng, đều có thể dễ dàng làm chủ chiếc xe.</p>\n<h2><br><strong>Quãng đường vượt trội</strong></h2>\n<p><br>Điểm sáng rực rỡ nhất của Bruke chính là hệ thống Pin Lithium 48V-15Ah. Pin Lithium là công nghệ tiên tiến, sở hữu mật độ năng lượng cao hơn hẳn ắc quy chì truyền thống, giúp xe nhẹ hơn và có tuổi thọ lâu bền hơn. Việc sử dụng pin Lithium là một bước nâng cấp đáng giá, tối ưu hóa trải nghiệm sử dụng.</p>\n<p><br>Với dung lượng 15Ah, chiếc <strong>xe đạp điện Bruke</strong> có khả năng đạt quãng đường di chuyển từ 45 đến 50km sau mỗi lần sạc đầy. Phạm vi hoạt động rộng này giúp người dùng hoàn toàn yên tâm sử dụng xe cho các nhu cầu đi lại hàng ngày như đi học, đi làm, hoặc dạo phố. Việc không cần lo lắng về việc sạc pin liên tục là một lợi thế tiện dụng lớn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-bruke-pin-lithium-15ah-8.webp\" alt=\"Xe Đạp Điện Bruke Pin Lithium 15Ah\" loading=\"lazy\"></p>\n<p><br>Thời gian sạc pin nhanh chóng, chỉ mất từ 4 đến 5 tiếng để nạp đầy năng lượng, phù hợp để sạc qua đêm hoặc tận dụng giờ nghỉ trưa. Bộ sạc được tích hợp tính năng tự động ngắt khi pin đầy, một cơ chế bảo vệ pin khỏi tình trạng sạc quá mức, từ đó đảm bảo tuổi thọ tối đa cho Pin Lithium. Chính sách bảo hành 1 năm cho Pin là cam kết cần thiết về chất lượng.</p>\n<h2><br><strong>Vóc dáng cơ động</strong></h2>\n<p><br><strong>Bruke</strong> được thiết kế với vóc dáng gọn gàng, tôn vinh tính cơ động và sự linh hoạt trong môi trường đô thị chật hẹp. Xe sở hữu chiều cao yên 690mm, một mức lý tưởng giúp người lái dễ dàng chống chân và giữ thăng bằng. Vành bánh xe 12 inch được làm bằng thép đúc nguyên khối, đảm bảo độ chắc chắn và khả năng chịu lực.</p>\n<p><br>Trọng lượng tổng thể của xe là 35kg, khá nhẹ nhàng so với một chiếc xe điện được trang bị Pin Lithium dung lượng lớn. Trọng lượng này giúp người lái dễ dàng dắt bộ hoặc di chuyển xe thủ công qua các khu vực hẹp. Tải trọng tối đa của xe lên tới 150kg, cho phép chở hai người lớn hoặc mang theo hành lý cần thiết mà vẫn duy trì được sự ổn định.</p>\n<p><br>Thiết kế ngoại hình của <strong>Bruke</strong> có sẵn nhiều màu sắc cơ bản. Sự lựa chọn đa dạng này giúp người dùng cá nhân hóa phương tiện, biến chiếc xe thành một phụ kiện thể hiện cá tính riêng. Sự kết hợp giữa thép đúc chắc chắn, vóc dáng cân đối và trọng lượng nhẹ tạo nên một tổng thể vừa bền bỉ, vừa dễ dàng điều khiển.</p>\n<h2><br><strong>Hệ thống phanh</strong></h2>\n<p><br>Yếu tố an toàn luôn được <strong>Bruke</strong> đặt lên hàng đầu thông qua việc trang bị hệ thống phanh đĩa cho cả bánh trước và bánh sau. Phanh đĩa cung cấp lực hãm mạnh mẽ, chính xác và phản ứng nhanh nhạy hơn hẳn phanh cơ truyền thống. Sự trang bị kép này tối đa hóa khả năng kiểm soát tốc độ và dừng xe an toàn trong mọi điều kiện, kể cả khi đường trơn trượt.</p>\n<p><br>Lốp xe được sử dụng là loại không săm, một trang bị hiện đại và thiết thực. Lốp không săm có khả năng tự vá tạm thời hoặc xì hơi từ từ khi cán phải vật nhọn, giảm thiểu nguy cơ nổ lốp đột ngột, giúp người lái an toàn hơn khi di chuyển trên đường. Loại lốp này cũng thường có độ bền cao hơn và ít cần bảo dưỡng hơn.</p>\n<p><br>Hệ thống giảm xóc của <strong>Bruke</strong> sử dụng giảm chấn thủy lực, một công nghệ hiệu quả trong việc hấp thụ xung lực. Giảm chấn thủy lực giúp triệt tiêu các rung động mạnh từ mặt đường, mang lại trải nghiệm lái xe êm ái và thoải mái. Dù đi qua gờ giảm tốc hay các đoạn đường gồ ghề, người lái vẫn cảm thấy dễ chịu, không bị xóc nảy quá mức.</p>\n<h2><br><strong>Tiện ích vượt trội</strong></h2>\n<p><br>Ngoài các tính năng vận hành cơ bản, Bruke còn tích hợp nhiều tiện ích nhằm tối ưu hóa trải nghiệm người dùng. Xe được trang bị hệ thống đèn chiếu sáng và đèn tín hiệu đầy đủ, đảm bảo an toàn khi di chuyển ban đêm hay trong điều kiện ánh sáng yếu. Mọi thông số vận hành đều được hiển thị rõ ràng trên màn hình điều khiển.</p>\n<p><br>Việc vận hành \"tự động hoàn toàn\" là một ưu điểm lớn, loại bỏ nhu cầu về bằng lái xe máy và các thao tác phức tạp. Xe dễ dàng sử dụng cho mọi lứa tuổi, đặc biệt là học sinh. Tải trọng 150kg cũng được coi là một tiện ích, cho phép <strong>xe điện giá rẻ</strong> phục vụ nhiều mục đích khác nhau, từ chở người đến chở đồ đạc cá nhân.</p>\n<p><br>Các phụ kiện đi kèm như sạc và sổ bảo hành cũng được cung cấp đầy đủ, khẳng định tính chính hãng và sự quan tâm đến quyền lợi khách hàng. Tính năng sạc tự động ngắt khi đầy là một tiện ích nhỏ nhưng vô cùng quan trọng, giúp người dùng không cần phải theo dõi quá trình sạc pin, giảm thiểu rủi ro chập cháy hoặc chai pin.</p>\n<h2><br><strong>Sự an tâm khi sử dụng</strong></h2>\n<p><br><strong>Bruke</strong> là sản phẩm nhập khẩu 100%, được kiểm định chất lượng nghiêm ngặt trước khi đưa ra thị trường. Điều này mang lại sự an tâm về nguồn gốc và tiêu chuẩn kỹ thuật. Nhà sản xuất cung cấp chế độ bảo hành khung xe dài hạn lên đến 3 năm, thể hiện sự tin tưởng vào độ cứng cáp và vật liệu chế tạo.</p>\n<p><br>Động cơ 350W được bảo hành 2 năm, là lời cam kết về hiệu suất và tính ổn định của hệ thống truyền động. Khoản bảo hành này giúp người dùng không phải lo lắng về các sự cố kỹ thuật lớn trong thời gian đầu sử dụng, giảm thiểu chi phí phát sinh.</p>\n<p><br>Pin Lithium và ắc quy đều được bảo hành 1 năm. Đây là thời hạn bảo hành tiêu chuẩn đối với các linh kiện lưu trữ điện năng, đảm bảo rằng Pin Lithium 48V-15Ah hoạt động đúng công suất và tuổi thọ như đã công bố. Sự minh bạch và rõ ràng trong chính sách bảo hành là yếu tố then chốt củng cố lòng tin của người tiêu dùng.</p>\n<p><br><strong>Xe Đạp Điện Bruke</strong> Pin Lithium 15Ah là một sự kết hợp tinh tế giữa hiệu suất Pin Lithium và thiết kế cơ động. Với quãng đường di chuyển 45-50km và vận tốc tối đa 40km/h, nó hoàn thành xuất sắc vai trò phương tiện xanh, kinh tế. Hệ thống phanh đĩa kép và tải trọng 150kg là những điểm cộng đắt giá, xác lập Bruke là lựa chọn an toàn và linh hoạt cho cuộc sống năng động.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dibao-hotgirl-keva', 'Xe Đạp Điện Dibao Hotgirl Keva', 'dibao', '[\"xe-dap-dien\"]', 14500000, 14500000, '/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-6.webp\"]', '[]', '[]', '[]', '<p>Buổi sáng vội đến trường, chiều ghé quán cà phê cùng bạn bè, cuối tuần lại muốn lang thang vài con phố để đổi gió. Với những cô nàng có lịch trình luôn đầy ắp như vậy, một chiếc xe phù hợp không chỉ giúp việc đi lại thuận tiện hơn mà còn khiến mỗi chuyến đi trở thành một phần thú vị của cuộc sống. Đó cũng là tinh thần mà xe đạp điện Dibao Hotgirl Keva hướng đến: trẻ trung, linh hoạt và có nét cuốn hút riêng.</p>\n<p>Không cần vẻ ngoài quá hầm hố để gây chú ý, Hotgirl Keva chinh phục người nhìn bằng dáng xe gọn gàng cùng phong cách hiện đại. Đây là lựa chọn đáng cân nhắc dành cho những bạn trẻ muốn tìm một phương tiện đi lại hằng ngày nhưng vẫn quan tâm đến tính thẩm mỹ và dấu ấn cá nhân.</p>', '<h1>&nbsp;</h1>\n<p>Buổi sáng vội đến trường, chiều ghé quán cà phê cùng bạn bè, cuối tuần lại muốn lang thang vài con phố để đổi gió. Với những cô nàng có lịch trình luôn đầy ắp như vậy, một chiếc xe phù hợp không chỉ giúp việc đi lại thuận tiện hơn mà còn khiến mỗi chuyến đi trở thành một phần thú vị của cuộc sống. Đó cũng là tinh thần mà xe đạp điện Dibao Hotgirl Keva hướng đến: trẻ trung, linh hoạt và có nét cuốn hút riêng.</p>\n<p>Không cần vẻ ngoài quá hầm hố để gây chú ý, Hotgirl Keva chinh phục người nhìn bằng dáng xe gọn gàng cùng phong cách hiện đại. Đây là lựa chọn đáng cân nhắc dành cho những bạn trẻ muốn tìm một phương tiện đi lại hằng ngày nhưng vẫn quan tâm đến tính thẩm mỹ và dấu ấn cá nhân.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2>Có những chiếc xe sinh ra để hợp với tuổi trẻ</h2>\n<p>Tuổi trẻ là lúc người ta thích thử những điều mới, muốn tự mình khám phá nhiều nơi và không ngại thể hiện cá tính. Một chiếc xe đồng hành mỗi ngày vì thế cũng cần mang đến cảm giác phù hợp với người sử dụng, từ ngoại hình đến sự thuận tiện khi vận hành.</p>\n<p><strong>Dibao Hotgirl Keva</strong> sở hữu kích thước khoảng 1.700 x 700 x 1.055 mm, tạo tổng thể tương đối gọn gàng khi đi qua những con phố đông đúc. Thiết kế này phù hợp với nhịp sống đô thị, nơi người dùng thường xuyên phải dừng đỗ, quay đầu hoặc di chuyển trong không gian không quá rộng.</p>\n<p>Điểm thú vị nằm ở việc chiếc xe không chỉ phục vụ nhu cầu đi lại mà còn có thể trở thành một phần phong cách thường ngày. Khi kết hợp với chiếc balo đi học, bộ trang phục năng động hay một buổi hẹn cuối tuần, Hotgirl Keva mang đến hình ảnh trẻ trung mà không cần quá nhiều chi tiết cầu kỳ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Xe có nhiều lựa chọn màu sắc để người dùng tìm được phiên bản hợp sở thích. Bởi đôi khi, niềm vui khi mua xe không chỉ nằm ở việc sở hữu phương tiện mới mà còn là cảm giác tìm thấy một món đồ thực sự mang dấu ấn của mình.</p>\n<h2>Nhỏ gọn để cuộc sống bớt những bất tiện</h2>\n<p>Một chiếc xe có thể trông rất đẹp trong ảnh, nhưng điều quyết định nó có phù hợp hay không lại nằm ở những tình huống rất đời thường. Đó là lúc cần dắt xe ra khỏi nhà, tìm chỗ đỗ trước cổng trường hay xoay trở trong một con ngõ nhỏ.</p>\n<p>Với trọng lượng khoảng 78 kg và chiều cao yên tham khảo 750 mm, Dibao Hotgirl Keva hướng đến sự gọn gàng trong quá trình sử dụng. Dù vậy, cảm giác điều khiển còn tùy thuộc vào vóc dáng từng người, nên bạn vẫn nên ngồi thử và kiểm tra khả năng chống chân trước khi lựa chọn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-keva-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Sự tiện lợi còn đến từ cách xe đáp ứng những nhu cầu quen thuộc. Bạn không cần một phương tiện quá lớn nếu phần lớn hành trình chỉ xoay quanh nhà, trường học, nơi làm thêm và các điểm vui chơi gần đó. Một chiếc xe vừa vặn với lịch trình đôi khi hữu ích hơn nhiều so với việc chạy theo những trang bị mà mình hiếm khi sử dụng.</p>\n<h2>Đừng để vẻ ngoài đánh lừa, Hotgirl Keva còn có sức mạnh riêng</h2>\n<p>Ngoại hình là điều khiến người ta chú ý đầu tiên, nhưng khả năng vận hành mới quyết định chiếc xe có đáp ứng được nhu cầu hằng ngày hay không. Dibao Hotgirl Keva được trang bị động cơ điện công suất 1.400W, vận hành tự động và có tốc độ tối đa theo thông số sản phẩm khoảng 50 km/h.</p>\n<p>Cấu hình này hướng đến những chuyến đi thường ngày, từ việc di chuyển trong khu dân cư đến các hành trình quen thuộc trong thành phố. Với những người thường xuyên sử dụng xe, điều quan trọng không phải lúc nào cũng là tốc độ cao, mà là khả năng điều khiển phù hợp, vận hành đúng cách và duy trì tình trạng xe ổn định.</p>\n<p>Hotgirl Keva có tải trọng tối đa theo thông số được cung cấp khoảng 160 kg. Người dùng nên tuân thủ giới hạn tải trọng, tránh chở quá nặng và điều chỉnh tốc độ theo điều kiện đường sá. Dù chiếc xe có thiết kế trẻ trung đến đâu, sự an toàn vẫn cần được đặt lên trước trong mỗi chuyến đi.</p>\n<h2>70 km cho những kế hoạch không muốn bị gián đoạn</h2>\n<p>Một ngày có thể chỉ bắt đầu bằng chuyến đi học ngắn, nhưng sau đó còn hàng loạt việc cần giải quyết. Bởi vậy, quãng đường di chuyển là yếu tố đáng cân nhắc khi chọn xe điện.</p>\n<p>Dibao Hotgirl Keva có thể đi khoảng 70 km sau mỗi lần sạc đầy trong điều kiện phù hợp. Xe sử dụng bộ ắc quy Dibao gồm 5 bình, dung lượng 22Ah, đáp ứng nhu cầu di chuyển thường ngày của nhiều người dùng có lịch trình trong khu vực.</p>\n<p>Thời gian sạc tham khảo khoảng 8–10 tiếng, phù hợp để sắp xếp sạc vào buổi tối khi xe không còn được sử dụng. Bộ sạc có chức năng tự ngắt khi ắc quy đầy theo thông tin sản phẩm. Tuy nhiên, người dùng vẫn cần sử dụng bộ sạc tương thích, đặt xe ở nơi khô ráo, thông thoáng và làm theo hướng dẫn của nhà sản xuất.</p>\n<p>Mức quãng đường thực tế có thể thay đổi theo tốc độ, tải trọng, địa hình và tình trạng ắc quy. Vì vậy, nếu mỗi ngày phải di chuyển nhiều nơi, bạn nên tính toán lịch trình hợp lý và kiểm tra lượng điện còn lại trước khi đi xa. Chủ động một chút sẽ giúp những kế hoạch trong ngày diễn ra suôn sẻ hơn.</p>\n<h2>Những chi tiết nhỏ tạo nên sự yên tâm</h2>\n<p>Một chiếc xe đồng hành mỗi ngày cần được quan tâm không chỉ ở ngoại hình hay động cơ mà còn ở các bộ phận ảnh hưởng trực tiếp đến việc vận hành. Dibao Hotgirl Keva được trang bị phanh đĩa phía trước và phanh tang trống phía sau, hỗ trợ người lái kiểm soát tốc độ khi di chuyển.</p>\n<p>Xe còn sử dụng lốp không săm Kenda kích thước 300-10, vành thép đúc cùng hệ thống giảm xóc thủy lực. Những trang bị này góp phần phục vụ nhu cầu đi lại thường ngày trên đường phố. Để duy trì khả năng vận hành ổn định, người dùng nên kiểm tra phanh, lốp và hệ thống giảm xóc định kỳ.</p>\n<p>Đặc biệt, đừng đợi đến khi xe có dấu hiệu bất thường mới mang đi kiểm tra. Phanh kém nhạy, lốp non hơi hoặc quãng đường di chuyển giảm rõ rệt đều là những dấu hiệu nên được chú ý. Việc bảo dưỡng đúng lúc giúp bạn hạn chế những phiền toái không đáng có trên đường.</p>\n<h2>Chọn chiếc <strong>xe đạp điện gọn gàng</strong>, hợp mình, không cần giống bất kỳ ai</h2>\n<p>Dibao Hotgirl Keva phù hợp để tìm hiểu nếu bạn yêu thích kiểu dáng trẻ trung, cần một phương tiện gọn gàng và thường xuyên di chuyển trong khu vực đô thị. Tuy nhiên, mỗi người có một lịch trình khác nhau, vì vậy đừng chọn xe chỉ vì thấy đẹp hoặc được nhiều người quan tâm.</p>\n<p>Hãy bắt đầu từ những câu hỏi đơn giản: Mỗi ngày bạn đi bao xa? Bạn có thường xuyên phải chở đồ không? Chiều cao yên có phù hợp với vóc dáng? Bạn thích kiểu dáng nhẹ nhàng hay màu sắc nổi bật? Khi trả lời được những câu hỏi này, bạn sẽ dễ dàng xác định Hotgirl Keva có phải lựa chọn phù hợp hay không.</p>\n<p>Nếu đang tìm mua <strong>xe đạp điện Dibao Hotgirl</strong> Keva, bạn có thể đến Yên Thoa để xem xe thực tế, tham khảo màu sắc, thông số và chính sách bảo hành trước khi quyết định. Trải nghiệm trực tiếp sẽ giúp bạn đánh giá chính xác hơn về tư thế ngồi, cảm giác điều khiển và sự thuận tiện khi sử dụng.</p>\n<p>Bởi một chiếc xe đáng chọn không chỉ là chiếc xe khiến bạn thích ngay từ cái nhìn đầu tiên, mà còn là chiếc xe khiến bạn cảm thấy thoải mái mỗi khi bước lên và bắt đầu hành trình mới. Với Dibao Hotgirl Keva, sự trẻ trung không chỉ nằm ở vẻ ngoài mà còn ở cách chiếc xe có thể đồng hành cùng nhịp sống năng động của người trẻ mỗi ngày.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dibao-hotgirl-s-one', 'Xe Đạp Điện Dibao HotGirl S-ONe', 'dibao', '[\"xe-dap-dien\"]', 16200000, 16200000, '/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-6.webp\"]', '[]', '[]', '[]', '<p>Giữa vô vàn lựa chọn xe điện trên thị trường, không phải mẫu xe nào cũng đủ sức khiến người dùng “chốt đơn” ngay từ cái nhìn đầu tiên. Nhưng Dibao HotGirl S-One lại là một ngoại lệ. Sở hữu thiết kế thời thượng, vận hành êm ái cùng khả năng di chuyển ấn tượng, mẫu xe này nhanh chóng trở thành cái tên được săn đón trong phân khúc xe điện đô thị. Không chỉ đơn thuần là phương tiện đi lại, S-One còn mang đến trải nghiệm tiện lợi, tiết kiệm và phù hợp hoàn hảo với phong cách sống năng động của giới trẻ hiện nay.</p>\n<p>Ngay từ cái nhìn đầu tiên, Dibao HotGirl S-One đã tạo thiện cảm nhờ ngoại hình gọn gàng nhưng không kém phần nổi bật. Tổng thể xe mang phong cách năng động, trẻ trung với những đường nét mềm mại kết hợp cùng các chi tiết tinh chỉnh sắc sảo.</p>', '<p>Giữa vô vàn lựa chọn xe điện trên thị trường, không phải mẫu xe nào cũng đủ sức khiến người dùng “chốt đơn” ngay từ cái nhìn đầu tiên. Nhưng Dibao HotGirl S-One lại là một ngoại lệ. Sở hữu thiết kế thời thượng, vận hành êm ái cùng khả năng di chuyển ấn tượng, mẫu xe này nhanh chóng trở thành cái tên được săn đón trong phân khúc xe điện đô thị. Không chỉ đơn thuần là phương tiện đi lại, S-One còn mang đến trải nghiệm tiện lợi, tiết kiệm và phù hợp hoàn hảo với phong cách sống năng động của giới trẻ hiện nay.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế hiện đại, trẻ trung và cực kỳ phù hợp đô thị</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, <strong>Dibao HotGirl S-One</strong> đã tạo thiện cảm nhờ ngoại hình gọn gàng nhưng không kém phần nổi bật. Tổng thể xe mang phong cách năng động, trẻ trung với những đường nét mềm mại kết hợp cùng các chi tiết tinh chỉnh sắc sảo.</p>\n<p>Không quá hầm hố hay góc cạnh như các dòng xe thể thao, S-One đi theo hướng thiết kế nhẹ nhàng, thanh thoát. Điều này giúp xe phù hợp với nhiều đối tượng, đặc biệt là học sinh và người dùng trẻ yêu thích sự tinh tế nhưng vẫn muốn thể hiện cá tính riêng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Kích thước tổng thể 1700mm x 700mm x 1055mm được tính toán hợp lý, giúp xe dễ dàng di chuyển trong các tuyến phố đông đúc hoặc ngõ nhỏ. Đây là một lợi thế cực lớn trong môi trường đô thị như Hà Nội hay TP.HCM, nơi việc xoay trở linh hoạt luôn được ưu tiên hàng đầu.</p>\n<p>Chiều cao yên 750mm là một điểm cộng đáng giá. Với thông số này, người dùng có thể chống chân dễ dàng, giữ thăng bằng tốt hơn khi dừng xe. Điều này đặc biệt quan trọng với những người mới sử dụng xe điện hoặc có vóc dáng nhỏ.</p>\n<p>Không chỉ dừng lại ở form dáng, màu sắc của xe cũng rất đa dạng, từ các gam màu nhẹ nhàng đến cá tính, giúp người dùng dễ dàng lựa chọn theo sở thích. Lớp sơn phủ bóng kết hợp cùng các chi tiết hoàn thiện tỉ mỉ tạo nên một tổng thể cao cấp hơn hẳn so với nhiều mẫu xe cùng phân khúc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-hotgirl-s-one-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Động cơ mạnh mẽ 1550W – Vận hành êm ái, tăng tốc mượt mà</strong></h2>\n<p>Bên trong vẻ ngoài nhẹ nhàng của Dibao HotGirl S-One là một “trái tim” mạnh mẽ đến từ động cơ không chổi than BLDC công suất 1550W. Đây là mức công suất rất ấn tượng trong phân khúc xe đạp điện, mang lại khả năng vận hành ổn định và bền bỉ.</p>\n<p>Động cơ BLDC có ưu điểm lớn là giảm ma sát, hạn chế hao mòn và vận hành êm hơn so với động cơ truyền thống. Nhờ đó, xe gần như không phát ra tiếng ồn lớn, mang lại cảm giác dễ chịu khi di chuyển trong thành phố.</p>\n<p>Khả năng tăng tốc của xe cũng rất đáng chú ý. Khi vặn ga, xe phản hồi nhanh, không bị trễ, giúp người lái dễ dàng hòa vào dòng giao thông đông đúc. Điều này đặc biệt hữu ích khi cần vượt xe hoặc di chuyển qua các đoạn đường đông.</p>\n<p>Tốc độ tối đa của xe đạt khoảng 55km/h – một con số lý tưởng để đảm bảo vừa đủ nhanh cho nhu cầu di chuyển, vừa đảm bảo an toàn. Với mức tốc độ này, người dùng có thể đi học, đi làm hay di chuyển trong nội thành một cách linh hoạt mà không gặp bất kỳ trở ngại nào.</p>\n<h2><strong>Quãng đường di chuyển ấn tượng – Đi cả ngày không lo hết điện</strong></h2>\n<p>Một trong những yếu tố khiến nhiều người cân nhắc khi mua <strong>xe đạp điện đô thị</strong> chính là quãng đường di chuyển. Và với Dibao HotGirl S-One, nỗi lo này gần như được giải quyết hoàn toàn.</p>\n<p>Xe có thể di chuyển lên tới khoảng 90km sau mỗi lần sạc đầy. Đây là con số cực kỳ ấn tượng trong phân khúc xe đạp điện, đủ để đáp ứng nhu cầu đi lại trong nhiều ngày mà không cần sạc lại.</p>\n<p>Với học sinh, sinh viên, quãng đường này có thể đáp ứng việc đi học, đi chơi, thậm chí đi thêm nhiều điểm khác trong ngày mà vẫn dư pin. Còn với người đi làm, việc sử dụng xe cho cả tuần cũng không phải vấn đề quá lớn.</p>\n<p>Khả năng di chuyển xa giúp người dùng chủ động hơn trong lịch trình, không còn phụ thuộc vào việc phải sạc xe liên tục. Đây chính là một lợi thế lớn khiến S-One trở nên nổi bật trên thị trường.</p>\n<h2><strong>Hệ thống ắc quy ổn định và cơ chế sạc an toàn</strong></h2>\n<p>Dibao HotGirl S-One sử dụng bộ 5 bình ắc quy 20Ah tiêu chuẩn, cung cấp nguồn điện ổn định cho toàn bộ hệ thống vận hành. Ngoài ra, người dùng còn có thể nâng cấp lên ắc quy 23Ah để tăng dung lượng và hiệu suất sử dụng.</p>\n<p>Thời gian sạc đầy dao động từ 8 đến 10 tiếng, phù hợp để sạc qua đêm. Đây là thói quen sử dụng phổ biến, giúp người dùng không bị gián đoạn trong quá trình di chuyển hàng ngày.</p>\n<p>Điểm đáng giá nhất nằm ở cơ chế sạc thông minh. Xe được trang bị tính năng tự động ngắt điện khi đầy, giúp tránh tình trạng quá tải, nóng bình hoặc nguy cơ cháy nổ. Điều này mang lại sự an tâm tuyệt đối cho người dùng khi sạc xe tại nhà.</p>\n<p>Ngoài ra, hệ thống sạc còn được thiết kế nhằm tối ưu tuổi thọ ắc quy, hạn chế tình trạng chai pin theo thời gian. Đây là yếu tố giúp tiết kiệm chi phí sử dụng lâu dài.</p>\n<h2><strong>Hệ thống an toàn tối ưu cho người sử dụng</strong></h2>\n<p>An toàn luôn là yếu tố quan trọng hàng đầu đối với bất kỳ phương tiện nào, đặc biệt là xe điện dành cho học sinh. Và Dibao HotGirl S-One đã làm rất tốt ở điểm này.</p>\n<p>Xe được trang bị phanh đĩa cho bánh trước, kết hợp cùng phanh cơ phía sau. Sự kết hợp này mang lại lực phanh mạnh mẽ, giúp người lái kiểm soát tốc độ tốt hơn trong các tình huống khẩn cấp.</p>\n<p>Hệ thống giảm xóc thủy lực trước và sau giúp xe vận hành êm ái hơn khi đi qua các đoạn đường xấu. Điều này không chỉ tăng sự thoải mái mà còn giúp bảo vệ khung xe và các bộ phận khác.</p>\n<p>Lốp không săm Kenda 300-10 là một điểm cộng lớn. Loại lốp này giúp giảm nguy cơ xì hơi đột ngột, tăng độ bám đường và đảm bảo an toàn khi di chuyển trong điều kiện thời tiết xấu.</p>\n<h2><strong>Trải nghiệm lái nhẹ nhàng, phù hợp mọi đối tượng</strong></h2>\n<p>Một trong những điểm khiến Dibao HotGirl S-One được yêu thích chính là cảm giác lái cực kỳ dễ làm quen. Xe sử dụng hệ thống vận hành hoàn toàn tự động, không cần thao tác phức tạp.</p>\n<p>Trọng lượng xe khoảng 80kg giúp việc dắt xe, quay đầu hay đỗ xe trở nên dễ dàng hơn. Đây là yếu tố rất quan trọng với học sinh hoặc người dùng nữ.</p>\n<p>Khả năng chịu tải lên tới 180kg cho phép xe chở thêm người hoặc đồ đạc mà vẫn đảm bảo ổn định. Điều này giúp xe trở nên linh hoạt hơn trong nhiều tình huống sử dụng thực tế.</p>\n<p>Các nút điều khiển, đồng hồ hiển thị và hệ thống đèn đều được bố trí khoa học, giúp người dùng dễ dàng thao tác ngay từ lần đầu sử dụng.</p>\n<h2><strong>Chính sách bảo hành uy tín – Yên tâm sử dụng lâu dài</strong></h2>\n<p>Một trong những lý do khiến nhiều người lựa chọn <strong>xe&nbsp;Dibao</strong> chính là chính sách hậu mãi rõ ràng và đáng tin cậy.</p>\n<p>Dibao HotGirl S-One được bảo hành khung xe lên tới 3 năm – một con số rất ấn tượng, thể hiện sự tự tin về chất lượng sản phẩm. Động cơ được bảo hành 2 năm, đảm bảo hiệu suất vận hành ổn định trong thời gian dài.</p>\n<p>Hệ thống ắc quy được bảo hành 1 năm, giúp người dùng yên tâm trong quá trình sử dụng. Ngoài ra, linh kiện thay thế luôn sẵn có do xe được lắp ráp tại Việt Nam, giúp việc sửa chữa nhanh chóng và tiết kiệm chi phí.</p>\n<h2><strong>Chi phí vận hành tiết kiệm – Lợi thế lớn của xe điện</strong></h2>\n<p>So với xe máy xăng, chi phí vận hành của Dibao HotGirl S-One thấp hơn rất nhiều. Mỗi lần sạc đầy chỉ tốn khoảng vài chục nghìn đồng, trong khi có thể đi được gần 90km.</p>\n<p>Nếu tính theo chi phí hàng tháng, người dùng chỉ cần bỏ ra một khoản rất nhỏ để duy trì việc di chuyển hàng ngày. Đây là lợi thế cực lớn, đặc biệt với học sinh, sinh viên.</p>\n<p>Ngoài ra, xe điện không cần thay dầu nhớt hay bảo dưỡng phức tạp, giúp giảm đáng kể chi phí bảo trì.</p>\n<p>Xe đạp điện Dibao HotGirl S-One không chỉ đơn thuần là một phương tiện di chuyển mà còn là một lựa chọn thông minh cho cuộc sống hiện đại. Với thiết kế đẹp mắt, động cơ mạnh mẽ, quãng đường di chuyển dài và chi phí vận hành thấp, mẫu xe này đáp ứng gần như đầy đủ mọi nhu cầu của người dùng trẻ.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe điện vừa bền bỉ, vừa tiết kiệm, lại có phong cách riêng, thì Dibao HotGirl S-One chắc chắn là cái tên rất đáng để cân nhắc. Đây là sự đầu tư xứng đáng cho một phương tiện di chuyển tiện lợi, an toàn và đầy cá tính trong thời đại giao thông xanh.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dibao-queen-day-du-giay-to', 'Xe Đạp Điện Dibao Queen Đầy Đủ Giấy Tờ', 'dibao', '[\"xe-dap-dien\"]', 16190000, 16190000, '/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Những mẫu xe đạp điện thế hệ mới đang dần chiếm được cảm tình của người dùng, đặc biệt là giới trẻ, dân văn phòng và những người thường xuyên di chuyển trong nội đô. Và Dibao Queen đang dần trở thành cái tên quen thuộc nhờ sự kết hợp hài hòa giữa thiết kế thanh lịch, hiệu suất ổn định và khả năng tiết kiệm chi phí vượt trội. Không đơn thuần là một chiếc xe điện, Dibao Queen mang đến một phong cách sống – nơi việc di chuyển trở nên nhẹ nhàng, tiện lợi và thông minh hơn mỗi ngày.</p>\n<p>Khi sử dụng Dibao Queen trong môi trường đô thị, điều đầu tiên mà người dùng dễ dàng cảm nhận chính là sự linh hoạt. Với thiết kế tổng thể nhỏ gọn, các đường nét mềm mại và tinh tế, chiếc xe này dễ dàng len lỏi qua những con phố đông đúc, những con hẻm nhỏ hay khu vực chợ đông người mà không gặp bất kỳ trở ngại nào. Đây là lợi thế rất lớn so với các dòng xe máy cồng kềnh, đặc biệt trong giờ cao điểm khi giao thông thường xuyên ùn tắc.</p>', '<p>Những mẫu <strong>xe đạp điện thế hệ mới</strong> đang dần chiếm được cảm tình của người dùng, đặc biệt là giới trẻ, dân văn phòng và những người thường xuyên di chuyển trong nội đô. Và Dibao Queen đang dần trở thành cái tên quen thuộc nhờ sự kết hợp hài hòa giữa thiết kế thanh lịch, hiệu suất ổn định và khả năng tiết kiệm chi phí vượt trội. Không đơn thuần là một chiếc xe điện, Dibao Queen mang đến một phong cách sống – nơi việc di chuyển trở nên nhẹ nhàng, tiện lợi và thông minh hơn mỗi ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Trải nghiệm hàng ngày với dibao queen: nhỏ gọn nhưng khác biệt lớn</strong></h2>\n<p>Khi sử dụng Dibao Queen trong môi trường đô thị, điều đầu tiên mà người dùng dễ dàng cảm nhận chính là sự linh hoạt. Với thiết kế tổng thể nhỏ gọn, các đường nét mềm mại và tinh tế, chiếc xe này dễ dàng len lỏi qua những con phố đông đúc, những con hẻm nhỏ hay khu vực chợ đông người mà không gặp bất kỳ trở ngại nào. Đây là lợi thế rất lớn so với các dòng xe máy cồng kềnh, đặc biệt trong giờ cao điểm khi giao thông thường xuyên ùn tắc.</p>\n<p>Không chỉ dừng lại ở sự linh hoạt, Dibao Queen còn mang đến cảm giác thoải mái trong quá trình sử dụng. Chiều cao yên xe được thiết kế hợp lý, phù hợp với vóc dáng người Việt, giúp người lái dễ dàng chống chân khi dừng đèn đỏ hay di chuyển chậm. Điều này tưởng chừng nhỏ nhưng lại cực kỳ quan trọng trong việc giảm mệt mỏi khi phải di chuyển liên tục trong ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Một điểm cộng đáng chú ý khác là khả năng “thích nghi” với cuộc sống đô thị. Bạn có thể dễ dàng dắt xe vào thang máy, đưa lên tầng lầu hoặc xoay trở trong không gian hẹp mà không gặp khó khăn. Với trọng lượng chỉ khoảng 86kg, việc di chuyển xe trong các khu chung cư hoặc nhà phố trở nên nhẹ nhàng hơn rất nhiều.</p>\n<h2><strong>Thiết kế thanh lịch: không chỉ để đi mà còn để “thể hiện”</strong></h2>\n<p>Trong thời đại mà phương tiện cũng là một phần của phong cách cá nhân, thiết kế đóng vai trò vô cùng quan trọng. Dibao Queen không chỉ là một chiếc xe điện đơn thuần mà còn là một “phụ kiện thời trang” giúp người dùng thể hiện cá tính.</p>\n<p>Tổng thể xe được thiết kế theo phong cách hiện đại, tối giản nhưng không kém phần sang trọng. Các đường cong mềm mại kết hợp với tỷ lệ cân đối giúp chiếc xe trở nên hài hòa và bắt mắt. Dù bạn là sinh viên, nhân viên văn phòng hay người kinh doanh tự do, Dibao Queen vẫn phù hợp và dễ dàng “ăn nhập” với phong cách của bạn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-queen-day-du-giay-to-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Hệ thống đèn pha LED bi siêu sáng không chỉ đóng vai trò chiếu sáng mà còn là điểm nhấn thẩm mỹ. Ánh sáng trắng rõ nét giúp bạn quan sát tốt hơn vào ban đêm, đồng thời tạo nên diện mạo hiện đại, nổi bật khi di chuyển trên đường phố.</p>\n<p>Ngoài ra, bảng màu đa dạng từ trắng, đen, xanh đến đỏ giúp người dùng dễ dàng lựa chọn theo sở thích cá nhân. Đây là yếu tố quan trọng giúp Dibao Queen không bị “đại trà” như nhiều mẫu xe điện khác trên thị trường.</p>\n<h2><strong>Hiệu suất vận hành: êm ái nhưng không hề yếu</strong></h2>\n<p>Một trong những điểm khiến nhiều người bất ngờ khi trải nghiệm Dibao Queen chính là khả năng vận hành. Dù mang dáng vẻ nhẹ nhàng, thanh lịch, nhưng chiếc xe này lại sở hữu động cơ mạnh mẽ đủ để đáp ứng nhu cầu di chuyển hàng ngày trong đô thị.</p>\n<p>Động cơ BLDC công suất từ 1000W đến 1550W (tùy phiên bản) giúp xe tăng tốc mượt mà, không giật cục. Khi di chuyển trong phố hoặc leo dốc nhẹ, xe vẫn giữ được độ ổn định và không tạo cảm giác ì máy. Điều này đặc biệt hữu ích khi bạn cần di chuyển nhanh trong giờ cao điểm hoặc vượt qua các đoạn đường dốc trong thành phố.</p>\n<p>Một ưu điểm lớn của động cơ không chổi than là hoạt động êm ái, gần như không gây tiếng ồn. Điều này mang lại trải nghiệm dễ chịu hơn, đồng thời giảm ô nhiễm tiếng ồn – một vấn đề đang ngày càng được quan tâm tại các đô thị lớn.</p>\n<h2><strong>Quãng đường di chuyển: đủ cho cả ngày năng động</strong></h2>\n<p>Đối với người dùng xe điện, nỗi lo lớn nhất luôn là “hết pin giữa đường”. Tuy nhiên, với <strong>Dibao Queen</strong>, vấn đề này gần như được giải quyết triệt để.</p>\n<p>Phiên bản sử dụng pin Lithium 60V – 30Ah cho phép xe di chuyển lên đến 130km sau mỗi lần sạc đầy. Đây là con số rất ấn tượng trong phân khúc xe đạp điện, đủ để bạn đi làm cả tuần mà không cần sạc lại nếu quãng đường di chuyển không quá xa.</p>\n<p>Đối với phiên bản sử dụng ắc quy, quãng đường 80–90km mỗi lần sạc vẫn đáp ứng tốt nhu cầu đi lại cơ bản như đi học, đi làm, đi chợ hay gặp gỡ bạn bè. Điều này giúp người dùng yên tâm hơn khi sử dụng xe hàng ngày mà không phải lo lắng quá nhiều về việc sạc pin.</p>\n<h2><strong>An toàn và ổn định: yếu tố không thể bỏ qua</strong></h2>\n<p>Một chiếc xe tốt không chỉ cần mạnh mà còn phải an toàn. Dibao Queen được trang bị hệ thống phanh đĩa phía trước kết hợp với phanh cơ phía sau, giúp người lái kiểm soát tốc độ hiệu quả trong mọi tình huống.</p>\n<p>Lốp Kenda kích thước 300-10 có độ bám đường tốt, giúp xe vận hành ổn định ngay cả khi đường trơn trượt sau mưa. Đây là yếu tố rất quan trọng trong điều kiện thời tiết thất thường tại Việt Nam.</p>\n<p>Ngoài ra, vành đúc chắc chắn không chỉ tăng độ bền mà còn giúp xe chịu lực tốt hơn, giảm nguy cơ hỏng hóc khi di chuyển trên những đoạn đường xấu.</p>\n<h2><strong>Tiết kiệm chi phí: lợi thế lớn trong thời đại giá xăng tăng</strong></h2>\n<p>Một trong những lý do khiến nhiều người chuyển sang xe điện là chi phí vận hành thấp, và Dibao Queen là một minh chứng rõ ràng.</p>\n<p>Với mức tiêu thụ điện năng chỉ khoảng 35,03Wh/km, chi phí cho mỗi km di chuyển chỉ vào khoảng 500 đồng – một con số cực kỳ tiết kiệm so với xe máy xăng. Trong bối cảnh giá nhiên liệu liên tục biến động, đây là lợi thế rất lớn giúp người dùng giảm đáng kể chi phí sinh hoạt hàng tháng.</p>\n<p>Ngoài ra, xe điện cũng ít hỏng vặt hơn, không cần thay dầu, không cần bảo dưỡng động cơ phức tạp, giúp tiết kiệm thêm chi phí sửa chữa trong dài hạn.</p>\n<h2><strong>Thông số kỹ thuật: nền tảng cho hiệu suất ổn định</strong></h2>\n<p>Về mặt kỹ thuật, Dibao Queen sở hữu những thông số phù hợp với nhu cầu di chuyển trong đô thị. Kích thước xe cân đối, không quá lớn cũng không quá nhỏ, giúp người dùng dễ dàng điều khiển.</p>\n<p>Tốc độ tối đa 40–45 km/h phù hợp với quy định giao thông và đảm bảo an toàn khi di chuyển trong thành phố. Khả năng chịu tải lên đến 130kg giúp xe có thể chở thêm người hoặc hàng hóa mà không ảnh hưởng đến hiệu suất.</p>\n<p>Thời gian sạc khoảng 12 tiếng cho phép bạn sạc qua đêm và sử dụng cả ngày hôm sau mà không bị gián đoạn.</p>\n<h2><strong>Dibao queen phù hợp với ai?</strong></h2>\n<p>Dibao Queen là lựa chọn lý tưởng cho nhiều nhóm người dùng khác nhau. Từ học sinh, sinh viên cần phương tiện tiết kiệm, đến nhân viên văn phòng cần di chuyển hàng ngày, hay những người kinh doanh nhỏ cần phương tiện linh hoạt – tất cả đều có thể tìm thấy sự phù hợp ở mẫu xe này.</p>\n<p>Đặc biệt, với những ai quan tâm đến môi trường và muốn giảm thiểu khí thải, Dibao Queen là một lựa chọn đáng cân nhắc. Không chỉ giúp tiết kiệm chi phí, chiếc xe còn góp phần xây dựng một môi trường sống xanh hơn.</p>\n<p>Trong một thế giới mà mọi thứ đang hướng tới sự tiện lợi, tiết kiệm và bền vững,<strong> xe đạp điện Dibao</strong> Queen nổi lên như một giải pháp di chuyển toàn diện cho đô thị. Không chỉ đơn thuần là một chiếc xe điện, Dibao Queen mang đến trải nghiệm di chuyển nhẹ nhàng, êm ái và hiệu quả. Từ thiết kế, hiệu suất cho đến chi phí vận hành, tất cả đều được tối ưu để phục vụ nhu cầu thực tế của người dùng.</p>\n<p>Nếu bạn đang tìm kiếm một phương tiện vừa đẹp, vừa tiện, vừa tiết kiệm, thì Dibao Queen chắc chắn là một lựa chọn đáng để cân nhắc trong năm nay.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dibao-rosa-the-he-moi', 'Xe Đạp Điện Dibao Rosa Thế Hệ Mới', 'dibao', '[\"xe-dap-dien\"]', 16500000, 16500000, '/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-6.webp\"]', '[]', '[]', '[]', '<p>Ngay từ lần đầu xuất hiện,Dibao Rosa mang lại một cảm giác rất khác: nhẹ nhàng, gọn gàng nhưng không hề đơn điệu. Nó không cố gắng trở nên hầm hố hay quá nổi loạn, mà chọn cách chinh phục người dùng bằng sự tinh tế trong từng chi tiết và trải nghiệm sử dụng thực tế. Chính vì vậy, Dibao Rosa nhanh chóng trở thành lựa chọn được nhiều học sinh, sinh viên và đặc biệt là phái nữ quan tâm – những người cần một chiếc xe vừa đẹp, dễ đi, lại phải tiết kiệm và bền bỉ trong thời gian dài.</p>\n<p>Điểm dễ nhận ra nhất khi nhìn vào Dibao Rosa chính là cảm giác “dễ chịu” mà thiết kế mang lại. Không góc cạnh, không quá cầu kỳ, chiếc xe lựa chọn những đường cong mềm mại, bo tròn tinh tế để tạo nên tổng thể hài hòa và thân thiện với người dùng.</p>', '<p>Ngay từ lần đầu xuất hiện,Dibao Rosa mang lại một cảm giác rất khác: nhẹ nhàng, gọn gàng nhưng không hề đơn điệu. Nó không cố gắng trở nên hầm hố hay quá nổi loạn, mà chọn cách chinh phục người dùng bằng sự tinh tế trong từng chi tiết và trải nghiệm sử dụng thực tế. Chính vì vậy, Dibao Rosa nhanh chóng trở thành lựa chọn được nhiều học sinh, sinh viên và đặc biệt là phái nữ quan tâm – những người cần một chiếc xe vừa đẹp, dễ đi, lại phải tiết kiệm và bền bỉ trong thời gian dài.</p>\n<h2><strong>Thiết kế nhỏ gọn nhưng không hề “nhạt nhòa”</strong></h2>\n<p>Điểm dễ nhận ra nhất khi nhìn vào <strong>Dibao Rosa</strong> chính là cảm giác “dễ chịu” mà thiết kế mang lại. Không góc cạnh, không quá cầu kỳ, chiếc xe lựa chọn những đường cong mềm mại, bo tròn tinh tế để tạo nên tổng thể hài hòa và thân thiện với người dùng.</p>\n<p>Với kích thước tổng thể 1630 x 675 x 1010 mm cùng chiều cao yên khoảng 730 mm, Rosa trở nên cực kỳ phù hợp với vóc dáng người Việt. Người lái có thể dễ dàng chống chân khi dừng xe, điều khiển linh hoạt trong phố đông hoặc quay đầu trong không gian hẹp mà không gặp nhiều khó khăn. Đây là một yếu tố rất quan trọng nhưng thường bị bỏ qua trên nhiều mẫu xe khác.</p>\n<p>Phần đầu xe được thiết kế nổi bật với cụm đèn LED bi cầu dạng tròn, mang hơi hướng cổ điển nhưng vẫn giữ được nét hiện đại nhờ công nghệ chiếu sáng tiên tiến. Bao quanh là dải đèn demi tạo hiệu ứng ánh sáng rất bắt mắt khi di chuyển vào ban đêm. Logo mạ crom đặt chính giữa không quá phô trương nhưng đủ để tạo điểm nhấn sang trọng nhẹ nhàng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Chắn bùn trước được thiết kế theo dạng bầu bĩnh, vừa tăng tính thẩm mỹ vừa đảm bảo khả năng chắn nước và bùn đất khi di chuyển trong điều kiện thời tiết xấu. Tổng thể chiếc xe mang lại cảm giác “xinh xắn có chủ đích”, không quá nổi loạn nhưng đủ để tạo sự khác biệt giữa đám đông.</p>\n<h2><strong>Trải nghiệm thực tế: ngồi lên là thấy hợp ngay</strong></h2>\n<p>Một chiếc xe đẹp sẽ thu hút bạn trong vài phút, nhưng một chiếc xe thoải mái mới là thứ giữ bạn lại lâu dài. Dibao Rosa làm khá tốt điều này khi mang lại trải nghiệm sử dụng rất dễ chịu ngay từ lần đầu tiên.</p>\n<p>Yên xe được bọc da PU dày, có độ đàn hồi tốt, mang lại cảm giác êm ái khi ngồi lâu. Với thiết kế yên dài và rộng, người dùng có thể chở thêm người phía sau mà vẫn đảm bảo sự thoải mái, không bị gò bó như một số mẫu xe nhỏ khác.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Sàn để chân rộng rãi, có vân chống trượt, giúp người lái giữ được tư thế ổn định ngay cả khi đi mưa hoặc mang giày trơn. Đây là một chi tiết nhỏ nhưng lại rất quan trọng trong quá trình sử dụng hàng ngày.</p>\n<p>Ghi-đông được bố trí ở vị trí hợp lý, giúp người lái giữ được tư thế thẳng lưng, không bị mỏi tay hay đau vai khi di chuyển trong thời gian dài. Tất cả những yếu tố này kết hợp lại tạo nên một trải nghiệm lái nhẹ nhàng, phù hợp với cả những người lần đầu sử dụng xe điện.</p>\n<h2><strong>Động cơ 1000W – không quá mạnh nhưng đủ để “thích”</strong></h2>\n<p>Dibao Rosa được trang bị động cơ BLDC công suất 1000W, một mức công suất không quá lớn nhưng lại rất phù hợp với nhu cầu di chuyển trong đô thị.</p>\n<p>Động cơ không chổi than giúp xe vận hành êm ái, gần như không tạo ra tiếng ồn đáng kể. Khi vặn ga, xe tăng tốc mượt mà, không bị giật cục – điều mà nhiều người dùng mới sẽ đánh giá rất cao. Tốc độ tối đa khoảng 50 km/h đủ để di chuyển linh hoạt trong phố mà vẫn đảm bảo an toàn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-rosa-the-he-moi-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Xe được tích hợp 3 chế độ tốc độ khác nhau, cho phép người dùng tùy chỉnh theo điều kiện di chuyển. Khi đi trong khu đông người có thể sử dụng chế độ chậm để đảm bảo an toàn, khi di chuyển bình thường trong phố có thể chọn chế độ trung bình, và khi cần vượt xe hoặc đi đường thoáng có thể chuyển sang chế độ nhanh hơn.</p>\n<p>Khả năng vận hành ổn định, dễ kiểm soát chính là điểm mạnh giúp Rosa phù hợp với nhiều đối tượng, đặc biệt là học sinh và phái nữ.</p>\n<h2><strong>Quãng đường di chuyển: đáp ứng tốt nhu cầu hàng ngày</strong></h2>\n<p>Một trong những yếu tố quan trọng nhất khi chọn xe điện chính là khả năng di chuyển sau mỗi lần sạc. Dibao Rosa mang lại sự linh hoạt khá tốt ở điểm này.</p>\n<p>Phiên bản tiêu chuẩn sử dụng 5 bình ắc quy 60V – 20Ah, cho quãng đường khoảng 70–80 km sau mỗi lần sạc đầy. Con số này đủ để người dùng di chuyển trong 2–3 ngày mà không cần sạc lại, tùy theo nhu cầu sử dụng.</p>\n<p>Nếu cần quãng đường lớn hơn, người dùng có thể nâng cấp lên pin lithium 60V – 30Ah, giúp xe có thể đi được khoảng 120–130 km mỗi lần sạc. Đây là một lợi thế lớn đối với những người có nhu cầu di chuyển nhiều hoặc không muốn sạc xe thường xuyên.</p>\n<p>Thời gian sạc trung bình từ 8–10 tiếng và xe được trang bị tính năng tự ngắt khi đầy, giúp bảo vệ pin và tăng tuổi thọ sử dụng. Người dùng hoàn toàn có thể sạc qua đêm mà không cần lo lắng quá nhiều.</p>\n<h2><strong>Khả năng vận hành trong điều kiện thực tế tại Việt Nam</strong></h2>\n<p>Đường phố và thời tiết tại Việt Nam luôn là một “bài test” thực tế đối với mọi dòng xe. Dibao Rosa được trang bị đủ để đáp ứng những điều kiện này một cách ổn định.</p>\n<p>Xe đạt chuẩn chống nước IP67X, cho phép di chuyển qua những đoạn ngập nhẹ mà không ảnh hưởng đến hệ thống điện. Đây là một điểm cộng rất lớn trong điều kiện mưa nhiều tại các thành phố.</p>\n<p>Hệ thống giảm xóc thủy lực trước – sau giúp xe vận hành êm ái hơn khi đi qua ổ gà hoặc gờ giảm tốc. Lốp không săm tăng độ bám đường và giảm nguy cơ xịt lốp đột ngột, mang lại sự an toàn cao hơn.</p>\n<p>Hệ thống phanh đĩa trước kết hợp phanh cơ sau giúp người lái kiểm soát tốc độ tốt, đặc biệt trong các tình huống cần phanh gấp.</p>\n<h2><strong>Những tiện ích nhỏ nhưng tạo khác biệt lớn</strong></h2>\n<p><strong>Xe đạp điện</strong> Dibao Rosa không chỉ dừng lại ở việc đáp ứng nhu cầu di chuyển mà còn mang đến nhiều tiện ích giúp trải nghiệm hàng ngày trở nên dễ dàng hơn.</p>\n<p>Cốp xe dung tích khoảng 25 lít đủ để chứa mũ bảo hiểm, áo mưa hoặc túi xách. Ngoài ra, xe còn có hộc để đồ phía trước rất tiện lợi cho các vật dụng nhỏ.</p>\n<p>Hệ thống khóa smartkey kết hợp thẻ từ NFC giúp việc mở khóa và khởi động trở nên nhanh chóng, đồng thời tăng tính an toàn khi sử dụng. Đồng hồ điện tử hiển thị rõ ràng các thông số giúp người lái dễ dàng theo dõi tình trạng xe.</p>\n<p>Những chi tiết này tuy không quá nổi bật khi nhìn riêng lẻ, nhưng khi sử dụng lâu dài sẽ trở thành những yếu tố “khó thiếu”.</p>\n<h2><strong>Giá thành hợp lý – giá trị vượt mong đợi</strong></h2>\n<p>Một trong những lý do khiến <strong>Dibao</strong> Rosa được nhiều người lựa chọn chính là mức giá dễ tiếp cận. Chỉ với khoảng hơn 16 triệu đồng, người dùng đã có thể sở hữu một chiếc xe có thiết kế đẹp, động cơ ổn định, quãng đường tốt và nhiều tiện ích.</p>\n<p>So với những gì mà xe mang lại, đây là một mức giá khá hợp lý, đặc biệt phù hợp với học sinh, sinh viên hoặc những người cần một phương tiện tiết kiệm nhưng vẫn đảm bảo chất lượng.</p>\n<p>Dibao Rosa không phải là chiếc xe mạnh nhất trên thị trường, cũng không phải là mẫu xe đắt tiền nhất. Nhưng nó làm rất tốt một điều quan trọng: phù hợp với nhu cầu thực tế của người dùng.Thiết kế đủ đẹp để nổi bật, động cơ đủ mạnh để sử dụng thoải mái, quãng đường đủ dài để không phải lo lắng mỗi ngày và tiện ích đủ đầy để việc sử dụng trở nên dễ dàng hơn.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dibao-ryan', 'Xe Đạp Điện Dibao Ryan', 'dibao', '[\"xe-dap-dien\"]', 16200000, 16200000, '/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dibao-ryan-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dk-apollo-du-giay-to', 'Xe Đạp Điện DK Apollo Đủ Giấy Tờ', 'dk', '[\"xe-dap-dien\"]', 14500000, 14500000, '/sites/yenthoa/img/sp/xe-dap-dien-dk-apollo-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dk-apollo-du-giay-to-1.webp\"]', '[]', '[]', '[]', '<p>Thay vì đi theo phong cách nhỏ nhắn, hiền lành như đa số xe đạp điện truyền thống, Xe Đạp Điện DK Apollo mang dáng dấp của một chiếc mô tô điện thu nhỏ, khỏe khoắn, nam tính và đậm chất đường phố. Nhưng bên dưới vẻ ngoài cá tính ấy là một hệ thống vận hành được tối ưu cho nhu cầu sử dụng thực tế của học sinh, sinh viên và người đi làm trong đô thị.</p>\n<p>Ngay từ cái nhìn đầu tiên, Xe đạp điện DK Apollo đã tạo cảm giác khác biệt so với các mẫu xe đạp điện phổ thông. Tổng thể xe mang phong cách thể thao mạnh mẽ với những đường gân dập nổi, thân xe vuốt sắc và phần đầu cao ráo, hầm hố. Nếu đặt cạnh một chiếc xe đạp điện truyền thống, Apollo trông “trưởng thành” và dữ dằn hơn rõ rệt, gần với mô tô điện hơn là xe đạp điện học đường.</p>', '<p>Thay vì đi theo phong cách nhỏ nhắn, hiền lành như đa số xe đạp điện truyền thống, Xe Đạp Điện DK Apollo mang dáng dấp của một chiếc mô tô điện thu nhỏ, khỏe khoắn, nam tính và đậm chất đường phố. Nhưng bên dưới vẻ ngoài cá tính ấy là một hệ thống vận hành được tối ưu cho nhu cầu sử dụng thực tế của học sinh, sinh viên và người đi làm trong đô thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-apollo-du-giay-to-2.webp\" alt=\"Xe Đạp Điện DK Apollo Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<h2><strong>DK Apollo mang dáng dấp moto điện thu nhỏ</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, <strong>Xe đạp điện</strong> DK Apollo đã tạo cảm giác khác biệt so với các mẫu xe đạp điện phổ thông. Tổng thể xe mang phong cách thể thao mạnh mẽ với những đường gân dập nổi, thân xe vuốt sắc và phần đầu cao ráo, hầm hố. Nếu đặt cạnh một chiếc xe đạp điện truyền thống, Apollo trông “trưởng thành” và dữ dằn hơn rõ rệt, gần với mô tô điện hơn là xe đạp điện học đường.</p>\n<p>Phần đầu xe nổi bật với cụm đèn LED bi cầu đặt chính giữa, được bao bọc bởi mặt nạ hình khối góc cạnh. Ánh nhìn trực diện của xe mang vẻ lạnh lùng, mạnh mẽ, tạo ấn tượng thị giác ngay cả khi đứng yên. Đèn xi-nhan và đèn định vị được bố trí hài hòa hai bên, vừa đảm bảo tính thẩm mỹ vừa tăng khả năng nhận diện trên đường.</p>\n<p>Thân xe được thiết kế liền mạch, các đường bo không quá mềm mại mà thiên về cảm giác rắn rỏi. Sàn để chân rộng, phẳng và có vân chống trượt, phù hợp cho cả nam lẫn nữ. Tay lái cao và rộng tạo tư thế ngồi thoải mái, giúp người lái kiểm soát tốt hơn khi tăng tốc hoặc vào cua.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-apollo-du-giay-to-3.webp\" alt=\"Xe Đạp Điện DK Apollo Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<p>Khung xe của Apollo được làm từ thép chống gỉ cao cấp, có khả năng chịu tải lên đến khoảng 150 kg. Điều này không chỉ giúp xe bền bỉ trước va chạm mà còn đảm bảo sự ổn định khi chở hai người hoặc mang thêm đồ. Nhà sản xuất bảo hành khung lên đến 3 năm – một cam kết mạnh mẽ về chất lượng kết cấu.</p>\n<p>Dàn nhựa của xe sử dụng ABS dày khoảng 2.5 mm, có độ đàn hồi và khả năng chịu lực tốt. Khi sờ vào các tấm ốp, người dùng có thể cảm nhận rõ độ chắc chắn, không mỏng manh như nhiều mẫu xe giá rẻ khác. Các mối ghép được hoàn thiện khá khít, hạn chế rung lắc hay phát tiếng kêu khi chạy đường xấu.</p>\n<h2><strong>Điều gì gây ấn tượng với người dùng?</strong></h2>\n<p>Thiết kế có thể thu hút ánh nhìn, nhưng điều giữ chân người dùng lâu dài chính là khả năng vận hành. Xe Đạp Điện DK Apollo được trang bị động cơ BLDC không chổi than – loại động cơ nổi tiếng về hiệu suất cao, ít hao điện và tuổi thọ bền bỉ. Công suất danh định khoảng 800W, nhưng có thể đạt đỉnh tới 1.200W khi cần tăng tốc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-apollo-du-giay-to-4.webp\" alt=\"Xe Đạp Điện DK Apollo Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<p>Trong thực tế sử dụng, xe có khả năng bứt tốc rất ấn tượng. Chỉ mất khoảng 10 giây để tăng từ 0 lên 40 km/h – một con số đáng nể trong phân khúc xe đạp điện. Điều này giúp người lái dễ dàng vượt xe chậm, nhập làn nhanh hơn hoặc thoát khỏi tình huống giao thông phức tạp.</p>\n<p>Tốc độ tối đa của xe nằm ở khoảng 45–50 km/h (tùy điều kiện tải trọng và mặt đường), đủ nhanh để di chuyển linh hoạt trong đô thị nhưng vẫn trong ngưỡng an toàn cho người dùng trẻ. Cảm giác ga mượt, không giật cục, giúp việc điều khiển trở nên dễ chịu ngay cả với người mới sử dụng.</p>\n<p>Xe được trang bị 2 chế độ lái: Eco và Power. Ở chế độ Eco, xe tối ưu hóa mức tiêu thụ điện, tăng quãng đường di chuyển, phù hợp cho việc đi học, đi làm hàng ngày. Ở chế độ Power, động cơ phát huy tối đa sức mạnh, giúp tăng tốc nhanh và leo dốc tốt hơn – rất hữu ích khi di chuyển trên cầu, dốc cao hoặc chở hai người.</p>\n<p>Bộ ắc quy của <strong>DK Apollo</strong> gồm 4 bình 20Ah chính hãng, cho quãng đường di chuyển lên đến khoảng 80 km sau mỗi lần sạc đầy. Đây là mức rất ấn tượng, đủ để sử dụng cả tuần với nhu cầu đi lại trung bình. Thời gian sạc từ 6–7 giờ, thuận tiện để sạc qua đêm mà không ảnh hưởng đến sinh hoạt.</p>\n<h2><strong>Các chi tiết tuy nhỏ nhưng không thế thiếu</strong></h2>\n<p>Xe sử dụng phanh tang trống cả trước và sau, kết hợp má phanh carbon chất lượng cao. Cấu hình này mang lại lực phanh ổn định, không quá gắt, phù hợp với học sinh và người mới lái. Khi phanh khẩn cấp, xe vẫn giữ được sự cân bằng tốt, hạn chế hiện tượng trượt bánh.</p>\n<p>Hệ thống giảm xóc gồm phuộc dầu ống lồng phía trước và phuộc lò xo trụ phía sau. Sự kết hợp này giúp xe hấp thụ tốt các rung chấn từ mặt đường, giảm cảm giác xóc khi đi qua ổ gà, gờ giảm tốc hoặc đoạn đường kém bằng phẳng. Ngay cả khi chở hai người, xe vẫn giữ được độ êm ái tương đối.</p>\n<p>Lốp xe sử dụng loại không săm Kenda kích thước 300-10 với rãnh sâu, tăng độ bám đường và hạn chế trơn trượt khi trời mưa. Lốp không săm cũng giảm nguy cơ xì hơi đột ngột khi cán đinh – một yếu tố rất quan trọng trong điều kiện đường phố Việt Nam.</p>\n<p>Yên xe được thiết kế dài và rộng, đủ chỗ cho hai người ngồi thoải mái mà không bị chật chội. Bề mặt yên có độ đàn hồi tốt, không quá cứng, giúp giảm mệt mỏi khi di chuyển quãng đường dài.</p>\n<p>Sàn để chân rộng rãi không chỉ tạo tư thế lái thoải mái mà còn tiện lợi khi đặt túi xách, balo nhỏ hoặc đồ cá nhân. Xe còn trang bị gác chân hợp kim bản rộng cho người ngồi sau, tăng sự thoải mái và an toàn.</p>\n<h2><strong>Tiện ích thật cho người dùng thật</strong></h2>\n<p>DK Apollo không chỉ mạnh mẽ mà còn được trang bị nhiều công nghệ hiện đại, giúp việc sử dụng trở nên tiện lợi và an toàn hơn.</p>\n<p>Màn hình LCD điện tử hiển thị rõ ràng tốc độ, mức pin, quãng đường đã đi và các thông số cơ bản khác. Giao diện trực quan, dễ đọc ngay cả dưới ánh nắng mạnh, giúp người lái luôn nắm bắt tình trạng xe.</p>\n<p>Hệ thống đèn LED bi cầu cung cấp ánh sáng mạnh, chiếu xa và rộng, giúp người lái quan sát tốt hơn khi đi ban đêm. Ánh sáng trắng của LED cũng giúp xe nổi bật hơn trên đường, tăng độ an toàn khi di chuyển.</p>\n<p>Nút P Parking giúp ngắt ga khi dừng xe, tránh tình trạng vặn nhầm tay ga gây nguy hiểm – một tính năng nhỏ nhưng rất thực tế, nhất là với người mới lái.</p>\n<p>Xe còn có cốp dưới yên để đựng đồ cá nhân như áo mưa, găng tay hoặc dụng cụ sửa xe cơ bản. Móc treo kim loại chắc chắn phía trước giúp treo túi xách hoặc đồ nhẹ một cách tiện lợi.</p>\n<p>Về pháp lý, đây là điểm khiến nhiều phụ huynh và người dùng yên tâm. Xe Đạp Điện DK Apollo được phân phối với đầy đủ giấy tờ hợp lệ, có thể đăng ký biển số theo quy định hiện hành. Điều này giúp người dùng di chuyển tự tin trên mọi tuyến đường mà không lo bị xử phạt hành chính.</p>\n<p>Với mức giá khoảng 15 triệu đồng, Xe <strong>DK Bike</strong> Apollo được xem là lựa chọn hợp lý khi xét trên tổng thể: thiết kế đẹp, động cơ mạnh, công nghệ hiện đại, độ bền cao và giấy tờ minh bạch. Xe Đạp Điện DK Apollo không phải là mẫu xe dành cho những ai thích sự đơn giản, hiền lành. Đây là chiếc xe dành cho những người trẻ muốn thể hiện cá tính, yêu thích phong cách thể thao và cần một phương tiện đủ mạnh để đáp ứng nhịp sống năng động.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dk-lyva-cola-dung-4-ac-quy-24ah', 'Xe Đạp Điện DK Lyva Cola Dùng 4 Ắc Quy 24Ah', 'dk', '[\"xe-dap-dien\"]', 16250000, 16250000, '/sites/yenthoa/img/sp/xe-dap-dien-dk-lyva-cola-dung-4-ac-quy-24ah-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dk-lyva-cola-dung-4-ac-quy-24ah-1.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to', 'Xe Đạp Điện DK Samurai Pin Lithium Đầy Đủ Giấy Tờ', 'dk', '[\"xe-dap-dien\"]', 16290000, 16290000, '/sites/yenthoa/img/sp/xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to-1.webp\"]', '[]', '[]', '[]', '<p>Xe đạp điện DK Samurai Pin Lithium khẳng định vị thế là mẫu xe đô thị lý tưởng dành cho học sinh, sinh viên và người trẻ năng động. Sản phẩm gây ấn tượng nhờ sự kết hợp hài hòa giữa thiết kế nhỏ gọn, hiệu suất vận hành ổn định và công nghệ pin hiện đại.</p>\n<p>Không cồng kềnh hay nặng nề như nhiều mẫu xe điện truyền thống, DK Samurai hướng đến trải nghiệm di chuyển linh hoạt, giúp người dùng dễ dàng làm chủ mọi cung đường phố thị đông đúc. Mỗi hành trình đi học hay đi làm đều trở nên nhẹ nhàng, tiện lợi và mang đậm hơi thở hiện đại.</p>', '<p><strong>Xe đạp điện DK Samurai Pin Lithium</strong> khẳng định vị thế là mẫu xe đô thị lý tưởng dành cho học sinh, sinh viên và người trẻ năng động. Sản phẩm gây ấn tượng nhờ sự kết hợp hài hòa giữa thiết kế nhỏ gọn, hiệu suất vận hành ổn định và công nghệ pin hiện đại.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to-2.webp\" alt=\"Xe đạp điện DK Samurai Pin Lithium\" loading=\"lazy\"></p>\n<p><br>Không cồng kềnh hay nặng nề như nhiều mẫu xe điện truyền thống, DK Samurai hướng đến trải nghiệm di chuyển linh hoạt, giúp người dùng dễ dàng làm chủ mọi cung đường phố thị đông đúc. Mỗi hành trình đi học hay đi làm đều trở nên nhẹ nhàng, tiện lợi và mang đậm hơi thở hiện đại.</p>\n<h2><br><strong>Gọn nhẹ nhưng đầy cuốn hút giữa phố đông</strong></h2>\n<p><br><strong>DK Samurai</strong> sở hữu ngoại hình gọn gàng với kích thước tổng thể cân đối, cho phép xe dễ dàng di chuyển trong các con hẻm nhỏ hoặc khu vực thường xuyên ùn tắc vào giờ cao điểm. Chiều cao yên thấp tạo tư thế ngồi vững vàng, giúp người có vóc dáng nhỏ vẫn chống chân dễ dàng và tự tin điều khiển xe.</p>\n<p><br>Trọng lượng xe chỉ khoảng 25 kg, giúp việc dắt xe, quay đầu hay đưa xe lên xuống bậc thềm trở nên đơn giản hơn rất nhiều. Dù nhẹ nhưng khung sườn vẫn được gia công chắc chắn, mang lại cảm giác cứng cáp và an tâm khi sử dụng. Bảng màu đa dạng, từ trung tính đến nổi bật, giúp người dùng dễ dàng lựa chọn theo phong cách cá nhân.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to-3.webp\" alt=\"Xe đạp điện DK Samurai Pin Lithium\" loading=\"lazy\"></p>\n<p><br>Thiết kế tay lái, cụm đèn và thân xe được bố trí khoa học, tạo nên tổng thể hài hòa giữa nét cổ điển đặc trưng của dòng Samurai và phong cách công nghệ hiện đại. Bánh xe có kích thước vừa phải, đảm bảo sự cân đối về thẩm mỹ cũng như độ ổn định khi vận hành. DK Samurai không chỉ là phương tiện di chuyển mà còn là điểm nhấn thể hiện cá tính trẻ trung của người sở hữu.</p>\n<h2><br><strong>Sức mạnh đáng kinh ngạc sau thân hình nhỏ bé</strong></h2>\n<p><br><strong>DK Samurai</strong> được trang bị động cơ công suất 600W, đáp ứng tốt nhu cầu di chuyển hàng ngày trong thành phố. Xe vận hành ổn định trên đường bằng, dễ dàng vượt qua các đoạn dốc nhẹ mà không bị ì máy. Vận tốc tối đa đạt khoảng 45 km/h, đủ nhanh để di chuyển linh hoạt nhưng vẫn đảm bảo an toàn cho người sử dụng.</p>\n<p><br>Hệ thống vận hành tự động hoàn toàn giúp việc điều khiển xe trở nên đơn giản. Người dùng chỉ cần vặn ga và tập trung quan sát giao thông, không phải thao tác chuyển số phức tạp. Tay ga phản hồi nhạy, cho cảm giác tăng tốc êm ái, phù hợp với điều kiện giao thông đô thị đông đúc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-samurai-pin-lithium-day-du-giay-to-4.webp\" alt=\"Xe đạp điện DK Samurai Pin Lithium\" loading=\"lazy\"></p>\n<p><br>Một điểm nổi bật khác là khả năng chịu tải lên đến 220 kg. Dù có thân hình nhỏ gọn, <strong>xe đạp điện DK Samurai</strong> vẫn có thể chở hai người trưởng thành hoặc mang theo nhiều đồ dùng cần thiết mà không ảnh hưởng đến hiệu suất. Điều này cho thấy chất lượng khung sườn và động cơ được đầu tư kỹ lưỡng, mang lại sự bền bỉ và đáng tin cậy trong quá trình sử dụng lâu dài.</p>\n<h2><br><strong>Pin Lithium – Trái tim công nghệ của Samurai</strong></h2>\n<p><br>Phiên bản đánh dấu bước nâng cấp quan trọng khi DK Samurai sử dụng pin Lithium thay cho ắc quy chì truyền thống. Công nghệ pin Lithium giúp giảm trọng lượng xe, đồng thời cung cấp nguồn năng lượng ổn định và hiệu quả hơn. Với mỗi lần sạc đầy, xe có thể di chuyển quãng đường khoảng 40 đến 50 km, đáp ứng tốt nhu cầu đi học, đi làm trong vài ngày liên tục.</p>\n<p><br>Thời gian sạc được rút ngắn chỉ còn khoảng 4 đến 6 tiếng, rất thuận tiện cho người dùng sạc qua đêm hoặc trong thời gian nghỉ ngơi. Tính năng tự động ngắt khi pin đầy giúp hạn chế tình trạng quá tải, bảo vệ pin và đảm bảo an toàn trong quá trình sạc. Hệ thống bảo vệ dòng điện và chống tụt áp giúp xe luôn vận hành trong ngưỡng an toàn, hạn chế các sự cố về điện.</p>\n<p><br>Pin Lithium còn có tuổi thọ cao, ít chai pin và thân thiện hơn với môi trường. Việc sử dụng nguồn năng lượng sạch giúp người dùng tiết kiệm đáng kể chi phí vận hành so với xe máy chạy xăng, đồng thời góp phần giảm khí thải, hướng đến lối sống xanh và bền vững.</p>\n<h2><br><strong>Lái xe an tâm trong mọi tình huống thường ngày</strong></h2>\n<p><br><strong>DK Samurai</strong> được trang bị phanh đĩa cho bánh trước, mang lại lực phanh mạnh và chính xác. Người lái có thể xử lý tốt các tình huống khẩn cấp mà không lo bị trượt bánh. Kết hợp với lốp không săm có độ bám đường cao, xe vận hành ổn định ngay cả khi di chuyển trên đường ướt hoặc trơn trượt.</p>\n<p><br>Hệ thống giảm xóc giúp hạn chế rung lắc khi đi qua gờ giảm tốc hoặc đoạn đường gồ ghề, mang lại cảm giác êm ái và dễ chịu. Lốp không săm cũng giúp giảm nguy cơ xẹp lốp đột ngột, đảm bảo hành trình không bị gián đoạn.</p>\n<p><br>Ngoài ra, xe còn được trang bị khóa báo động chống trộm hiện đại. Khi có tác động bất thường, hệ thống sẽ phát tín hiệu cảnh báo, giúp người dùng yên tâm hơn khi để xe ở nơi công cộng. Bộ sạc chính hãng đi kèm đảm bảo độ tương thích và an toàn trong quá trình sử dụng.</p>\n<h2><br><strong>Những tiện nghi nhỏ tạo nên khác biệt lớn</strong></h2>\n<p><br>Bảng điều khiển của <strong>DK Samurai</strong> hiển thị rõ ràng các thông số cơ bản như tốc độ và dung lượng pin, giúp người lái dễ dàng theo dõi tình trạng xe. Sàn để chân rộng rãi cùng yên xe êm ái mang lại sự thoải mái, kể cả khi phải di chuyển trong thời gian dài.</p>\n<p><br>Xe có nhiều tùy chọn màu sắc thời trang, phù hợp với sở thích đa dạng của giới trẻ. Thiết kế sạc điện tiện lợi cho phép cắm trực tiếp vào nguồn điện gia đình mà không cần thiết bị chuyển đổi phức tạp.</p>\n<p><br>Với tải trọng lớn và trọng lượng bản thân nhẹ, DK Samurai có thể linh hoạt sử dụng cho nhiều mục đích khác nhau, từ đi học cá nhân đến chở đồ sinh hoạt hàng ngày. Từng chi tiết nhỏ đều được nghiên cứu kỹ lưỡng để phù hợp với thói quen sử dụng thực tế của người Việt.</p>\n<h2><br><strong>Chất lượng được bảo chứng từ thương hiệu Việt uy tín</strong></h2>\n<p><br><strong>DK Samurai</strong> là sản phẩm của DK Bike – thương hiệu xe điện uy tín tại Việt Nam. Quy trình sản xuất nghiêm ngặt cùng linh kiện chính hãng mang lại sự yên tâm về chất lượng và độ bền. Hệ thống điện được thiết kế ổn định, hạn chế các lỗi vặt thường gặp ở những dòng xe giá rẻ không rõ nguồn gốc.</p>\n<p><br>Sự kết hợp giữa khung sườn chắc chắn và pin Lithium hiện đại giúp xe duy trì hiệu suất ổn định trong thời gian dài. Đây không chỉ là phương tiện đi lại mà còn là khoản đầu tư xứng đáng cho cuộc sống tiện nghi và an toàn hơn.</p>\n<p><br><strong>Xe đạp điện DK Samurai</strong> là lựa chọn đáng cân nhắc cho những ai đang tìm kiếm một mẫu xe nhỏ gọn, mạnh mẽ và an toàn để di chuyển trong đô thị. Thiết kế tinh tế, động cơ bền bỉ, pin Lithium tiên tiến cùng hệ thống an toàn đầy đủ giúp sản phẩm đáp ứng trọn vẹn nhu cầu của người dùng trẻ hiện đại. DK Samurai là biểu tượng cho phong cách sống năng động, thông minh và thân thiện với môi trường.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dk-sparta-the-he-moi', 'Xe Đạp Điện DK Sparta Thế Hệ Mới', 'dk', '[\"xe-dap-dien\"]', 14500000, 14500000, '/sites/yenthoa/img/sp/xe-dap-dien-dk-sparta-the-he-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dk-sparta-the-he-moi-1.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dk-vc-s1-moi-nhat-2024', 'Xe Đạp Điện DK VC S1 Mới Nhất 2024', 'dk', '[\"xe-dap-dien\"]', 12990000, 12990000, '/sites/yenthoa/img/sp/xe-dap-dien-dk-vc-s1-moi-nhat-2024-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dk-vc-s1-moi-nhat-2024-1.webp\"]', '[]', '[]', '[]', '<p>DK VC S1 phiên bản mới xuất hiện như một tuyên ngôn về sự nâng cấp trong phân khúc xe đạp điện tầm trung, đáp ứng nhu cầu di chuyển tiện lợi và phong cách của người tiêu dùng hiện đại, đặc biệt là nhóm khách hàng trẻ. Mẫu xe này là sự hòa quyện giữa ngôn ngữ thiết kế năng động, trẻ trung và hiệu suất vận hành bền bỉ từ hệ thống truyền động điện tiên tiến. DK VC S1 nhanh chóng trở thành tâm điểm chú ý nhờ vào sự ổn định vượt trội cùng với các tính năng an toàn được tích hợp cẩn thận, mang đến trải nghiệm lái xe an toàn, thoải mái trên mọi hành trình.</p>\n<p>Phiên bản DK VC S1 thể hiện rõ ràng định hướng thiết kế thiên về sự mạnh mẽ và cá tính, với các chi tiết góc cạnh, dứt khoát, tạo nên sự khác biệt nổi bật so với các đối thủ cùng phân khúc. Phần đầu xe được vuốt nhọn, kết hợp với các mảng khối tinh tế, mang lại cái nhìn năng động, gợi cảm hứng về một phương tiện di chuyển hiện đại, đậm chất thể thao. Khung sườn thép cao cấp được sơn tĩnh điện bền màu, đảm bảo khả năng chống gỉ sét và duy trì vẻ ngoài như mới qua thời gian dài sử dụng.</p>', '<p><strong>DK VC S1</strong> phiên bản mới xuất hiện như một tuyên ngôn về sự nâng cấp trong phân khúc xe đạp điện tầm trung, đáp ứng nhu cầu di chuyển tiện lợi và phong cách của người tiêu dùng hiện đại, đặc biệt là nhóm khách hàng trẻ. Mẫu xe này là sự hòa quyện giữa ngôn ngữ thiết kế năng động, trẻ trung và hiệu suất vận hành bền bỉ từ hệ thống truyền động điện tiên tiến. DK VC S1 nhanh chóng trở thành tâm điểm chú ý nhờ vào sự ổn định vượt trội cùng với các tính năng an toàn được tích hợp cẩn thận, mang đến trải nghiệm lái xe an toàn, thoải mái trên mọi hành trình.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-vc-s1-moi-nhat-2024-2.webp\" alt=\"Xe Đạp Điện DK VC S1 Mới Nhất 2024\" loading=\"lazy\"></p>\n<h2><br><strong>Diện mạo thể thao, cá tính</strong></h2>\n<p><br>Phiên bản <strong>DK VC S1</strong> thể hiện rõ ràng định hướng thiết kế thiên về sự mạnh mẽ và cá tính, với các chi tiết góc cạnh, dứt khoát, tạo nên sự khác biệt nổi bật so với các đối thủ cùng phân khúc. Phần đầu xe được vuốt nhọn, kết hợp với các mảng khối tinh tế, mang lại cái nhìn năng động, gợi cảm hứng về một phương tiện di chuyển hiện đại, đậm chất thể thao. Khung sườn thép cao cấp được sơn tĩnh điện bền màu, đảm bảo khả năng chống gỉ sét và duy trì vẻ ngoài như mới qua thời gian dài sử dụng.</p>\n<p><br>Cụm đèn chiếu sáng sử dụng công nghệ LED toàn bộ, được thiết kế theo dạng Multi-LED, tạo ra chùm sáng rõ ràng, cường độ cao và tập trung. Thiết kế đèn này vừa tăng tính thẩm mỹ cho tổng thể xe, vừa đóng vai trò quan trọng trong việc cải thiện tầm nhìn cho người lái khi đi vào điều kiện thiếu sáng. Vị trí đèn xi-nhan và đèn định vị được tối ưu, tăng cường khả năng nhận diện phương tiện từ xa, góp phần nâng cao tính an toàn khi tham gia giao thông.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-vc-s1-moi-nhat-2024-3.webp\" alt=\"Xe Đạp Điện DK VC S1 Mới Nhất 2024\" loading=\"lazy\"></p>\n<p><br>Kích thước tổng thể của <strong>VC S1</strong> được tối ưu hóa nhằm mang lại sự ổn định cần thiết, đồng thời đảm bảo khả năng xoay trở linh hoạt trong các không gian hẹp. Yên xe được bọc da cao cấp, thiết kế liền khối, mang lại sự thoải mái tối đa. Chiều cao xe vừa phải, phù hợp với đại đa số người dùng Việt Nam, giúp việc điều khiển xe trở nên dễ dàng.</p>\n<h2><br><strong>Động cơ điện hiệu suất cao</strong></h2>\n<p><br>Sức mạnh cốt lõi của <strong>DK VC S1</strong> đến từ khối động cơ điện thế hệ mới, được DK Bike tinh chỉnh để đạt hiệu suất hoạt động tối ưu nhất, cung cấp công suất ổn định và mạnh mẽ. Động cơ này được lắp đặt ở vị trí trung tâm, giúp phân bổ trọng lượng xe cân đối hơn, cải thiện đáng kể khả năng cân bằng và độ bám đường khi vào cua hoặc di chuyển ở tốc độ cao.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-dk-vc-s1-moi-nhat-2024-4.webp\" alt=\"Xe Đạp Điện DK VC S1 Mới Nhất 2024\" loading=\"lazy\"></p>\n<p><br>Hệ thống truyền động điện hoạt động êm ái, gần như không phát ra tiếng ồn trong quá trình vận hành, tạo ra một trải nghiệm lái xe yên tĩnh và thư thái. Công nghệ kiểm soát nhiệt độ tiên tiến được tích hợp giúp động cơ duy trì trạng thái hoạt động mát mẻ, ngay cả trong những chuyến đi kéo dài hoặc khi xe phải tải trọng nặng.</p>\n<p><br>Khả năng tăng tốc của <strong>VC S1</strong> được đánh giá là mượt mà và dứt khoát, cho phép người lái dễ dàng vượt qua các chướng ngại vật hoặc tăng tốc khi cần thiết. Vận tốc tối đa của xe được kiểm soát nghiêm ngặt theo tiêu chuẩn an toàn cho xe đạp điện, đảm bảo tuân thủ đầy đủ các quy định hiện hành về giao thông đường bộ.</p>\n<h2><br><strong>Năng lượng bền bỉ, hiện đại</strong></h2>\n<p><br><strong>VC S1</strong> sử dụng bộ ắc quy chì axit cao cấp, được sản xuất với công nghệ tiên tiến, mang lại khả năng tích trữ điện năng vượt trội và độ bền cao theo thời gian. Bộ ắc quy này được tối ưu hóa để cung cấp nguồn điện ổn định cho động cơ, duy trì hiệu suất vận hành cao nhất trong suốt hành trình.</p>\n<p><br>Quãng đường di chuyển mà xe có thể đạt được sau mỗi lần sạc đầy rất ấn tượng, đáp ứng hoàn hảo nhu cầu đi học, đi làm hàng ngày mà không cần lo lắng về việc phải sạc pin thường xuyên. Sự bền bỉ về năng lượng này giúp người dùng hoàn toàn chủ động trong lịch trình di chuyển của mình, nâng cao tính tiện lợi.</p>\n<p><br>Hệ thống sạc điện thông minh đi kèm có tính năng tự động ngắt kết nối khi ắc quy đã đạt mức năng lượng tối đa, giúp bảo vệ ắc quy khỏi các hư hỏng do sạc quá mức. Tính năng này đóng vai trò quan trọng trong việc kéo dài tuổi thọ của bộ pin, đồng thời đảm bảo an toàn tuyệt đối cho người sử dụng trong quá trình sạc điện.</p>\n<h2><br><strong>Hệ thống phanh cơ, giảm xóc</strong></h2>\n<p><br><strong>DK VC S1</strong> được trang bị hệ thống phanh cơ cho cả bánh trước và bánh sau, một cấu hình phanh đã được chứng minh về độ tin cậy, dễ bảo trì và có chi phí thay thế thấp. Phanh cơ được thiết kế để cung cấp lực hãm vừa phải, phù hợp với tốc độ và trọng lượng của xe đạp điện, đảm bảo khả năng dừng <strong>xe đạp điện</strong> an toàn.</p>\n<p><br>Mặc dù sử dụng phanh cơ, nhưng chất lượng vật liệu và sự tinh chỉnh của DK Bike đảm bảo hiệu quả phanh ổn định trên nhiều loại bề mặt đường khác nhau. Người lái có thể dễ dàng kiểm soát tốc độ và dừng xe một cách êm ái, đặc biệt quan trọng khi di chuyển trong khu vực có mật độ giao thông cao.</p>\n<p><br>Hệ thống giảm xóc của <strong>VC S1</strong> bao gồm phuộc trước ống lồng và giảm chấn lò xo trụ ở phía sau, được thiết kế để hấp thụ tối đa các xung động. Sự kết hợp này mang lại trải nghiệm lái xe vô cùng êm ái, giảm thiểu cảm giác xóc nảy khi đi qua các đoạn đường xấu, cải thiện sự thoải mái cho người lái và người ngồi sau.</p>\n<h2><br><strong>Tiện ích thông minh, hiện đại</strong></h2>\n<p><br>Mặt đồng hồ hiển thị của <strong>VC S1</strong> là một điểm nhấn công nghệ, sử dụng màn hình điện tử LCD sắc nét, hiển thị đầy đủ các thông số vận hành một cách trực quan. Thông tin về vận tốc, mức năng lượng pin còn lại, và chế độ lái được cập nhật liên tục, giúp người điều khiển dễ dàng theo dõi tình trạng xe.</p>\n<p><br>Một tiện ích nổi bật khác là không gian chứa đồ được bố trí khéo léo, bao gồm hộc đựng đồ nhỏ gọn phía trước và cốp dưới yên xe với dung tích vừa phải. Không gian này đủ để cất giữ các vật dụng cá nhân cần thiết như áo mưa, ví tiền hoặc sách vở, nâng cao tính thực dụng trong sử dụng hàng ngày.</p>\n<p><br>Xe còn được tích hợp hệ thống khóa chống trộm điện tử hiện đại, cho phép người dùng khóa và mở khóa xe từ xa. Tính năng này cung cấp một lớp bảo vệ tăng cường cho phương tiện, mang lại sự an tâm tuyệt đối cho chủ sở hữu khi phải đậu xe ở nơi công cộng.</p>\n<h2><br><strong>Cam kết từ DK Bike</strong></h2>\n<p><br><strong>Xe đạp điện DK Bike</strong> là một thương hiệu đã khẳng định được uy tín vững chắc trong phân khúc phương tiện di chuyển bằng điện tại Việt Nam, với các sản phẩm được đánh giá cao về độ bền và chất lượng lắp ráp. VC S1 là một minh chứng rõ ràng cho sự cam kết nghiêm túc của hãng đối với người tiêu dùng.</p>\n<p><br>Chính sách bảo hành của <strong>DK Bike</strong> cho mẫu <strong>VC S1</strong> rất rõ ràng và hào phóng, với thời gian bảo hành khung xe lên đến 3 năm và chính sách bảo hành dài hạn cho động cơ và ắc quy. Điều này thể hiện sự tin tưởng tuyệt đối của nhà sản xuất vào chất lượng linh kiện và quy trình lắp ráp sản phẩm của mình.</p>\n<p><br>Hệ thống đại lý và trung tâm dịch vụ của DK Bike được phân bố rộng khắp trên toàn quốc, đảm bảo người dùng luôn dễ dàng tiếp cận các dịch vụ bảo dưỡng, sửa chữa và thay thế phụ tùng chính hãng. Sự hỗ trợ hậu mãi toàn diện này giúp người sở hữu VC S1 hoàn toàn yên tâm trong suốt vòng đời sử dụng của xe.</p>\n<p><br>DK VC S1 là sự kết hợp hài hòa giữa diện mạo thể thao, hiệu suất vận hành ổn định và các tính năng an toàn, tiện ích vượt trội, đáp ứng tối đa nhu cầu di chuyển trong đô thị của giới trẻ. Mẫu xe này không chỉ là phương tiện đi lại mà còn là một lựa chọn thông minh, tiết kiệm và đáng tin cậy, khẳng định vị thế dẫn đầu trong phân khúc xe đạp điện hiện nay.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-dylexe-vc-k1-day-du-giay-to', 'Xe Đạp Điện Dylexe VC K1 Đầy Đủ Giấy Tờ', 'khac', '[\"xe-dap-dien\"]', 12600000, 12600000, '/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-dylexe-vc-k1-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-gap-lihaze-pin-lithium', 'Xe Đạp Điện Gấp Lihaze Pin Lithium', 'khac', '[\"xe-dap-dien\"]', 8900000, 8900000, '/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-6.webp\"]', '[]', '[]', '[]', '<p>Xe đạp điện gấp Lihaze với trang bị Pin Lithium đang tạo ra một giải pháp giao thông cá nhân hiệu quả và gọn gàng, đặc biệt phù hợp cho những ai tìm kiếm sự tiện lợi khi di chuyển và tối ưu không gian cất giữ. Mẫu xe nhập khẩu này là một phương tiện giao thông cá nhân hiệu quả, đại diện cho xu hướng sống năng động. Chiếc xe dễ dàng mang theo và sẵn sàng đồng hành trên mọi hành trình từ ngắn đến trung bình, với lời cam kết về độ bền và hiệu suất vận hành ổn định.</p>\n<p>Kết cấu của xe điện Lihaze Pin Lithium được chế tạo để đảm bảo cả tính ổn định và khả năng gấp gọn tối ưu. Với kích thước tổng thể 1400mm x 700mm x 1050mm, chiếc xe giữ được sự cân đối cần thiết khi di chuyển, đồng thời nhanh chóng thu gọn lại khi cần lưu trữ hoặc vận chuyển. Khung xe được nhà sản xuất cam kết bảo hành lên đến 3 năm, cho thấy sự tự tin vào chất lượng vật liệu và quy trình lắp ráp.</p>', '<p><strong>Xe đạp điện gấp Lihaze</strong> với trang bị Pin Lithium đang tạo ra một giải pháp giao thông cá nhân hiệu quả và gọn gàng, đặc biệt phù hợp cho những ai tìm kiếm sự tiện lợi khi di chuyển và tối ưu không gian cất giữ. Mẫu xe nhập khẩu này là một phương tiện giao thông cá nhân hiệu quả, đại diện cho xu hướng sống năng động. Chiếc xe dễ dàng mang theo và sẵn sàng đồng hành trên mọi hành trình từ ngắn đến trung bình, với lời cam kết về độ bền và hiệu suất vận hành ổn định.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-7.webp\" alt=\"Xe Đạp Điện Gấp Lihaze Pin Lithium\" loading=\"lazy\"></p>\n<h2><br><strong>Bộ khung vững chắc, thiết kế độc đáo</strong></h2>\n<p><br>Kết cấu của <strong>xe điện&nbsp;Lihaze </strong><strong>Pin Lithium</strong>&nbsp;được chế tạo để đảm bảo cả tính ổn định và khả năng gấp gọn tối ưu. Với kích thước tổng thể 1400mm x 700mm x 1050mm, chiếc xe giữ được sự cân đối cần thiết khi di chuyển, đồng thời nhanh chóng thu gọn lại khi cần lưu trữ hoặc vận chuyển. Khung xe được nhà sản xuất cam kết bảo hành lên đến 3 năm, cho thấy sự tự tin vào chất lượng vật liệu và quy trình lắp ráp.</p>\n<p><br>Trọng lượng tổng thể của xe là 35kg, một con số khá hợp lý đối với một mẫu xe điện trang bị động cơ và pin. Điều này giúp xe không quá nặng nề khi cần dắt bộ hoặc di chuyển thủ công trong phạm vi hẹp, đồng thời vẫn giữ được độ đầm khi chạy ở tốc độ cao. Khoảng sáng gầm xe 100mm đảm bảo xe vượt qua các chướng ngại vật nhỏ và các đoạn đường xấu nhẹ một cách dễ dàng, giảm thiểu nguy cơ va chạm gầm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-8.webp\" alt=\"Xe Đạp Điện Gấp Lihaze Pin Lithium\" loading=\"lazy\"></p>\n<p><br>Thiết kế ngoại hình của Lihaze mang phong cách tối giản và hiện đại. Chiều cao yên xe là 680mm, phù hợp với vóc dáng của nhiều người dùng Việt Nam, tạo tư thế ngồi thoải mái, kiểm soát tốt. Xe có sẵn trong nhiều lựa chọn màu sắc khác nhau, cho phép người dùng cá nhân hóa phương tiện theo sở thích riêng biệt, tăng tính thẩm mỹ và thu hút ánh nhìn.</p>\n<h2><br><strong>Động cơ 400W – Hiệu suất thầm lặng</strong></h2>\n<p><br>Trái tim của chiếc <strong>xe Lihaze</strong> là động cơ điện 400W loại không chổi than. Đây là loại động cơ được đánh giá cao về hiệu quả năng lượng, khả năng vận hành êm ái và độ bền vượt trội. Công suất 400W đủ mạnh để đáp ứng nhu cầu di chuyển hàng ngày, giúp xe dễ dàng tăng tốc và duy trì vận tốc ổn định.</p>\n<p><br>Động cơ này cho phép xe đạt tốc độ tối đa từ 40 đến 50km/h, một giới hạn vận tốc lý tưởng cho việc lưu thông trong nội thành hoặc các khu vực đông dân cư. Khả năng đạt được dải tốc độ này không đòi hỏi người điều khiển phải thao tác phức tạp, bởi xe được thiết kế để vận hành hoàn toàn tự động, mang lại trải nghiệm lái xe đơn giản và thân thiện.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-gap-lihaze-pin-lithium-9.webp\" alt=\"Xe Đạp Điện Gấp Lihaze Pin Lithium\" loading=\"lazy\"></p>\n<p><br>Hãng xe cung cấp chế độ bảo hành 2 năm cho động cơ, đây là một yếu tố quan trọng khẳng định chất lượng và độ tin cậy của bộ phận truyền động. Sự vận hành \"thầm lặng\" của động cơ không chổi than còn góp phần tạo nên một hành trình di chuyển thư thái, không gây ra tiếng ồn khó chịu, đồng thời giảm thiểu tối đa nhu cầu bảo trì bảo dưỡng định kỳ.</p>\n<h2><br><strong>Công nghệ Pin Lithium, quãng đường chinh phục</strong></h2>\n<p><br><strong>Xe điện</strong> Lihaze sử dụng Pin Lithium 48V-15A, loại pin tiên tiến sở hữu mật độ năng lượng cao và tuổi thọ kéo dài hơn so với các loại ắc quy truyền thống. Việc chuyển sang dùng Pin Lithium là một bước nâng cấp đáng giá, giúp giảm trọng lượng tổng thể của xe và cải thiện hiệu suất sạc/xả, đem lại sự an tâm cho người sử dụng.</p>\n<p><br>Với một lần sạc đầy, chiếc xe có khả năng chinh phục quãng đường di chuyển lên đến 50km. Đây là một phạm vi lý tưởng cho các chuyến đi lại hàng ngày như từ nhà đến cơ quan, trường học hoặc đi chợ. Mức di chuyển này giúp người dùng yên tâm sử dụng xe trong vài ngày mà không cần lo lắng về việc sạc lại liên tục.</p>\n<p><br>Quá trình sạc pin diễn ra nhanh chóng, chỉ mất khoảng 4 đến 5 tiếng để nạp đầy năng lượng. Bộ sạc đi kèm còn có tính năng tự động ngắt khi pin đã đầy, bảo vệ pin khỏi tình trạng sạc quá mức, từ đó kéo dài tuổi thọ của pin. Chính sách bảo hành 1 năm cho pin Lithium là cam kết cần thiết để người dùng tin tưởng vào chất lượng lâu dài của bộ phận quan trọng này.</p>\n<h2><br><strong>Trải nghiệm an toàn với hệ thống phanh và lốp</strong></h2>\n<p><br><strong>Lihaze</strong> chú trọng đến yếu tố an toàn bằng việc trang bị hệ thống phanh đĩa cho bánh trước. Phanh đĩa cung cấp lực hãm lớn hơn và phản ứng nhanh nhạy, đặc biệt hiệu quả trong các tình huống cần giảm tốc độ gấp hoặc khi di chuyển dưới điều kiện thời tiết không thuận lợi như mưa ướt. Sự kết hợp này mang lại cảm giác kiểm soát lái chắc chắn cho người điều khiển.</p>\n<p><br>Về lốp và vành, xe sử dụng lốp KENDA 2.75-14 loại không săm. Lốp không săm là một trang bị thiết thực, giúp người lái an tâm hơn khi xe vô tình cán phải vật nhọn, vì lốp sẽ xì hơi từ từ chứ không nổ đột ngột. Kích thước vành đúc 14 inch (314mm) và đường kính lốp 426mm tạo sự cân bằng giữa khả năng bám đường và sự linh hoạt cần có của một chiếc xe gấp.</p>\n<p><br>Hệ thống giảm xóc thủy lực được tích hợp nhằm tối ưu hóa sự êm ái khi di chuyển. Bộ giảm chấn này có nhiệm vụ hấp thụ xung lực từ mặt đường, đặc biệt quan trọng khi xe vận hành trên các đoạn đường gồ ghề, giúp người lái và hành khách luôn cảm thấy thoải mái, giảm thiểu tối đa rung động truyền lên khung xe.</p>\n<h2><br><strong>Tiện ích, khả năng chịu tải ấn tượng</strong></h2>\n<p><br>Khả năng gấp gọn là tính năng chủ đạo và mang lại giá trị sử dụng cao nhất của chiếc<strong> Lihaze</strong>. Thiết kế này giải quyết bài toán không gian cho người sống trong căn hộ nhỏ hoặc những ai thường xuyên phải kết hợp nhiều phương thức di chuyển (như mang xe lên xe buýt, tàu điện ngầm hoặc cất trong cốp ô tô). Việc gấp mở xe được thực hiện nhanh chóng, chỉ qua vài thao tác đơn giản.</p>\n<p><br>Mặc dù có thiết kế gọn gàng, Lihaze lại sở hữu khả năng chịu tải ấn tượng, lên đến 160kg. Mức tải trọng này cao hơn đáng kể so với nhiều mẫu xe điện hoặc xe đạp điện thông thường, cho phép xe chở được hai người trưởng thành hoặc mang theo nhiều đồ đạc cá nhân, đáp ứng tốt nhu cầu của các gia đình nhỏ hoặc người cần chở hàng hóa nhẹ.</p>\n<p><br>Việc vận hành \"tự động hoàn toàn\" loại bỏ mọi phức tạp trong quá trình lái xe. Người dùng chỉ cần vặn ga và di chuyển mà không cần lo lắng về việc chuyển số hay các thao tác kỹ thuật rườm rà. Tính năng sạc tự động ngắt khi pin đầy cũng là một tiện ích nhỏ nhưng quan trọng, giúp người dùng không cần phải canh thời gian rút sạc.</p>\n<h2><br><strong>Cam kết độ bền với hậu mãi tốt</strong></h2>\n<p><br><strong>Lihaze</strong> là sản phẩm nhập khẩu, và việc nhà phân phối đưa ra các chính sách bảo hành rõ ràng là một điểm cộng lớn giúp người tiêu dùng an tâm. Thời gian bảo hành được phân loại cụ thể cho từng bộ phận chính, thể hiện sự minh bạch về chất lượng của từng cấu kiện.</p>\n<p><br>Khung xe được hưởng chế độ bảo hành dài nhất, lên đến 3 năm. Điều này củng cố niềm tin về độ cứng cáp và tính bền vững của bộ khung chịu lực, nơi mọi chi tiết khác của xe được lắp ráp. Đây là cam kết thiết thực nhất về khả năng chống chịu và tuổi thọ vật lý của chiếc xe.</p>\n<p><br>Các bộ phận điện tử quan trọng như động cơ và pin cũng được đảm bảo bằng thời gian bảo hành cụ thể. Động cơ được bảo hành 2 năm, trong khi pin Lithium có thời hạn bảo hành 1 năm. Sự cam kết này giúp người dùng an tâm về chi phí sửa chữa hoặc thay thế trong giai đoạn đầu sử dụng, giảm thiểu rủi ro khi đầu tư vào một phương tiện giao thông mới.</p>\n<p><br><strong>Xe Điện Gấp Lihaze Pin Lithium</strong> là một sự lựa chọn thông minh cho di chuyển đô thị, dung hòa giữa tính tiện dụng và hiệu năng ổn định. Với quãng đường 50km, tốc độ 40-50km/h và khả năng gấp gọn, nó hoàn thành xuất sắc vai trò phương tiện cá nhân linh hoạt. Khả năng chịu tải 160kg kết hợp với công nghệ Pin Lithium hiện đại thực sự nâng cao giá trị sử dụng của sản phẩm.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-gap-miyijia', 'Xe Đạp Điện Gấp MiYiJiA', 'khac', '[\"xe-dap-dien\"]', 9300000, 9300000, '/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-gap-miyijia-6.webp\"]', '[]', '[]', '[]', '<p>Xe đạp điện gấp là một mẫu xe khá là HOT trong thời gian gần đây không chỉ kiểu dáng nhỏ gọn, phong cách thể thao mà nó còn có khả năng gấp gọn tiện lợi có thể mang lên chung cư hay bỏ cốp xe đi du lịch chẳng hạn. Hôm nay mình sẽ giới thiệu đến các bạn một siêu phẩm xe điện gấp với kiểu dáng đẳng cấp sang trọng vươn tầm cao mới đó chính là chiếc xe đạp điện gấp Miyijia. Hãy cùng mình tìm hiểu qua các điểm nổi bật của dòng xe này nhé!</p>\n<p>Xe đạp điện gấp Miyijia thiết kế phá vỡ mọi quy cách truyền thống. Xe được cấu tạo bởi bộ khung làm từ cacbon cao cấp có độ bền bỉ cao đặc biệt phủ lên dàn khung cacbon này là lớp sơn tĩnh điện cao cấp không chỉ giúp xe trở nên bắt mắt thu hút ánh nhìn mà còn đảm bảo xe luôn giữ được tính thẩm mỹ theo thời gian nữa.</p>', '<p><strong><em>Xe đạp điện gấp là một mẫu xe khá là HOT trong thời gian gần đây không chỉ kiểu dáng nhỏ gọn, phong cách thể thao mà nó còn có khả năng gấp gọn tiện lợi có thể mang lên chung cư hay bỏ cốp xe đi du lịch chẳng hạn. Hôm nay mình sẽ giới thiệu đến các bạn một siêu phẩm&nbsp;xe điện gấp&nbsp;với kiểu dáng đẳng cấp sang trọng vươn tầm cao mới đó chính là chiếc xe đạp điện gấp Miyijia. Hãy cùng mình tìm hiểu qua các điểm nổi bật của dòng xe này nhé!</em></strong></p>\n<h2><strong>THIẾT KẾ ĐẲNG CẤP TẠO NÊN SỰ KHÁC BIỆT TRONG NGÀNH XE ĐIỆN</strong></h2>\n<p>Xe đạp điện gấp Miyijia thiết kế phá vỡ mọi quy cách truyền thống. Xe được cấu tạo bởi bộ khung làm từ cacbon cao cấp có độ bền bỉ cao đặc biệt phủ lên dàn khung cacbon này là lớp sơn tĩnh điện cao cấp không chỉ giúp xe trở nên bắt mắt thu hút ánh nhìn mà còn đảm bảo xe luôn giữ được tính thẩm mỹ theo thời gian nữa.</p>\n<p>Cũng nhờ bộ khung được làm từ Cacbon cao cấp nên tổng trọng lượng của xe khá là nhẹ chỉ tầm khoảng 20kg mà thôi nếu tính thêm Pin lithium vào nữa thì tầm khoảng 23kg. Việc xách vác xe cũng trở nên đơn giản hơn rất nhiều người trưởng thành hoàn toàn có thể nâng chiếc xe này bằng 1 tay rất thoải mái.</p>\n<h2><strong>KHẢ NĂNG GẤP GỌN ẤN TƯỢNG</strong></h2>\n<p>Xe điện gấp Miyijia có thể gấp đôi lại rất dễ dàng tay lái cũng có thể gập xuống được nên diện tích để xe chiếm vị trí khá là nhỏ, thậm chí bạn hoàn toàn có thể bỏ nó sau cốp chiếc xe oto trong mỗi chuyến du lịch cũng rất tiện nữa đó.</p>\n<p>Các khớp nối mở khoá, đóng khoá được làm cực kỳ tỷ mỉ có độ chính xác cao đảm bảo sự chắc chắn mỗi lần đóng gập xe, hạn chế tình trạng bị lỏng khớp nối trong quá trình sử dụng lâu dài. Việc đóng gập xe điện gấp Miyijia khá là đơn giản không tốn quá nhiều sức lực các bạn trẻ, các bạn học sinh cũng hoàn toàn có thể mở và gấp chiếc xe này dễ dàng, chỉ cần mở đúng khớp là được.</p>\n<h2><strong>CÁC TIỆN ÍCH TRÊN CHIẾC XE ĐẠP ĐIỆN GẤP MIYIJIA</strong></h2>\n<p>Xe hiện đang trang bị 2 yên cả hai đều được bộc đệm cao su cao cấp cho cảm giác ngồi thoải mái. Yên trước có thể điều chỉnh độ cao phù hợp với người lái rất đơn giản. Còn yên sau thiết kế hơi thấp nếu sử dụng thì chắc cho các em nhỏ ngồi sau là thích hợp nhất còn với người trưởng thành ngồi khá là khó và mỏi chân đó nhé.</p>\n<p>Đây là chiếc xe đạp điện gấp rất phù hợp dành cho các bậc cha mẹ hay chở con cái đi dạo loanh quanh trong công viên, đi dạo phố.</p>\n<p>Bạn để ý ở dưới yên trước có một thanh hợp kim nhôm cacbon nhô ra khá dài thì đây chính là tâm điểm để bạn cầm và nhấc chiếc xe đạp điện gấp Miyijia này. Kể cả bạn gấp gọn hay để xe mở ra thì nó vẫn là trọng tâm cho bạn cầm và nhấc xe.</p>\n<p>Dường như hãng Miyijia này rất để ý đến trả nghiệm người dùng khi mà trang bị cho xe rất nhiều công năng nổi bật hỗ trợ tốt trong quá trình di chuyển chẳng hạn như ở phần suờn xe có trang bị chỗ để chai nước tiện lợi vì không có giỏ xe hay cốp xe nên việc trang bị miếng ốp để bỏ chai nước là điều rất hay. Còn trên phần tay lái hãng có trang bị một giá để điện thoại tiện lợi tích hợp thêm một giắc cắm sạc tiện lợi bạn có thể vừa chạy xe vừa sạc cho chiếc dế yêu của mình. Nhất là mỗi chuyến đi du lịch đường xá không rành thì việc để chiếc điện thoại trên tay lái vừa tham quan vừa có thể nhìn được bản đồ thì còn gì tuyệt vời hơn nữa. Thay vì nếu không có giá đỡ thì mỗi lần di chuyển bạn sẽ phải dừng lại lấy điện thoại ra xem coi đi đúng chưa như thế sẽ ảnh hưởng khá nhiều với trải nghiệm du lịch phải không nào.</p>\n<p>Hệ thống đèn có đầy đủ trên chiếc xe điện gấp Miyijia nhỏ gọn này, đèn pha trước thiết kế dạng bóng bi cầu led cho ánh sáng trắng đảm bảo đủ sáng khi đi vào buổi tối, phần đuôi xe có hệ thống đèn hậu xi nhan trái phải đầy đủ hỗ trợ tối đa cho bạn khi tham gia giao thông, đảm bảo an toàn trên từng chặng đường.</p>\n<h2><strong>KHẢ NĂNG VẬN HÀNH TRÊN XE ĐẠP ĐIỆN MIYIJIA </strong></h2>\n<p>Về khả năng vận hành thì khá là tốt với một chiếc xe điện gấp nhỏ gọn như này bạn không thể đòi hỏi quá nhiều về vận tốc cũng như quãng đường di chuyển của xe. Xe trang bị động cơ 350W cho phép xe chạy với tốc độ 35-40km/h, sử dụng Pin Lithium đời mới với khả năng trữ điện tốt cũng như độ bền cao mỗi lần sạc bạn có thể đi 40-45 cây số. Xe có trang bị chế độ điều tốc nên bạn có thể tuỳ chỉnh tốc độ phù hợp với từng địa hình nhé.</p>\n<p>Xe còn trang bị bộ bàn đạp trợ lực cao cấp giúp người lái có thể sử dụng mỗi lần xe hết điện, yếu bình, đạp xe rất nhẹ nhàng không tốn nhiều sức lực.</p>\n<p>Bánh xe thiết kế có kích thước 8 inch khá là nhỏ, vành xe được đúc nguyên khối cao cấp, có 3 màu sắc pha trộn vào nhau: đen - đỏ - trắng rất tinh tế tạo tính thẩm mỹ cho xe. Dòng&nbsp;xe điện gấp Miyijia&nbsp;này trang bị hệ thống phanh đĩa cả trước và sau an toàn đảm bảo người lái có thể làm chủ tốc độ của xe, khả năng phanh nhạy hoạt động tốt trong mọi điều kiện thời tiết.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-honda-model-m8', 'Xe Đạp Điện Honda Model M8', 'honda', '[\"xe-dap-dien\"]', 14300000, 14300000, '/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-honda-model-m8-6.webp\"]', '[]', '[]', '[]', '<p>Đối với những ai chỉ thích một chiếc xe đạp điện có một thiết kế đẹp với một sức mạnh vừa đủ dùng thì chiếc xe điện Honda M8 đùng là một chiếc xe dành cho bạn. Nếu như bạn đã lỡ thích chiếc xe điện trên thì bạn hoàn toàn có thể rẽ qua bất kì showroom nào của Yên Thoa.</p>\n<p>Xe đạp điện Honda M8 sử dụng nhựa ABS-PP cao cấp làm dàn áo của xe đồng thời áp dụng công nghệ phưn sởn 5 lớp giúp màu sắc của xe trung thực và bắt mắt. Đặc biệt hơn nữa là bộ tem nước cực kỳ tinh tế được dãn đều ở 2 bên thân xe giúp bạn có thể dễ dàng nhận dạng xe hơn. Bộ tem nước này sử dụng công nghệ mới dán như in hẳn vào dàn áo nên không thể nào bóc ra được tạo nên sự thu hút và điểm nhấn cho xe.</p>', '<p>Đối với những ai chỉ thích một chiếc&nbsp;<strong>xe đạp điện</strong>&nbsp;có một thiết kế đẹp với một sức mạnh vừa đủ dùng thì chiếc&nbsp;<em><strong>xe điện Honda M8</strong></em>&nbsp;đùng là một chiếc xe dành cho bạn. Nếu như bạn đã lỡ thích chiếc&nbsp;xe điện&nbsp;trên thì bạn hoàn toàn có thể rẽ qua bất kì showroom nào của&nbsp;<em><strong>Yên Thoa.</strong></em></p>\n<p>Bộ tem nước tinh tế của Honda M8</p>\n<p>Xe đạp điện Honda M8 sử dụng nhựa ABS-PP cao cấp làm dàn áo của xe đồng thời áp dụng công nghệ phưn sởn 5 lớp giúp màu sắc của xe trung thực và bắt mắt. Đặc biệt hơn nữa là bộ tem nước cực kỳ tinh tế được dãn đều ở 2 bên thân xe giúp bạn có thể dễ dàng nhận dạng xe hơn. Bộ tem nước này sử dụng công nghệ mới dán như in hẳn vào dàn áo nên không thể nào bóc ra được tạo nên sự thu hút và điểm nhấn cho xe.&nbsp;</p>\n<p>Ổ khoá mở cốp xe điện Honda M8</p>\n<p>Bạn nhìn ngang như vậy có thể thấy được yên xe này khá là nhỏ nếu ngồi 2 người lớn khá là chật trừ khi bạn bỏ chiếc hộp ở phía sau ra thì có thể ngồi thoải mái 2 ngươi trên chiếc xe đạp điện Honda M8 này. Bên hông thân xe có một ổ khoá mở cốp tiện lợi tuy nhiên bên trong cốp xe dưới yên bạn sẽ không thể bỏ thêm đồ dùng gì vào được cả vì cốp này đã chứa bộ bình acquy của xe bao gồm 4 bình 20Ah. Với bộ bình này thì cứ mỗi lần sạc xe điện Honda M8 này có thể di chuyển được quãng đường 60km/1 lần sạc mỗi lần sạc mất tầm 10 tiếng đồng hồ.&nbsp;</p>\n<p>Cốp dưới yên xe chứa acquy</p>\n<p>Nếu mà nói có thể bỏ đồ gì được vào chiếc cốp dưới yên xe này thì theo mình chỉ bỏ được áo mưa đã gấp gọn mà thôi. Nhưng bù lại thì hãng Honda đã trang bị cho chiếc M8 này một hộp chứa đồ siêu to ở phía sau vừa là nơi chứa đồ đạc vừa là nơi tựa lưng an toàn khi chạy 2 người.&nbsp;</p>\n<p>Hộp chứa đồ xe điện Honda M8 siêu to</p>\n<p>Dung tích chiếc hợp chứa đồ này khá lớn bạn có thể bỏ khá là nhiều đồ đặc theo rất là tiện lợi. Thậm chí bạn có thể bỏ nón bảo hiểm vào trong này và khoá lại an toàn cũng được nữa. Hộp chứa đồ này được làm từ nhựa ABS-PP như dàn áo của xe khá là chắc chắn và bền bỉ chịu lực rất tốt. Nó được bắt chắc chắn với baga của xe tinh tế nên khi di chuyển xe thì chiếc hộp này sẽ được cố định chắc chắn không rung lắc làm ảnh hưởng đến khả năng di chuyển của xe.&nbsp;</p>\n<p>Diện tích hộp chứa đồ rộng rãi&nbsp;</p>\n<p>Xe đạp điện Honda M8 trang bị bộ vành đúc 5 chấu cực kỳ cá tính hiện đại. 5 chấu của vành xe được phủ lên lớp sơn đen tĩnh điện giúp xe trở nên cá tính mạnh mẽ hơn. Còn viền vành xe thì được phủ lên lớp sơn bạc tĩn điện tạo sự phối màu độc đáo bắt mắt mang lại ấn tượng lớn cho từ cái nhìn đầu tiên.&nbsp;</p>\n&nbsp;\n<p>Vành đúc 5 chấu cá tính</p>\n<p>Kết hợp cùng bộ lốp có săm cao làm từ cao su cao cấp, bề mặt lốp có nhiều đường rãnh nhỏ tăng khả năng bám đường giúp xe di chuyển ổn định an toàn kể cả các đoạn đường trơn trươt. Phanh cơ trước sau an toàn nhất là chỉ với chiếc xe đạp điện tốc độ tối đa chỉ tầm 40km/h thì hệ thống phanh cơ đã quá đủ. Đặc biệt là các bạn trẻ học sinh mới sử dụng xe điện thì phan cơ sẽ an toàn và dễ sử dụng hơn rất nhiều.</p>\n<p>Lốp xe có săm bám đường tốt</p>\n<p>Và cuối cùng không thể thiếu đó là hệ thống giảm xóc trước là phuộc nhún dầu có tác dụng giảm mọi tác động từ bánh xe lên tay lái đảm bảo tay lái luôn vững vàng ổn định khi di chuyển. </p>\n<p>Giảm xóc sau cặp lò xo kép cao cấp</p>\n<p>Và ở sau&nbsp;<strong>xe đạp&nbsp;điện Honda M8</strong>&nbsp;thì được trang bị cặp lò xo kép cao cấp được mạ niken sáng bóng. Bộ giảm xóc sau có tác dụng giúp xe chịu tải trọng lớn, cho xe chạy 2 người thoải mái và giảm các tác động rung chấn khi di chuyển qua các đoạn đường xấu.&nbsp;</p>\n<p>Yên Thoa cam kết chỉ bán sản phẩm đẳng cấp chính hãng chất lượng cao của những lớn uy tín và nổi tiếng nhất thế giới. Chúng tôi luôn khuyên quý khách tìm hiểu về hãng sản xuất và xem thật kỹ sản phẩm để mua được những sản phẩm tốt nhất. Tránh mua nhầm hàng giả, nhái, kém chất lượng.</p>\n<h2><strong>GIẤY TỜ XE ĐẠP ĐIỆN HONDA MODEL M8:</strong></h2>\n<p>Giấy kiểm định chất lượng xe điện Honda M8</p>\n<p><em>Hóa đơn nhập khẩu xe điện honda M8</em></p>\n<em><br></em>\n&nbsp;\n&nbsp;', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-osakar-heidi', 'Xe Đạp Điện Osakar Heidi', 'osakar', '[\"xe-dap-dien\"]', 14500000, 14500000, '/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-6.webp\"]', '[]', '[]', '[]', '<p>Chọn xe đạp điện hiện nay không còn là chuyện mua tạm để đi, mà là chọn một phương tiện có thể dùng ổn định trong nhiều năm. Người dùng bắt đầu quan tâm nhiều hơn đến việc xe có đủ khỏe, đủ bền và đủ an toàn cho nhu cầu hằng ngày hay không. Xe Đạp Điện Osakar Heidi Từ vận hành, an toàn đến độ bền, mẫu xe này được xây dựng để giải quyết đúng những vấn đề mà người dùng thường gặp phải sau một thời gian sử dụng xe điện.</p>\n<p>Trên thị trường hiện nay, phần lớn xe đạp điện rơi vào hai nhóm: một là xe nhẹ nhưng yếu, hai là xe khỏe nhưng nặng và khó kiểm soát. Xe Đạp Điện Osakar Heidi đi theo hướng khác: tối ưu sự cân bằng giữa sức mạnh – độ nhẹ – tính tiện dụng.</p>', '<p>Chọn xe đạp điện hiện nay không còn là chuyện mua tạm để đi, mà là chọn một phương tiện có thể dùng ổn định trong nhiều năm. Người dùng bắt đầu quan tâm nhiều hơn đến việc xe có đủ khỏe, đủ bền và đủ an toàn cho nhu cầu hằng ngày hay không. Xe Đạp Điện Osakar Heidi Từ vận hành, an toàn đến độ bền, mẫu xe này được xây dựng để giải quyết đúng những vấn đề mà người dùng thường gặp phải sau một thời gian sử dụng xe điện.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-7.webp\" alt=\"Xe Đạp Điện Osakar Heidi\" loading=\"lazy\"></p>\n<h2><strong>Vì sao Xe Đạp Điện Osakar Heidi không giống phần còn lại?</strong></h2>\n<p>Trên thị trường hiện nay, phần lớn xe đạp điện rơi vào hai nhóm: một là xe nhẹ nhưng yếu, hai là xe khỏe nhưng nặng và khó kiểm soát. <strong>Xe Đạp Điện</strong> Osakar Heidi đi theo hướng khác: tối ưu sự cân bằng giữa sức mạnh – độ nhẹ – tính tiện dụng.</p>\n<p>Thay vì chỉ tập trung vào thông số, Heidi được thiết kế xoay quanh trải nghiệm sử dụng thực tế hằng ngày: đi học, đi làm, leo dốc, chở thêm người, thậm chí xử lý các tình huống như gần hết điện hoặc gặp sự cố giữa đường. Điều này khiến chiếc xe không chỉ “đủ dùng”, mà còn “dùng lâu vẫn thấy hợp”.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-8.webp\" alt=\"Xe Đạp Điện Osakar Heidi\" loading=\"lazy\"></p>\n<h2><strong>Bàn đạp trợ lực dùng được thật</strong></h2>\n<p>Một trong những điểm khiến Xe Đạp Điện Osakar Heidi khác biệt rõ ràng chính là hệ thống bàn đạp trợ lực. Nghe thì quen thuộc, nhưng cách Heidi triển khai lại hoàn toàn khác so với phần lớn xe đạp điện hiện nay.</p>\n<p>Thông thường, bàn đạp trên xe đạp điện chỉ mang tính hình thức để đáp ứng quy định. Khi xe yếu điện, người dùng gần như không thể đạp nổi vì xe nặng, lực cản lớn và không có hỗ trợ thực sự từ hệ thống điện. Đây là lý do nhiều người gần như “bỏ quên” tính năng này sau khi mua xe.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-heidi-9.webp\" alt=\"Xe Đạp Điện Osakar Heidi\" loading=\"lazy\"></p>\n<p>Tuy nhiên, với Heidi, bàn đạp được tích hợp cùng cơ chế trợ lực giúp người dùng vẫn có thể di chuyển khi xe yếu điện, duy trì tốc độ ổn định thay vì phải dắt bộ. Điều này cực kỳ quan trọng với học sinh đi học xa hoặc người sử dụng xe trong cả ngày dài.</p>\n<p>Không chỉ vậy, khi leo dốc hoặc chở thêm người, bàn đạp trợ lực còn đóng vai trò như một “cú đẩy bổ sung”, giúp xe vượt qua đoạn đường khó một cách nhẹ nhàng hơn. Đây là chi tiết nhỏ nhưng mang lại giá trị sử dụng rất lớn – và cũng là thứ mà nhiều xe khác không làm được</p>\n<h2><strong>Hệ thống an toàn nhiều lớp E-ABS + SOS + nút P&nbsp;</strong></h2>\n<p>Nếu chỉ nhìn bề ngoài, nhiều người có thể nghĩ rằng Heidi là một chiếc xe đơn giản. Nhưng khi đi sâu vào trang bị, có thể thấy rõ đây là mẫu xe được đầu tư mạnh về yếu tố an toàn – điều mà không nhiều xe đạp điện trong phân khúc làm được.</p>\n<p>Trước hết là hệ thống phanh đĩa trước tích hợp E-ABS. Công nghệ này giúp hạn chế tình trạng bó cứng bánh khi phanh gấp, đặc biệt hữu ích khi đi trên đường trơn hoặc trong điều kiện mưa. So với phanh cơ thông thường, E-ABS mang lại cảm giác kiểm soát tốt hơn và giảm rủi ro trượt bánh.</p>\n<p>Tiếp theo là nút P (parking) một chi tiết nhỏ nhưng cực kỳ thực tế. Khi dừng xe, người dùng có thể kích hoạt nút này để ngắt hoàn toàn tay ga, tránh tình trạng xe bất ngờ lao về phía trước nếu vô tình vặn ga. Đây là tính năng rất hữu ích với học sinh hoặc người mới sử dụng xe điện.</p>\n<p>Đặc biệt, Heidi còn được trang bị nút SOS một tính năng hiếm thấy. Trong trường hợp tay ga gặp lỗi hoặc xe gặp sự cố, nút này cho phép xe tiếp tục di chuyển trong một quãng đường ngắn, giúp người dùng xử lý tình huống mà không bị “kẹt giữa đường”.</p>\n<p>Khi kết hợp lại, ba yếu tố này tạo nên một hệ thống an toàn nhiều lớp: phanh an toàn – kiểm soát chủ động hỗ trợ khi gặp sự cố. Đây là cách tiếp cận gần với xe máy hơn là xe đạp điện thông thường.</p>\n<h2><strong>Động cơ mạnh nhưng thân xe vẫn nhẹ</strong></h2>\n<p>Một trong những điểm khiến người dùng dễ nhận ra sự khác biệt của Xe Đạp Điện <strong>Osakar Heidi</strong> chính là cảm giác lái. Xe không chỉ “chạy được”, mà mang lại cảm giác dễ điều khiển ngay từ lần đầu sử dụng.</p>\n<p>Theo thông số, xe sử dụng động cơ công suất danh định khoảng 500W và có thể đạt mức cao hơn khi cần thiết, cho phép xe đạt vận tốc khoảng 50 km/h. Đây là mức hiệu năng khá cao trong phân khúc xe đạp điện.</p>\n<p>Tuy nhiên, điểm đáng nói không nằm ở con số, mà nằm ở cách xe vận hành. Heidi không mang cảm giác “bốc gắt” như một số xe điện mạnh khác, mà được tinh chỉnh để tăng tốc mượt, dễ kiểm soát và ổn định. Điều này giúp người lái, đặc biệt là học sinh, không bị “giật mình” khi vặn ga.</p>\n<p>Song song với đó, trọng lượng xe được giữ ở mức nhẹ, giúp việc dắt xe, quay đầu hay di chuyển trong không gian hẹp trở nên dễ dàng hơn. Đây là sự cân bằng rất khó đạt được, bởi nhiều xe mạnh thường đi kèm trọng lượng lớn.</p>\n<h2><strong>Điều người dùng cần ở Osakar Heidi</strong></h2>\n<p>Bên cạnh ba điểm mạnh cốt lõi, Xe Đạp Điện Osakar Heidi vẫn được hoàn thiện tốt ở những yếu tố cơ bản mà người dùng cần mỗi ngày.</p>\n<p>Chiều cao yên khoảng 740 mm giúp người dùng dễ chống chân, phù hợp với học sinh và người có chiều cao trung bình. Thiết kế hai yên tách biệt tạo cảm giác thoải mái khi chở thêm người, đồng thời giữ được sự gọn gàng cho tổng thể xe.</p>\n<p>Sàn để chân rộng, tư thế ngồi thẳng lưng giúp giảm mỏi khi di chuyển lâu. Đây là yếu tố quan trọng nhưng thường bị bỏ qua khi chọn xe.</p>\n<p>Phần vỏ xe sử dụng nhựa ABS dày, kết hợp lớp sơn tĩnh điện nhiều lớp giúp tăng độ bền và giữ màu tốt theo thời gian. Điều này giúp xe không bị “xuống cấp nhanh” sau một thời gian sử dụng – yếu tố rất đáng cân nhắc khi mua xe cho con.</p>\n<p>Xe sử dụng bộ ắc quy 20Ah, cho quãng đường di chuyển khoảng 70–80 km mỗi lần sạc, đủ cho nhu cầu đi học hoặc đi làm trong nhiều ngày. Thời gian sạc khoảng 6–8 tiếng, phù hợp với thói quen sạc qua đêm.</p>\n<p>Chi phí sạc điện chỉ ở mức vài nghìn đồng mỗi lần, thấp hơn rất nhiều so với chi phí xăng xe. Ngoài ra, xe điện cũng không cần thay dầu, ít hỏng vặt, giúp giảm đáng kể chi phí bảo dưỡng. Tuổi thọ ắc quy trung bình khoảng 1,5–2 năm, chi phí thay thế hợp lý. Khi tính tổng chi phí sử dụng trong vài năm, Heidi cho thấy rõ lợi thế kinh tế so với xe máy truyền thống.</p>\n<p>Trong một thị trường mà nhiều mẫu xe đạp điện còn mang tính “tạm thời” hoặc chỉ phục vụ nhu cầu ngắn hạn, X<strong>e Đạp Điện Osakar</strong> Heidi lại đi theo hướng khác, không chỉ là điểm cộng về mặt kỹ thuật, mà còn giải quyết trực tiếp những vấn đề người dùng thường gặp.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-osakar-mandi', 'Xe Đạp Điện Osakar Mandi', 'osakar', '[\"xe-dap-dien\"]', 14690000, 14690000, '/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-6.webp\"]', '[]', '[]', '[]', '<p>Nổi lên như một hiện tượng trong năm 2026, xe đạp điện Osakar Mandi đã nhanh chóng chinh phục người dùng bởi thiết kế độc đáo \"nhỏ mà có võ\", khả năng vận hành ấn tượng và mức giá \"dễ chịu\". Chiếc xe này không chỉ là phương tiện đi lại mà còn là tuyên ngôn phong cách, khẳng định sự sành điệu và gu thẩm mỹ tinh tế của người sở hữu.</p>\n<p>Thị trường xe đạp điện từng có giai đoạn bị “đóng khung” với những thiết kế đơn giản, thiên về tính tiện dụng. Tuy nhiên, sự thay đổi trong nhu cầu của người dùng đã thúc đẩy các thương hiệu phải đổi mới. Osakar Mandi chính là minh chứng rõ ràng cho sự chuyển mình đó.</p>', '<p>Nổi lên như một hiện tượng trong năm 2026, xe đạp điện Osakar Mandi đã nhanh chóng chinh phục người dùng bởi thiết kế độc đáo \"nhỏ mà có võ\", khả năng vận hành ấn tượng và mức giá \"dễ chịu\". Chiếc xe này không chỉ là phương tiện đi lại mà còn là tuyên ngôn phong cách, khẳng định sự sành điệu và gu thẩm mỹ tinh tế của người sở hữu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Osakar Mandi – làn gió mới trong phân khúc xe đạp điện</strong></h2>\n<p>Thị trường <strong>xe đạp điện</strong> từng có giai đoạn bị “đóng khung” với những thiết kế đơn giản, thiên về tính tiện dụng. Tuy nhiên, sự thay đổi trong nhu cầu của người dùng đã thúc đẩy các thương hiệu phải đổi mới. Osakar Mandi chính là minh chứng rõ ràng cho sự chuyển mình đó.</p>\n<p>Mẫu xe này không còn mang dáng dấp của một chiếc xe “chỉ dành cho học sinh”, mà được nâng cấp toàn diện cả về ngoại hình lẫn trải nghiệm. Thiết kế cân đối, thanh thoát giúp xe phù hợp với nhiều đối tượng, từ học sinh cấp 2, cấp 3 đến sinh viên hay người đi làm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Điểm đặc biệt của Mandi là sự kết hợp hài hòa giữa phong cách cổ điển và hiện đại. Điều này tạo nên một tổng thể vừa quen thuộc, vừa mới mẻ – dễ dàng thu hút ánh nhìn ngay từ lần đầu tiên.</p>\n<h2><strong>Thiết kế nhỏ gọn nhưng đầy cuốn hút</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, Osakar Mandi đã tạo ấn tượng với phong cách thiết kế mang hơi hướng châu Âu, gợi nhớ đến những dòng xe cổ điển nhưng được làm mới bằng các chi tiết hiện đại.</p>\n<p>Kích thước xe được tối ưu để phù hợp với môi trường đô thị. Nhờ đó, người dùng có thể dễ dàng di chuyển trong những con phố đông đúc, ngõ nhỏ hay khu vực trường học đông người. Trọng lượng nhẹ cũng giúp việc dắt xe, quay đầu trở nên đơn giản hơn rất nhiều.</p>\n<p>Chiều cao yên xe được tính toán hợp lý, giúp người dùng dễ dàng chống chân khi dừng lại, mang lại cảm giác an toàn – đặc biệt quan trọng với học sinh.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-osakar-mandi-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Không chỉ dừng lại ở sự tiện dụng, thiết kế của Mandi còn chú trọng đến yếu tố thẩm mỹ. Các đường cong mềm mại, liền mạch tạo nên tổng thể hài hòa, giúp chiếc xe trông cao cấp hơn so với phân khúc giá.</p>\n<h2><strong>Màu sắc trendy – dễ dàng thể hiện cá tính</strong></h2>\n<p>Một trong những yếu tố giúp Osakar Mandi “ghi điểm” mạnh mẽ chính là bảng màu đa dạng và bắt trend. Từ những gam màu trung tính như đen, xám đến các màu sáng như trắng hay xanh, mỗi phiên bản đều mang một cá tính riêng. Điều này giúp người dùng dễ dàng lựa chọn chiếc xe phù hợp với phong cách của mình.</p>\n<p>Lớp sơn tĩnh điện nhiều lớp giúp xe giữ được độ bóng và độ bền màu theo thời gian. Đây là điểm rất quan trọng, bởi với giới trẻ, ngoại hình của chiếc xe gần như gắn liền với hình ảnh cá nhân.</p>\n<h2><strong>Động cơ mạnh mẽ – đúng nghĩa “nhỏ mà có võ”</strong></h2>\n<p>Dù sở hữu thiết kế nhỏ gọn, Osakar Mandi lại gây bất ngờ với khả năng vận hành. Xe được trang bị động cơ công suất từ 500W đến 1000W tùy phiên bản. Điều này giúp xe có thể đạt tốc độ từ 40km/h đến 60km/h – đủ để di chuyển linh hoạt trong thành phố.</p>\n<p>Khả năng tăng tốc mượt, không giật và đặc biệt là leo dốc tốt giúp Mandi xử lý dễ dàng các tình huống thường gặp như hầm gửi xe, cầu vượt hay đường dốc.</p>\n<p>Công nghệ hỗ trợ tự động điều chỉnh công suất giúp xe vận hành ổn định hơn, đồng thời tiết kiệm năng lượng trong quá trình sử dụng.</p>\n<p>Khả năng chống nước đạt chuẩn cao cũng là một điểm cộng lớn, giúp xe hoạt động ổn định ngay cả trong điều kiện thời tiết mưa nhiều – đặc trưng tại Việt Nam.</p>\n<h2><strong>Bàn đạp trợ lực – lợi thế cực lớn cho học sinh</strong></h2>\n<p>Một trong những điểm khác biệt lớn của<strong> Osakar Mandi</strong> so với nhiều mẫu xe khác chính là việc tích hợp bàn đạp trợ lực.</p>\n<p>Tính năng này không chỉ giúp người dùng linh hoạt hơn khi sử dụng, mà còn mang ý nghĩa rất quan trọng về mặt pháp lý. Nhờ có bàn đạp, xe được xếp vào nhóm xe đạp điện, không yêu cầu bằng lái hay đăng ký biển số.</p>\n<p>Điều này giúp học sinh cấp 2 hoàn toàn có thể sử dụng xe một cách hợp pháp và an toàn. Ngoài ra, trong những trường hợp xe yếu điện hoặc cần tiết kiệm pin, người dùng có thể sử dụng bàn đạp để hỗ trợ di chuyển – một tính năng rất thực tế.</p>\n<h2><strong>Pin bền bỉ – quãng đường đáp ứng mọi nhu cầu</strong></h2>\n<p>Osakar Mandi mang đến nhiều lựa chọn về pin, phù hợp với từng nhu cầu sử dụng.</p>\n<p>Phiên bản sử dụng ắc quy cho quãng đường khoảng 60–80km, đủ để đi học và di chuyển trong vài ngày mà không cần sạc.</p>\n<p>Trong khi đó, phiên bản pin lithium có thể đạt quãng đường lên tới 100km, mang lại sự thoải mái tối đa cho người dùng.</p>\n<p>Pin lithium cũng có ưu điểm về trọng lượng nhẹ, tuổi thọ cao và độ an toàn tốt hơn. Đây là lựa chọn phù hợp với những người di chuyển nhiều hoặc muốn sử dụng lâu dài.</p>\n<p>Thời gian sạc từ 6–8 tiếng giúp người dùng dễ dàng sạc qua đêm, đảm bảo xe luôn sẵn sàng cho ngày mới.</p>\n<h2><strong>Trang bị tiện nghi – An toàn tối đa</strong></h2>\n<p>Không chỉ mạnh mẽ và thời trang, Osakar Mandi còn chú trọng đến trải nghiệm tiện nghi và sự an toàn cho người sử dụng.</p>\n<p>+ Hệ thống khóa thông minh 3 trong 1: Xe tích hợp công nghệ khóa thẻ từ NFC, Smartkey tiện lợi, cùng với chìa khóa cơ truyền thống. Chỉ cần quẹt thẻ hoặc bấm nút Smartkey, xe sẽ tự động mở khóa, vô cùng nhanh chóng và hiện đại.</p>\n<p>+ Nút P - Chế độ khóa động cơ an toàn: Nút P trên tay lái giúp khóa động cơ khi xe đứng yên, ngăn chặn tình trạng xe bị trượt ga đột ngột khi khởi động, đảm bảo an toàn tuyệt đối cho người lái và phương tiện.</p>\n<p>+ Đèn pha LED siêu sáng: Cụm đèn pha LED hình tròn không chỉ tạo điểm nhấn thẩm mỹ mà còn cung cấp ánh sáng trắng sắc nét, tăng cường khả năng quan sát khi di chuyển trong điều kiện thiếu sáng hoặc ban đêm.</p>\n<p>+ Đồng hồ điện tử đa thông tin: Màn hình kỹ thuật số hiển thị đầy đủ các thông số cần thiết như tốc độ, quãng đường, mức pin, đèn báo,... giúp người lái dễ dàng nắm bắt tình trạng xe.</p>\n<p>+ Lốp Kenda không săm 3.00-10: Lốp xe của thương hiệu nổi tiếng Kenda có độ bám đường tốt, khả năng chống mài mòn cao và giảm thiểu rủi ro xì hơi, đảm bảo xe vận hành ổn định trên mọi địa hình.</p>\n<p>+ Hệ thống phanh an toàn: Xe trang bị phanh đĩa ở bánh trước và phanh cơ ở bánh sau, mang lại khả năng dừng xe hiệu quả và an toàn trong mọi tình huống.</p>\n<p>+ Giảm xóc thủy lực êm ái: Hệ thống giảm xóc trước và sau giúp hấp thụ tối đa rung động từ mặt đường, mang lại trải nghiệm lái êm ái, giảm thiểu mệt mỏi.</p>\n<p>+ Khung xe chắc chắn, nhựa ABS cao cấp: Khung xe được chế tạo từ vật liệu chắc chắn, kết hợp với lớp vỏ nhựa ABS dày, đàn hồi cao, đảm bảo độ bền bỉ và an toàn ngay cả khi có va chạm nhẹ.</p>\n<h2><strong>Giải pháp lý tưởng cho học sinh và gia đình</strong></h2>\n<p>Trong bối cảnh quy định ngày càng chặt chẽ về phương tiện cho học sinh, Osakar Mandi nổi lên như một lựa chọn cực kỳ hợp lý.</p>\n<p>Xe không yêu cầu bằng lái, không cần đăng ký biển số, dễ sử dụng và an toàn. Đây là những yếu tố khiến phụ huynh yên tâm khi lựa chọn cho con.</p>\n<p>Bên cạnh đó, chi phí vận hành thấp giúp tiết kiệm đáng kể so với xe xăng. Việc không cần bảo dưỡng phức tạp cũng giúp giảm gánh nặng chi phí lâu dài.</p>\n<p>Đối với học sinh, việc sở hữu một chiếc xe như Mandi không chỉ giúp chủ động hơn trong việc đi học mà còn mang lại sự tự tin trong cuộc sống hàng ngày.</p>\n<p><strong>Osakar</strong> Mandi không chỉ là một chiếc xe đạp điện, mà là sự kết hợp giữa phong cách, công nghệ và tính thực dụng. Với thiết kế “nhỏ mà có võ”, khả năng vận hành mạnh mẽ, chi phí hợp lý và sự phù hợp với người trẻ, mẫu xe này hoàn toàn xứng đáng trở thành lựa chọn hàng đầu trong năm 2026.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe vừa đẹp, vừa tiện, vừa thể hiện được cá tính riêng, Osakar Mandi chắc chắn là cái tên không nên bỏ qua.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-gr54-day-du-giay-to', 'Xe Đạp Điện Tailg GR54 Đầy Đủ Giấy Tờ', 'tailg', '[\"xe-dap-dien\"]', 14846500, 14846500, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-4.webp\"]', '[]', '[]', '[]', '<p>Tailg GR54 gây ấn tượng mạnh với phong cách thiết kế trẻ trung bắt kịp xu hướng, kết hợp cùng khả năng vận hành ổn định, pin bền bỉ và quãng đường lên tới 70km cho mỗi lần sạc. Không chỉ đơn thuần là một phương tiện di chuyển, GR54 còn là người bạn đồng hành phù hợp với nhịp sống năng động của giới trẻ năm 2026, nơi sự tiện lợi, an toàn và tính thẩm mỹ được đặt lên hàng đầu.</p>\n<p>Phần đầu xe nổi bật với cụm đèn tròn cổ điển kết hợp cùng giỏ trước, vừa tăng tính thẩm mỹ vừa cực kỳ thực dụng trong quá trình sử dụng hàng ngày. Bạn có thể dễ dàng để túi xách, balo nhỏ hoặc đồ cá nhân mà không cần phải treo lỉnh kỉnh.</p>', '<p>Tailg GR54 gây ấn tượng mạnh với phong cách thiết kế trẻ trung bắt kịp xu hướng, kết hợp cùng khả năng vận hành ổn định, pin bền bỉ và quãng đường lên tới 70km cho mỗi lần sạc. Không chỉ đơn thuần là một phương tiện di chuyển, GR54 còn là người bạn đồng hành phù hợp với nhịp sống năng động của giới trẻ năm 2026, nơi sự tiện lợi, an toàn và tính thẩm mỹ được đặt lên hàng đầu.</p>\n<h2>Thiết kế <strong>Tailg GR54</strong> – nhẹ nhàng nhưng không hề đơn giản</h2>\nĐiểm đầu tiên khiến người dùng chú ý đến Tailg GR54 chính là thiết kế mang phong cách vintage pha hiện đại. Tổng thể xe được tạo hình với các đường bo tròn mềm mại, mang lại cảm giác thân thiện, dễ nhìn và không bị lỗi thời theo thời gian. Đây là kiểu thiết kế không gây “choáng ngợp” nhưng lại càng nhìn càng thấy hợp mắt, đặc biệt phù hợp với các bạn học sinh, sinh viên hoặc người thích sự nhẹ nhàng.\n&nbsp;\n<p>Phần đầu xe nổi bật với cụm đèn tròn cổ điển kết hợp cùng giỏ trước, vừa tăng tính thẩm mỹ vừa cực kỳ thực dụng trong quá trình sử dụng hàng ngày. Bạn có thể dễ dàng để túi xách, balo nhỏ hoặc đồ cá nhân mà không cần phải treo lỉnh kỉnh.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-5.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Màu sắc cũng là điểm khiến GR54 ghi điểm mạnh. Những gam màu pastel như hồng kem, trắng ngà không chỉ tạo cảm giác sang nhẹ mà còn giúp xe luôn “ăn hình” khi chụp ảnh. Đây là yếu tố mà nhiều người trẻ hiện nay rất quan tâm, đặc biệt là các bạn nữ.</p>\n<h2>Kích thước và cảm giác sử dụng – dễ tiếp cận cho mọi đối tượng</h2>\n<p>Một trong những điểm mạnh rõ ràng nhất của Tailg GR54 là kích thước nhỏ gọn và trọng lượng nhẹ. Điều này không chỉ giúp xe linh hoạt khi di chuyển trong phố đông mà còn giúp người dùng cảm thấy tự tin hơn khi điều khiển.</p>\n<p>Chiều cao yên thấp giúp người có chiều cao khiêm tốn vẫn có thể chống chân dễ dàng. Đây là yếu tố cực kỳ quan trọng đối với học sinh cấp 2, cấp 3 hoặc những người mới làm quen với xe điện. Khi bạn có thể chống chân chắc chắn, cảm giác lái xe sẽ an toàn hơn rất nhiều.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-6.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Ngoài ra, trọng lượng nhẹ cũng giúp việc dắt xe, quay đầu trong không gian hẹp hoặc gửi xe ở bãi trở nên đơn giản hơn. Những chi tiết nhỏ như vậy tưởng không quan trọng, nhưng lại ảnh hưởng trực tiếp đến trải nghiệm sử dụng hàng ngày.</p>\n<h2>Động cơ vận hành – êm, mượt và kiểm soát tốt</h2>\n<p>Tailg GR54 được trang bị động cơ khoảng 500W, đây là mức công suất phù hợp với dòng xe đạp điện và đúng với mục đích sử dụng của xe. Điểm quan trọng không nằm ở việc xe chạy nhanh đến đâu, mà là xe có dễ điều khiển và ổn định hay</p>\n<p>không.</p>\n<p>Trong quá trình sử dụng thực tế, GR54 cho cảm giác tăng tốc nhẹ nhàng, không bị giật cục, rất phù hợp với người mới đi hoặc người thích cảm giác lái an toàn. Khi di chuyển trong khu dân cư đông đúc hoặc đường phố nhiều xe, khả năng kiểm soát tốt sẽ giúp bạn xử lý tình huống linh hoạt hơn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr54-day-du-giay-to-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Bên cạnh đó, động cơ vận hành khá êm ái, không gây tiếng ồn lớn, tạo cảm giác dễ chịu khi sử dụng lâu dài. Đây là điểm mà nhiều người sau khi chuyển từ xe xăng sang xe điện đều cảm nhận rất rõ.</p>\n<h2>Quãng đường di chuyển – đáp ứng tốt nhu cầu thực tế</h2>\n<p>Một trong những yếu tố khiến người dùng quan tâm nhất khi chọn xe điện là quãng đường di chuyển. <strong>Xe đạp điện Tailg</strong> GR54 có thể đi được khoảng 60–70km sau mỗi lần sạc đầy, mức này được xem là khá hợp lý trong phân khúc xe đạp điện.</p>\n<p>Trong thực tế, con số này hoàn toàn đủ để đáp ứng nhu cầu đi học, đi làm hoặc di chuyển cá nhân trong nội thành. Với tần suất sử dụng bình thường, bạn không cần phải sạc mỗi ngày mà có thể sử dụng trong 2–3 ngày mới cần sạc lại.</p>\n<p>Điều này giúp giảm bớt sự phụ thuộc vào việc tìm chỗ sạc, đặc biệt với những người sống ở chung cư hoặc khu vực có điều kiện sạc hạn chế.</p>\n<h2>Hệ thống ắc quy – lựa chọn thực tế và dễ sử dụng lâu dài</h2>\n<p>Tailg GR54 sử dụng hệ ắc quy chì axit, đây là lựa chọn phổ biến và phù hợp với điều kiện sử dụng tại Việt Nam hiện nay. Dù không “hiện đại” như pin lithium, nhưng ắc quy lại có ưu điểm rõ ràng về tính thực dụng.</p>\n<p>Chi phí thay thế thấp hơn đáng kể, dễ tìm linh kiện và dễ sửa chữa khi cần. Đối với người dùng phổ thông, đặc biệt là học sinh, sinh viên, đây là yếu tố rất quan trọng vì giúp tiết kiệm chi phí lâu dài.</p>\n<p>Ngoài ra, hệ ắc quy cũng hoạt động ổn định trong điều kiện thời tiết nóng ẩm, phù hợp với môi trường sử dụng tại Việt Nam.</p>\n<h2>Tiện ích đi kèm – phục vụ đúng nhu cầu hàng ngày</h2>\n<p>GR54 được trang bị đầy đủ những tiện ích cần thiết để phục vụ nhu cầu di chuyển hàng ngày, không chỉ dừng lại ở mức “đủ dùng” mà còn mang lại sự tiện lợi rõ rệt trong quá trình sử dụng thực tế. Phần giỏ trước thiết kế rộng rãi đi kèm khóa hiện đại, giúp bạn yên tâm để đồ cá nhân như túi xách, điện thoại hay vật dụng quan trọng mà không lo rơi rớt hay bị lấy trộm khi dừng xe trong thời gian ngắn. Đây là chi tiết nhỏ nhưng cực kỳ đáng giá với người dùng thường xuyên di chuyển trong đô thị.</p>\n<p>Bên cạnh đó, cốp dưới yên vẫn đảm bảo không gian chứa đồ cơ bản như áo mưa, bộ sạc hoặc những vật dụng cá nhân cần thiết, giúp bạn luôn chủ động trong mọi tình huống hàng ngày mà không cần mang theo quá nhiều đồ trên người. Ngoài ra, xe còn được trang bị <strong>bàn đạp trợ lực</strong>, giúp người dùng có thể hỗ trợ khi cần thiết, đặc biệt hữu ích trong những trường hợp xe yếu điện hoặc cần di chuyển quãng ngắn mà không muốn dùng điện hoàn toàn.</p>\n<p>Hệ thống chiếu sáng LED được trang bị giúp xe vận hành an toàn hơn vào ban đêm, ánh sáng rõ và ổn định, tăng khả năng quan sát khi di chuyển trong điều kiện thiếu sáng. Kết hợp với đó là phanh đĩa trước mang lại cảm giác phanh chắc chắn, hỗ trợ xử lý tốt trong những tình huống cần dừng gấp hoặc khi đi trên đường trơn trượt.</p>\n<p>Đáng chú ý, GR54 còn sử dụng khóa smartkey hiện đại, giúp tăng khả năng chống trộm và nâng cao trải nghiệm sử dụng, không còn phụ thuộc vào chìa khóa cơ truyền thống. Tất cả những tiện ích này có thể không quá “hào nhoáng”, nhưng lại là những thứ bạn sẽ sử dụng mỗi ngày, và chính điều đó mới tạo nên giá trị thực sự của một chiếc xe điện – tiện lợi, an toàn và phù hợp với cuộc sống hàng ngày.</p>\n<p>Tất cả những tiện ích này có thể không quá phô trương hay mang tính “công nghệ cao”, nhưng lại là những thứ bạn sử dụng mỗi ngày. Và chính những yếu tố tưởng chừng nhỏ này mới tạo nên giá trị thực sự của một chiếc xe điện – dễ dùng, tiện lợi và phù hợp với cuộc sống hàng ngày</p>\n&nbsp;\n<h2>Đối tượng phù hợp – không phải ai cũng cần xe mạnh</h2>\n<p>Tailg GR54 không phải là chiếc xe dành cho tất cả mọi người, nhưng lại rất phù hợp với một nhóm người dùng cụ thể. Nếu bạn là học sinh, sinh viên hoặc người cần một phương tiện di chuyển nhẹ nhàng trong thành phố, đây là lựa chọn rất hợp lý.</p>\n<p>Xe phù hợp với những ai ưu tiên sự dễ sử dụng, không cần tốc độ cao và không muốn phải xử lý một chiếc xe quá mạnh. Ngược lại, nếu bạn cần đi xa, leo dốc nhiều hoặc chở nặng thường xuyên, bạn nên cân nhắc các dòng xe máy điện công suất lớn hơn.</p>\n<h2>Chi phí sử dụng – lợi thế lớn của xe điện</h2>\n<p>Một trong những lý do khiến xe điện ngày càng phổ biến là chi phí vận hành thấp. Với Tailg GR54, mỗi lần sạc điện chỉ tốn một khoản rất nhỏ, thấp hơn rất nhiều so với chi phí đổ xăng.</p>\n<p>Ngoài ra, xe điện ít phải bảo dưỡng hơn vì không có nhiều bộ phận cơ khí phức tạp. Điều này giúp bạn tiết kiệm được một khoản chi phí đáng kể trong quá trình sử dụng lâu dài.</p>\n<h2>Có nên mua Tailg GR54 ở thời điểm hiện tại?</h2>\n<p>Thị trường xe điện đang phát triển nhanh, các hãng liên tục tung ra sản phẩm mới và cạnh tranh mạnh về giá. Điều này tạo ra lợi thế lớn cho người mua vì có nhiều lựa chọn hơn và giá cả ngày càng hợp lý.</p>\n<p>Tuy nhiên, điều quan trọng là bạn không nên vội vàng. Người bán luôn muốn bạn quyết định nhanh, nhưng bạn nên dành thời gian tìm hiểu kỹ để chọn đúng chiếc xe phù hợp với nhu cầu.</p>\n<p>GR54 là một mẫu xe đã được kiểm chứng về độ ổn định và phù hợp với nhu cầu phổ thông. Nếu bạn đang cần một chiếc xe để sử dụng hàng ngày mà không muốn gặp quá nhiều rắc rối, đây là lựa chọn đáng cân nhắc.</p>\n<p>Tailg GR54 là chiếc <strong>xe đạp điện thông minh</strong> đáp ứng đúng những gì người dùng cần trong cuộc sống hàng ngày. Thiết kế đẹp, dễ sử dụng, chi phí hợp lý và phù hợp với nhiều đối tượng – đó là những gì khiến GR54 trở thành một lựa chọn đáng giá. Trong một thị trường đầy lựa chọn, đôi khi bạn không cần chiếc xe tốt nhất, mà chỉ cần chiếc xe phù hợp nhất. Và với rất nhiều người, Tailg GR54 chính là câu trả lời đó</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-gr55-day-du-giay-to', 'Xe Đạp Điện Tailg GR55 Đầy Đủ Giấy Tờ', 'tailg', '[\"xe-dap-dien\"]', 14540000, 14540000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Xe đạp điện ngày nay không còn đơn thuần là một phương tiện di chuyển mà đã trở thành một phần trong phong cách sống của giới trẻ. Từ học sinh, sinh viên đến nhân viên văn phòng, đặc biệt là phái nữ, ai cũng muốn sở hữu một chiếc xe vừa đẹp, vừa tiện lợi và đủ “chất riêng”. Trong số đó, Tailg GR55 nổi lên như một lựa chọn cực kỳ đáng chú ý khi không chỉ sở hữu thiết kế xinh xắn mà còn được nâng cấp mạnh mẽ về công nghệ pin, cho khả năng di chuyển lên tới 130km mỗi lần sạc.</p>\n<p>Đây không chỉ là một con số ấn tượng, mà còn là bước tiến giúp xe đạp điện tiến gần hơn đến sự tiện lợi của xe máy, mở ra trải nghiệm hoàn toàn khác cho người dùng đô thị hiện đại.</p>', '<p>Xe đạp điện ngày nay không còn đơn thuần là một phương tiện di chuyển mà đã trở thành một phần trong phong cách sống của giới trẻ. Từ học sinh, sinh viên đến nhân viên văn phòng, đặc biệt là phái nữ, ai cũng muốn sở hữu một chiếc xe vừa đẹp, vừa tiện lợi và đủ “chất riêng”. Trong số đó, Tailg GR55 nổi lên như một lựa chọn cực kỳ đáng chú ý khi không chỉ sở hữu thiết kế xinh xắn mà còn được nâng cấp mạnh mẽ về công nghệ pin, cho khả năng di chuyển lên tới 130km mỗi lần sạc.</p>\n<p>Đây không chỉ là một con số ấn tượng, mà còn là bước tiến giúp xe đạp điện tiến gần hơn đến sự tiện lợi của xe máy, mở ra trải nghiệm hoàn toàn khác cho người dùng đô thị hiện đại.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế nhỏ gọn, thời thượng, sinh ra dành cho giới trẻ</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, <strong>Tailg GR55</strong> đã tạo được thiện cảm nhờ kiểu dáng nhỏ nhắn, thanh thoát và cực kỳ “ăn ảnh”. Không quá hầm hố như các dòng xe thể thao, cũng không quá đơn giản như xe phổ thông, GR55 nằm ở điểm cân bằng hoàn hảo giữa thời trang và tính ứng dụng.</p>\n<p>Để tạo nên sự cuốn hút này, thiết kế xe được trau chuốt với những đường cong mềm mại, phần thân xe gọn gàng giúp tổng thể trở nên nhẹ nhàng và tinh tế hơn. Đây là yếu tố đặc biệt phù hợp với các bạn nữ hoặc những người yêu thích phong cách thanh lịch, tối giản.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Không chỉ dừng lại ở kiểu dáng, bảng màu của xe cũng là điểm cộng lớn. Từ những gam màu pastel nhẹ nhàng như hồng, trắng, xanh nhạt cho đến các màu cá tính như đen, đỏ, xanh đậm… tất cả đều được hoàn thiện tỉ mỉ, giúp người dùng dễ dàng chọn được chiếc xe đúng “gu”.</p>\n<h2><strong>Trang bị hiện đại nâng tầm trải nghiệm sử dụng</strong></h2>\n<p>Không chỉ đẹp, Tailg GR55 còn được trang bị đầy đủ các tiện ích hiện đại, giúp việc sử dụng hàng ngày trở nên dễ dàng và tiện lợi hơn rất nhiều.</p>\n<p>Hệ thống đèn LED trước sau mang lại ánh sáng rõ nét, giúp di chuyển an toàn vào buổi tối hoặc trong điều kiện thiếu sáng. Đồng thời, ánh sáng LED còn góp phần làm tăng tính thẩm mỹ, khiến chiếc xe trở nên hiện đại hơn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr55-day-du-giay-to-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Bảng đồng hồ điện tử hiển thị rõ ràng các thông số như tốc độ, dung lượng pin, quãng đường di chuyển… giúp người lái dễ dàng kiểm soát hành trình mà không cần phỏng đoán.</p>\n<p>Yên xe được thiết kế êm ái, độ đàn hồi tốt, mang lại cảm giác thoải mái kể cả khi di chuyển lâu. Chiều cao yên hợp lý cũng giúp người dùng dễ chống chân, đặc biệt là với những bạn có chiều cao khiêm tốn.</p>\n<h2><strong>Pin 130km – bước đột phá khiến xe đạp điện “lên tầm”</strong></h2>\n<p>Sau khi làm quen với thiết kế và tiện ích, điều khiến nhiều người bất ngờ nhất chính là khả năng vận hành của GR55, đặc biệt là phiên bản pin dung lượng lớn.</p>\n<p>Trước đây, xe đạp điện thường chỉ đi được khoảng 50–80km mỗi lần sạc, khiến người dùng phải sạc thường xuyên và khó đi xa. Tuy nhiên, với phiên bản pin nâng cấp, Tailg GR55 có thể đạt tới 130km/lần sạc trong điều kiện lý tưởng.</p>\n<p>Để đạt được con số này, xe sử dụng pin Lithium-ion – loại pin hiện đại có mật độ năng lượng cao, giúp lưu trữ nhiều điện hơn mà vẫn giữ được kích thước gọn nhẹ. Bên cạnh đó, dung lượng pin lớn hơn và hệ thống quản lý pin thông minh (BMS) giúp tối ưu quá trình sạc – xả, tăng hiệu suất và kéo dài tuổi thọ pin.</p>\n<p>Điều này mang lại lợi ích rất rõ ràng trong thực tế. Người dùng có thể đi học, đi làm, đi chơi nhiều ngày liên tục mà không cần sạc. Với những người bận rộn, đây là một sự thay đổi cực kỳ đáng giá.</p>\n<h2>Đi xa hơn, thoải mái hơn trong mọi nhu cầu di chuyển</h2>\n<p>Với quãng đường lên tới 130km, GR55 không còn bị giới hạn như các <strong>dòng xe đạp điện truyền thống</strong>. Học sinh, sinh viên có thể sử dụng xe cho cả tuần mà chỉ cần sạc một vài lần. Người đi làm có thể di chuyển từ nhà đến công ty, thậm chí đi thêm nhiều việc khác mà không lo hết pin giữa đường.</p>\n<p>Ngay cả những người kinh doanh nhỏ lẻ, giao hàng trong phạm vi thành phố cũng có thể tận dụng lợi thế này để tối ưu công việc mà không cần đầu tư xe máy tốn kém hơn.</p>\n<h2><strong>Vận hành êm ái, ổn định và an toàn</strong></h2>\n<p>Bên cạnh pin, khả năng vận hành của xe cũng là yếu tố rất quan trọng. Tailg GR55 được trang bị động cơ công suất khoảng 800W, đủ mạnh để di chuyển linh hoạt trong đô thị mà vẫn giữ được sự êm ái.</p>\n<p>Xe tăng tốc mượt, không giật, không gây tiếng ồn lớn, mang lại cảm giác dễ chịu khi sử dụng hàng ngày. Đây là điểm rất được lòng người dùng, đặc biệt là những ai thường xuyên di chuyển trong khu dân cư hoặc khu vực đông người.</p>\n<p>Hệ thống phanh được trang bị đầy đủ với phanh đĩa phía trước và phanh cơ hoặc phanh đĩa phía sau, giúp kiểm soát tốc độ tốt và đảm bảo an toàn khi cần dừng gấp.</p>\n<p>Ngoài ra, khả năng chống nước ở mức cơ bản giúp người dùng yên tâm hơn khi đi dưới trời mưa nhẹ hoặc qua những đoạn đường ẩm ướt.</p>\n<h2><strong>Công nghệ thông minh mang lại sự tiện lợi</strong></h2>\n<p>Một số phiên bản của GR55 còn được tích hợp các công nghệ hiện đại như mở khóa bằng thẻ từ hoặc remote, giúp việc sử dụng trở nên tiện lợi hơn và tăng khả năng chống trộm.</p>\n<p>Những chi tiết nhỏ này tuy không quá phô trương nhưng lại góp phần nâng cao trải nghiệm, giúp chiếc xe trở nên “đáng tiền” hơn trong mắt người dùng.</p>\n<h2><strong>Tiết kiệm chi phí – lợi ích lâu dài không thể bỏ qua</strong></h2>\n<p>So với xe xăng, xe điện nói chung và GR55 nói riêng có lợi thế rất lớn về chi phí vận hành. Chi phí sạc điện thấp hơn rất nhiều so với đổ xăng, giúp tiết kiệm đáng kể nếu sử dụng hàng ngày. Với những người đi học hoặc đi làm thường xuyên, khoản tiết kiệm này là không hề nhỏ.</p>\n<p>Bên cạnh đó, pin Lithium có tuổi thọ cao hơn ắc quy truyền thống, ít bị chai và ít phải thay thế. Điều này giúp giảm chi phí phát sinh trong quá trình sử dụng.</p>\n<p>Ngoài ra, cấu tạo xe điện đơn giản hơn, ít bộ phận chuyển động nên ít hỏng vặt, không cần thay dầu hay bảo dưỡng phức tạp như xe xăng.</p>\n<h2><strong>Tailg GR55 – lựa chọn đáng cân nhắc trong phân khúc xe điện thời trang</strong></h2>\n<p>Có thể thấy, <strong>Tailg</strong>&nbsp;GR55 không chỉ là một chiếc xe đẹp mà còn là một sản phẩm được đầu tư nghiêm túc về công nghệ và trải nghiệm người dùng.</p>\n<p>Từ thiết kế nhỏ gọn, thời trang cho đến khả năng vận hành ổn định và đặc biệt là quãng đường 130km ấn tượng, tất cả đều cho thấy đây là một trong những mẫu xe đáng mua trong phân khúc xe đạp điện hiện nay.</p>\n<p>Trong bối cảnh xe điện ngày càng phát triển mạnh mẽ, Tailg GR55 bản pin 130km chính là minh chứng rõ ràng cho xu hướng “xe nhỏ nhưng khả năng lớn”. Không chỉ phù hợp với nhu cầu di chuyển hàng ngày, chiếc xe này còn đáp ứng tốt yêu cầu về thẩm mỹ, sự tiện lợi và chi phí sử dụng lâu dài.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe đạp điện vừa đẹp, vừa bền, vừa đi xa mà không cần lo lắng quá nhiều về việc sạc pin, thì Tailg GR55 chắc chắn là một lựa chọn rất đáng để cân nhắc.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-gr56-day-du-giay-to', 'Xe Đạp Điện Tailg GR56 Đầy Đủ Giấy Tờ', 'tailg', '[\"xe-dap-dien\"]', 15350000, 15350000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Tailg GR56 là mẫu xe đạp điện được sinh ra để cân bằng giữa sự tiện dụng, tính an toàn pháp lý và vẻ ngoài hiện đại, năng động. Chiếc xe này đại diện cho sự lựa chọn thông minh của người tiêu dùng, những người muốn một phương tiện di chuyển nhẹ nhàng, tiết kiệm nhưng vẫn đảm bảo sự minh bạch về nguồn gốc và chất lượng. GR56 là sự kết hợp tinh tế giữa khả năng vận hành êm ái, bền bỉ cùng với sự đảm bảo pháp lý toàn diện, mang lại sự an tâm tuyệt đối trên mọi nẻo đường.</p>\n<p>Tailg GR56 sở hữu một diện mạo thể thao, khỏe khoắn, với các đường nét thiết kế dứt khoát và mạnh mẽ, tạo nên một phong thái năng động, trẻ trung. Thiết kế tổng thể của xe gọn gàng nhưng không hề lỏng lẻo, tạo cảm giác chắc chắn và bền bỉ khi vận hành. Chiếc xe này rất phù hợp với giới trẻ, đặc biệt là học sinh, sinh viên, những người cần một phương tiện cá tính và linh hoạt.</p>', '<p><strong>Tailg GR56</strong> là mẫu <strong>xe đạp điện</strong> được sinh ra để cân bằng giữa sự tiện dụng, tính an toàn pháp lý và vẻ ngoài hiện đại, năng động. Chiếc xe này đại diện cho sự lựa chọn thông minh của người tiêu dùng, những người muốn một phương tiện di chuyển nhẹ nhàng, tiết kiệm nhưng vẫn đảm bảo sự minh bạch về nguồn gốc và chất lượng. GR56 là sự kết hợp tinh tế giữa khả năng vận hành êm ái, bền bỉ cùng với sự đảm bảo pháp lý toàn diện, mang lại sự an tâm tuyệt đối trên mọi nẻo đường.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-7.webp\" alt=\"Xe Đạp Điện Tailg GR56 Đầy Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<h2><br><strong>Ngoại hình năng động, trẻ</strong></h2>\n<p><br><strong>Tailg GR56</strong> sở hữu một diện mạo thể thao, khỏe khoắn, với các đường nét thiết kế dứt khoát và mạnh mẽ, tạo nên một phong thái năng động, trẻ trung. Thiết kế tổng thể của xe gọn gàng nhưng không hề lỏng lẻo, tạo cảm giác chắc chắn và bền bỉ khi vận hành. Chiếc xe này rất phù hợp với giới trẻ, đặc biệt là học sinh, sinh viên, những người cần một phương tiện cá tính và linh hoạt.</p>\n<p><br>Phần đầu xe nổi bật với cụm đèn pha LED lớn, được thiết kế hình học sắc nét, mang lại khả năng chiếu sáng vượt trội, đảm bảo tầm nhìn rõ ràng và an toàn khi di chuyển vào ban đêm. Mặt đồng hồ hiển thị thường là dạng LCD kỹ thuật số nhỏ gọn, cung cấp đầy đủ thông số như vận tốc, dung lượng pin và trạng thái đèn một cách trực quan, dễ dàng quan sát.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-8.webp\" alt=\"Xe Đạp Điện Tailg GR56 Đầy Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<p><br>Yên xe được thiết kế liền mạch, bọc đệm êm ái, tạo cảm giác thoải mái cho người lái, đặc biệt trong những chuyến đi ngắn. Sàn để chân rộng rãi là một ưu điểm lớn, giúp người lái có tư thế ngồi dễ chịu và thoải mái. Ngoại hình này đã biến GR56 thành một biểu tượng của sự tiện dụng và phong cách hiện đại.</p>\n<h2><br><strong>Động cơ vận hành mượt</strong></h2>\n<p><br><strong>Tailg GR56</strong> được trang bị khối động cơ điện BLDC có công suất định mức vừa phải, thường đạt khoảng 350W - 450W. Mức công suất này là sự cân bằng lý tưởng cho một chiếc xe đạp điện, đảm bảo xe có khả năng tăng tốc nhẹ nhàng, mượt mà mà vẫn giữ được tính kinh tế cao trong việc tiêu thụ năng lượng.</p>\n<p><br>Động cơ BLDC hoạt động cực kỳ yên tĩnh, gần như không phát ra tiếng ồn, mang lại cảm giác lướt nhẹ nhàng trên mặt đường. Sự êm ái trong vận hành là một yếu tố quan trọng, tạo ra một không gian di chuyển thư thái, không bị căng thẳng bởi tiếng ồn động cơ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gr56-day-du-giay-to-9.webp\" alt=\"Xe Đạp Điện Tailg GR56 Đầy Đủ Giấy Tờ\" loading=\"lazy\"></p>\n<p><br>Vận tốc tối đa của GR56 được giới hạn ở mức an toàn, khoảng 35 - 40 km/h (tùy thuộc vào quy định đăng kiểm). Tốc độ này đáp ứng tốt nhu cầu di chuyển hàng ngày trong đô thị, phù hợp với mọi lứa tuổi, đồng thời đảm bảo an toàn giao thông, đặc biệt đối với học sinh.</p>\n<h2><br><strong>Hành trình và pin bền</strong></h2>\n<p><br><strong>GR56</strong> thường được trang bị hệ thống ắc quy chì-axit (thường là 4 bình 12Ah hoặc 13Ah) với tổng dung lượng được tối ưu hóa cho phạm vi di chuyển. Hệ thống ắc quy này là sự lựa chọn phổ thông, mang lại sự ổn định và dễ dàng bảo trì.</p>\n<p><br>Nhờ sự cân bằng hoàn hảo giữa công suất động cơ và dung lượng ắc quy, Tailg GR56 có thể đạt được quãng đường di chuyển ổn định, thường từ 40km đến 50km cho mỗi lần sạc đầy. Quãng đường này là đủ cho các nhu cầu đi học, đi làm hoặc các hoạt động trong phạm vi gần.</p>\n<p><br>Thời gian để nạp đầy năng lượng cho bộ ắc quy thường mất khoảng 6 đến 8 tiếng. Bộ sạc thông minh được tích hợp cơ chế tự ngắt điện, một cơ chế bảo vệ thiết yếu giúp kéo dài tuổi thọ của ắc quy và đảm bảo sự an toàn tuyệt đối trong quá trình sạc.</p>\n<h2><br><strong>Cơ cấu an toàn thiết yếu</strong></h2>\n<p><br><strong>Tailg GR56</strong> được trang bị hệ thống an toàn cơ bản nhưng hiệu quả. xe trang bị hệ thống phanh cơ dễ dàng kiểm soát, chi phí bảo trì thấp, đồng thời cung cấp lực hãm ổn định ở dải tốc độ của <strong>xe đạp điện</strong>.</p>\n<p><br>Hệ thống giảm xóc của xe bao gồm phuộc ống lồng phía trước và giảm xóc lò xo trụ phía sau. Hệ thống này được thiết kế để hấp thụ tốt những rung động từ mặt đường, giúp xe vận hành êm ái và không bị nảy quá nhiều khi đi qua các đoạn đường xấu.</p>\n<p><br>Xe sử dụng bộ vành đúc hợp kim hoặc vành nan hoa (tùy phiên bản), đi kèm với lốp có săm hoặc không săm. Lốp xe có kích thước phù hợp, với vân lốp được thiết kế để tăng độ bám đường, đảm bảo sự an toàn khi di chuyển trong điều kiện mặt đường ẩm ướt.</p>\n<h2><br><strong>Tính hợp pháp minh bạch</strong></h2>\n<p><br>Yếu tố \"đầy đủ giấy tờ\" là một ưu điểm vượt trội và quan trọng của <strong>Tailg GR56</strong>. Xe được cung cấp đầy đủ các giấy tờ pháp lý cần thiết, bao gồm Giấy Chứng Nhận Chất Lượng (CQ), Giấy Kiểm Định (XK) và hóa đơn VAT. Sự minh bạch này là cam kết về chất lượng sản phẩm chính hãng.</p>\n<p><br>Việc xe có đầy đủ giấy tờ giúp người dùng hoàn toàn yên tâm khi lưu thông trên đường, không lo bị kiểm tra hoặc phạt vì vi phạm quy định về phương tiện giao thông. Tính hợp pháp này là sự bảo đảm về quyền lợi chính đáng và sự an tâm tuyệt đối cho người sở hữu.</p>\n<p><br>Sự minh bạch về giấy tờ cũng giúp việc bảo hành và bảo trì sau này trở nên dễ dàng và thuận tiện hơn. Người dùng có thể hoàn toàn tin tưởng vào chất lượng và nguồn gốc xuất xứ của chiếc xe, đây là một yếu tố quyết định đối với nhiều khách hàng.</p>\n<h2><br><strong>Tiện ích và tính phổ thông</strong></h2>\n<p><br>Mặc dù là <strong>xe đạp điện</strong>, <strong>GR56</strong> vẫn được trang bị những tiện ích thiết thực. Xe có giỏ xe lớn ở phía trước, rất tiện lợi để đựng sách vở, ba lô hoặc vật phẩm mua sắm hàng ngày. Giỏ xe được thiết kế chắc chắn, không gây rung lắc khi xe di chuyển.</p>\n<p><br>Sàn để chân rộng rãi cùng với bàn đạp trợ lực là một đặc điểm không thể thiếu của dòng xe đạp điện. Bàn đạp trợ lực cho phép người dùng chủ động rèn luyện sức khỏe hoặc di chuyển khi ắc quy cạn kiệt, tăng tính linh hoạt và giảm thiểu sự phụ thuộc vào nguồn điện.</p>\n<p><br>Các nút điều khiển chức năng (còi, đèn, xi-nhan) được bố trí hợp lý trên tay lái, dễ dàng thao tác mà không gây phân tâm cho người lái. Sự đơn giản, dễ sử dụng này đã biến <strong>xe đạp điện Tailg GR56</strong> thành một phương tiện giao thông phổ thông, dễ dàng tiếp cận với mọi đối tượng khách hàng.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to', 'Xe Đạp Điện Tailg GX30 Chính Hãng (Đầy Đủ Giấy Tờ)', 'tailg', '[\"xe-dap-dien\"]', 13450000, 13450000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Trong nhiều năm qua, Tailg đã khẳng định vị thế của mình là một trong những thương hiệu xe điện uy tín hàng đầu, được người tiêu dùng tin tưởng nhờ chất lượng ổn định, thiết kế hiện đại và khả năng vận hành bền bỉ. Các dòng xe của Tailg không chỉ đáp ứng nhu cầu di chuyển hằng ngày mà còn bắt kịp xu hướng sống xanh, tiết kiệm và thông minh của giới trẻ hiện đại.</p>\n<p>Tiếp nối triết lý đó, xe đạp điện Tailg GX30 ra đời như một lựa chọn nổi bật trong phân khúc xe điện thể thao. Sở hữu ngoại hình mạnh mẽ, động cơ khỏe cùng hệ thống ắc quy bền bỉ, GX30 mang đến trải nghiệm di chuyển linh hoạt, an toàn và đầy cá tính cho học sinh, sinh viên cũng như người đi làm trẻ.</p>', '<p>Trong nhiều năm qua, Tailg đã khẳng định vị thế của mình là một trong những thương hiệu xe điện uy tín hàng đầu, được người tiêu dùng tin tưởng nhờ chất lượng ổn định, thiết kế hiện đại và khả năng vận hành bền bỉ. Các dòng xe của Tailg không chỉ đáp ứng nhu cầu di chuyển hằng ngày mà còn bắt kịp xu hướng sống xanh, tiết kiệm và thông minh của giới trẻ hiện đại.</p>\n<p>Tiếp nối triết lý đó, xe đạp điện Tailg GX30 ra đời như một lựa chọn nổi bật trong phân khúc xe điện thể thao. Sở hữu ngoại hình mạnh mẽ, động cơ khỏe cùng hệ thống ắc quy bền bỉ, GX30 mang đến trải nghiệm di chuyển linh hoạt, an toàn và đầy cá tính cho học sinh, sinh viên cũng như người đi làm trẻ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế tổng thể đậm chất thể thao, khác biệt ngay từ cái nhìn đầu tiên</strong></h2>\n<p>Ngay từ lần đầu chạm mắt, Tailg GX30 đã tạo được dấu ấn rõ rệt nhờ ngoại hình cứng cáp và đầy cá tính. Xe sở hữu phong cách thiết kế thể thao hiện đại, với những đường nét góc cạnh, dứt khoát, mang đến cảm giác mạnh mẽ và chắc chắn. Kiểu dáng này không chỉ giúp GX30 nổi bật giữa dòng <strong>xe đạp điện phổ thông</strong> mà còn rất phù hợp với những người trẻ yêu thích phong cách khỏe khoắn, năng động.</p>\n<p>Phần đầu xe được tạo hình ấn tượng với mặt nạ lớn, kết hợp hài hòa cùng hệ thống đèn LED hiện đại. Tổng thể phía trước mang lại cảm giác vững chãi, tạo sự tự tin cho người lái khi di chuyển trên nhiều dạng địa hình khác nhau. Thân xe được thiết kế gọn gàng nhưng không hề mảnh mai, ngược lại còn toát lên vẻ cứng cáp, giúp xe trông giống một mẫu xe máy điện thể thao thu nhỏ.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Khung xe của Tailg GX30 được chế tạo từ hợp kim thép cao cấp, cho khả năng chịu lực tốt và độ bền cao trong quá trình sử dụng lâu dài. Kết cấu khung chắc chắn giúp xe vận hành ổn định, hạn chế rung lắc khi đi qua các đoạn đường gồ ghề, đồng thời đảm bảo khả năng chịu tải phù hợp với nhiều đối tượng người dùng khác nhau.</p>\n<h2><strong>Màu sắc và tem xe tạo điểm nhấn cá tính</strong></h2>\n<p>Bên cạnh thiết kế hình khối mạnh mẽ, Tailg GX30 còn ghi điểm nhờ bảng màu đa dạng, mang đậm hơi thở trẻ trung và hiện đại. Các gam màu như đen xanh lá, đỏ đen, xanh da trời đen, trắng, bạc, xám xi măng hay kem sữa đều được phối một cách tinh tế, giúp xe vừa nổi bật vừa giữ được sự hài hòa tổng thể.</p>\n<p>Lớp sơn cao cấp được xử lý bằng công nghệ hiện đại giúp bề mặt xe luôn bóng đẹp, hạn chế bong tróc và phai màu theo thời gian. Đây là yếu tố rất quan trọng với những người sử dụng xe hằng ngày, thường xuyên tiếp xúc với nắng mưa và môi trường đô thị nhiều khói bụi.</p>\n<p>Bộ tem xe được thiết kế theo phong cách thể thao, đường nét sắc sảo và phối màu bắt mắt, tạo nên điểm nhấn thị giác rõ ràng. Nhờ đó, GX30 luôn nổi bật khi di chuyển trên đường, dễ dàng thu hút ánh nhìn và thể hiện rõ cá tính của người sở hữu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-gx30-chinh-hang-day-du-giay-to-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><strong>Đèn chiếu sáng LED hiện đại, an toàn khi di chuyển ban đêm</strong></p>\n<p>Tailg GX30 được trang bị hệ thống chiếu sáng LED đồng bộ trên toàn xe, mang lại hiệu quả sử dụng cao và tính thẩm mỹ hiện đại. Đèn pha LED phía trước cho ánh sáng mạnh, vùng chiếu rộng, giúp người lái quan sát rõ ràng hơn trong điều kiện thiếu sáng, đặc biệt là khi di chuyển vào buổi tối hoặc sáng sớm.</p>\n<p>Đèn xi nhan và đèn hậu LED không chỉ đảm bảo khả năng nhận diện tốt từ xa mà còn góp phần tăng độ an toàn khi lưu thông trong khu vực đông phương tiện. Một số chi tiết LED trang trí dọc thân xe giúp GX30 trở nên nổi bật hơn vào ban đêm, đồng thời tăng khả năng nhận diện trong điều kiện ánh sáng yếu.</p>\n<h2><strong>Đồng hồ điện tử trực quan, dễ quan sát</strong></h2>\n<p>Bảng đồng hồ của Tailg GX30 sử dụng màn hình LED điện tử hiện đại, hiển thị đầy đủ các thông tin cần thiết trong quá trình vận hành. Các thông số như vận tốc, quãng đường di chuyển, mức năng lượng ắc quy được hiển thị rõ ràng, trực quan, giúp người lái dễ dàng theo dõi và chủ động hơn trong mỗi hành trình.</p>\n<p>Thiết kế đồng hồ đơn giản, dễ nhìn, phù hợp với mọi đối tượng sử dụng, kể cả những người lần đầu làm quen với xe đạp điện.</p>\n<h2><strong>Hệ thống phanh và bánh xe đảm bảo an toàn tối đa</strong></h2>\n<p>Yếu tố an toàn luôn được Tailg chú trọng, và<strong> GX30</strong>cũng không ngoại lệ. Xe được trang bị phanh đĩa cho cả bánh trước và bánh sau, giúp tăng hiệu quả phanh và giảm quãng đường dừng xe trong những tình huống khẩn cấp. Hệ thống phanh hoạt động ổn định, mang lại cảm giác yên tâm cho người lái khi di chuyển trong khu vực đông đúc.</p>\n<p>Bánh xe không săm là một điểm cộng lớn, giúp hạn chế tình trạng xì hơi đột ngột khi cán phải vật nhọn. Điều này đặc biệt hữu ích với những người thường xuyên di chuyển quãng đường dài hoặc sử dụng xe hằng ngày.</p>\n<h2><strong>Động cơ mạnh mẽ, phù hợp di chuyển đô thị</strong></h2>\n<p>Tailg GX30 được trang bị động cơ điện công suất khoảng 800W, cho khả năng vận hành mạnh mẽ và ổn định. Xe có thể đạt vận tốc tối đa khoảng 50km/h, đáp ứng tốt nhu cầu di chuyển trong đô thị, từ đi học, đi làm cho đến những chuyến đi dạo cuối tuần.</p>\n<p>Động cơ hoạt động êm ái, ít tiếng ồn, mang lại trải nghiệm lái thoải mái và thân thiện với môi trường. Khả năng tăng tốc mượt mà giúp người lái dễ dàng hòa vào dòng xe cộ đông đúc mà không gặp cảm giác giật cục hay ì máy.</p>\n<h2><strong>Hệ thống ắc quy bền bỉ, quãng đường di chuyển ấn tượng</strong></h2>\n<p>Một trong những điểm mạnh nổi bật của Tailg GX30 chính là hệ thống ắc quy chất lượng cao. Xe sử dụng cấu hình ắc quy dung lượng lớn, phổ biến với 4 bình ắc quy, mang lại khả năng di chuyển từ 80km đến hơn 100km sau mỗi lần sạc đầy, tùy điều kiện sử dụng và tải trọng.</p>\n<p>Với quãng đường di chuyển như vậy, GX30 hoàn toàn đáp ứng được nhu cầu đi lại hằng ngày của học sinh, sinh viên hay người đi làm mà không cần lo lắng việc sạc xe quá thường xuyên. Thời gian sạc khoảng 8 tiếng, rất tiện lợi để sạc qua đêm, giúp xe luôn sẵn sàng cho ngày mới.</p>\n<h2><strong>Trải nghiệm lái êm ái, thoải mái trong mọi hành trình</strong></h2>\n<p>Không chỉ mạnh mẽ, Tailg GX30 còn mang đến trải nghiệm lái dễ chịu nhờ hệ thống giảm xóc hoạt động hiệu quả. Xe vận hành êm ái trên nhiều dạng địa hình khác nhau, hạn chế rung lắc khi đi qua ổ gà hay đoạn đường xấu.</p>\n<p>Yên xe được thiết kế liền khối, bọc da êm ái, mang lại cảm giác thoải mái cho cả người lái và người ngồi sau. Sàn để chân rộng rãi giúp tư thế ngồi tự nhiên, không gây mỏi khi di chuyển trong thời gian dài. Chiều cao yên khoảng 725–730mm phù hợp với vóc dáng của đa số người Việt, kể cả học sinh cấp 2, cấp 3 hay người lớn.</p>\n<h2><strong>Giải pháp di chuyển tiết kiệm và thân thiện môi trường</strong></h2>\n<p>So với xe máy xăng truyền thống, Tailg GX30 giúp tiết kiệm đáng kể chi phí vận hành. Chi phí sạc điện thấp, không tốn xăng, không phát thải khí độc hại ra môi trường, góp phần giảm ô nhiễm không khí và tiếng ồn trong đô thị.</p>\n<p>Đây là lựa chọn phù hợp với xu hướng sống xanh, sống thông minh mà ngày càng nhiều người trẻ hướng tới.</p>\n<p>Với thiết kế thể thao cá tính, động cơ mạnh mẽ, hệ thống ắc quy bền bỉ, khả năng di chuyển xa cùng nhiều trang bị an toàn hiện đại, <strong>xe đạp điện</strong> Tailg GX30 xứng đáng là người bạn đồng hành đáng tin cậy trong cuộc sống hằng ngày. Mẫu xe này không chỉ đáp ứng tốt nhu cầu đi lại mà còn thể hiện phong cách sống năng động, chủ động và hiện đại của người sử dụng. Nếu bạn đang tìm kiếm một chiếc xe đạp điện bền bỉ, đẹp mắt, vận hành ổn định và tiết kiệm chi phí, Tailg GX30 chắc chắn là lựachọn không nên bỏ qua.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-js32-day-du-giay-to', 'Xe Đạp Điện Tailg JS32 (Đầy Đủ Giấy Tờ)', 'tailg', '[\"xe-dap-dien\"]', 13650000, 13650000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js32-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-js50-day-du-giay-to', 'Xe Đạp Điện Tailg JS50 (Đầy Đủ Giấy Tờ)', 'tailg', '[\"xe-dap-dien\"]', 16250000, 16250000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Xe Đạp Điện Tailg JS50 là mẫu xe điện bán chạy, được lòng học sinh, sinh viên và người dùng nữ nhờ thiết kế thanh lịch, trang nhã. JS50 sở hữu ngoại hình bắt mắt, hiệu năng vận hành ổn định, quãng đường di chuyển ấn tượng và sự minh bạch về pháp lý với đầy đủ giấy tờ, đảm bảo người dùng hoàn toàn yên tâm khi lưu thông. Chiếc xe này đại diện cho sự kết hợp hài hòa giữa tính thẩm mỹ, hiệu suất và sự an toàn trong môi trường đô thị hiện đại.</p>\n<p>Tailg JS50 sở hữu vẻ ngoài cổ điển nhưng vẫn toát lên nét hiện đại, nữ tính. Xe được thiết kế theo phong cách tối giản, với các đường nét mềm mại, bo tròn, tạo cảm giác thân thiện và dễ điều khiển. Kích thước xe được tối ưu hóa, không quá lớn, giúp người dùng dễ dàng dắt và quay đầu xe trong không gian hẹp.</p>', '<p><strong>Xe Đạp Điện Tailg JS50</strong> là mẫu <strong>xe điện bán chạy</strong>, được lòng học sinh, sinh viên và người dùng nữ nhờ thiết kế thanh lịch, trang nhã. JS50 sở hữu ngoại hình bắt mắt, hiệu năng vận hành ổn định, quãng đường di chuyển ấn tượng và sự minh bạch về pháp lý với đầy đủ giấy tờ, đảm bảo người dùng hoàn toàn yên tâm khi lưu thông. Chiếc xe này đại diện cho sự kết hợp hài hòa giữa tính thẩm mỹ, hiệu suất và sự an toàn trong môi trường đô thị hiện đại.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-7.webp\" alt=\"Xe Đạp Điện Tailg Princess JS50\" loading=\"lazy\"></p>\n<h2><br><strong>Ngoại hình và ấn tượng</strong></h2>\n<p><br><strong>Tailg JS50</strong> sở hữu vẻ ngoài cổ điển nhưng vẫn toát lên nét hiện đại, nữ tính. Xe được thiết kế theo phong cách tối giản, với các đường nét mềm mại, bo tròn, tạo cảm giác thân thiện và dễ điều khiển. Kích thước xe được tối ưu hóa, không quá lớn, giúp người dùng dễ dàng dắt và quay đầu xe trong không gian hẹp.</p>\n<p><br>Cụm đèn pha phía trước được thiết kế lớn, hình tròn hoặc oval tùy phiên bản, sử dụng công nghệ LED hoặc Halogen cường độ cao, đảm bảo khả năng chiếu sáng tốt vào ban đêm và tăng tính an toàn. Đèn xi-nhan và đèn hậu cũng được chăm chút tỉ mỉ, tích hợp hài hòa vào tổng thể xe, tạo nên một cái nhìn liền mạch, sang trọng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-8.webp\" alt=\"Xe Đạp Điện Tailg Princess JS50\" loading=\"lazy\"></p>\n<p><br>Mặt đồng hồ hiển thị của JS50 được thiết kế trực quan, rõ ràng, hiển thị đầy đủ các thông số quan trọng như vận tốc, lượng pin còn lại và quãng đường đã đi. Điều này giúp người lái dễ dàng theo dõi tình trạng xe, chủ động hơn trong việc sạc điện. Xe thường có nhiều tùy chọn màu sắc tươi sáng như trắng, hồng, xanh ngọc, rất được lòng phái nữ.</p>\n<h2><br><strong>Sức mạnh từ động cơ</strong></h2>\n<p><br><strong>Tailg JS50</strong> được trang bị động cơ điện không chổi than (BLDC) có công suất định mức khoảng 800W (tùy phiên bản). Mức công suất này được xem là lý tưởng cho xe đạp điện, cung cấp đủ sức mạnh để xe vận hành ổn định, linh hoạt trên nhiều loại địa hình, kể cả khi lên dốc hoặc chở thêm người.</p>\n<p><br>Động cơ BLDC mang lại ưu điểm vượt trội về hiệu suất, hoạt động êm ái, giảm thiểu tiếng ồn và ít cần bảo trì hơn so với động cơ có chổi than truyền thống. Công suất đầu ra ổn định giúp xe đạt được vận tốc tối đa khoảng 45-50 km/h (tùy thuộc vào quy định và cấu hình pin/ắc quy).</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-js50-day-du-giay-to-9.webp\" alt=\"Xe Đạp Điện Tailg Princess JS50\" loading=\"lazy\"></p>\n<p><br>Sức mạnh của động cơ được truyền tải mượt mà qua hệ thống truyền động, cho phép xe tăng tốc nhẹ nhàng, phù hợp với môi trường giao thông đô thị đông đúc. Tải trọng tối đa của xe thường đạt khoảng 150 - 180kg, cho thấy khung xe và động cơ có khả năng chịu tải tốt, đáp ứng nhu cầu di chuyển của hai người.</p>\n<h2><br><strong>Pin và quãng đường</strong></h2>\n<p><br>Điểm nổi bật nhất của<strong>&nbsp;JS50</strong> nằm ở khả năng di chuyển ấn tượng sau mỗi lần sạc đầy. Xe sử dụng hệ thống ắc quy chì-axit (thường là 5 bình 20Ah hoặc 22.3Ah), hoặc có thể nâng cấp lên Pin Lithium-ion.</p>\n<p><br>Với cấu hình ắc quy tiêu chuẩn, <strong>Tailg JS50</strong> có thể di chuyển quãng đường từ 80km đến 90km cho một lần sạc đầy. Đây là một con số rất ấn tượng, giúp người dùng hoàn toàn thoải mái di chuyển đi học, đi làm, hoặc đi chơi trong phạm vi thành phố mà không cần phải lo lắng về việc hết điện giữa đường.</p>\n<p><br>Thời gian sạc đầy cho bộ ắc quy thường dao động từ 8 đến 12 tiếng (tùy thuộc vào dung lượng và loại sạc). Xe được trang bị hệ thống sạc tự động ngắt khi ắc quy đầy, giúp bảo vệ ắc quy, kéo dài tuổi thọ và đảm bảo an toàn điện.</p>\n<h2><br><strong>Hệ thống phanh an toàn</strong></h2>\n<p><br>Sự an toàn luôn là yếu tố được Tailg ưu tiên hàng đầu, đặc biệt với một dòng xe hướng đến đối tượng học sinh, sinh viên. <strong>JS50</strong> thường được trang bị phanh đĩa ở bánh trước và phanh cơ (tang trống) ở bánh sau.</p>\n<p><br>Hệ thống phanh đĩa trước cung cấp lực hãm mạnh mẽ, độ nhạy cao và khả năng tản nhiệt tốt, giúp người lái kiểm soát tốc độ một cách chính xác trong các tình huống cần phanh gấp. Phanh cơ sau có độ bền cao và dễ dàng bảo trì, kết hợp với phanh đĩa trước tạo nên sự cân bằng, giúp xe dừng lại an toàn và ổn định.</p>\n<p><br>Bên cạnh hệ thống phanh hiệu quả, xe còn được trang bị lốp không săm (Kenda 3.00-10 hoặc tương đương), giúp tăng độ bám đường, giảm thiểu nguy cơ bị thủng lốp đột ngột. Vành xe thép đúc nguyên khối hoặc hợp kim nhôm không chỉ tăng tính thẩm mỹ mà còn cải thiện độ cứng vững của bánh xe, góp phần vào sự ổn định chung khi xe vận hành.</p>\n<h2><br><strong>Thiết kế tiện nghi, thực dụng</strong></h2>\n<p><br><strong>Tailg JS50</strong> được tích hợp nhiều tiện ích nhỏ nhưng vô cùng hữu dụng cho người dùng hàng ngày.</p>\n<p><br>+ Cốp xe rộng rãi: Mặc dù là <strong>xe đạp điện</strong>, JS50 vẫn được thiết kế cốp xe dưới yên tương đối rộng, đủ để chứa mũ bảo hiểm nửa đầu, áo mưa và các vật dụng cá nhân khác, tăng tính tiện lợi so với nhiều mẫu xe điện khác chỉ có giỏ phía trước.</p>\n<p><br>+ Sàn để chân lớn: Sàn để chân rộng rãi, thoải mái, giúp người lái có tư thế ngồi dễ chịu, đặc biệt trong các hành trình dài. Sàn cũng được thiết kế chống trơn trượt, đảm bảo an toàn khi lái xe trong điều kiện ẩm ướt.</p>\n<p><br>+ Giảm xóc chất lượng: Xe được trang bị hệ thống giảm xóc trước dạng ống lồng thủy lực và giảm xóc sau lò xo trụ, có khả năng hấp thụ xung động tốt, giúp xe vận hành êm ái, giảm thiểu rung lắc khi đi qua các đoạn đường gồ ghề, mang lại trải nghiệm lái thoải mái.</p>\n<p><br>+ Chìa khóa thông minh: Nhiều phiên bản <strong>JS50</strong> được trang bị khóa chống trộm điện tử, khóa từ hoặc thậm chí là khởi động thông minh, tăng cường khả năng bảo vệ xe khỏi bị trộm cắp.</p>\n<h2><br><strong>Tính pháp lý, giấy tờ</strong></h2>\n<p><br>Đặc điểm quan trọng nhất của dòng xe này là việc \"Đầy Đủ Giấy Tờ\", bao gồm giấy chứng nhận chất lượng, hóa đơn VAT và giấy đăng kiểm. Điều này đảm bảo chiếc xe được đăng ký chính chủ và cấp biển số theo đúng quy định của pháp luật Việt Nam.</p>\n<p><br>Việc có đầy đủ giấy tờ giúp người dùng tránh được các rắc rối về pháp lý khi tham gia giao thông và thể hiện nguồn gốc, xuất xứ rõ ràng của sản phẩm. Người điều khiển xe đạp điện có biển số hợp lệ sẽ tuân thủ nghiêm ngặt các quy định về an toàn giao thông, nâng cao ý thức chấp hành luật pháp. Đối với học sinh, đây là một yếu tố then chốt, giúp phụ huynh hoàn toàn yên tâm về mặt pháp luật khi con em mình sử dụng phương tiện di chuyển.</p>\n<h2><br><strong>Đánh giá tổng quan sử dụng</strong></h2>\n<p><br><strong>Tailg JS50</strong> là một chiếc <strong>xe điện</strong> hoàn hảo cho nhu cầu đi lại hàng ngày. Sự kết hợp giữa thiết kế thanh lịch, động cơ mạnh mẽ, quãng đường di chuyển xa và hệ thống an toàn được đầu tư kỹ lưỡng (phanh đĩa, lốp không săm) tạo nên một sản phẩm chất lượng cao trong phân khúc xe điện.</p>\n<p><br>Khả năng tiết kiệm chi phí năng lượng là một lợi thế lớn, khiến chiếc xe trở thành giải pháp kinh tế và thân thiện với môi trường. Xe không yêu cầu bằng lái, dễ sử dụng, phù hợp với nhiều đối tượng người dùng.</p>\n<p><br><strong>Xe đạp điện Tailg&nbsp;JS50</strong> là một lựa chọn thông minh, an toàn và phong cách cho cuộc sống đô thị, với cam kết về mặt pháp lý rõ ràng, mang lại sự an tâm tuyệt đối cho người sử dụng.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah', 'Xe Đạp Điện Tailg JY33 Mini Bike 4 ACQUY 13Ah', 'tailg', '[\"xe-dap-dien\"]', 11350000, 11350000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-6.webp\"]', '[]', '[]', '[]', '<p>Tailg JY33 Mini Bike, với cấu hình 4 ắc quy 13Ah, là một tuyên ngôn về sự tối giản và tiện lợi trong Yên Thoa. Mẫu xe này không chạy theo trào lưu tốc độ hay kích thước đồ sộ, mà ngược lại, lại tôn vinh vẻ đẹp nhỏ gọn, tinh tế và sự linh hoạt tối đa. JY33 được thiết kế dành cho những người tìm kiếm sự dễ dàng, nhẹ nhàng trong di chuyển hàng ngày, một phương tiện lý tưởng để lướt qua những con phố chật hẹp, tránh xa sự phức tạp của giao thông đô thị.</p>\n<p>JY33 Mini Bike gây ấn tượng mạnh mẽ với kích thước nhỏ nhắn, đáng yêu, nhưng vẫn giữ được sự cân đối và vẻ ngoài chắc chắn. Thiết kế tổng thể nghiêng về phong cách retro, với những đường cong mềm mại, bo tròn, tạo nên một sự lãng mạn nhẹ nhàng, rất hợp nhãn với học sinh và nữ giới. Chiếc xe này như một món trang sức di động, làm nổi bật cá tính thanh lịch của người sở hữu.</p>', '<p><strong>Tailg JY33 Mini Bike</strong>, với cấu hình 4 ắc quy 13Ah, là một tuyên ngôn về sự tối giản và tiện lợi trong Yên Thoa. Mẫu xe này không chạy theo trào lưu tốc độ hay kích thước đồ sộ, mà ngược lại, lại tôn vinh vẻ đẹp nhỏ gọn, tinh tế và sự linh hoạt tối đa. JY33 được thiết kế dành cho những người tìm kiếm sự dễ dàng, nhẹ nhàng trong di chuyển hàng ngày, một phương tiện lý tưởng để lướt qua những con phố chật hẹp, tránh xa sự phức tạp của giao thông đô thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-7.webp\" alt=\"Xe Đạp Điện Tailg JY33 Mini Bike 4 ACQUY 13Ah\" loading=\"lazy\"></p>\n<h2><br><strong>Diện mạo tiểu thư</strong></h2>\n<p><br><strong>JY33 Mini Bike</strong> gây ấn tượng mạnh mẽ với kích thước nhỏ nhắn, đáng yêu, nhưng vẫn giữ được sự cân đối và vẻ ngoài chắc chắn. Thiết kế tổng thể nghiêng về phong cách retro, với những đường cong mềm mại, bo tròn, tạo nên một sự lãng mạn nhẹ nhàng, rất hợp nhãn với học sinh và nữ giới. Chiếc xe này như một món trang sức di động, làm nổi bật cá tính thanh lịch của người sở hữu.</p>\n<p><br>Khung xe được chế tạo từ vật liệu chịu lực cao nhưng vẫn giữ được trọng lượng nhẹ, giúp việc điều khiển và dắt xe trở nên vô cùng dễ dàng. Cụm đèn pha tròn, lớn, mang nét cổ điển, được trang bị thấu kính phản quang tốt, cung cấp luồng sáng dịu dàng nhưng hiệu quả, đảm bảo an toàn thị giác cho người lái. Các chi tiết nhựa và nước sơn được hoàn thiện tỉ mỉ, tạo nên một bề mặt bóng bẩy, có độ bền màu cao, chống phai nhạt dưới ánh nắng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-8.webp\" alt=\"Xe Đạp Điện Tailg JY33 Mini Bike 4 ACQUY 13Ah\" loading=\"lazy\"></p>\n<p><br>Mặt đồng hồ hiển thị của <strong>JY33</strong> là sự kết hợp giữa truyền thống và hiện đại, thường là đồng hồ cơ hoặc LCD nhỏ gọn, hiển thị các thông số thiết yếu như vận tốc và dung lượng pin còn lại. Yên xe được thiết kế liền khối, có độ dày và độ đàn hồi tốt, mang lại sự thoải mái tuyệt đối cho những quãng đường ngắn. Thiết kế yên thấp và sàn để chân rộng rãi là điểm cộng lớn, giúp người lái dễ dàng chống chân và giữ thăng bằng.</p>\n<h2><br><strong>Lực kéo vừa đủ</strong></h2>\n<p><br><strong>Tailg JY33</strong> được trang bị khối động cơ điện không chổi than BLDC có công suất định mức khiêm tốn, thường nằm trong khoảng 250W – 350W. Đây là mức công suất lý tưởng cho một chiếc xe đạp điện, được tính toán để tối ưu hóa hiệu suất năng lượng và đảm bảo sự êm ái, yên tĩnh tuyệt đối khi vận hành. Động cơ này hoạt động gần như không phát ra tiếng động, mang lại cảm giác lướt nhẹ nhàng trên mặt đường.</p>\n<p><br>Động cơ cung cấp lực kéo ổn định, giúp xe tăng tốc mượt mà, không bị giật cục. Khả năng duy trì vận tốc tối đa an toàn, thường đạt khoảng 25 - 30 km/h, phù hợp với quy định về xe đạp điện. Tốc độ này rất thích hợp cho môi trường học đường và khu dân cư, nơi sự an toàn luôn được đặt lên hàng đầu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy33-mini-bike-4-acquy-13ah-9.webp\" alt=\"Xe Đạp Điện Tailg JY33 Mini Bike 4 ACQUY 13Ah\" loading=\"lazy\"></p>\n<p><br>JY33 đại diện cho triết lý \"đi chậm mà chắc\", không cần sức mạnh quá lớn nhưng vẫn đảm bảo sự linh hoạt và tính cơ động cao. Hệ thống truyền động được thiết kế đơn giản, giúp xe dễ dàng bảo dưỡng và có độ tin cậy cao, là một người bạn đồng hành thủy chung, ít khi gây ra sự cố bất ngờ.</p>\n<h2><br><strong>Năng lượng hành trình</strong></h2>\n<p><br>Phiên bản Mini Bike này sử dụng hệ thống 4 bình ắc quy chì-axit 13Ah. Đây là cấu hình năng lượng tiêu chuẩn, được cân đối hoàn hảo với công suất động cơ, mang lại một phạm vi hoạt động đủ rộng cho các hoạt động hàng ngày. Tổng dung lượng ắc quy cung cấp khả năng di chuyển ước tính khoảng 50km – 60km cho mỗi lần sạc đầy (tùy thuộc vào điều kiện sử dụng thực tế).</p>\n<p><br>Quãng đường 60km là một con số thuyết phục đối với xe đạp điện, đủ để người dùng di chuyển đi học, đi làm, hoặc thực hiện các công việc lặt vặt trong thành phố mà không cần phải bận tâm về việc sạc điện liên tục. Điều này mang lại sự tự tin và giảm thiểu tối đa sự phụ thuộc vào nguồn điện sạc công cộng.</p>\n<p><br>Thời gian sạc đầy cho bộ ắc quy 13Ah thường mất từ 6 đến 8 tiếng. Bộ sạc thông minh được tích hợp cơ chế tự động ngắt, có vai trò như một vệ sĩ bảo vệ ắc quy, ngăn ngừa tình trạng sạc quá tải, từ đó kéo dài tuổi thọ của pin và giữ vững hiệu suất hoạt động lâu dài.</p>\n<h2><br><strong>Chi tiết đảm bảo an toàn</strong></h2>\n<p><br><strong>JY33 Mini Bike</strong> được trang bị những cơ cấu an toàn cơ bản nhưng cực kỳ hiệu quả. <strong>Xe đạp điện</strong> sử dụng hệ thống phanh cơ cho cả 2 bánh. Phanh cơ hoạt động đáng tin cậy ở tốc độ thấp, cung cấp lực hãm vừa phải, giúp người lái, đặc biệt là các bạn học sinh, dễ dàng kiểm soát và dừng xe một cách êm ái.</p>\n<p><br>Hệ thống giảm xóc của xe bao gồm phuộc ống lồng phía trước và giảm xóc lò xo trụ phía sau. Các bộ phận này phối hợp nhịp nhàng, đóng vai trò như bộ lọc hấp thụ xung động từ mặt đường, mang lại trải nghiệm lái êm ái, không gây khó chịu khi đi qua các đoạn đường có độ nhấp nhô nhẹ. Sự êm ái là một yếu tố then chốt cho sự thoải mái hàng ngày.</p>\n<p><br>Xe được trang bị lốp có săm, có kích thước và vân lốp được thiết kế để tăng độ bám đường, đảm bảo sự ổn định khi vào cua hoặc di chuyển dưới trời mưa. Trọng tâm thấp của xe cũng là một yếu tố an toàn quan trọng, giúp xe giữ thăng bằng tốt, ngay cả khi người lái chưa có nhiều kinh nghiệm.</p>\n<h2><br><strong>Tiện ích thông minh</strong></h2>\n<p><br>Mặc dù mang danh \"Mini Bike\", <strong>Tailg JY33</strong> vẫn được trang bị những tiện ích tinh tế, nâng cao chất lượng trải nghiệm. Chiếc xe này thường được tích hợp một giỏ xe lớn, chắc chắn ở phía trước, một không gian lý tưởng để đựng sách vở, ba lô hoặc vật phẩm mua sắm hàng ngày. Giỏ xe được gắn cố định, hạn chế tối đa sự rung lắc khi xe đang chạy.</p>\n<p><br>Sự hiện diện của bàn đạp trợ lực là một điểm khác biệt quan trọng của xe đạp điện. Tính năng này cho phép người lái có thể đạp xe như một chiếc xe đạp thông thường khi muốn rèn luyện sức khỏe, hoặc trong trường hợp ắc quy cạn kiệt, đảm bảo hành trình không bao giờ bị gián đoạn.</p>\n<p><br>Các nút điều khiển chức năng như còi, đèn, xi-nhan được bố trí trực quan, dễ dàng thao tác bằng ngón tay cái mà không cần phải rời tay khỏi tay lái. Xe cũng thường được trang bị khóa chống trộm cơ bản, bảo vệ phương tiện khỏi những tác động xấu từ bên ngoài.</p>\n<h2><br><strong>Nhịp điệu đường phố</strong></h2>\n<p><br>Trải nghiệm lái <strong>xe đạp điện</strong>&nbsp;<strong>Tailg JY33</strong> là một sự thư giãn nhẹ nhàng. Trọng lượng xe nhẹ giúp người lái dễ dàng xoay trở trong không gian hẹp hoặc dắt xe lên lề. Đặc tính lướt êm, không tiếng ồn của động cơ điện tạo ra một không gian cá nhân tĩnh lặng, giúp người lái tập trung hơn vào hành trình và tận hưởng sự yên bình giữa lòng phố thị ồn ào.</p>\n<p><br><strong>Xe đạp điện Tailg</strong> có khả năng đáp ứng tốt các yêu cầu di chuyển trong phạm vi gần và trung bình, là giải pháp giao thông hoàn hảo cho học sinh, sinh viên và người nội trợ. Sự đơn giản trong thao tác và tính kinh tế vượt trội biến JY33 trở thành một sự lựa chọn không thể hợp lý hơn cho cuộc sống đô thị.</p>\n<p><br><strong>Tailg JY33 Mini Bike</strong>, với thiết kế quyến rũ và hiệu năng ổn định, là một chiếc <strong>xe điện</strong> đáng tin cậy. Nó là sự kết hợp hài hòa giữa phong cách tối giản và công nghệ điện tiện lợi, khẳng định vị thế của mình như một phương tiện giao thông an toàn, kinh tế và đầy cá tính.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac', 'Xe Đạp Điện Tailg JY34 - Dùng 4 Bình 13Ah 60km/1 Lần Sạc', 'tailg', '[\"xe-dap-dien\"]', 12750000, 12750000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-5.webp\"]', '[]', '[]', '[]', '<p>Trong bức tranh giao thông đô thị ngày càng chật chội và nhiều áp lực, việc lựa chọn một phương tiện di chuyển không còn đơn thuần là đi cho tới nơi. Người dùng ngày nay quan tâm nhiều hơn đến cảm giác sử dụng, chi phí dài hạn và cả tác động đến môi trường sống xung quanh. Những con đường đông đúc, giờ cao điểm kéo dài và chi phí xăng dầu liên tục biến động khiến nhiều người bắt đầu nhìn lại thói quen di chuyển của mình.</p>\n<p>Chính trong bối cảnh đó, Xe Đạp Điện Tailg JY34 xuất hiện như một giải pháp di chuyển vừa đủ thông minh, vừa đủ tinh tế, dành cho những ai muốn sống chậm hơn một nhịp nhưng vẫn luôn chủ động trên mọi cung đường. Không chỉ là phương tiện đi lại hằng ngày, Tailg JY34 còn phản ánh một lối sống mới – nơi sự tiện lợi, tiết kiệm và bền vững được đặt lên hàng đầu.</p>', '<p>Trong bức tranh giao thông đô thị ngày càng chật chội và nhiều áp lực, việc lựa chọn một phương tiện di chuyển không còn đơn thuần là đi cho tới nơi. Người dùng ngày nay quan tâm nhiều hơn đến cảm giác sử dụng, chi phí dài hạn và cả tác động đến môi trường sống xung quanh. Những con đường đông đúc, giờ cao điểm kéo dài và chi phí xăng dầu liên tục biến động khiến nhiều người bắt đầu nhìn lại thói quen di chuyển của mình.</p>\n<p>Chính trong bối cảnh đó, Xe Đạp Điện Tailg JY34 xuất hiện như một giải pháp di chuyển vừa đủ thông minh, vừa đủ tinh tế, dành cho những ai muốn sống chậm hơn một nhịp nhưng vẫn luôn chủ động trên mọi cung đường. Không chỉ là phương tiện đi lại hằng ngày, Tailg JY34 còn phản ánh một lối sống mới – nơi sự tiện lợi, tiết kiệm và bền vững được đặt lên hàng đầu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-6.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Một chiếc xe sinh ra cho đời sống thành phố</strong></h2>\n<p>Thành phố không cần những cỗ máy quá mạnh hay quá phức tạp, mà cần những phương tiện linh hoạt, dễ xoay trở trong dòng người đông đúc. T<strong>ailg JY34</strong> được phát triển đúng theo tinh thần đó, hướng tới việc tối ưu trải nghiệm sử dụng trong môi trường đô thị đặc trưng của Việt Nam.</p>\n<p>Kích thước xe gọn gàng, trọng lượng vừa phải giúp việc dắt xe, quay đầu trong hẻm nhỏ hay gửi xe tại trường học, chung cư, văn phòng trở nên nhẹ nhàng hơn rất nhiều. Đây là ưu điểm lớn so với các dòng xe máy điện cỡ lớn, vốn thường gây bất tiện trong không gian chật hẹp.</p>\n<p>Khi ngồi lên Tailg JY34, cảm giác đầu tiên mang lại là sự thân thiện và dễ làm quen. Tư thế lái thẳng lưng giúp người dùng không bị mỏi khi di chuyển quãng đường dài. Tay lái vừa tầm, thao tác nhẹ, không cần dùng quá nhiều lực. Yên xe êm ái và có thể điều chỉnh độ cao linh hoạt, phù hợp với nhiều vóc dáng khác nhau.</p>\n<p>Chính ngoại hình dễ dùng này khiến Tailg JY34 đặc biệt phù hợp với học sinh, sinh viên hoặc người lớn tuổi – những đối tượng luôn ưu tiên sự an toàn, ổn định và thoải mái trong quá trình di chuyển hằng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thẩm mỹ vừa đủ để không lỗi thời</strong></h2>\n<p>Tailg JY34 không chạy theo những xu hướng thiết kế quá phô trương hay màu mè. Thay vào đó, xe chọn phong cách trung tính, hiện đại và có khả năng sống lâu với thời gian. Đây là kiểu thiết kế càng dùng lâu càng thấy hợp, không bị lỗi mốt chỉ sau một vài năm.</p>\n<p>Các đường nét bo tròn mềm mại kết hợp cùng khung sườn chắc chắn tạo nên tổng thể hài hòa, cân đối. Xe không quá cá tính để gây kén người dùng, nhưng cũng không hề nhàm chán khi đặt cạnh những mẫu xe đạp điện phổ thông khác.</p>\n<p>Cụm đèn pha tròn là chi tiết tạo điểm nhấn rõ nét cho phần đầu xe. Thiết kế này mang hơi hướng cổ điển nhưng được hoàn thiện theo phong cách hiện đại, vừa đảm bảo khả năng chiếu sáng tốt khi di chuyển ban đêm, vừa giúp xe dễ nhận diện hơn trong điều kiện giao thông đông đúc.</p>\n<p>Nhìn tổng thể, Tailg JY34 giống như một món đồ dùng bền bỉ, thực tế hơn là một phương tiện để khoe mẽ. Và chính điều đó lại khiến xe dễ được lòng người dùng lâu dài, đặc biệt là những ai đề cao giá trị sử dụng thực tế hơn hình thức bên ngoài.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-jy34-dung-4-binh-13ah-60km-1-lan-sac-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Sức mạnh vừa đủ cho mọi hành trình quen thuộc</strong></h2>\n<p>Trong thực tế sử dụng hằng ngày, điều người dùng cần không phải là những con số quá ấn tượng trên giấy tờ, mà là sự ổn định và tin cậy trong từng chuyến đi. Tailg JY34 được trang bị động cơ QS Motor công suất 400W, một mức công suất được đánh giá là phù hợp với điều kiện giao thông đô thị Việt Nam.</p>\n<p>Xe tăng tốc nhẹ nhàng, không giật, không gây cảm giác mất kiểm soát. Khi di chuyển trong phố đông, phản hồi tay ga mượt giúp người lái dễ dàng điều chỉnh tốc độ theo tình huống thực tế, từ việc len lỏi qua dòng xe đông cho tới những đoạn đường cần giảm tốc đột ngột.</p>\n<p>Với tốc độ tối đa khoảng 40–45 km/h, Tailg JY34 đủ nhanh để không bị đuối giữa dòng xe, nhưng vẫn giữ được sự an toàn cần thiết cho người sử dụng. Đây là mức tốc độ lý tưởng cho<strong> xe đạp điện</strong>, vừa đảm bảo hiệu quả di chuyển, vừa hạn chế rủi ro khi tham gia giao thông.</p>\n<p>Khả năng leo dốc của xe đáp ứng tốt các đoạn cầu vượt, đường hầm chung cư hay những con dốc quen thuộc trong thành phố. Điều này giúp người dùng yên tâm hơn khi sử dụng xe hằng ngày, không phải e ngại những cung đường hơi khó, vốn là nỗi lo thường gặp với xe đạp điện công suất thấp.</p>\n<h2><strong>Đi xa hay gần, người dùng được quyền lựa chọn</strong></h2>\n<p>Xe sử dụng 4 bình ắc quy Tianneng 13Ah đáp ứng tốt nhu cầu di chuyển cơ bản trong đô thị. Với quãng đường lên tới khoảng 60 km cho mỗi lần sạc đầy, phù hợp cho học sinh, sinh viên hoặc người đi làm. Đây là lựa chọn giúp tiết kiệm chi phí đầu tư ban đầu nhưng vẫn đảm bảo hiệu quả sử dụng hằng ngày.</p>\n<p>Điều này giúp người dùng thoải mái hơn trong những chuyến đi mà không phải lo lắng quá nhiều về việc canh pin hay sạc giữa chừng. Thời gian sạc xe dao động từ 5–8 giờ, phù hợp với thói quen sạc qua đêm của đa số người dùng đô thị hiện nay.</p>\n<h2><strong>Cảm giác an tâm đến từ những chi tiết nhỏ</strong></h2>\n<p>Sự an toàn của Tailg JY34 không đến từ những công nghệ quá phức tạp, mà đến từ cách nhà sản xuất hoàn thiện từng chi tiết cơ bản một cách chỉn chu. Xe được trang bị hệ thống phanh cơ hoạt động ổn định, phản hồi tốt trong điều kiện giao thông đông đúc, giúp người lái dễ kiểm soát khi cần giảm tốc hoặc dừng xe.</p>\n<p>Lốp không săm kích thước lớn giúp xe bám đường tốt hơn, giảm nguy cơ trượt bánh khi di chuyển dưới trời mưa hoặc qua những đoạn đường xấu. Đây là yếu tố quan trọng đối với xe đạp điện sử dụng hằng ngày trong môi trường đô thị.</p>\n<p>Khung xe được thiết kế chắc chắn, khả năng chịu tải tốt, giúp xe luôn giữ được sự ổn định kể cả khi chở thêm người hoặc đồ đạc. Tất cả những yếu tố này kết hợp lại tạo nên cảm giác yên tâm khi sử dụng, đặc biệt quan trọng với phụ huynh khi chọn xe cho con em mình.</p>\n<h2><strong>Bài toán chi phí được giải quyết gọn gàng</strong></h2>\n<p>So với xe máy xăng, Tailg JY34 cho thấy rõ lợi thế về mặt kinh tế. Chi phí sạc điện thấp, gần như không đáng kể nếu tính theo quãng đường di chuyển mỗi ngày. Việc bảo dưỡng xe điện cũng đơn giản hơn rất nhiều, ít hỏng vặt, không cần thay dầu hay bảo trì động cơ phức tạp.</p>\n<p>Trong dài hạn, Tailg JY34 giúp người dùng tiết kiệm đáng kể chi phí vận hành. Đây là yếu tố then chốt khiến mẫu xe này đặc biệt phù hợp với học sinh, sinh viên và người lao động trẻ – những đối tượng luôn cần tối ưu ngân sách nhưng vẫn muốn có phương tiện di chuyển chủ động, ổn định.</p>\n<h2><strong>Một lựa chọn nhỏ cho lối sống xanh lớn hơn</strong></h2>\n<p>Việc sử dụng xe đạp điện không chỉ mang lại lợi ích cá nhân mà còn góp phần cải thiện môi trường sống chung. Tailg JY34 vận hành êm ái, không phát thải khí độc, không gây tiếng ồn, giúp giảm áp lực ô nhiễm không khí và tiếng ồn tại các đô thị đông dân.</p>\n<p>Mỗi chuyến đi bằng xe điện là một bước tiến nhỏ hướng tới lối sống xanh và bền vững hơn. Và khi ngày càng nhiều người lựa chọn những phương tiện như Tailg JY34, bức tranh giao thông đô thị cũng dần trở nên dễ chịu, văn minh hơn.</p>\n<p>Không cần quá nhiều lời hoa mỹ, <strong>Xe Đạp Điện Tailg</strong> JY34 chinh phục người dùng bằng sự thực tế và bền bỉ. Đây là chiếc xe dành cho những ai cần một phương tiện dễ dùng, tiết kiệm, an toàn và phù hợp với nhịp sống đô thị hiện đại. Nếu bạn đang tìm kiếm một giải pháp di chuyển gọn nhẹ cho học tập, công việc hay sinh hoạt hằng ngày, Tailg JY34 chính là lựa chọn vừa đẹp, đủ bền và đủ thông minh để đồng hành lâu dài.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-dap-dien-tailg-x51-plus-day-du-giay-to', 'Xe Đạp Điện Tailg X51 Plus (Đầy Đủ Giấy Tờ)', 'tailg', '[\"xe-dap-dien\"]', 15840000, 15840000, '/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-1.webp', '[\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-1.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-2.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-3.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-4.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-5.webp\",\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-6.webp\"]', '[]', '[]', '[]', '<p>Sự kết hợp giữa thiết kế thông minh, khả năng vận hành ổn định cùng nhiều trang bị tiện ích đã giúp mẫu Xe Đạp Điện Tailg X51 Plus ghi điểm mạnh mẽ. Không quá phô trương, nhưng đủ khác biệt để tạo nên dấu ấn riêng, Xe Đạp Điện Tailg X51 Plus mang đến trải nghiệm di chuyển đơn giản nhưng hiệu quả, đáp ứng tốt nhu cầu đi lại hàng ngày trong thành phố.</p>\n<p>Xe Đạp Điện Tailg X51 Plus được thiết kế với kích thước cân đối, không quá cồng kềnh nhưng cũng đủ đầm chắc để mang lại cảm giác an toàn khi sử dụng. Sự tối ưu này đặc biệt phù hợp với học sinh, sinh viên, những người cần một phương tiện linh hoạt, dễ xoay trở trong những con đường đông đúc hoặc không gian hẹp.</p>', '<p>Sự kết hợp giữa thiết kế thông minh, khả năng vận hành ổn định cùng nhiều trang bị tiện ích đã giúp mẫu Xe Đạp Điện Tailg X51 Plus&nbsp;ghi điểm mạnh mẽ. Không quá phô trương, nhưng đủ khác biệt để tạo nên dấu ấn riêng, Xe Đạp Điện Tailg X51&nbsp;Plus&nbsp;mang đến trải nghiệm di chuyển đơn giản nhưng hiệu quả, đáp ứng tốt nhu cầu đi lại hàng ngày trong thành phố.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-7.webp\" alt=\"Xe Đạp Điện Tailg Discovery X51\" loading=\"lazy\"></p>\n<h2><strong>Phong cách tổng thể xe đạp điện Tailg X51 Plus&nbsp;</strong></h2>\n<p><strong>Xe Đạp Điện</strong> Tailg X51 Plus&nbsp;được thiết kế với kích thước cân đối, không quá cồng kềnh nhưng cũng đủ đầm chắc để mang lại cảm giác an toàn khi sử dụng. Sự tối ưu này đặc biệt phù hợp với học sinh, sinh viên, những người cần một phương tiện linh hoạt, dễ xoay trở trong những con đường đông đúc hoặc không gian hẹp.</p>\n<p>Về tổng thể, xe mang phong cách trẻ trung, hiện đại, hướng đến sự năng động trong đô thị. Các chi tiết được tạo hình hài hòa, kết hợp giữa những đường cong mềm mại và các điểm nhấn cứng cáp, giúp chiếc xe vừa có sự thanh thoát, vừa toát lên vẻ chắc chắn. Đây là kiểu thiết kế dễ tiếp cận, phù hợp với nhiều nhóm người dùng khác nhau.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-8.webp\" alt=\"Xe Đạp Điện Tailg Discovery X51\" loading=\"lazy\"></p>\n<p>Xe được hoàn thiện với độ cứng vững cao, tạo cảm giác yên tâm khi vận hành lâu dài. Bên ngoài là lớp sơn chất lượng, có khả năng giữ màu tốt và hạn chế trầy xước, giúp xe luôn duy trì vẻ ngoài mới mẻ sau thời gian sử dụng. Nhờ đó, Xe Đạp Điện Tailg X51 Plus&nbsp;Plus&nbsp;vẫn giữ được sức hút trong phân khúc xe điện phổ thông.</p>\n<p>Yên xe vừa tầm, khu vực để chân rộng và tay lái bố trí hợp lý giúp người điều khiển không bị mỏi khi di chuyển lâu. Chính sự thân thiện này khiến Xe Đạp Điện Tailg X51 Plus&nbsp;trở thành lựa chọn phù hợp ngay cả với những người lần đầu sử dụng xe điện.</p>\n<h2><strong>Xe đạp điện Tailg X51 Plus&nbsp;vận hành có khỏe không?</strong></h2>\n<p><img src=\"/sites/yenthoa/img/sp/xe-dap-dien-tailg-x51-plus-day-du-giay-to-9.webp\" alt=\"Xe Đạp Điện Tailg Discovery X51\" loading=\"lazy\"></p>\n<p>Khi di chuyển trong thành phố, xe cho cảm giác tăng tốc nhẹ nhàng, không bị giật cục. Điều này đặc biệt hữu ích khi phải dừng, đi liên tục trong giờ cao điểm. Khả năng vận hành êm ái cũng giúp giảm tiếng ồn, mang lại trải nghiệm dễ chịu hơn so với các dòng xe truyền thống.</p>\n<p>Với quãng đường di chuyển lên đến khoảng 80–90 km sau mỗi lần sạc, Xe Đạp Điện Tailg X51 Plus&nbsp;hoàn toàn đáp ứng nhu cầu đi lại hàng ngày mà không cần sạc quá thường xuyên. Đây là một lợi thế lớn đối với người dùng bận rộn, đặc biệt là học sinh – sinh viên.</p>\n<p>Xe cũng thể hiện khả năng leo dốc tương đối tốt trong điều kiện đô thị. Khi chở thêm người hoặc hành lý, động cơ vẫn giữ được sự ổn định, không bị hụt lực. Nhờ đó, Xe Đạp Điện Tailg X51 Plus&nbsp;có thể phục vụ linh hoạt nhiều mục đích sử dụng khác nhau.</p>\n<p>Hệ thống vận hành được tối ưu để tiết kiệm năng lượng, giúp giảm chi phí sử dụng lâu dài. Đây là điểm cộng lớn khiến Xe Đạp Điện Tailg X51 Plus&nbsp;trở thành lựa chọn kinh tế trong bối cảnh giá nhiên liệu ngày càng tăng.</p>\n<p>Màn hình hiển thị điện tử giúp cung cấp đầy đủ thông tin như tốc độ, dung lượng pin và các trạng thái vận hành. Nhờ đó, người lái có thể dễ dàng kiểm soát tình trạng xe trong suốt hành trình.</p>\n<p>Hệ thống đèn LED được thiết kế hiện đại, cho ánh sáng rõ và tiết kiệm điện. Khi di chuyển vào ban đêm, ánh sáng từ đèn giúp tăng khả năng quan sát và nhận diện, góp phần nâng cao độ an toàn.</p>\n<p>Ngoài ra, xe còn được trang bị cốp chứa đồ tiện lợi, đủ để đựng những vật dụng cá nhân cần thiết. Đây là chi tiết nhỏ nhưng mang lại sự tiện dụng lớn, đặc biệt đối với người thường xuyên di chuyển.</p>\n<p>Các nút điều khiển được bố trí khoa học, dễ thao tác, phù hợp với cả người mới sử dụng. Chính những yếu tố này giúp Xe Đạp Điện <strong>Tailg X51</strong> Plus&nbsp;trở nên thân thiện hơn với người dùng ở mọi độ tuổi.</p>\n<h2><strong>Giá bán xe Tailg X51 Plus&nbsp;và độ an toàn</strong></h2>\n<p>An toàn luôn là yếu tố được đặt lên hàng đầu khi lựa chọn phương tiện di chuyển. Xe Đạp Điện Tailg X51 Plus&nbsp;được trang bị hệ thống phanh hiệu quả, giúp người lái kiểm soát tốc độ tốt trong nhiều tình huống khác nhau. Khả năng bám đường của xe cũng được cải thiện nhờ lốp không săm, giúp hạn chế trơn trượt khi đi trên đường ướt. Đây là yếu tố rất quan trọng trong điều kiện thời tiết thất thường.</p>\n<p>Hệ thống giảm xóc hoạt động ổn định, giúp xe vận hành êm ái ngay cả khi đi qua những đoạn đường gồ ghề. Điều này không chỉ tăng sự thoải mái mà còn góp phần bảo vệ các bộ phận của xe. Độ bền của xe đến từ sự kết hợp giữa khung chắc chắn và các chi tiết được hoàn thiện tốt. Nhờ đó, Xe Đạp Điện Tailg X51 Plus&nbsp;có thể duy trì hiệu suất ổn định trong thời gian dài mà không cần bảo trì quá nhiều.</p>\n<p>Khả năng chống nước và chống bụi cũng giúp xe thích nghi tốt với điều kiện môi trường đô thị. Đây là điểm cộng lớn khiến Xe Đạp Điện Tailg X51 Plus&nbsp;trở nên đáng tin cậy trong quá trình sử dụng lâu dài.</p>\n<p>Một trong những lý do khiến Xe Đạp Điện Tailg X51 Plus&nbsp;được nhiều người quan tâm chính là mức giá hợp lý so với những gì xe mang lại. So với chi phí vận hành của xe máy xăng, việc sử dụng xe điện giúp tiết kiệm đáng kể trong dài hạn.</p>\n<p>Ngoài chi phí ban đầu, người dùng gần như không phải lo lắng về các khoản như thay nhớt hay bảo dưỡng phức tạp. Điều này giúp giảm áp lực tài chính, đặc biệt đối với học sinh và sinh viên. Chế độ bảo hành cũng là yếu tố tạo nên sự yên tâm. Khi lựa chọn Xe Đạp Điện Tailg X51 Plus, người dùng thường được hưởng chính sách bảo hành rõ ràng, hỗ trợ kỹ thuật nhanh chóng và thuận tiện.</p>\n<p>Không chỉ đơn thuần là một phương tiện di chuyển, <strong>Xe Đạp Điện Tailg</strong>&nbsp;X51 Plus&nbsp;còn mang đến một giải pháp đi lại thông minh, phù hợp với xu hướng sống hiện đại. Từ thiết kế nhỏ gọn, khả năng vận hành ổn định đến các tiện ích thiết thực, tất cả đều hướng đến trải nghiệm người dùng.</p>', 1);
