INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi', 'Xe Ga 50cc AT88 Pro Victoria Việt Nhật Đời Mới', 'xe-50cc', '[\"xe-tay-ga\"]', 19400000, 19400000, '/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-at88-pro-victoria-viet-nhat-doi-moi-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-crea-f1-sieu-giam-gia', 'Xe Ga 50cc Crea F1 Siêu Giảm Giá', 'xe-50cc', '[\"xe-tay-ga\"]', 18150000, 18150000, '/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-6.webp\"]', '[]', '[]', '[]', '<p>Không phải ai cũng cần một chiếc xe mạnh mẽ hay nhiều công nghệ phức tạp. Với nhiều người, đặc biệt là học sinh, sinh viên, phụ nữ hoặc người mới bắt đầu đi xe máy, điều quan trọng nhất lại rất đơn giản: dễ chạy, dễ kiểm soát và tạo cảm giác yên tâm mỗi khi lăn bánh. Crea F1 50cc mang đến đúng cảm giác đó – một chiếc xe không khiến người lái phải “học cách thích nghi”, mà nhẹ nhàng hòa vào nhịp sống hằng ngày.</p>\n<p>Ngay từ những ngày đầu làm quen, Crea F1 cho cảm giác thân thiện, dễ gần, giống như một người bạn đồng hành hơn là một cỗ máy cần làm chủ.</p>', '<p>Không phải ai cũng cần một chiếc xe mạnh mẽ hay nhiều công nghệ phức tạp. Với nhiều người, đặc biệt là học sinh, sinh viên, phụ nữ hoặc người mới bắt đầu đi xe máy, điều quan trọng nhất lại rất đơn giản: dễ chạy, dễ kiểm soát và tạo cảm giác yên tâm mỗi khi lăn bánh. Crea F1 50cc mang đến đúng cảm giác đó – một chiếc xe không khiến người lái phải “học cách thích nghi”, mà nhẹ nhàng hòa vào nhịp sống hằng ngày.</p>\n<p>Ngay từ những ngày đầu làm quen, Crea F1 cho cảm giác thân thiện, dễ gần, giống như một người bạn đồng hành hơn là một cỗ máy cần làm chủ.</p>\n<p>&nbsp;<img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Ấn tượng đầu tiên khi nhìn và chạm vào xe</strong></h2>\n<p>Lần đầu tiếp xúc với <strong>Crea F1</strong>, cảm giác dễ nhận ra nhất chính là sự mềm mại trong thiết kế. Xe không có những góc cạnh sắc nét hay đường nét hầm hố. Thay vào đó là tổng thể bo tròn liền mạch, nhìn nhẹ mắt và tạo thiện cảm ngay cả với những người không rành về xe cộ.</p>\n<p>Phần đầu xe với cụm đèn pha tròn lớn mang hơi hướng cổ điển, nhưng không hề cũ kỹ. Khi đứng trước xe, cảm giác giống như đang nhìn một mẫu scooter châu Âu nhỏ gọn, thanh lịch, vừa đủ nổi bật nhưng không phô trương. Những chi tiết như đèn xi-nhan, đèn hậu được thiết kế đồng bộ, giúp tổng thể xe trông gọn gàng và cân đối.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Khi dắt xe, trọng lượng nhẹ và kích thước nhỏ gọn giúp việc xoay trở trở nên rất dễ dàng. Với những ai thường xuyên phải dắt xe trong hẻm nhỏ, bãi gửi xe chật hoặc quay đầu trong không gian hẹp, đây là một điểm cộng rất rõ ràng.</p>\n<h2><strong>Cảm giác ngồi lên xe – thấp, gọn và rất “dễ chịu”</strong></h2>\n<p>Ngồi lên Crea F1, cảm giác đầu tiên là yên xe khá thấp và dễ chống chân. Điều này đặc biệt quan trọng với người có chiều cao khiêm tốn hoặc người mới lái, bởi chỉ cần đặt chân xuống là đã cảm thấy vững vàng, không bị với hay chông chênh.</p>\n<p>Tư thế ngồi thẳng lưng, tay lái vừa tầm, không cần rướn người hay khom lưng quá nhiều. Khi ngồi lâu, cảm giác không bị mỏi vai hay căng tay. Yên xe có độ êm vừa phải, không quá mềm nhưng đủ để tạo sự thoải mái khi di chuyển hằng ngày.</p>\n<p>Sàn để chân phẳng và rộng, tạo cảm giác thoải mái khi đặt chân. Với người hay mang thêm đồ nhỏ như túi xách, balo hoặc đồ đi chợ, phần sàn này cũng rất tiện để tận dụng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-f1-sieu-giam-gia-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Khi bắt đầu lăn bánh – nhẹ nhàng và không áp lực</strong></h2>\n<p>Khởi động xe bằng đề điện, tiếng máy nổ êm, không quá lớn. Với <strong>xe động cơ 50cc</strong>, Crea F1 không tạo cảm giác “vọt” khi vặn ga. Xe tăng tốc từ tốn, đều và rất dễ kiểm soát. Đây là điểm khiến người mới đi xe cảm thấy an tâm, bởi xe không phản ứng quá nhanh hay bất ngờ.</p>\n<p>Khi di chuyển trong phố, đặc biệt là giờ cao điểm, Crea F1 thể hiện rõ ưu thế của một chiếc xe nhỏ gọn. Xe dễ luồn lách qua dòng xe đông đúc, quay đầu nhẹ, không cần nhiều thao tác. Ngay cả khi chạy chậm hoặc dừng – chạy liên tục, xe vẫn giữ được sự ổn định, không rung lắc khó chịu.</p>\n<p>Với tốc độ vừa phải, Crea F1 phù hợp với việc đi học, đi làm gần nhà, đi chợ hoặc dạo phố. Xe không tạo cảm giác bị “đuối” trong điều kiện đô thị thông thường, nhưng vẫn giữ được sự an toàn cần thiết cho người lái.</p>\n<h2><strong>Trải nghiệm tay ga và khả năng kiểm soát</strong></h2>\n<p>Tay ga của Crea F1 được tinh chỉnh khá nhẹ. Chỉ cần vặn ga vừa phải là xe đã lăn bánh mượt mà. Với người mới, điều này giúp hạn chế tình trạng giật ga hoặc tăng tốc đột ngột – một trong những nỗi lo phổ biến khi mới tập đi xe tay ga.</p>\n<p>Tay lái vừa tầm, không quá rộng, giúp việc đánh lái trong không gian hẹp trở nên dễ dàng. Khi vào cua hoặc quay đầu, xe cho cảm giác gọn gàng, không bị ì hay nặng đầu.</p>\n<h2><strong>Tiện ích sử dụng hằng ngày – vừa đủ nhưng rất thực tế</strong></h2>\n<p>Crea F1 không cố gắng “nhồi nhét” nhiều tiện ích, nhưng những gì có đều phục vụ rất đúng nhu cầu hằng ngày. Cốp dưới yên đủ để đựng mũ bảo hiểm nửa đầu, áo mưa và vài vật dụng cá nhân. Với nhu cầu đi học, đi làm gần, dung tích này là hoàn toàn hợp lý.</p>\n<p>Hộc chứa đồ phía trước khá tiện, nhất là khi cần cất điện thoại, khẩu trang hoặc chai nước nhỏ. Việc có sẵn một vị trí để đồ dễ lấy giúp trải nghiệm sử dụng xe trở nên thoải mái hơn rất nhiều.</p>\n<p>Mặt đồng hồ hiển thị rõ ràng, dễ nhìn, cung cấp các thông tin cơ bản như tốc độ, mức nhiên liệu và đèn báo. Không cầu kỳ, nhưng đủ để người lái luôn nắm được tình trạng xe trong quá trình sử dụng.</p>\n<h2>Cảm giác an toàn khi di chuyển trong phố</h2>\n<p>Với hệ thống phanh tang trống trước và sau, Crea F1 cho khả năng hãm tốc ổn định trong điều kiện đô thị. Phanh không quá gắt, nhưng đủ lực để kiểm soát tốc độ một cách an toàn, đặc biệt phù hợp với người mới lái.</p>\n<p>Lốp không săm giúp xe giữ thăng bằng tốt hơn khi di chuyển qua những đoạn đường không bằng phẳng. Trong trường hợp cán phải vật nhọn, lốp không xì hơi đột ngột, giúp người lái giữ được sự kiểm soát.</p>\n<p>Hệ thống giảm xóc hoạt động ổn định, giúp xe êm hơn khi đi qua gờ giảm tốc, ổ gà nhỏ hoặc đường hơi xấu. Điều này góp phần tạo cảm giác dễ chịu khi sử dụng xe mỗi ngày, nhất là với những ai thường xuyên di chuyển trong khu dân cư.</p>\n<h2>Crea F1 trong nhịp sống thường ngày</h2>\n<p>Sau một thời gian sử dụng, Crea F1 cho cảm giác rất “đời”. Xe không khiến người dùng phải suy nghĩ quá nhiều trước mỗi lần lấy xe ra khỏi nhà. Chỉ cần lên xe, vặn ga và đi. Không áp lực, không phức tạp.</p>\n<p>Đối với học sinh, sinh viên, đây là chiếc <strong>xe ga 50cc</strong> vừa đủ để đi học, đi làm thêm, sinh hoạt hằng ngày. Với phụ nữ hoặc người mới đi xe, Crea F1 mang lại cảm giác an tâm và tự tin hơn mỗi khi tham gia giao thông.</p>\n<p>Crea F1 50cc không phải là chiếc xe để khoe sức mạnh hay công nghệ, mà là lựa chọn dành cho những ai trân trọng sự đơn giản, dễ dùng và ổn định. Thiết kế cổ điển pha hiện đại, động cơ êm ái, không cần bằng lái và chi phí sử dụng hợp lý khiến Crea F1 trở thành người bạn đồng hành phù hợp cho cuộc sống đô thị.</p>\n<p>Nếu bạn đang tìm một chiếc xe không gây áp lực khi sử dụng, dễ làm quen ngay từ ngày đầu và đủ đẹp để gắn bó lâu dài, Crea F1 50cc là cái tên rất đáng để cân nhắc.</p>', 1);
