INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat', 'Xe Ga 50cc Crea HSV3 Hyosung Đời Mới Nhất', 'xe-50cc', '[\"xe-tay-ga\"]', 18200000, 18200000, '/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng xe\",\"value\":\"Hyosung\"},{\"label\":\"Xuất xứ\",\"value\":\"Hàn Quốc\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"6 tháng\"},{\"label\":\"Motor\",\"value\":\"1 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1720mm x 660mm x 1160mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"760mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Vành xe 10 inch\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"Xăng không chì (octane ≥92), 4 kỳ, 1 xi lanh, làm mát bằng không khí\"},{\"label\":\"Vận hành\",\"value\":\"Tự động có nút đề\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50km/h\"},{\"label\":\"Tải trọng\",\"value\":\"140kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"79kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"1,68 lit xăng / 100km\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh cơ trước và sau\"},{\"label\":\"Dung tích xi lanh\",\"value\":\"49,5cm3\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Ống lồng, lò xo trụ đơn giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, sổ bảo hành\"}]}]', '<p>Nhóm khách hàng học sinh, sinh viên hoặc những người muốn một chiếc xe tiện lợi để di chuyển trong thành phố đang ngày càng quan tâm đến các dòng xe ga 50cc có thiết kế đẹp và dễ sử dụng. Trong số đó, Crea HSV3 Hyosung nổi bật như một lựa chọn đáng chú ý nhờ phong cách cổ điển, khả năng vận hành ổn định và mức tiêu hao nhiên liệu tiết kiệm.</p>\n<p>Không chỉ gây ấn tượng bởi ngoại hình mang hơi hướng châu Âu cổ điển, mẫu xe này còn được đánh giá cao về sự tiện dụng và phù hợp với nhiều đối tượng người dùng. Với thiết kế nhỏ gọn, chiều cao yên hợp lý và khả năng vận hành nhẹ nhàng, Crea HSV3 Hyosung đang dần trở thành một trong những dòng xe ga 50cc được nhiều người tìm kiếm.</p>', '<p>Nhóm khách hàng học sinh, sinh viên hoặc những người muốn một chiếc xe tiện lợi để di chuyển trong thành phố đang ngày càng quan tâm đến các dòng xe ga 50cc có thiết kế đẹp và dễ sử dụng. Trong số đó, <strong>Crea HSV3 Hyosung</strong> nổi bật như một lựa chọn đáng chú ý nhờ phong cách cổ điển, khả năng vận hành ổn định và mức tiêu hao nhiên liệu tiết kiệm.</p>\n<p>Không chỉ gây ấn tượng bởi ngoại hình mang hơi hướng châu Âu cổ điển, mẫu xe này còn được đánh giá cao về sự tiện dụng và phù hợp với nhiều đối tượng người dùng. Với thiết kế nhỏ gọn, chiều cao yên hợp lý và khả năng vận hành nhẹ nhàng, Crea HSV3 Hyosung đang dần trở thành một trong những dòng xe ga 50cc được nhiều người tìm kiếm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-7.webp\" alt=\"xe ga 50cc hsv3 hyosung\" loading=\"lazy\"></p>\n<h2><strong>Thiết Kế Ngoại Hình Thời Trang Và Ấn Tượng</strong></h2>\n<p>Điểm gây ấn tượng đầu tiên của <strong>Hyosung Crea HSV3</strong> chính là thiết kế mang phong cách trẻ trung và thời trang. Mẫu xe này sở hữu những đường nét mềm mại, uyển chuyển nhưng vẫn giữ được sự cá tính và hiện đại. Tổng thể chiếc xe được thiết kế nhỏ gọn, thanh lịch, phù hợp với phong cách năng động của giới trẻ, đặc biệt là nữ sinh và sinh viên.</p>\n<p>Phần đầu xe được thiết kế nổi bật với cụm đèn pha lớn sử dụng công nghệ LED hiện đại. Đèn LED không chỉ mang lại ánh sáng mạnh và rõ hơn so với đèn halogen truyền thống mà còn giúp tăng tính thẩm mỹ cho chiếc xe. Ánh sáng trắng từ đèn LED hỗ trợ người lái quan sát tốt hơn khi di chuyển vào ban đêm hoặc trong điều kiện thời tiết xấu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-8.webp\" alt=\"xe ga 50cc hsv3 hyosung\" loading=\"lazy\"></p>\n<p>Bên cạnh đó, mặt nạ trước của xe còn được trang bị tấm chắn gió bằng hợp kim mạ crom sáng bóng, tạo điểm nhấn sang trọng cho tổng thể thiết kế. Chi tiết này không chỉ mang tính thẩm mỹ mà còn giúp hạn chế bụi bẩn và gió tạt trực tiếp vào người lái khi di chuyển.</p>\n<p>Hai bên đầu xe là hệ thống đèn xi nhan được tích hợp hài hòa vào thân xe, tạo cảm giác liền mạch và hiện đại. Thiết kế này giúp chiếc xe trở nên tinh tế và gọn gàng hơn so với nhiều mẫu xe ga 50cc khác trên thị trường.</p>\n<h2><strong>Dàn Áo Nhựa ABS Cao Cấp Bền Bỉ</strong></h2>\n<p>Một trong những yếu tố giúp Hyosung Crea HSV3 ghi điểm trong mắt người dùng chính là chất lượng dàn áo. Toàn bộ thân xe được làm từ nhựa ABS cao cấp – loại vật liệu thường được sử dụng trên nhiều dòng xe cao cấp nhờ độ bền cao và khả năng chịu va đập tốt.</p>\n<p>Nhựa ABS không chỉ giúp tăng độ bền cho xe mà còn mang lại bề mặt sơn bóng đẹp, hạn chế trầy xước trong quá trình sử dụng. Điều này giúp chiếc xe luôn giữ được vẻ ngoài mới mẻ và sang trọng sau thời gian dài sử dụng.</p>\n<p>Ngoài ra, các chi tiết viền kim loại mạ crom chạy dọc thân xe cũng góp phần tạo nên vẻ ngoài nổi bật và cao cấp. Sự kết hợp giữa các đường nét bo tròn mềm mại và các chi tiết kim loại sáng bóng mang lại cảm giác vừa hiện đại vừa sang trọng cho chiếc xe.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-crea-hsv3-hyosung-doi-moi-nhat-9.webp\" alt=\"xe ga 50cc hsv3 hyosung\" loading=\"lazy\"></p>\n<h2><strong>Màu Sắc Đa Dạng, Phù Hợp Với Giới Trẻ</strong></h2>\n<p>Không chỉ chú trọng đến thiết kế, Hyosung Crea HSV3 còn mang đến nhiều tùy chọn màu sắc khác nhau để người dùng dễ dàng lựa chọn theo sở thích cá nhân. Các màu sắc phổ biến của mẫu xe này bao gồm xanh da trời, xám, kem, ghi đá và một số phiên bản phối màu cá tính khác.</p>\n<p>Các gam màu được phối hợp hài hòa cùng những họa tiết hình học tinh tế trên thân xe, tạo nên vẻ ngoài trẻ trung và năng động. Nhờ đó, người dùng có thể dễ dàng thể hiện phong cách cá nhân và gu thẩm mỹ riêng khi sở hữu chiếc xe này.</p>\n<h2><strong>Động Cơ 50cc Mạnh Mẽ Và Ổn Định</strong></h2>\n<p>Mặc dù thuộc phân khúc xe ga 50cc nhỏ gọn, Hyosung Crea HSV3 vẫn được trang bị khối động cơ khá mạnh mẽ so với nhiều đối thủ cùng phân khúc. Xe sử dụng động cơ xăng 4 kỳ, 1 xi-lanh với dung tích 49.5cc, làm mát bằng không khí, mang lại khả năng vận hành ổn định và bền bỉ.</p>\n<p>Động cơ này được thiết kế nhằm tối ưu hóa hiệu suất vận hành trong đô thị. Nhờ đó, xe có thể di chuyển mượt mà trên nhiều loại địa hình khác nhau, từ đường phố bằng phẳng cho đến những đoạn đường hơi dốc.</p>\n<p>Tốc độ tối đa của xe có thể đạt hơn 50 km/h, thậm chí trong điều kiện thuận lợi có thể lên đến khoảng 55 km/h. Mức tốc độ này hoàn toàn phù hợp với nhu cầu di chuyển trong thành phố và đáp ứng tốt các quy định dành cho xe 50cc.</p>\n<h2><strong>Khả Năng Leo Dốc Tốt Trong Phân Khúc</strong></h2>\n<p>Một trong những ưu điểm đáng chú ý của Crea HSV3 là khả năng leo dốc khá tốt so với nhiều mẫu <strong>xe ga 50cc</strong> khác. Ngay cả khi chở hai người, xe vẫn có thể di chuyển ổn định trên các đoạn đường dốc mà không bị ì máy.</p>\n<p>Điều này mang lại sự tự tin cho người lái khi di chuyển trong các khu vực có địa hình phức tạp hoặc khi cần chở thêm người. Khả năng vận hành linh hoạt giúp chiếc xe phù hợp với nhiều điều kiện giao thông khác nhau.</p>\n<h2><strong>Khả Năng Tiết Kiệm Nhiên Liệu Ấn Tượng</strong></h2>\n<p>Trong bối cảnh giá xăng dầu thường xuyên biến động, khả năng tiết kiệm nhiên liệu là yếu tố được nhiều người dùng quan tâm khi lựa chọn xe. Hyosung Crea HSV3 ghi điểm khi có mức tiêu thụ nhiên liệu khá thấp, chỉ khoảng 1.68 lít xăng cho quãng đường 100 km.</p>\n<p>Mức tiêu hao này giúp người dùng tiết kiệm đáng kể chi phí nhiên liệu trong quá trình sử dụng hàng ngày. Đối với học sinh, sinh viên hoặc những người cần di chuyển thường xuyên trong thành phố, đây là một lợi thế rất lớn.</p>\n<h2><strong>Trang Bị Tiện Ích Phù Hợp Cho Người Dùng Trẻ</strong></h2>\n<p>Không chỉ chú trọng đến thiết kế và động cơ, Hyosung Crea HSV3 còn được trang bị nhiều tiện ích nhằm mang lại sự thoải mái cho người sử dụng.</p>\n<p>Tay lái của xe được thiết kế khoa học với các cụm công tắc bố trí hợp lý, giúp người lái dễ dàng thao tác khi điều khiển xe. Phần tay nắm được bọc cao su mềm và có các điểm tăng độ bám, giúp hạn chế trơn trượt và giảm mỏi tay khi di chuyển trong thời gian dài.</p>\n<p>Sàn để chân của xe khá rộng rãi và được thiết kế bằng phẳng với các rãnh chống trơn trượt. Điều này không chỉ giúp người lái cảm thấy thoải mái hơn mà còn có thể đặt thêm đồ dùng cá nhân khi cần thiết.</p>\n<h2><strong>Cốp Xe Và Hộc Đựng Đồ Tiện Lợi</strong></h2>\n<p>Phần cốp xe dưới yên có dung tích khá rộng, đủ để chứa một mũ bảo hiểm cùng một số vật dụng cá nhân như áo mưa, túi xách nhỏ hoặc sách vở. Đây là một tiện ích rất hữu ích đối với học sinh và sinh viên khi cần mang theo đồ dùng hàng ngày.</p>\n<p>Ngoài ra, phía trước xe còn có hộc đựng đồ nhỏ và móc treo tiện lợi, giúp người dùng dễ dàng treo túi hoặc balo khi đi mua sắm hay đi học.</p>\n<h2><strong>Hệ Thống Phanh An Toàn Và Dễ Bảo Dưỡng</strong></h2>\n<p>Hyosung Crea HSV3 được trang bị hệ thống phanh cơ cho cả bánh trước và bánh sau. Mặc dù không phải là phanh đĩa, nhưng hệ thống phanh cơ này vẫn đảm bảo độ an toàn nhờ sử dụng má phanh chất lượng cao, có khả năng chịu nhiệt tốt và ít bị mài mòn.</p>\n<p>Ưu điểm của phanh cơ là dễ bảo dưỡng và sửa chữa, chi phí thay thế cũng thấp hơn so với nhiều hệ thống phanh khác. Điều này giúp người dùng tiết kiệm chi phí bảo trì trong quá trình sử dụng xe.</p>\n<h2><strong>Hệ Thống Giảm Xóc Êm Ái</strong></h2>\n<p>Để đảm bảo sự thoải mái khi di chuyển, xe được trang bị hệ thống giảm xóc thủy lực kết hợp với bộ vành đúc chắc chắn và lốp không săm dày dặn. Nhờ đó, xe có thể vận hành êm ái trên nhiều loại địa hình khác nhau.</p>\n<p>Ngay cả khi đi qua các đoạn đường gồ ghề hoặc ổ gà nhỏ, hệ thống giảm xóc vẫn giúp hạn chế rung lắc, mang lại cảm giác lái ổn định và dễ chịu.</p>\n<h2><strong>Kích Thước Nhỏ Gọn Phù Hợp Cho Học Sinh</strong></h2>\n<p>Hyosung Crea HSV3 có kích thước tổng thể khoảng 1720mm x 660mm x 1160mm cùng chiều cao yên khoảng 760mm. Với kích thước này, chiếc xe rất phù hợp với người có chiều cao từ khoảng 1m50 trở lên.</p>\n<p>Thiết kế nhỏ gọn giúp xe dễ dàng di chuyển trong những con phố đông đúc và thuận tiện khi tìm chỗ đỗ. Trọng lượng xe khoảng 89kg cũng giúp việc dắt xe hoặc xoay xe trở nên nhẹ nhàng hơn.</p>\n<h2><strong>Lựa Chọn Lý Tưởng Trong Phân Khúc Xe Ga 50cc</strong></h2>\n<p>Với sự kết hợp giữa thiết kế thời trang, động cơ ổn định, khả năng tiết kiệm nhiên liệu và nhiều tiện ích thực tế, Hyosung Crea HSV3 là một mẫu xe ga 50cc rất đáng cân nhắc trong phân khúc hiện nay.</p>\n<p>Chiếc xe này đặc biệt phù hợp với học sinh, sinh viên, nữ giới hoặc những người cần một phương tiện di chuyển nhỏ gọn, linh hoạt trong thành phố. Không chỉ giúp việc di chuyển trở nên thuận tiện hơn, mẫu xe còn mang lại phong cách trẻ trung và hiện đại cho người sử dụng.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe ga 50cc vừa đẹp, vừa tiết kiệm lại dễ sử dụng thì <strong>Hyosung</strong> Crea HSV3 chắc chắn là một lựa chọn đáng để tham khảo.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-dibao-creer-phanh-dia', 'Xe Ga 50cc Dibao Creer Phanh Đĩa', 'xe-50cc', '[\"xe-tay-ga\"]', 21500000, 21500000, '/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-creer-phanh-dia-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-dibao-pansy-xs1-neo-pro', 'Xe Ga 50cc Dibao Pansy XS1 Neo Pro', 'xe-50cc', '[\"xe-tay-ga\"]', 18450000, 18450000, '/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-6.webp\"]', '[]', '[]', '[]', '<p>Với sự kết hợp giữa thiết kế thời trang, động cơ bền bỉ và chi phí sử dụng hợp lý, Dibao Pansy XS1 Neo Pro đang trở thành một trong những mẫu xe ga 50cc được quan tâm nhiều trên thị trường. Đặc biệt với học sinh, sinh viên hoặc những người mới bắt đầu sử dụng xe máy, một mẫu xe đơn giản nhưng ổn định luôn là lựa chọn được ưu tiên hơn so với những dòng xe công suất lớn.</p>\n<p>Một trong những yếu tố tạo nên sức hút của Xe 50 phân khối Dibao Pansy XS1 Neo Pro chính là phong cách thiết kế thanh lịch mang hơi hướng scooter châu Âu. Tổng thể chiếc xe được xây dựng theo triết lý tối giản nhưng tinh tế, giúp xe trông gọn gàng mà vẫn nổi bật khi di chuyển trên đường phố.</p>', '<p>Với sự kết hợp giữa thiết kế thời trang, động cơ bền bỉ và chi phí sử dụng hợp lý, Dibao Pansy XS1 Neo Pro đang trở thành một trong những mẫu xe ga 50cc được quan tâm nhiều trên thị trường. Đặc biệt với học sinh, sinh viên hoặc những người mới bắt đầu sử dụng xe máy, một mẫu xe đơn giản nhưng ổn định luôn là lựa chọn được ưu tiên hơn so với những dòng xe công suất lớn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-7.webp\" alt=\"Xe Ga 50cc Dibao Pansy XS1 Neo Pro\" loading=\"lazy\"></p>\n<h2><strong>Dấu ấn thẩm mỹ châu Âu trên mẫu xe ga 50cc hiện đại</strong></h2>\n<p>Một trong những yếu tố tạo nên sức hút của <strong>Xe 50 phân khối</strong> Dibao Pansy XS1 Neo Pro chính là phong cách thiết kế thanh lịch mang hơi hướng scooter châu Âu. Tổng thể chiếc xe được xây dựng theo triết lý tối giản nhưng tinh tế, giúp xe trông gọn gàng mà vẫn nổi bật khi di chuyển trên đường phố.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-8.webp\" alt=\"Pansy XS1\" loading=\"lazy\"></p>\n<p>Các đường nét thiết kế trên xe được bo tròn nhẹ nhàng, tạo cảm giác mềm mại và thân thiện. Kiểu tạo hình này thường thấy ở những dòng scooter châu Âu cổ điển, nơi sự thanh lịch luôn được đặt lên hàng đầu. Nhờ vậy, Dibao Pansy XS1 Neo Pro mang lại cảm giác sang trọng hơn so với nhiều mẫu xe 50cc phổ thông.</p>\n<p>Một điểm nhấn dễ nhận thấy là hệ thống đèn pha LED tròn đặt cao. Thiết kế này không chỉ tạo điểm nhận diện đặc trưng mà còn giúp cải thiện khả năng chiếu sáng khi di chuyển vào buổi tối. Ánh sáng LED trắng mang lại độ phủ tốt hơn so với đèn halogen truyền thống, đồng thời tiêu thụ điện năng thấp và có tuổi thọ cao.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-dibao-pansy-xs1-neo-pro-9.webp\" alt=\"Xe Ga 50cc Dibao Pansy XS1 Neo Pro\" loading=\"lazy\"></p>\n<p>Những chi tiết trang trí viền crom sáng bóng được bố trí khéo léo trên thân xe giúp tổng thể trở nên nổi bật hơn. Khi kết hợp với lớp sơn tĩnh điện nhiều lớp, bề mặt xe luôn giữ được độ bóng và hạn chế phai màu theo thời gian.</p>\n<p>Xe cũng có nhiều lựa chọn màu sắc trẻ trung như trắng, hồng, xanh mint hay đỏ đô. Các gam màu này không chỉ phù hợp với xu hướng thẩm mỹ của giới trẻ mà còn giúp chiếc xe trở thành một “phụ kiện thời trang di động” khi xuất hiện trên đường phố.</p>\n<h2><strong>Lợi thế gì khi Dibao Pansy XS1 di chuyển trong thành phố</strong></h2>\n<p>Xe có kích thước tổng thể khoảng 1.800 mm chiều dài, 660 mm chiều rộng và 1.150 mm chiều cao. Với thông số này, chiếc xe giữ được sự gọn gàng cần thiết để dễ dàng di chuyển trong các con phố đông đúc hoặc những con hẻm nhỏ.</p>\n<p>Trọng lượng xe khoảng 80 kg, giúp người dùng dễ dàng dắt xe hoặc xoay đầu khi cần. Đây là một ưu điểm lớn đối với học sinh hoặc nữ giới, bởi việc điều khiển xe trở nên nhẹ nhàng hơn rất nhiều so với các dòng xe ga dung tích lớn.</p>\n<p>Chiều cao yên khoảng 780 mm, mức chiều cao được đánh giá là phù hợp với vóc dáng của người Việt Nam. Ngay cả những người có chiều cao khiêm tốn cũng có thể chống chân chắc chắn khi dừng xe.</p>\n<p>Sàn để chân rộng và phẳng mang lại sự tiện lợi trong quá trình sử dụng. Người lái có thể để chân thoải mái hoặc đặt thêm túi xách, balo khi cần. Thiết kế này cũng đặc biệt phù hợp với người thường xuyên mặc váy hoặc cần mang theo nhiều đồ cá nhân.</p>\n<p>Khoang cốp dưới yên của xe có dung tích tương đối rộng. Người dùng có thể chứa mũ bảo hiểm nửa đầu, áo mưa hoặc một số vật dụng cá nhân khác. Điều này giúp việc di chuyển hằng ngày trở nên thuận tiện hơn mà không cần mang theo quá nhiều túi xách.</p>\n<h2><strong>Ưu điểm lớn so với các dòng xe có cùng phân khúc</strong></h2>\n<p>Khối động cơ xăng 4 thì, 1 xi-lanh, dung tích 49,5cc. Động cơ này cho công suất tối đa khoảng 2.600W tại 6.500 vòng/phút, đủ để đáp ứng nhu cầu di chuyển trong đô thị. Ưu điểm của động cơ 50cc nằm ở khả năng vận hành ổn định và dễ kiểm soát. Khi vặn ga, xe tăng tốc nhẹ nhàng và mượt mà, giúp người mới lái dễ làm quen. Khả năng phản hồi ga cũng khá nhạy nhưng không quá mạnh, tạo cảm giác an toàn khi di chuyển.</p>\n<p>Xe sử dụng hệ thống làm mát bằng không khí, giúp duy trì nhiệt độ động cơ ổn định trong quá trình hoạt động. Nhờ vậy, động cơ ít bị quá nhiệt và có tuổi thọ cao hơn.</p>\n<p>Một điểm đáng chú ý là động cơ của <strong>Dibao Pansy XS1 Neo Pro</strong> được thiết kế theo hướng tiết kiệm nhiên liệu. Mức tiêu hao xăng trung bình của xe khoảng 2,2 lít cho mỗi 100 km. Với bình xăng dung tích khoảng 3,7 đến 4 lít, người dùng có thể di chuyển từ 150 đến 200 km sau mỗi lần đổ đầy nhiên liệu.</p>\n<p>Ngoài ra, xe sử dụng hộp số vô cấp tự động (CVT). Điều này giúp việc điều khiển xe trở nên đơn giản hơn rất nhiều so với xe số truyền thống. Người lái chỉ cần vặn ga để di chuyển và bóp phanh để giảm tốc.</p>\n<p>Xe sử dụng phanh đĩa ở bánh trước và phanh cơ ở bánh sau, mang lại khả năng kiểm soát tốc độ tốt hơn trong nhiều tình huống. Hệ thống phanh này giúp người lái dừng xe an toàn ngay cả khi di chuyển trên đường trơn hoặc cần phanh gấp.</p>\n<p>Hệ thống giảm xóc của xe gồm giảm xóc trước dạng ống lồng và giảm xóc sau lò xo trụ đôi. Sự kết hợp này giúp hấp thụ chấn động tốt khi đi qua gờ giảm tốc hoặc những đoạn đường gồ ghề, mang lại cảm giác lái êm ái hơn.</p>\n<p>Xe cũng được trang bị lốp không săm kích thước 90/90-10. Loại lốp này giúp tăng độ bám đường và giảm nguy cơ thủng lốp khi cán phải vật sắc nhọn.</p>\n<p>Bảng đồng hồ của xe được thiết kế kết hợp giữa điện tử và kim cơ. Các thông tin như vận tốc, quãng đường và mức nhiên liệu đều được hiển thị rõ ràng, giúp người lái dễ dàng theo dõi khi di chuyển.</p>\n<p>Ngoài ra, xe còn có một số tiện ích nhỏ nhưng hữu ích như móc treo đồ phía trước, sàn để chân chống trượt và tay dắt sau chắc chắn. Những chi tiết này tuy đơn giản nhưng lại góp phần nâng cao trải nghiệm sử dụng hàng ngày.</p>\n<h2><strong>Đối tượng người dùng phù hợp với Dibao Pansy XS1 Neo Pro</strong></h2>\n<p>Với học sinh và sinh viên, chiếc xe mang lại khả năng di chuyển an toàn, tiết kiệm chi phí và không yêu cầu bằng lái. Đây là yếu tố khiến nhiều phụ huynh lựa chọn khi mua xe cho con đi học.</p>\n<p>Đối với nhân viên văn phòng trẻ, thiết kế thanh lịch của xe giúp dễ dàng sử dụng trong môi trường công sở. Kích thước nhỏ gọn cũng giúp việc gửi xe tại các bãi đỗ đông đúc trở nên thuận tiện hơn.</p>\n<p>Ngoài ra, những người cần một phương tiện di chuyển đơn giản và tiết kiệm trong thành phố cũng có thể cân nhắc mẫu xe này. Động cơ bền bỉ và chi phí bảo dưỡng thấp giúp xe <strong>Dibao 50cc</strong> trở thành lựa chọn hợp lý cho việc sử dụng lâu dài.</p>\n<p>Chiếc xe mang phong cách scooter thanh lịch, kích thước gọn gàng và động cơ vận hành ổn định. Bên cạnh đó, những trang bị tiện ích và an toàn cơ bản cũng giúp nâng cao trải nghiệm sử dụng hằng ngày.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat', 'Xe Ga 50cc Giorno HSV2 Hyosung Đời Mới Nhất', 'xe-50cc', '[\"xe-tay-ga\"]', 18200000, 18200000, '/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng xe\",\"value\":\"Hyosung\"},{\"label\":\"Xuất xứ\",\"value\":\"Hàn Quốc\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1710mm x 710mm x 1050mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"750mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Vành xe 10 inch\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"Xăng không chì (octane ≥92), 4 kỳ, 1 xi lanh, làm mát bằng không khí\"},{\"label\":\"Vận hành\",\"value\":\"Tự động có nút đề\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50km/h\"},{\"label\":\"Tải trọng\",\"value\":\"140kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"79kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"1,69 lit xăng / 100km\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh cơ trước và sau\"},{\"label\":\"Dung tích xylanh\",\"value\":\"49,5cm3\"},{\"label\":\"Dung tích nhớt máy\",\"value\":\"0,7lit khi thay, 0,8 lít tháo máy\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Ống lồng, lò xo trụ đơn giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, sổ bảo hành\"}]}]', '<p>Một chiếc xe được dùng nhiều năm thường không gây chú ý ở thời điểm mua, mà thể hiện giá trị trong quá trình sử dụng. Ít hỏng vặt, vận hành đều, chi phí thấp và càng dùng càng thấy tiện mới là điều quan trọng. Xe Ga 50cc Giorno HSV2 Hyosung được xây dựng theo triết lý đó, ưu tiên độ bền, sự ổn định và cảm giác thân thiện để người dùng có thể gắn bó lâu dài trong môi trường đô thị.</p>\n<p>không phải ai cũng cần một mẫu xe mạnh, nhiều công nghệ hay thiết kế quá nổi bật. Rất nhiều người chỉ tìm một phương tiện vừa đủ: dễ điều khiển, nhẹ nhàng khi sử dụng hằng ngày và không tạo áp lực cho người lái. Xe Ga 50cc Giorno HSV2 Hyosung ra đời để phục vụ đúng nhóm nhu cầu đó.</p>', '<p>Một chiếc xe được dùng nhiều năm thường không gây chú ý ở thời điểm mua, mà thể hiện giá trị trong quá trình sử dụng. Ít hỏng vặt, vận hành đều, chi phí thấp và càng dùng càng thấy tiện mới là điều quan trọng. Xe Ga 50cc Giorno HSV2 Hyosung được xây dựng theo triết lý đó, ưu tiên độ bền, sự ổn định và cảm giác thân thiện để người dùng có thể gắn bó lâu dài trong môi trường đô thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-7.webp\" alt=\"Xe Ga 50cc Giorno HSV2 Hyosung Chất Lượng Cao\" loading=\"lazy\"></p>\n<h3><strong>Một chiếc xe nhỏ cho nhịp sống chậm rãi trong phố</strong></h3>\n<p>không phải ai cũng cần một mẫu xe mạnh, nhiều công nghệ hay thiết kế quá nổi bật. Rất nhiều người chỉ tìm một phương tiện vừa đủ: dễ điều khiển, nhẹ nhàng khi sử dụng hằng ngày và không tạo áp lực cho người lái. <strong>Xe Ga 50cc</strong> Giorno HSV2 Hyosung ra đời để phục vụ đúng nhóm nhu cầu đó.</p>\n<p>Giorno HSV2 không hướng đến cảm giác “thể thao” hay phô trương. Thay vào đó, xe mang tinh thần của một chiếc xe đô thị thuần túy: gọn, êm, thân thiện và tạo cảm giác an tâm ngay từ lần đầu cầm lái. Đây là mẫu xe phù hợp với những ai đề cao sự ổn định, đặc biệt là học sinh lớn tuổi, người mới đi xe ga hoặc người cần phương tiện di chuyển nhẹ nhàng mỗi ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-8.webp\" alt=\"Xe Ga 50cc Giorno HSV2 Hyosung Chất Lượng Cao\" loading=\"lazy\"></p>\n<h2><strong>Giorno HSV2 Hyosung gọn gàng, đủ chắc để tạo cảm giác yên tâm</strong></h2>\n<p>Điểm dễ nhận thấy nhất trên Xe Ga 50cc Giorno HSV2 Hyosung là dáng xe nhỏ gọn nhưng không “mảnh mai” quá mức. Tổng thể xe được thiết kế hài hòa, các mảng thân bo tròn mềm mại nhưng khung xe vẫn cho cảm giác chắc chắn khi quan sát và khi vận hành thực tế.</p>\n<p>Với kích thước khoảng 1710 x 710 x 1050 mm và trọng lượng chỉ khoảng 79 kg, Giorno HSV2 rất dễ xoay trở trong phố đông, bãi xe hẹp hay những con hẻm nhỏ. Chiều cao yên 750 mm giúp người lái dễ chống chân, đặc biệt phù hợp với vóc dáng người Việt. Đây là yếu tố quan trọng tạo nên sự tự tin khi dừng – khởi hành, nhất là với người mới làm quen xe ga.</p>\n<p>Thiết kế của xe đi theo phong cách trung tính, không kén tuổi, không kén giới. Cụm đèn pha tròn cổ điển kết hợp viền crom tạo điểm nhấn vừa đủ, giúp xe nhìn thanh lịch mà không lỗi thời. Các tùy chọn màu sắc trải từ pastel nhẹ nhàng đến gam trầm sang trọng, cho phép người dùng lựa chọn theo cá tính mà không bị “đóng khung” đối tượng sử dụng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-giorno-hsv2-hyosung-doi-moi-nhat-9.webp\" alt=\"Xe Ga 50cc Giorno HSV2 Hyosung Chất Lượng Cao\" loading=\"lazy\"></p>\n<h2><strong>Điểm tinh tế trên xe Giorno HSV2 Hyosung</strong></h2>\n<p>Điều làm nên giá trị thực tế của Xe Ga 50cc <strong>Giorno HSV2 Hyosung</strong> không nằm ở thông số phức tạp, mà ở cách xe phục vụ người dùng mỗi ngày. Tư thế ngồi được thiết kế thoải mái, tay lái đặt vừa tầm, không gây mỏi vai hay căng lưng khi di chuyển lâu trong đô thị.</p>\n<p>Sàn để chân phẳng và đủ rộng, giúp người lái đặt chân tự nhiên, đồng thời tiện lợi khi mang theo balo, túi xách hoặc đồ dùng cá nhân. Bề mặt sàn có gân chống trượt, tăng độ an toàn khi đi mưa – một chi tiết nhỏ nhưng rất “đúng nhu cầu”.</p>\n<p>Yên xe bọc da êm, độ đàn hồi vừa phải, không gây lún khi ngồi lâu. Khi chở thêm người phía sau, không gian vẫn đủ thoải mái, không tạo cảm giác chật chội. Cốp xe dưới yên tuy không quá lớn nhưng đáp ứng tốt nhu cầu cơ bản như mũ bảo hiểm nửa đầu, áo mưa và các vật dụng cá nhân hằng ngày.</p>\n<p>Bảng đồng hồ cơ truyền thống hiển thị rõ ràng tốc độ, mức xăng và các đèn báo cần thiết. Giao diện đơn giản, dễ nhìn, phù hợp với cả học sinh và người lớn tuổi những đối tượng không cần màn hình điện tử phức tạp.</p>\n<h2><strong>Giorno HSV2 Hyosung đủ để đi lại mỗi ngày</strong></h2>\n<p>Xe Ga 50cc Giorno HSV2 Hyosung sử dụng động cơ xăng 4 thì, dung tích 49.5cc, làm mát bằng không khí. Đây là cấu hình quen thuộc, ưu tiên độ bền và sự ổn định hơn là sức mạnh.</p>\n<p>Vận tốc tối đa khoảng 50 km/h – mức tốc độ an toàn, phù hợp cho việc đi học, đi làm gần hoặc dạo phố. Khi vận hành, xe cho cảm giác ga mượt, ít rung, không giật cục. Ngay cả khi chở hai người, xe vẫn giữ được sự ổn định trong điều kiện giao thông đô thị thông thường.</p>\n<p>Một ưu điểm rất lớn của mẫu xe này nằm ở khả năng tiết kiệm nhiên liệu. Mức tiêu hao trung bình chỉ khoảng 1.68 lít/100 km. Với bình xăng 4.5 lít, xe có thể di chuyển hơn 250 km cho mỗi lần đổ đầy – giúp người dùng giảm đáng kể chi phí vận hành hàng tháng.</p>\n<p>Hệ thống phanh đĩa trước kết hợp phanh tang trống sau mang lại lực phanh vừa phải, dễ kiểm soát, phù hợp với người mới lái. Giảm xóc trước ống lồng và giảm xóc sau thủy lực giúp xe vận hành êm ái khi đi qua gờ giảm tốc hoặc mặt đường không bằng phẳng. Lốp không săm Kenda tăng độ bám đường và độ an toàn khi di chuyển dưới trời mưa.</p>\n<p>Xe Ga 50cc Giorno HSV2 <strong>Hyosung</strong> không phải là mẫu xe để gây ấn tượng ngay lập tức bằng công nghệ hay sức mạnh. Giá trị của xe nằm ở sự ổn định, ít hỏng vặt và chi phí sử dụng dễ chịu theo thời gian.</p>\n<p>Cấu trúc xe đơn giản giúp việc bảo dưỡng nhanh chóng và tiết kiệm. Các linh kiện phổ biến, dễ thay thế, không gây phiền toái trong quá trình sử dụng lâu dài. Khung xe được sơn tĩnh điện nhiều lớp, hạn chế gỉ sét và giữ màu tốt khi sử dụng thường xuyên ngoài trời.</p>\n<p>Với thiết kế thân thiện, động cơ bền bỉ và khả năng tiết kiệm nhiên liệu, Giorno HSV2 là lựa chọn phù hợp cho những ai cần một chiếc xe nhỏ, dễ dùng, không áp lực và đủ tin cậy để gắn bó mỗi ngày.</p>\n<br>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-osakar-nispa-lumia-rova-p', 'Xe Ga 50cc Osakar Nispa Lumia Rova P', 'xe-50cc', '[\"xe-tay-ga\"]', 19300000, 19300000, '/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-lumia-rova-p-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-osakar-nispa-vera-p', 'Xe Ga 50cc Osakar Nispa Vera P', 'xe-50cc', '[\"xe-tay-ga\"]', 19300000, 19300000, '/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-6.webp\"]', '[]', '[]', '[]', '<p>Quên đi những chiếc xe ga 50cc nhàm chán, giờ đây, bạn có thể bước ra phố với một tuyên ngôn phong cách đầy ấn tượng. Osakar Nispa Vera P không chỉ là một phương tiện di chuyển đơn thuần mà là sự khẳng định cá tính, là cách bạn xuất hiện giữa phố đông với thần thái tự tin và gu thẩm mỹ khác biệt. Lấy cảm hứng từ huyền thoại Vespa, nhưng được tái sinh trong hình hài hiện đại, trẻ trung và phù hợp hơn với nhịp sống đô thị Việt Nam, Vera P mang đến một làn gió mới cho phân khúc xe ga 50cc vốn đã quá quen thuộc.</p>\n<p>Ngay từ ánh nhìn đầu tiên, Osakar Nispa Vera P đã tạo nên sức hút khó cưỡng nhờ những đường cong mềm mại chạy dọc thân xe, gợi nhớ đến phong cách Ý cổ điển nhưng không hề cũ kỹ. Tổng thể xe được cân đối hài hòa giữa phần đầu bo tròn thanh thoát và thân xe thuôn dài thanh lịch, tạo cảm giác vừa sang trọng vừa gần gũi. Đây không phải là sự sao chép hình thức mà là sự chắt lọc tinh thần thiết kế – giữ lại nét hoài niệm, đồng thời bổ sung các chi tiết hiện đại để phù hợp với thế hệ người dùng trẻ trung, năng động.</p>', '<p>Quên đi những chiếc xe ga 50cc nhàm chán, giờ đây, bạn có thể bước ra phố với một tuyên ngôn phong cách đầy ấn tượng. Osakar Nispa Vera P không chỉ là một phương tiện di chuyển đơn thuần mà là sự khẳng định cá tính, là cách bạn xuất hiện giữa phố đông với thần thái tự tin và gu thẩm mỹ khác biệt. Lấy cảm hứng từ huyền thoại <strong>Vespa</strong>, nhưng được tái sinh trong hình hài hiện đại, trẻ trung và phù hợp hơn với nhịp sống đô thị Việt Nam, Vera P mang đến một làn gió mới cho phân khúc xe ga 50cc vốn đã quá quen thuộc.</p>\n<p><strong><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-7.webp\" alt=\"\" loading=\"lazy\"></strong></p>\n<h2><strong>Vespa tái sinh trong hình hài hiện đại: đẹp mê mẩn, vạn người mê!</strong></h2>\n<p>Ngay từ ánh nhìn đầu tiên, <strong>Osakar Nispa Vera P</strong> đã tạo nên sức hút khó cưỡng nhờ những đường cong mềm mại chạy dọc thân xe, gợi nhớ đến phong cách Ý cổ điển nhưng không hề cũ kỹ. Tổng thể xe được cân đối hài hòa giữa phần đầu bo tròn thanh thoát và thân xe thuôn dài thanh lịch, tạo cảm giác vừa sang trọng vừa gần gũi. Đây không phải là sự sao chép hình thức mà là sự chắt lọc tinh thần thiết kế – giữ lại nét hoài niệm, đồng thời bổ sung các chi tiết hiện đại để phù hợp với thế hệ người dùng trẻ trung, năng động.</p>\n<p>Phần đầu xe nổi bật với cụm đèn pha thiết kế sắc sảo, tích hợp công nghệ LED cho ánh sáng rõ và đều, đảm bảo khả năng chiếu sáng tốt khi di chuyển ban đêm. Đèn xi nhan và đèn hậu được bố trí gọn gàng, tinh tế, vừa đảm bảo tính an toàn khi lưu thông, vừa tăng thêm điểm nhấn thẩm mỹ. Các chi tiết như tay lái, gương chiếu hậu, viền đèn, logo đều được hoàn thiện tỉ mỉ, thể hiện sự đầu tư nghiêm túc trong khâu thiết kế.</p>\n<p>Không thể không nhắc đến bảng màu đa dạng của Nispa Vera P. Từ những gam màu trung tính như trắng, đen, xám, be cho đến các sắc màu nổi bật như đỏ, xanh hay hồng, mỗi phiên bản đều mang một cá tính riêng. Người dùng có thể dễ dàng lựa chọn màu sắc phù hợp với phong cách cá nhân, biến chiếc xe trở thành một phần trong hình ảnh thường ngày của mình chứ không chỉ là phương tiện đi lại.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Không gian riêng của bạn: tiện nghi tối ưu cho nhịp sống vội vã</strong></h2>\n<p>Trong môi trường đô thị đông đúc, một chiếc xe đẹp thôi là chưa đủ, nó còn phải tiện lợi và thực dụng. Osakar Nispa Vera P được thiết kế để đáp ứng chính xác nhu cầu đó với hàng loạt tiện ích được bố trí hợp lý và khoa học. Cốp xe rộng rãi là một điểm cộng lớn khi có thể chứa mũ bảo hiểm nửa đầu, áo mưa và nhiều vật dụng cá nhân khác, giúp người dùng không còn phải lỉnh kỉnh mang theo quá nhiều đồ bên ngoài.</p>\n<p>Sàn để chân phẳng và rộng tạo cảm giác thoải mái khi ngồi lái, đặc biệt phù hợp với phái nữ khi có thể đặt thêm túi xách hoặc balo phía trước mà vẫn đảm bảo an toàn. Tư thế ngồi được thiết kế tự nhiên, không gò bó, giúp người lái không bị mỏi khi di chuyển quãng đường dài trong thành phố.</p>\n<p>Bảng đồng hồ hiển thị rõ ràng các thông số cơ bản như tốc độ, mức nhiên liệu và quãng đường, giúp người lái dễ dàng theo dõi tình trạng vận hành của xe. Cụm công tắc bố trí vừa tầm tay, thao tác nhẹ và nhạy, giúp người dùng nhanh chóng làm quen dù là lần đầu sử dụng xe ga.</p>\n<p><strong><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-vera-p-9.webp\" alt=\"\" loading=\"lazy\"></strong></p>\n<h2><strong>Trái tim êm ái, mạnh mẽ và tiết kiệm</strong></h2>\n<p>Ẩn dưới lớp vỏ thanh lịch là khối động cơ 50cc 4 kỳ vận hành bền bỉ và ổn định. Đây là loại động cơ được đánh giá cao trong phân khúc nhờ khả năng hoạt động êm ái, ít rung và tiết kiệm nhiên liệu. Khi di chuyển trong phố, xe cho cảm giác mượt mà, không giật cục, rất phù hợp với học sinh hoặc người mới bắt đầu làm quen với xe máy.</p>\n<p>Mức tiêu thụ nhiên liệu trung bình chỉ khoảng hơn 2 lít trên 100 km, giúp giảm đáng kể chi phí sử dụng hằng tháng. Trong bối cảnh giá xăng có nhiều biến động, một chiếc xe tiết kiệm nhiên liệu chính là giải pháp kinh tế thông minh cho gia đình. Bên cạnh đó, động cơ 4 kỳ nổi tiếng với độ bền cao, ít hỏng vặt, chi phí bảo dưỡng thấp, mang lại sự an tâm trong quá trình sử dụng lâu dài.</p>\n<p>Một ưu điểm quan trọng khác của dòng xe 50cc là không yêu cầu bằng lái đối với người từ 16 tuổi trở lên theo quy định hiện hành. Điều này mở ra sự chủ động trong việc di chuyển cho học sinh, giúp các bạn có thể tự đến trường, học thêm hoặc tham gia hoạt động ngoại khóa mà vẫn đảm bảo tuân thủ pháp luật.</p>\n<h2><strong>An toàn là nền tảng của mọi hành trình</strong></h2>\n<p><strong>Osakar</strong> Nispa Vera P không chỉ tập trung vào vẻ ngoài mà còn chú trọng đến yếu tố an toàn trong quá trình vận hành. Hệ thống phanh trước và sau được tinh chỉnh để mang lại khả năng kiểm soát ổn định trong nhiều tình huống giao thông khác nhau. Khi cần giảm tốc đột ngột, xe vẫn giữ được sự cân bằng cần thiết, hạn chế trượt bánh.</p>\n<p>Bộ giảm xóc hoạt động hiệu quả giúp xe vận hành êm ái hơn khi đi qua các đoạn đường gồ ghề. Lốp xe có độ bám tốt, hỗ trợ tăng độ ổn định khi vào cua hoặc di chuyển trên mặt đường trơn nhẹ. Khung xe chắc chắn cũng góp phần tạo nên cảm giác an tâm cho người điều khiển.</p>\n<h2><strong>Giá trị vượt mong đợi trong phân khúc 50cc</strong></h2>\n<p>Với mức giá dao động trong khoảng hơn 20 triệu đồng tùy phiên bản và khu vực phân phối, Osakar Nispa Vera P nằm trong nhóm xe ga 50cc có mức đầu tư hợp lý. So với những gì chiếc xe mang lại từ thiết kế, tiện ích cho đến khả năng vận hành, đây là lựa chọn cân bằng giữa chi phí và giá trị sử dụng.</p>\n<p>Không chỉ phù hợp với học sinh, Nispa Vera P còn là phương án lý tưởng cho người nội trợ, nhân viên văn phòng hoặc người lớn tuổi cần một phương tiện gọn nhẹ, dễ điều khiển và tiết kiệm. Thiết kế thanh lịch giúp xe không bị giới hạn bởi độ tuổi hay giới tính, ai cũng có thể tìm thấy sự phù hợp trong đó.</p>\n<p>Osakar Nispa Vera P là minh chứng cho việc<strong> xe ga 50cc</strong> không hề nhàm chán nếu được đầu tư đúng mức về thiết kế và chất lượng. Từ cảm hứng cổ điển pha trộn hiện đại, không gian tiện nghi phục vụ nhu cầu hằng ngày, động cơ êm ái tiết kiệm cho đến mức giá dễ tiếp cận, tất cả tạo nên một mẫu xe đáng cân nhắc trong phân khúc.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe không chỉ để đi lại mà còn để thể hiện phong cách, Osakar Nispa Vera P chính là lựa chọn đáng để trải nghiệm. Một chiếc xe nhỏ gọn, thanh lịch nhưng đủ sức khiến bạn nổi bật giữa phố đông – đó mới là giá trị thực sự của một mẫu xe ga 50cc thời đại mới.</p>\n&nbsp;\n&nbsp;\n&nbsp;', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-osakar-nispa-viva-p', 'Xe Ga 50cc Osakar Nispa Viva P', 'xe-50cc', '[\"xe-tay-ga\"]', 21200000, 21200000, '/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-6.webp\"]', '[]', '[]', '[]', '<p>Ngay từ khi ra mắt, mẫu Xe Ga 50cc Osakar Nispa Viva P đã nhanh chóng thu hút sự quan tâm của nhiều nhóm người dùng khác nhau, đặc biệt là học sinh, sinh viên hoặc những người cần một chiếc xe nhẹ nhàng để đi lại hàng ngày. Không quá phô trương về thiết kế hay hiệu năng, Xe Ga 50cc Osakar Nispa Viva P hướng đến sự cân bằng giữa ngoại hình thanh lịch, khả năng vận hành ổn định và chi phí sử dụng hợp lý.</p>\n<p>Thị trường có khá nhiều mẫu xe 50cc với thiết kế tương tự nhau. Tuy nhiên, Xe Ga 50cc Osakar Nispa Viva P vẫn tạo được dấu ấn riêng nhờ sự kết hợp hài hòa giữa phong cách thiết kế, kích thước xe và tính tiện dụng trong thực tế.</p>', '<p>Ngay từ khi ra mắt, mẫu Xe Ga 50cc Osakar Nispa Viva P đã nhanh chóng thu hút sự quan tâm của nhiều nhóm người dùng khác nhau, đặc biệt là học sinh, sinh viên hoặc những người cần một chiếc xe nhẹ nhàng để đi lại hàng ngày. Không quá phô trương về thiết kế hay hiệu năng, Xe Ga 50cc Osakar Nispa Viva P hướng đến sự cân bằng giữa ngoại hình thanh lịch, khả năng vận hành ổn định và chi phí sử dụng hợp lý.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-7.webp\" alt=\"Xe Ga 50cc Osakar Nispa Viva P\" loading=\"lazy\"></p>\n<h2><strong>Điểm khác biệt của mẫu xe so với các đối thủ</strong></h2>\n<p>Thị trường có khá nhiều mẫu <strong>xe 50cc</strong> với thiết kế tương tự nhau. Tuy nhiên, Xe Ga 50cc Osakar Nispa Viva P vẫn tạo được dấu ấn riêng nhờ sự kết hợp hài hòa giữa phong cách thiết kế, kích thước xe và tính tiện dụng trong thực tế.</p>\n<p>Điểm dễ nhận ra nhất chính là thiết kế tổng thể mang hơi hướng scooter cổ điển châu Âu. Các đường nét trên thân xe được tạo hình mềm mại, bo tròn và liền mạch, tạo nên cảm giác thanh lịch nhưng không lỗi thời. Phần đầu xe nổi bật với cụm đèn pha LED dạng khối vuông viền crom sáng, vừa giữ được nét hoài cổ vừa mang lại cảm giác hiện đại.</p>\n<p>Ánh sáng từ hệ thống đèn LED cho độ chiếu sáng rõ ràng, phân bố đều và giúp người lái quan sát tốt hơn khi di chuyển vào buổi tối hoặc trong điều kiện thời tiết xấu. So với các mẫu xe 50cc sử dụng đèn halogen thông thường, hệ thống đèn này mang lại hiệu quả chiếu sáng tốt hơn và tiêu thụ điện năng thấp hơn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-8.webp\" alt=\"Xe Ga 50cc Osakar Nispa Viva P\" loading=\"lazy\"></p>\n<p>Một yếu tố khác khiến Xe Ga 50cc Osakar Nispa Viva P nổi bật hơn một số đối thủ nằm ở kích thước xe được thiết kế khá hợp lý cho điều kiện giao thông Việt Nam. Xe có chiều dài khoảng 1.740 mm, rộng 705 mm và cao 1.125 mm – đủ gọn để di chuyển linh hoạt nhưng vẫn giữ được sự cân đối khi vận hành.</p>\n<p>Chiều cao yên xe khoảng 750 mm kết hợp với trọng lượng chỉ khoảng 84 kg giúp việc chống chân và dắt xe trở nên dễ dàng. Đây là một lợi thế lớn đối với người mới sử dụng xe máy hoặc người có vóc dáng nhỏ.</p>\n<p>Ngoài ra, bảng màu của xe cũng được lựa chọn khá đa dạng. Bên cạnh các màu cơ bản như đen, trắng và đỏ, xe còn có những màu sắc trẻ trung như xanh ngọc, ghi đá hay hồng pastel. Lớp sơn phủ tĩnh điện hai lớp kết hợp khả năng chống tia UV giúp xe giữ được độ bóng và màu sắc bền đẹp theo thời gian.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-ga-50cc-osakar-nispa-viva-p-9.webp\" alt=\"Xe Ga 50cc Osakar Nispa Viva P\" loading=\"lazy\"></p>\n<h2><strong>Nâng cấp đáng chú ý trong phiên bản xe ga 50cc Osakar Nispa Viva P mới</strong></h2>\n<p>Ở phiên bản mới, Xe Ga <strong>Osakar Nispa Viva P 50cc</strong> được cải thiện một số chi tiết nhằm mang lại trải nghiệm sử dụng tốt hơn cho người dùng.</p>\n<p>Một trong những nâng cấp đáng chú ý nằm ở hệ thống chiếu sáng. Xe sử dụng công nghệ đèn LED cho cả cụm đèn pha và đèn hậu, giúp tăng độ sáng và cải thiện khả năng nhận diện khi di chuyển trong điều kiện thiếu ánh sáng. Ngoài ra, đèn LED cũng có tuổi thọ cao hơn so với các loại bóng đèn truyền thống.</p>\n<p>Bảng đồng hồ của xe cũng được nâng cấp sang dạng điện tử LED hiện đại. Màn hình hiển thị các thông tin quan trọng như tốc độ, mức nhiên liệu và tín hiệu đèn một cách rõ ràng, dễ quan sát. Đồng hồ còn đạt tiêu chuẩn chống nước IP67, giúp đảm bảo khả năng hoạt động ổn định ngay cả khi xe di chuyển dưới trời mưa lớn hoặc trong quá trình rửa xe.</p>\n<p>Không gian lưu trữ trên xe cũng được tối ưu hơn để phục vụ nhu cầu sử dụng hàng ngày. Cốp xe có dung tích khoảng 25 lít, đủ để chứa một mũ bảo hiểm cùng với một số vật dụng cá nhân như áo mưa, balo hoặc túi xách nhỏ.</p>\n<p>Ngoài cốp chính, phần phía trước còn được trang bị hai hộc chứa đồ nhỏ. Người dùng có thể để điện thoại, chìa khóa hoặc chai nước một cách thuận tiện khi di chuyển.</p>\n<h2><strong>Hiệu năng vượt trội trong tầm giá</strong></h2>\n<p>Xe sử dụng động cơ xăng 4 kỳ, 1 xi-lanh, làm mát bằng không khí với dung tích thực 49.4cc. Khối động cơ này được thiết kế nhằm ưu tiên sự ổn định và độ bền thay vì tập trung vào hiệu suất cao.</p>\n<p>Công suất cực đại của xe đạt khoảng 2.7 kW tại 8.000 vòng/phút. Với mức công suất này, xe có thể tăng tốc mượt mà trong điều kiện giao thông đô thị. Tốc độ tối đa của xe khoảng 50 km/h, phù hợp với quy định dành cho xe 50cc và giúp người dùng có thể sử dụng xe mà không cần giấy phép lái xe.</p>\n<p>Hệ truyền động CVT tự động giúp việc điều khiển xe trở nên đơn giản hơn. Người lái chỉ cần vặn ga để di chuyển mà không cần phải sang số hay thao tác côn tay. Điều này đặc biệt phù hợp với học sinh, sinh viên hoặc những người mới làm quen với xe máy.</p>\n<p>Một điểm đáng chú ý khác của Xe Ga 50cc Osakar Nispa Viva P là khả năng tiết kiệm nhiên liệu. Mức tiêu hao trung bình của xe chỉ khoảng 2.2 lít xăng cho mỗi 100 km di chuyển. Khi kết hợp với bình xăng dung tích 4 lít, xe có thể đi được khoảng 180 km sau mỗi lần đổ đầy.</p>\n<p>Điều này giúp người dùng giảm đáng kể chi phí nhiên liệu trong quá trình sử dụng, đặc biệt khi chỉ cần di chuyển trong phạm vi nội đô.</p>\n<p>Cảm giác tăng ga của xe khá nhẹ nhàng và ổn định. Xe không tăng tốc quá đột ngột mà phản hồi ga theo cách từ tốn, giúp người lái dễ kiểm soát hơn khi di chuyển trong những khu vực đông phương tiện.</p>\n<h2><strong>Lý do mẫu xe ga 50cc Osakar Nispa Viva P này xứng đáng để sở hữu</strong></h2>\n<p>Không chỉ dừng lại ở thiết kế đẹp hay động cơ tiết kiệm nhiên liệu, Xe Ga 50cc Osakar Nispa Viva P còn mang lại nhiều giá trị thực tế cho người dùng trong quá trình sử dụng hàng ngày.</p>\n<p>Hệ thống khung gầm của xe được thiết kế khá chắc chắn, kết hợp với hệ thống giảm xóc trước dạng ống lồng và giảm xóc sau lò xo đôi Eagle. Nhờ đó, xe có thể hấp thụ tốt các dao động khi đi qua ổ gà hoặc gờ giảm tốc.</p>\n<p>Ngay cả khi chở hai người hoặc di chuyển trên những đoạn đường không bằng phẳng, xe vẫn giữ được sự ổn định cần thiết.</p>\n<p>Bộ lốp không săm Kenda kích thước 90/90-10 kết hợp với vành đúc hợp kim nguyên khối giúp tăng độ bám đường và cải thiện khả năng kiểm soát khi vào cua. Lốp không săm cũng an toàn hơn trong trường hợp cán phải vật nhọn trên đường.</p>\n<p>Hệ thống phanh của xe gồm phanh đĩa thủy lực phía trước và phanh tang trống phía sau. Sự kết hợp này giúp tăng hiệu quả phanh và hỗ trợ người lái kiểm soát xe tốt hơn trong những tình huống cần giảm tốc đột ngột.</p>\n<p>Ngoài ra, thiết kế sàn để chân rộng và phẳng giúp người dùng có tư thế ngồi thoải mái hơn khi di chuyển. Bề mặt sàn được làm nhám để hạn chế trơn trượt, đặc biệt hữu ích khi trời mưa.</p>\n<p>Yên xe được bọc da mềm với đường chỉ may nổi tạo cảm giác cao cấp hơn so với nhiều mẫu xe cùng phân khúc. Thiết kế yên rộng cũng giúp cả người lái và người ngồi sau cảm thấy dễ chịu khi di chuyển trong thời gian dài.</p>\n<p>Tay lái nhẹ, trọng lượng xe chỉ khoảng 84 kg giúp việc dắt xe hoặc quay đầu xe trở nên đơn giản. Điều này đặc biệt thuận tiện khi gửi xe ở bãi đông hoặc di chuyển trong những con hẻm nhỏ.</p>\n<p>Trong phân khúc xe ga dung tích nhỏ, <strong>Xe Ga 50cc Osakar</strong> Nispa Viva P không hướng đến sự hào nhoáng hay hiệu năng vượt trội. Thay vào đó, mẫu xe tập trung vào những yếu tố thiết thực nhất đối với người dùng, hãy đến Yên Thoa để trải nghiệm ngay</p>', 1);
