INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-vera-s-viet-thai-the-he-moi', 'Xe Ga 50cc Vera S Việt Thái Thế Hệ Mới', 'xe-50cc', '[\"xe-tay-ga\"]', 18700000, 18700000, '/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vera-s-viet-thai-the-he-moi-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-ga-50cc-vespa-dibao-pansy-xs', 'Xe Ga 50cc Vespa Dibao Pansy XS', 'xe-50cc', '[\"xe-tay-ga\"]', 21390000, 21390000, '/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-1.webp', '[\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-1.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-2.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-3.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-4.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-5.webp\",\"/sites/yenthoa/img/sp/xe-ga-50cc-vespa-dibao-pansy-xs-6.webp\"]', '[]', '[]', '[]', '<p>XE MÁY 50CC PANSY DIBAO XS CHIẾC XE MÁY 50CC ĐỈNH CAO TỪ THIẾT KẾ CHO ĐẾN CHẤT LƯỢNG CỦA HÃNG DIBAO. LÀ DÒNG XE TAY GA 50CC DUY NHẤT CÓ CẢ ĐỘNG CƠ LẪN LINH KIỆN ĐỀU NHẬP 100% TỪ NGƯỚC NGOÀI. ĐẶC BIỆT PHẦN ĐỘNG CƠ NHẬP KHẨU NGUYÊN CHIẾC CHẠY CỰC KỲ TIẾT KIỆM XĂNG.</p>\n<p>Đa số 90% các dòng xe tay ga 50cc ở Việt Nam động cơ của xe được sản xuất tại Việt Nam luôn nhưng với Pansy XS Dibao thì động cơ của xe được nhập khẩu nguyên chiếc 100% do đó chất lượng của xe ăn đứt các mẫu xe ga khác trên thị trường.</p>', '<p><strong>XE MÁY 50CC PANSY DIBAO XS</strong>&nbsp;CHIẾC XE MÁY 50CC ĐỈNH CAO TỪ THIẾT KẾ CHO ĐẾN CHẤT LƯỢNG CỦA HÃNG DIBAO. LÀ DÒNG <strong>XE TAY GA 50CC</strong> DUY NHẤT CÓ CẢ ĐỘNG CƠ LẪN LINH KIỆN ĐỀU NHẬP 100% TỪ NGƯỚC NGOÀI. ĐẶC BIỆT PHẦN ĐỘNG CƠ NHẬP KHẨU NGUYÊN CHIẾC&nbsp;CHẠY CỰC KỲ TIẾT KIỆM XĂNG.</p>\n<p>Đa số 90% các dòng xe tay ga 50cc ở Việt Nam động cơ của xe được sản xuất tại Việt Nam luôn nhưng với Pansy XS Dibao thì động cơ của xe được nhập khẩu nguyên chiếc 100% do đó chất lượng của xe ăn đứt các mẫu xe ga khác trên thị trường.</p>\n<h2><strong>GIỚI THIỆU VỀ CHẤT LƯỢNG XE THƯƠNG HIỆU DIBAO</strong></h2>\n<p>1. Hãng Dibao là 1 trong 3 hãng sản xuất xe điện lớn nhất thế giới hiện nay, và các loại xe của Dibao có mặt trên thịa trường Việt Nam đều được sản xuất 100% từ nước ngoài và nhập linh kiện về việt nam lắp ráp trên dây truyền công nghệ hiện đại do TẬP ĐOÀN DIBAO UỶ QUYỀN. Chứ không phải như nhiều hãng xe thương hiệu của Việt Nam nhập các linh kiện được sản xuất trong nước và lắp ráp xe. Chính vì vậy khi bạn đã trực tiếp xem hoặc tốt nhất là trải nghiệm xe điện hay xe máy 50cc của Dibao bạn sẽ cảm thấy xe của Dibao luôn chắc chắn và tốt hơn rất nhiều so với nhiều loại xe khác.</p>\n<p>2 : Hãng Dibao là tên tuổi lớn rất thành công ở Việt Nam càng ngày càng nhiều người sử dụng xe điện của Dibao và cảm thấy rất hài lòng với số tiền mình bỏ ra.</p>\n<p>3 : Luôn ưu tiên đặt chất lượng lên hàng đầu nên khi sản xuất xe hãng Dibao sản xuất luôn rất cẩn trọng và tỷ mỉ, riêng mẫu xe 50cc DIBAO PANSY XS hãng đã thử nghiệm trong suốt 2 năm từ giữa năm 2018 cho đến bây giờ là năm 2020, và sau hàng loạt những thay thế nâng cấp để tạo ra 1 chiếc xe tốt và hoàn hảo nhất đến tận tháng 6 năm 2020&nbsp;sau hàng loạt những thử nghiệp từ nước ngoài, cục đăng kiểm và quá trình chạy thử rất lâu hãng Dibao mới bắt đầu cho ra mắt sản phẩm đầu tiên.</p>\n<p>Mời các bạn cùng chúng tôi tìm hiểu kĩ hơn về&nbsp;<strong>Xe Ga 50cc </strong>DIBAO&nbsp;Vespa PANSY XS:&nbsp;</p>\n<p>Nhìn tổng thể bạn sẽ thấy được nét đẹp và sự lôi cuốn của chiếc PANSY XS Dibao 50cc này. Mọi đường nét, mọi chi tiết của xe đều được hãng cực kỳ chăm chút tỉ mỉ cho xe có độ sắc xảo, nổi bật hơn hẳn so với các dòng Vespa 50cc khác trên thị trường.&nbsp;</p>\n<p>Nổi bật hơn nữa là phần đầu xe có được viền kim loại mạ crom sáng bóng khá bắt mắt. Đặc biệt cả phần yếm trước của xe cũng được viền kim loại kéo dài từ yếm trước xuống đến hết sàn để chân của xe. Tao nên vẻ đẹp sang trọng thời thượng và đậm chất hiện đại.&nbsp;</p>\n<p>Nếu bạn để ý kỹ thì thương hiệu&nbsp;Dibao luôn xuất hiện ở mọi linh kiện của xe từ phần dàn áo, cho đến hệ thống đèn pha. Với đèn pha ở bên trong có một thanh kim loạt nằm chắn ngang và có khắc chữ Dibao bằng kim loại mạ crom nổi bật.</p>\n<p>Về phần tay lái của xe máy 50cc Vespa Dibao PANSY XS thiết kế cực kỳ chắc chắn với ghi đông được hàn tiện từ công nghệ tiên tiến nhất Châu Âu có độ chính xác cao. Đảm bảo tay lái luôn vững vàng trước mọi địa hình. Về cụm công tắc thì được phân bố khoa học với bên tay trái là các công tắc thường sử dụng khi xe di chuyển như đèn pha cos, còi và xi nhan trái phải.&nbsp;</p>\n<p>Còn cụm công tắc bên tay phải chủ yếu 2 loại chính đó là công tắc bật tắt đèn pha và công tắc đề. Đây là khung chuẩn chung hiện nay với các dòng xe máy, xe tay ga trên thị trường rồi. Nên việc làm quen các cụm công tắc này rất là đơn giản lên ngồi lái xe là bạn sẽ quen thuộc ngay.&nbsp;</p>\n<p>Ở ngay ốp mặt nạ trước hình chữ U bạn có thể thấy được có một tấm kim loại được mạ crom sáng bóng với những khe hút gió. Thì khe lọc gió này có tác dụng chuyển hướng gió, không khi đi vào lóc máy của xe giúp xe tản nhiệt tốt hơn, thông thoáng hơn. Từ đó mà xe luôn hoạt động ở điều kiện tốt với hiệu suất cao. Hai bên yếm trước chính là 2 xi nhan trái phải thiết kế đối xứng có dải đèn sương mù viền quanh khá là bắt mắt. Nhất là di chuyển vào buổi tối thì chiếc xe tay ga 50cc Vespa PANSY XS Dibao này trở nên cực kỳ lộng lẫy.&nbsp;</p>\n<p>Xe PANSY XS có thiết kế chân chống đứng và cả chân chống cạnh khá là tiện lợi. Cả 2 chân chống này đều được làm từ hợp kim cao cấp cực kỳ chắc chắn. Áp dụng công nghệ hàn tiện cao cấp từ Châu Âu nên đem lại tính thẩm mỹ cao.&nbsp;</p>\n<h2><strong>VÌ SAO NÊN CHỌN CHO MÌNH MỘT CHIẾC XE GA 50CC CHẤT LƯỢNG CAO NHƯ DIBAO PANSY XS?</strong></h2>\n<p>Nhiều người cứ nghĩ tầm giá đó thì đều như nhau thì đó là sai lầm vì chỉ chênh nhau 1 triệu đồng thôi chúng tôi cam kết với bạn chất lượng xe khác hẳn nhau chứ chưa nói đến cao hơn mấy triệu đồng. Mua xe rẻ khiến bạn tiết kiệm được khoản tiền trước mắt nhưng bạn sẽ mất rất nhiều tiền đổ xăng sau này khoảng 3,5 đến 4,5 lít xăng / 100km thì cứ mỗi năm 1 em học sinh đi học phải đổ trên 15 triệu tiền xăng so với chỉ 3-4 triệu / 1 năm khi sử dụng xe tiết kiệm nguyên liệu. Xe tốt không bị lỗi hỏng vặt rất khổ nhất là khi đứng giữa trưa trời nắng xe hỏng mà không làm cách nào được, và đặc biệt mua xe vì sự an toàn của bạn, gia đình và người thân chứ đừng mua xe máy 50cc vì mẫu mã, màu sắc, hay giá rẻ.</p>\n<h3><strong>Cách để chọn 1 chiếc xe máy 50cc chất lượng cao:</strong></h3>\n<p>- Đầu tiên là phải đẹp, tất nhiên là phải đẹp hoàn hảo từ thiết kế, sắc nét và mọi chi tiết phải hợp lý không thô xấu.</p>\n<p>-&nbsp;Nhìn nhựa xe phải thật sắc nét, chắc chắn, sơn xe đẹp và tỷ mỉ. Độ hở giữa các chỗ nối 2 phần nhựa với nhau phải chuẩn chứ không quá to hay quá nhỏ hoặc chỗ to chỗ nhỏ.</p>\n<p>-&nbsp;Hãng sản xuất của nước ngoài và phải thật nổi tiếng.</p>\n<p>-&nbsp;Xem đến phần khung xe phải dày dặn, những mối hàn phải chắc chắn và đẹp chứ không nham nhở. Đến khung xe mà hàn xấu thì chất lượng xe không ra gì mà rất nguy hiểm nếu gãy khung càng.</p>\n<p>-&nbsp;Xem từng chi tiết như vành bánh phải chắc chắn sắc nét, giảm xóc phải êm ái chứ cứng như ngồi trên khối bê tông thì dừng ngay việc mua nhé, yên xe sắc nét và êm ái, máy móc làm cản thận tỷ mỉ, kể cả phần không quan trọng lắm như chân chống giữa chân chống cạnh cũng phải đẹp và sắc nét cứng cáp, dựng chân chống cạnh ngồi lên xe nhiều xe bị oải ra ngay vì chất lượng kém.</p>\n<p>-&nbsp;Ngồi lên xe phải cảm nhận ngay được sự chắc chắn không ọp ẹp, xe đi đến những chỗ xóc nếu là xe điện thì hơi kêu do acquy trong xe lắp rời nhưng xe máy 50cc phải cảm thấy ngay sự chắc nịch của xe không 1 tiếng động khi đi vào những đoạn đường xấu.</p>\n<p>-&nbsp;Máy xe phải khoẻ và thoáng đi với vận tốc 35km / h phải cảm thấy êm ru , vặn ga lên không bị hụt hơi.</p>\n<p>-&nbsp;Và đặc biệt là theo kinh nghiệm bán hàng nhiều năm của TGXĐ riêng xe 2 bánh thì các bạn nhìn vào thống số kỹ thuật nếu chuẩn thì đẹp nhất. Hoặc bạn đến tận nơi xem chiếc xe đó có nặng không. Xe càng nặng thì càng tốt chất lượng càng cao chứ nhiều xe máy 50cc còn nhẹ như bèo nhẹ hơn cả xe đạp điện thì làm sao tốt được. Vì sao càng năng càng tốt lý do là khung dày và sử dụng thép loại tốt sẽ nặng, máy móc sử dụng vật liệu tốt thì sẽ nặng và bền bỉ, nhựa dày và tốt chắc chắn sẽ nặng hơn nhựa mỏng và chất lượng kém, và tất cả các thứ khác trên xe máy 50cc cứ tốt hơn thì chắc chắn sẽ nặng hơn.</p>\n<p>Yên Thoa -&nbsp;<strong>Xe ga 50cc&nbsp;</strong>cam kết chỉ bán sản phẩm đẳng cấp chính hãng chất lượng cao của những lớn uy tín và nổi tiếng nhất thế giới. Chúng tôi luôn khuyên quý khách tìm hiểu về hãng sản xuất và xem thật kỹ sản phẩm để mua được những sản phẩm tốt nhất. Tránh mua nhầm hàng giả, nhái, kém chất lượng.</p>\n&nbsp;\n&nbsp;\n&nbsp;', 1);
