INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-50cc-wave-victoria-viet-nhat-2023', 'Xe Máy 50cc Wave Victoria Việt Nhật 2023', 'xe-50cc', '[\"xe-so\"]', 14990000, 14990000, '/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-1.webp\",\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-2.webp\",\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-3.webp\",\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-4.webp\",\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-5.webp\",\"/sites/yenthoa/img/sp/xe-may-50cc-wave-victoria-viet-nhat-2023-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Victoria\"},{\"label\":\"Xuất xứ\",\"value\":\"Liên doanh\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"6 tháng\"},{\"label\":\"Động cơ\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1640mm x 640mm x 1200mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"750mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Vành 17 inch\"},{\"label\":\"Màu sắc\",\"value\":\"Đủ màu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"Xăng 4 kỳ, 1 xi-lanh, làm mát bằng không khí\"},{\"label\":\"Vận hành\",\"value\":\"Đề và đạp cần số, hộp số 4 cấp\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50km/h\"},{\"label\":\"Tải trọng\",\"value\":\"180kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"80kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"2 lit xăng / 100km\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh cơ\"},{\"label\":\"Dung tích bình xăng\",\"value\":\"3,5 lít\"},{\"label\":\"Vành xe\",\"value\":\"Nan hoa\"},{\"label\":\"Lốp\",\"value\":\"Có săm\"},{\"label\":\"Giảm xóc\",\"value\":\"Ống lồng trước, cặp lo xo trụ sau giảm chấn thuỷ lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gươn\"}]}]', '<p>Xe Máy 50cc Wave Victoria Việt Nhật 2023 một mẫu xe máy 50 phân khối nên bạn hoàn toàn có thể sở hữu và sử dụng mẫu xe này mà không cần nhất thiết phải có bằng lái xe. Trong thời gian tới mẫu xe này chắc chắn sẽ tạo cơn bão lớn trên thị trường.</p>\n<p>Mẫu Xe Máy 50cc Wave Victoria Việt Nhật này có thiết kế khá đẹp mắt, trẻ trung và cá tính. Xe cũng có độ hoàn thiện khá tốt với những chi tiết được chăm chút khá tỉ mỉ. Vỏ xe được gia công với loại vật liệu cao cấp giúp xe có khả chịu lực tốt. Phủ ngoài vỏ xe là lớp sơn sáng bóng đẹp mắt với nhiều màu sắc khác nhau cho bạn chọn.</p>', '<p>Xe Máy 50cc Wave Victoria Việt Nhật 2023&nbsp;một mẫu xe máy 50 phân khối nên bạn hoàn toàn có thể sở hữu và sử dụng mẫu xe này mà không cần nhất thiết phải có bằng lái xe. Trong thời gian tới mẫu xe này chắc chắn sẽ tạo cơn bão lớn trên thị trường.</p>\n<h3><strong>Thiết kế:</strong></h3>\n<p>Mẫu Xe Máy 50cc Wave Victoria Việt Nhật này có thiết kế khá đẹp mắt, trẻ trung và cá tính. Xe cũng có độ hoàn thiện khá tốt với những chi tiết được chăm chút khá tỉ mỉ. Vỏ xe được gia công với loại vật liệu cao cấp giúp xe có khả chịu lực tốt. Phủ ngoài vỏ xe là lớp sơn sáng bóng đẹp mắt với nhiều màu sắc khác nhau cho bạn chọn.</p>\n<h3><strong>Đèn xe:</strong></h3>\n<p>Phần đèn có kích thước khá lớn ở phía trước xe được dùng loại đèn halogen giúp tạo ra ánh sáng với chất lượng tuyệt vời giúp bạn có thể di chuyển dễ dàng hơn trong nhưng điều kiện khó nhìn. Với hệ thống đèn xinhan ở hai bên cũng giúp cho bạn có thể chuyển hướng hay rẽ một cách an toàn hơn.</p>\n<h3><strong>Mặt đồng hồ xe:</strong></h3>\n<p>Xe vẫn dùng loại mặt đồng hồ kim truyền thống, nhưng mặt đồng hồ xe vẫn có thể hiển thị rõ ràng và đầy đủ mọi thông số vận hành của mẫu xe Wave Victoria 50cc như vận tốc quãng đường, lượng xăng còn lại, … cho bạn có thể dẽ dàng quan sát và nắm bắt được và giúp bạn có thể dễ điều khiển được chiếc xe.</p>\n<h3><strong>Động cơ:</strong></h3>\n<p>Vì&nbsp;Xe Máy 50cc Wave Victoria Việt Nhật 2023 vẫn là một mẫu&nbsp;xe máy 50 phân khối&nbsp;nên vẫn được trang bị một khối động cơ 4 kì với phân khối là 50cc. Đây là một khối động cơ khá là nhẹ nhàng rất phù hợp để có thể vận hành trong những khu vực thành phố khá dễ dàng. Đặc biệt là bạn hoàn toàn có thể sở hữu một chiếc xe 50cc mà không cần phải có bằng lái xe.&nbsp;</p>\n<p>Mẫu&nbsp;Xe Máy 50cc Wave Victoria Việt Nhật 2023 này là một mẫu xe cực kì tuyệt vời và đáng để lựa chọn, đặc biệt là đối với các bạn học sinh – sinh viên vẫn chưa có bằng lái vấn có thể sử dụng bình thường</p>\n<br>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-ally-vegas-pro-ev', 'Xe Máy Điện Ally Vegas Pro EV', 'ally', '[\"xe-may-dien\"]', 18900000, 18900000, '/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-ally-vegas-pro-ev-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-creer-e-2-phanh-dia', 'Xe Máy Điện Dibao Creer E 2 Phanh Đĩa', 'dibao', '[\"xe-may-dien\"]', 14990000, 14990000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Dibao\"},{\"label\":\"Xuất xứ\",\"value\":\"Đài Loan\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Bảo hành Pin\",\"value\":\"2 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1.720mm x 660mm x 1.160mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"750mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Lốp không săm 90/90-10\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"1450W\"},{\"label\":\"Vận hành\",\"value\":\"Tự động\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50-55km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"90kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"70 - 80 km/lần sạc\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình acquy 20Ah\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm 90/90-10\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực. Phuộc sau: Lò so trụ đơn, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, chống trộm, sổ bảo hành\"}]}]', '<p>Bạn dành cả thời gian dài để tìm chiếc xe ưng ý nhưng vẫn chưa được bởi giá thành của những chiếc Crea cao cấp có giá tiền khá lớn so với thu nhập của bạn. Bạn thấy dòng xe này hợp với mình và mong muốn sở hữu chúng. Thay vì hướng đến mục tiêu khó thì bạn có thể sở hữu chiếc xe Crea tương tự nhưng có giá thành phù hợp hơn. Xe máy điện Dibao Creer E phanh đĩa  sở hữu đầy đủ những tiêu chuẩn của một chiếc Crea ấy mà bạn đang cần. Tìm hiểu xe qua những thông tin sau đây:</p>\n<p>Ngoại hình xe với những nét quen thuộc của dòng Crea được nhắc đến nhưng vẫn được Dibao sáng tạo nên những đặc điểm riêng biệt của mình. Dibao Creer E vô cùng nhẹ nhàng với phần ngôn ngữ body uyển chuyển, mặt trước hệ thống đèn tạo thành cụm thể hiện trên đầu xe, điểm kết là đuôi bo sang trọng.</p>', '<p>Bạn dành cả thời gian dài để tìm chiếc xe ưng ý nhưng vẫn chưa được bởi giá thành của những chiếc Crea cao cấp có giá tiền khá lớn so với thu nhập của bạn. Bạn thấy dòng xe này hợp với mình và mong muốn sở hữu chúng. Thay vì hướng đến mục tiêu khó thì bạn có thể sở hữu chiếc xe Crea tương tự nhưng có giá thành phù hợp hơn.&nbsp;Xe máy điện Dibao Creer E phanh đĩa &nbsp;sở hữu đầy đủ những tiêu chuẩn của một chiếc Crea ấy mà bạn đang cần. Tìm hiểu xe qua những thông tin sau đây:</p>\n<h2><strong>TỔNG QUAN NGOẠI HÌNH XE MÁY ĐIỆN</strong></h2>\n<p>Ngoại hình xe với những nét quen thuộc của dòng Crea được nhắc đến nhưng vẫn được Dibao sáng tạo nên những đặc điểm riêng biệt của mình. Dibao Creer E vô cùng nhẹ nhàng với phần ngôn ngữ body uyển chuyển, mặt trước hệ thống đèn tạo thành cụm thể hiện trên đầu xe, điểm kết là đuôi bo sang trọng.</p>\n<p>Xe sử dụng loại nhựa cao cấp ABS cho độ bền, bám màu tốt cũng như chống phai màu hiệu quả. Tên xe Creer E được thể hiện rõ ở phần thân, tên thương hiệu Dibao cũng được in ở những vị trí quan trọng. Xe máy điện không có nhiều tem mác nhưng vẫn thể hiện rõ những đặc điểm cần có.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-7.webp\" alt=\"Xe Máy Điện Dibao Creer E\" loading=\"lazy\"></p>\n\n<p>Đặc biệt hơn, phiên bản mới này cho ra mắt bộ siêu tập nhiều máu sắc từ cơ bản đến các tính nổi bật, đa dạng hơn cho sự lựa chọn của mình.</p>\n<h2><strong>SỞ HỮU CỤM ĐÈN LED CAO CẤP</strong></h2>\n<p>Xe máy điện Dibao Creer E 2 phanh đĩa giữ lại lối thiết kế đèn tròn với sự tỉ mĩ trong cách xây dựng. Ở đây, bạn có thể nhìn thấy viền đèn được bọc kim loại Crom tăng độ sáng bóng. Đèn xinhan lớn tạo thành cjm nằm ở vị trí 2 bên. Đèn hậu tạo thành cụm lớn ở điểm kết của đuôi xe, với các tín hiệu hiển thị rõ ràng.</p>\n<p>Xe được tích hợp bộ đèn với công nghệ đèn led cao cấp hiển thị các chế độ hoạt động linh hoạt từ pha/cos chỉ trong một vài thao tác đơn giản. So với đèn sợi đốt trước đây thì công nghệ này nổi trội hơn hẳn, ánh sáng phát ra tốt hơn, tiết kiệm nhiên liệu hơn. Đèn xinhan của xe cũng là đèn led, bóng led linh hoạt đồng bộ trước và sau với màu sắc phù hợp thông báo cho người điều khiển nhận biến. Chính hệ thống đèn này mang lại nét đặc trưng của dòng xe Crea nói chung và chiếc Creer E này nói riêng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-e-2-phanh-dia-9.webp\" alt=\"Xe Máy Điện Dibao Creer E\" loading=\"lazy\"></p>\n<h2><strong>MẶT ĐỒNG HỒ ĐIỆN TỬ CAO CẤP</strong></h2>\n<p>Đồng hồ điện tử cũng là một nét mới thường xuất hiện ở những phiên bản xe máy điện cao cấp hiện nay. Với phiên bản này, Dibao Creer E có mặt đồng hồ lớn với các thông số hiển thị to, rõ nét bao gồm các tín hiệu di chuyển như vận tốc, quãng đường, tín hiệu đèn xe, đèn xinhan, mức nhiên liệu,… Bạn chú ý các tín hiệu trên mặt đồng hồ để xem xét quá trính hoạt động của xe.</p>\n<p>Bộ tay nắm êm cầm chắc dễ dàng điều khiển kết hợp với các cụm công tắc được trang bị phù hợp 2 bên tay nắm có kí hiệu rõ ràng, đơn giản giúp người mới sử dụng có thể thao tác được.</p>\n<h2><strong>PHIÊN BẢN NÂNG CẤP, TỐI ƯU ĐỘNG CƠ</strong></h2>\n<p>Sở hữu động cơ khỏe là điều mà mà những phiên bản mới hiện nay đều được trang bị. Với Creer E , xe máy điện sở hữu động cơ khỏe công suất lớn 1000W định danh và max có thể lên đến 1450W. Công suất lớn cho sức mạnh tối ưu, đạt vận tốc 50 - 55 km/h là điều dễ dàng. Điều này phù hợp cho viêc di chuyển trong các khu vực nội thành phố, thích hợp cho các bạn học sinh, sinh viên hoặc người yêu thích sự nhẹ nhàng có ở những dòng xe như thế này.</p>\n<p>Hơn nữa, động cơ xe sử dụng công nghệ mới thiết kế khép kín cho khả năng kháng nước gần như tuyệt đối. Giờ đây, việc di chuyển xe dưới trời mưa hoặc lội nước là điều đơn giản mà bạn có thể thực hiện được.</p>\n<p>Ngoài ra, quãng đường di chuyển cũng là vấn đề được nhiều người quan tâm. Với chiếc xe này, bạn có thể di chuyển đến 80 km/lần sạc nhờ vào bộ 5 bình acquy 20Ah được đặt ở phần thân xe. Vì sử dụng bản acquy nên thời gian sạc vào khoảng 10 giờ. Tuy nhiên, sử dụng xe máy điện chính hãng cung cấp sạc điện chất lượng tự động ngắt điện khi đầy bình. Acquy xe điện được chúng tôi baoor hành đến 12 tháng nên bạn có thể an tâm sử dụng, được bảo hành đảm bảo chất lượng.</p>\n<h2><strong>KHẢ NĂNG CHỨA ĐỒ RỘNG RÃI</strong></h2>\n<p>Cốp xe – không gian chứa đồ, mà nhiều người quan tâm, nhất là các bạn nữ bởi đây là vị trí mà các bạn có thể thoải mái chứa các đồ đạc của mình. Với xe máy điện Dibao Creer 2 phanh đĩa này, xe được thiết kế phần cốp chính với thể tích lớn, rộng rãi có chiều sâu tối ưu chứa được nhiều đồ cần thiết bao gồm mũ bảo hiểm và các vật dụng liên quan. Ổ khóa mở cốp sau nằm ở phần giữa thân xe, dễ dàng nhìn thấy và thao tác mở cốp cũng đơn giản dễ thực hiện.</p>\n<p>Kèm theo đó là những móc treo đồ, treo nón bảo hiểm cũng tiện lợi không kém được nhiều khách hàng tận dụng cùng một sàn để chân vô cùng lớn cho tư thế đặt chân thoải mái hoặc để vật dụng, cũng có thể là cơ hội cho những “chiếc” thú cưng dễ thương ngồi ở đây.</p>\n<h2><strong>AN TOÀN TUYỆT ĐỐI CÙNG HỆ THỐNG PHANH ĐĨA</strong></h2>\n<p>Xe máy điện&nbsp;sử dụng bộ vành đúc sơn tĩnh điện cứng cáp, chắc chắn kết hợp với bánh không săm sử dụng phổ biến trong những chiếc xe máy chất lượng hiện nay. Với cặp bánh này, dù bạn có mắc phải đinh cũng có thể tiếp tục di chuyển an toàn đến nơi sửa chữa.</p>\n<p>Đối tượng sử dụng dòng xe này thường là các bạn học sinh cũng như chị em phụ nữ, tay lái họ thường không tốt nên hãng đã trang bị thêm bộ phanh đĩa đảm bảo an toàn cao. Không chỉ mỗi bánh trước, bánh sau xe cũng thêm phanh đĩa tạo nên bộ đôi ăn ý hỗ trợ an toàn trên mọi cung đường.</p>\n<p>Ngoài ra, việc kết hợp với bộ giảm xóc cao cấp giúp xe di chuyển êm hơn dù là có chở thêm người hoặc đi qua những đoạn đường dòng xóc.</p>\n<h2><strong>CÁC PHỤ HIỆN QUAN TRỌNG KHÁC KÈM THEO</strong></h2>\n<p>Để tạo nên sự hoàn thiện nhất khi sử dụng một chiếc xe máy điện xinh đẹp như thế này thì các phụ kiện đi kèm cũng là điều nhiều người quan tâm. Trong đó, chìa khóa smartkey chính là một thứ đặc biệt khi mua xe kèm theo. Với chìa khóa này, việc mở máy, tắt máy cũng như khóa xe chống trộm an toàn được đảm bảo. Ngoài ra, cặp gương chiếu hậu cũng là một phụ kiện hỗ trợ tối ưu cho quá trình di chuyển của bạn.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-creer-nile-cang-nhom-duc', 'Xe Máy Điện Dibao Creer Nile Càng Nhôm Đúc', 'dibao', '[\"xe-may-dien\"]', 17690000, 17690000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-6.webp\"]', '[]', '[]', '[]', '<p>Nếu bạn là người yêu thích phong cách Vespa cổ điển nhưng không muốn bỏ lỡ tiện ích và hiệu suất công nghệ hiện đại, Dibao Creer Nile chính là lựa chọn hoàn hảo cho bạn. Mẫu xe này không chỉ mang đến vẻ ngoài sang trọng, mà còn được trang bị đầy đủ tính năng an toàn, tiết kiệm năng lượng để phục vụ nhu cầu di chuyển hàng ngày.</p>\n<p>Dibao Creer Nile không chọn cách gây ấn tượng bằng những đường nét quá góc cạnh hay hầm hố, mà đi theo hướng tinh giản nhưng cực kỳ “có gu”. Tổng thể xe được thiết kế theo phong cách châu Âu hiện đại với các đường cong mềm mại, liền mạch, tạo cảm giác thanh thoát và dễ nhìn trong mọi góc độ. Điều đáng nói là dù không quá nổi bật theo kiểu “gây sốc thị giác”, nhưng càng nhìn lâu, mẫu xe này lại càng tạo được thiện cảm nhờ sự cân đối trong từng chi tiết.</p>', '<p>Nếu bạn là người yêu thích phong cách Vespa cổ điển nhưng không muốn bỏ lỡ tiện ích và hiệu suất công nghệ hiện đại, Dibao Creer Nile chính là lựa chọn hoàn hảo cho bạn. Mẫu xe này không chỉ mang đến vẻ ngoài sang trọng, mà còn được trang bị đầy đủ tính năng an toàn, tiết kiệm năng lượng để phục vụ nhu cầu di chuyển hàng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h3><strong>Thiết kế thanh lịch nhưng không hề đơn điệu, tạo dấu ấn riêng ngay từ cái nhìn đầu tiên</strong></h3>\n<p><strong>Dibao Creer Nile</strong> không chọn cách gây ấn tượng bằng những đường nét quá góc cạnh hay hầm hố, mà đi theo hướng tinh giản nhưng cực kỳ “có gu”. Tổng thể xe được thiết kế theo phong cách châu Âu hiện đại với các đường cong mềm mại, liền mạch, tạo cảm giác thanh thoát và dễ nhìn trong mọi góc độ. Điều đáng nói là dù không quá nổi bật theo kiểu “gây sốc thị giác”, nhưng càng nhìn lâu, mẫu xe này lại càng tạo được thiện cảm nhờ sự cân đối trong từng chi tiết.</p>\n<p>Chiều cao yên khoảng 760–780 mm giúp người dùng, đặc biệt là học sinh hoặc người có vóc dáng nhỏ, dễ dàng chống chân và kiểm soát xe. Trọng lượng xe dao động quanh mức 90–100 kg mang lại sự cân bằng tốt giữa độ đầm và độ linh hoạt. Khi di chuyển trong những con phố đông đúc hoặc quay đầu trong không gian hẹp, người dùng sẽ cảm nhận rõ sự “dễ chịu” mà thiết kế này mang lại.</p>\n<p>Cụm đèn LED phía trước không chỉ đóng vai trò chiếu sáng mà còn là điểm nhấn thẩm mỹ, giúp xe trông hiện đại hơn so với nhiều mẫu xe điện cùng phân khúc. Sự kết hợp giữa ánh sáng trắng sắc nét và thiết kế tinh gọn khiến Creer Nile dễ dàng nổi bật khi di chuyển vào ban đêm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h3><strong>Động cơ vừa đủ nhưng tối ưu trải nghiệm, mang lại cảm giác lái nhẹ nhàng và ổn định</strong></h3>\n<p>Dibao Creer Nile không cố gắng “chạy đua thông số” mà tập trung vào việc tối ưu trải nghiệm thực tế. Động cơ có công suất 1000W, một con số tưởng chừng không quá ấn tượng nhưng lại được tinh chỉnh để mang đến khả năng vận hành mượt mà, ổn định và dễ kiểm soát.</p>\n<p>Khi bắt đầu di chuyển, xe tăng tốc rất đều, không bị giật cục – điều cực kỳ quan trọng với người mới sử dụng <strong>xe máy điện đời mới</strong>. Tốc độ tối đa khoảng 45–50 km/h giúp đảm bảo an toàn khi đi trong đô thị, đặc biệt phù hợp với học sinh. Quan trọng hơn, ở dải tốc độ này, xe vẫn giữ được độ “đầm”, không bị rung lắc hay mất kiểm soát.</p>\n<p>Trong điều kiện thực tế như leo cầu vượt hoặc di chuyển trên đường hơi dốc, động cơ vẫn đủ lực để duy trì tốc độ ổn định nếu không chở quá tải. Đây chính là kiểu “sức mạnh vừa đủ” mà người dùng đô thị thực sự cần, thay vì những con số công suất cao nhưng khó kiểm soát.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-creer-nile-cang-nhom-duc-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<h3><strong>Hệ thống pin bền bỉ, quãng đường thực tế đáp ứng trọn vẹn nhu cầu di chuyển mỗi ngày</strong></h3>\n<p>Một trong những yếu tố khiến người dùng cân nhắc khi chọn xe điện chính là quãng đường di chuyển sau mỗi lần sạc. Dibao Creer Nile được trang bị hệ thống ắc quy 60V (5 bình 12V), cho phép xe vận hành ổn định trong suốt hành trình hàng ngày.</p>\n<p>Trong điều kiện sử dụng thực tế, xe có thể đi được khoảng 60–80 km cho mỗi lần sạc đầy. Đây là con số đủ để đáp ứng nhu cầu đi học, đi làm hoặc di chuyển nội thành trong cả ngày mà không cần sạc lại giữa chừng. Với những người có lịch trình di chuyển cố định, việc chỉ cần sạc qua đêm là đã đủ dùng cho ngày hôm sau là một lợi thế rất lớn.</p>\n<p>Thời gian sạc khoảng 8–10 tiếng tuy không phải quá nhanh, nhưng lại phù hợp với thói quen sinh hoạt. Người dùng chỉ cần cắm sạc vào buổi tối và sáng hôm sau xe đã sẵn sàng. Điều này giúp loại bỏ hoàn toàn cảm giác “bị phụ thuộc” vào việc sạc như nhiều người vẫn lo lắng khi chuyển sang xe điện.</p>\n<h3><strong>Trải nghiệm vận hành êm ái, phù hợp hoàn hảo với môi trường đô thị đông đúc</strong></h3>\n<p>Điểm khiến Dibao Creer Nile ghi điểm mạnh nhất không nằm ở thông số, mà ở cảm giác lái thực tế. Khi vận hành, xe gần như không phát ra tiếng ồn, tạo cảm giác rất “êm tai” và dễ chịu, đặc biệt khi di chuyển trong những con phố đông đúc hoặc khu dân cư.</p>\n<p>Tay ga phản hồi mượt, không bị trễ hay giật, giúp người lái dễ dàng kiểm soát tốc độ trong những tình huống cần xử lý nhanh như kẹt xe hay chuyển hướng liên tục. Đây là yếu tố cực kỳ quan trọng với học sinh hoặc người chưa có nhiều kinh nghiệm.</p>\n<p>Hệ thống giảm xóc hoạt động hiệu quả giúp xe không bị “nảy” quá nhiều khi đi qua các đoạn đường xấu. Dù không phải là mẫu xe chuyên off-road, nhưng Creer Nile vẫn đủ khả năng xử lý tốt những điều kiện đường sá phổ biến tại Việt Nam.</p>\n<h3><strong>Trang bị tiện ích đủ dùng nhưng rất thực tế, phục vụ đúng nhu cầu hàng ngày</strong></h3>\n<p>Thay vì tích hợp quá nhiều công nghệ phức tạp, Dibao Creer Nile tập trung vào những tiện ích thực sự cần thiết. Mặt đồng hồ điện tử hiển thị rõ ràng các thông tin như tốc độ, mức pin, giúp người dùng dễ dàng theo dõi mà không bị rối mắt.</p>\n<p>Cốp xe có dung tích vừa đủ để chứa các vật dụng cơ bản như áo mưa, túi xách nhỏ hoặc đồ cá nhân. Móc treo phía trước là chi tiết nhỏ nhưng cực kỳ hữu ích khi cần mang đồ.</p>\n<p>Ngoaig ra xe còn được trang bị khóa chống trộm hoặc khóa thông minh, giúp tăng tính an toàn khi gửi xe ở nơi công cộng. Đây là những tiện ích không quá “hào nhoáng” nhưng lại rất thiết thực trong cuộc sống hàng ngày.</p>\n<h3><strong>Chi phí sử dụng cực thấp, lợi thế lớn trong thời buổi giá xăng biến động</strong></h3>\n<p>Một trong những lý do khiến Dibao Creer Nile trở nên hấp dẫn chính là chi phí vận hành. Với mỗi lần sạc đầy chỉ tốn một khoản điện rất nhỏ, người dùng có thể tiết kiệm đáng kể so với việc đổ xăng hàng ngày.</p>\n<p>Không chỉ vậy, xe điện không cần thay dầu, ít hỏng vặt hơn do cấu tạo đơn giản, giúp giảm đáng kể chi phí bảo trì. Với mức giá bán phổ biến trong khoảng từ hơn 10 triệu đến dưới 20 triệu đồng, đây là lựa chọn cực kỳ hợp lý cho học sinh, sinh viên hoặc người cần phương tiện tiết kiệm.</p>\n<p>Dibao Creer Nile không phải là mẫu xe điện khiến người ta phải trầm trồ ngay từ cái nhìn đầu tiên, nhưng lại là chiếc xe khiến người dùng cảm thấy “hợp lý” sau khi sử dụng. Với động cơ1000W, quãng đường 60–80 km, tốc độ khoảng 50 km/h cùng thiết kế gọn gàng và chi phí thấp, mẫu xe này đáp ứng đúng những gì người dùng đô thị cần.</p>\n<p>Trong một thị trường ngày càng nhiều lựa chọn, đôi khi chính những mẫu xe cân bằng như <strong>xe máy điện Dibao</strong> Creer Nile lại là phương án thông minh nhất – không phô trương, không dư thừa, nhưng đủ tốt để đồng hành lâu dài. 🚀</p>\n&nbsp;\n&nbsp;\n&nbsp;', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-ella-90km-1-lan-sac', 'Xe Máy Điện Dibao ELLA 90km/1 lần sạc', 'dibao', '[\"xe-may-dien\"]', 15500000, 15500000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ella-90km-1-lan-sac-5.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-gogo-cross', 'Xe Máy Điện Dibao Gogo Cross', 'dibao', '[\"xe-may-dien\"]', 18590000, 18590000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện đang dần trở thành lựa chọn quen thuộc của nhiều người tại các thành phố lớn. Dibao Gogo Cross xuất hiện như một mẫu xe hướng đến sự ổn định, dễ sử dụng và phù hợp với nhiều nhóm tuổi khác nhau. Từ thiết kế, động cơ cho đến khả năng vận hành, mẫu xe này tập trung giải quyết những nhu cầu thực tế trong quá trình di chuyển hằng ngày.</p>\n<p>Xuất xứ từ Đài Loan giúp Dibao Gogo Cross thừa hưởng triết lý sản xuất đề cao độ bền và tính an toàn. Xe không chạy theo xu hướng phô trương mà tập trung vào trải nghiệm sử dụng lâu dài. Đây là yếu tố quan trọng với người dùng đang tìm kiếm một phương tiện gắn bó ổn định theo thời gian.</p>', '<p><strong>Xe máy điện</strong> đang dần trở thành lựa chọn quen thuộc của nhiều người tại các thành phố lớn. Dibao Gogo Cross xuất hiện như một mẫu xe hướng đến sự ổn định, dễ sử dụng và phù hợp với nhiều nhóm tuổi khác nhau. Từ thiết kế, động cơ cho đến khả năng vận hành, mẫu xe này tập trung giải quyết những nhu cầu thực tế trong quá trình di chuyển hằng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Xuất xứ từ Đài Loan giúp Dibao Gogo Cross thừa hưởng triết lý sản xuất đề cao độ bền và tính an toàn. Xe không chạy theo xu hướng phô trương mà tập trung vào trải nghiệm sử dụng lâu dài. Đây là yếu tố quan trọng với người dùng đang tìm kiếm một phương tiện gắn bó ổn định theo thời gian.</p>\n<h2><br><strong>Thiết kế tổng thể gọn gàng, phù hợp vóc dáng người Việt</strong></h2>\n<p><br><strong>Dibao Gogo Cross</strong> sở hữu kiểu dáng nhỏ gọn với các đường nét cân đối, tạo cảm giác thân thiện ngay từ cái nhìn đầu tiên. Kích thước tổng thể được tối ưu để phù hợp môi trường đô thị đông đúc, giúp người dùng dễ dàng di chuyển trong hẻm nhỏ hoặc bãi giữ xe chật hẹp. Phần thân xe liền mạch tạo nên sự chắc chắn khi quan sát và khi vận hành.</p>\n<p><br>Chiều cao yên xe khoảng 755mm mang lại tư thế ngồi tự nhiên cho cả nam và nữ. Người lái có thể chống chân dễ dàng khi dừng xe, đặc biệt thuận tiện trong điều kiện giao thông thường xuyên phải dừng chờ. Thiết kế này giúp người mới làm quen với xe điện nhanh chóng cảm thấy tự tin hơn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Màu sắc cơ bản của xe được lựa chọn theo hướng trung tính, phù hợp với nhiều độ tuổi và mục đích sử dụng khác nhau. Các chi tiết nhựa được hoàn thiện khá tốt, bề mặt mịn và ít bám bẩn trong quá trình sử dụng hằng ngày. Tổng thể ngoại hình hướng đến sự bền dáng và ít lỗi thời.</p>\n<h2><br><strong>Động cơ 800W mang lại khả năng vận hành ổn định</strong></h2>\n<p><br><strong>Xe máy điện Dibao Gogo Cross</strong> được trang bị động cơ công suất 800W, có thể đạt mức tối đa 1000W khi cần thiết. Thông số này đáp ứng tốt nhu cầu di chuyển trong thành phố, nơi thường xuyên phải tăng giảm tốc độ liên tục. Xe vận hành êm, ga lên đều và hạn chế cảm giác giật khi khởi động.</p>\n<p><br>Vận tốc tối đa khoảng 50km/h phù hợp với điều kiện giao thông đô thị và các quy định hiện hành. Khi di chuyển trên đường đông, xe phản hồi tay ga khá mượt, giúp người lái dễ kiểm soát tốc độ và xử lý tình huống. Điều này đặc biệt hữu ích với người sử dụng xe hằng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-cross-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Khả năng chịu tải lên đến 140kg cho phép chở thêm người hoặc đồ dùng cá nhân mà xe vẫn giữ được sự ổn định. Động cơ hoạt động tương đối êm ái, giảm tiếng ồn so với xe xăng truyền thống. Trải nghiệm lái vì thế trở nên nhẹ nhàng và thoải mái hơn.</p>\n<h2><br><strong>Hệ thống Pin chất lượng cao thêm lựa chọn tối ưu</strong></h2>\n<p><br><strong>Dibao Gogo Cross</strong> sử dụng 2 cấu hình bao gồm hệ thống 5 bình ắc quy 60V – 20Ah, cho quãng đường di chuyển khoảng 80km sau mỗi lần sạc đầy hoặc hệ oin thilium đời mới cho quãng đường lên đến 130km. Quãng đường này phù hợp với nhu cầu đi học, đi làm hoặc di chuyển nội thành trong cả một tuần dài. Người dùng không cần sạc xe mỗi ngày nếu lịch trình di chuyển hợp lý.</p>\n<p><br>Thời gian sạc từ 10 đến 12 tiếng, thích hợp sạc qua đêm tại nhà. Hệ thống tự động ngắt khi đầy giúp bảo vệ ắc quy và hạn chế tình trạng quá tải điện. Đây là điểm cộng về độ an toàn trong quá trình sử dụng lâu dài.</p>\n<p><br>Chi phí thay thế ắc quy được công bố rõ ràng, giúp người dùng chủ động hơn về kế hoạch sử dụng lâu dài. Việc lựa chọn ắc quy chính hãng Dibao giúp đảm bảo độ tương thích và tuổi thọ. Đây là yếu tố quan trọng với những ai xem xe như phương tiện gắn bó lâu năm.</p>\n<h2><br><strong>Khung xe chắc chắn, phanh và giảm xóc vận hành hiệu quả</strong></h2>\n<p><br>Khung<strong> xe may dien Dibao Gogo Cross</strong> được thiết kế cứng cáp, giúp xe đạt trọng lượng khoảng 93kg. Mức trọng lượng này tạo cảm giác đầm xe khi di chuyển, hạn chế rung lắc ở tốc độ trung bình. Xe giữ được sự ổn định ngay cả khi chở thêm người phía sau.</p>\n<p><br>Hệ thống phanh đĩa trước và sau giúp tăng khả năng kiểm soát khi cần giảm tốc đột ngột. Lực phanh rõ ràng, phản hồi nhanh và dễ làm quen với người mới sử dụng xe điện. Đây là yếu tố quan trọng giúp nâng cao mức độ an toàn khi đi trong phố đông.</p>\n<p><br>Giảm xóc trước dạng ống lồng kết hợp giảm chấn thủy lực giúp xe vận hành êm hơn trên mặt đường không bằng phẳng. Phuộc sau lò xo trụ hỗ trợ tốt khi chở nặng hoặc đi qua đoạn đường gồ ghề. Tổng thể hệ thống treo hướng đến sự ổn định và thoải mái.</p>\n<h2><br><strong>Trang bị thực dụng phục vụ tốt nhu cầu hằng ngày</strong></h2>\n<p><br><strong>Dibao Gogo Cross</strong> được trang bị sẵn các phụ kiện cần thiết như gương chiếu hậu, bộ sạc và sổ bảo hành. Người dùng có thể sử dụng xe ngay sau khi mua mà không cần trang bị thêm nhiều phụ kiện khác. Sự đầy đủ này mang lại cảm giác tiện lợi trong quá trình sử dụng ban đầu.</p>\n<p><br>Vành xe hợp kim đúc giúp tăng độ bền và giảm công bảo dưỡng so với vành nan hoa truyền thống. Lốp không săm giúp hạn chế tình trạng xì hơi đột ngột, mang lại sự yên tâm khi di chuyển trên quãng đường dài. Đây là lựa chọn phù hợp với điều kiện đường sá đô thị.</p>\n<p><br>Kích thước bánh xe 90/90-10 giúp xe linh hoạt khi di chuyển trong hẻm nhỏ hoặc khu dân cư đông đúc. Bán kính quay đầu gọn giúp người lái xoay trở dễ dàng trong bãi xe hoặc khi quay đầu trong không gian hẹp. Tính tiện dụng được thể hiện rõ trong thực tế sử dụng.</p>\n<h2><br><strong>Chính sách bảo hành rõ ràng, giá trị sử dụng bền vững</strong></h2>\n<p><br><strong>Xe máy điện Dibao Gogo Cross</strong> được bảo hành khung xe lên đến 3 năm, động cơ 2 năm và ắc quy 1 năm. Chính sách bảo hành minh bạch giúp người dùng yên tâm hơn trong quá trình sử dụng lâu dài. Đây là yếu tố quan trọng khi lựa chọn xe điện trong phân khúc phổ thông.</p>\n<p><br>Việc bảo hành rõ ràng giúp quá trình sửa chữa và thay thế linh kiện diễn ra thuận lợi hơn khi cần thiết. Người dùng không phải lo lắng về nguồn linh kiện hoặc chi phí phát sinh khó kiểm soát.</p>\n<p><br>Xét trên tổng thể, <strong>Dibao Gogo Cross</strong> mang lại giá trị sử dụng ổn định trong tầm giá. Xe phù hợp với học sinh, sinh viên, nhân viên văn phòng và người lớn tuổi cần phương tiện di chuyển nhẹ nhàng. Mẫu xe này hướng đến sự thực tế và bền bỉ theo thời gian.</p>\n<p><br>Dibao Gogo Cross là mẫu <strong>xe máy điện</strong> được thiết kế để phục vụ nhu cầu di chuyển hằng ngày một cách ổn định và dễ sử dụng. Xe sở hữu động cơ vừa đủ, quãng đường di chuyển hợp lý và hệ thống vận hành an toàn. Những yếu tố này giúp người dùng an tâm trong quá trình sử dụng lâu dài.</p>\n<p><br>Với thiết kế gọn gàng, khả năng vận hành êm ái và chính sách bảo hành rõ ràng, <strong>Dibao Gogo Cross</strong> là lựa chọn phù hợp cho cuộc sống đô thị hiện đại. Đây là mẫu xe dành cho những ai ưu tiên sự bền bỉ, tiện dụng và giá trị sử dụng theo thời gian.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-gogo-crown', 'Xe Máy Điện Dibao Gogo Crown', 'dibao', '[\"xe-may-dien\"]', 20490000, 20490000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-6.webp\"]', '[]', '[]', '[]', '<p>Trong rất nhiều cái tên đang cạnh tranh ở phân khúc xe điện phổ thông, Dibao Gogo Crown không phải là mẫu xe gây ồn ào nhất. Nhưng chính sự “im lặng” đó lại là thứ khiến nó đáng chú ý. Không chạy theo xu hướng quá đà, không cố gắng tạo khác biệt bằng những chi tiết phô trương, Gogo Crown chọn cách tiếp cận thực tế hơn: làm tốt những gì người dùng thực sự cần.</p>\n<p>Ấn tượng đầu tiên khi nhìn vào Dibao Gogo Crown là sự gọn gàng và cân đối. Xe có kích thước khoảng 1700 x 700 x 1050 mm — vừa đủ nhỏ để len lỏi trong phố đông, nhưng không quá “mỏng” để tạo cảm giác thiếu chắc chắn.</p>', '<p>Trong rất nhiều cái tên đang cạnh tranh ở phân khúc xe điện phổ thông, Dibao Gogo Crown không phải là mẫu xe gây ồn ào nhất. Nhưng chính sự “im lặng” đó lại là thứ khiến nó đáng chú ý. Không chạy theo xu hướng quá đà, không cố gắng tạo khác biệt bằng những chi tiết phô trương, Gogo Crown chọn cách tiếp cận thực tế hơn: làm tốt những gì người dùng thực sự cần.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế thanh lịch, nhìn đơn giản nhưng không hề đơn điệu</strong></h2>\n<p>Ấn tượng đầu tiên khi nhìn vào<strong> Dibao Gogo Crown</strong> là sự gọn gàng và cân đối. Xe có kích thước khoảng 1700 x 700 x 1050 mm — vừa đủ nhỏ để len lỏi trong phố đông, nhưng không quá “mỏng” để tạo cảm giác thiếu chắc chắn.</p>\n<p>Điểm hay nằm ở cách Dibao xử lý tổng thể. Các đường nét không quá sắc cạnh, cũng không quá bo tròn, mà được cân chỉnh ở mức vừa phải, tạo cảm giác dễ nhìn và không bị lỗi thời theo thời gian. Đây là kiểu thiết kế càng nhìn lâu càng thấy hợp lý.</p>\n<p>Cụm đèn LED phía trước không chỉ giúp tăng tính hiện đại mà còn cải thiện đáng kể khả năng chiếu sáng vào ban đêm. Ánh sáng rõ, gom tốt, đủ để di chuyển an toàn trong điều kiện thiếu sáng.</p>\n<h2><strong>Ngoại hình dễ dùng, phù hợp từ học sinh đến người đi làm</strong></h2>\n<p>Một chiếc xe đẹp nhưng khó sử dụng thì sớm muộn cũng bị bỏ lại. Dibao Gogo Crown hiểu rõ điều đó, nên mọi thông số đều được tối ưu để “dễ dùng” nhất có thể.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Chiều cao yên khoảng 750mm là một con số rất dễ chịu. Người cao từ 1m55 trở lên có thể chống chân thoải mái, không cần phải “nhón” quá nhiều. Điều này đặc biệt quan trọng với học sinh hoặc người mới đi xe.</p>\n<p>Sàn để chân rộng, khoảng cách tay lái vừa tầm, tạo tư thế ngồi tự nhiên. Khi đi quãng đường dài, bạn sẽ cảm nhận rõ sự khác biệt: không bị mỏi lưng, không bị gò bó — một chi tiết nhỏ nhưng ảnh hưởng lớn đến trải nghiệm.</p>\n<h2><strong>Khung sườn chắc chắn, cảm giác đầm xe rõ rệt</strong></h2>\n<p>Đây là phần mà nhiều người chỉ nhận ra sau khi sử dụng một thời gian. Dibao Gogo Crown sử dụng khung thép chịu lực, cho tải trọng tối đa khoảng 150–180kg, đủ để chở hai người mà xe vẫn giữ được sự ổn định.</p>\n<p>Trọng lượng xe khoảng 85kg tạo ra một điểm cân bằng khá tốt: đủ đầm khi chạy để không bị “bồng bềnh”, nhưng vẫn nhẹ để dắt xe trong ngõ hẹp hoặc bãi xe đông.</p>\n<p>Các chi tiết hoàn thiện như nhựa vỏ, nước sơn hay khớp nối đều ở mức ổn trong tầm giá. Không có cảm giác lỏng lẻo, cũng không tạo cảm giác “xe rẻ tiền” — một điểm cộng khá rõ khi so với nhiều đối thủ cùng phân khúc.</p>\n<h2><strong>Động cơ vận hành mượt, đủ nhanh để dùng mỗi ngày</strong></h2>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-crown-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Dibao Gogo Crown được trang bị động cơ khoảng 1600W, cho tốc độ tối đa vào khoảng 55-60 km/h. Con số này không quá ấn tượng trên giấy, nhưng lại rất “đúng nhu cầu” trong thực tế.</p>\n<p>Đi trong phố, điều quan trọng không phải là chạy nhanh bao nhiêu, mà là xe có mượt không, có dễ kiểm soát không. Và ở điểm này, Gogo Crown làm khá tốt.</p>\n<p>Khi vặn ga, xe tăng tốc đều, không giật, không bị trễ quá lâu. Cảm giác lái nhẹ nhàng, dễ làm quen, đặc biệt phù hợp với người mới hoặc học sinh.</p>\n<h2><strong>Leo dốc ổn định, không bị hụt hơi trong tình huống thực tế</strong></h2>\n<p>Với mức công suất này, xe có thể xử lý các đoạn dốc khoảng 10–12 độ — đủ để đi hầm chung cư, cầu vượt nhỏ hoặc đường nội khu.</p>\n<p>Điểm đáng nói là xe không bị “đuối” quá nhanh khi chở thêm người. Dù không mạnh kiểu xe công suất lớn, nhưng vẫn đủ để bạn không cảm thấy bị giới hạn khi sử dụng hàng ngày.</p>\n<h2><strong>Pin 60V – 20Ah, quãng đường đủ dùng trong 2–3 ngày</strong></h2>\n<p>Một chiếc xe điện tốt không phải là xe đi xa nhất, mà là xe “đủ dùng mà không phải lo nghĩ”. Dibao Gogo Crown với hệ thống ắc quy 60V – 20Ah cho quãng đường khoảng 80–100km mỗi lần sạc.</p>\n<p>Con số này rất thực tế. Nếu bạn đi học hoặc đi làm mỗi ngày 10–20km, thì hoàn toàn có thể dùng 2–3 ngày mới cần sạc lại. Thời gian sạc khoảng 8–10 tiếng, chỉ cần cắm qua đêm là sáng hôm sau có xe đi tiếp, không cần thay đổi thói quen sinh hoạt.</p>\n<h2><strong>Chi phí sử dụng thấp – lý do khiến nhiều người chuyển sang xe điện</strong></h2>\n<p>Đây mới là “điểm ăn tiền” thật sự. Mỗi lần sạc đầy chỉ tiêu tốn khoảng 1–1.5 số điện — một con số quá nhỏ so với việc đổ xăng hàng tuần.</p>\n<p>Không chỉ vậy, xe điện gần như không cần bảo dưỡng phức tạp. Không thay dầu, không bugi, không động cơ đốt trong — đồng nghĩa với việc giảm rất nhiều chi phí phát sinh. Nếu tính dài hạn, đây là khoản tiết kiệm cực kỳ đáng kể.</p>\n<h2><strong>Trang bị thực dụng, tập trung đúng vào trải nghiệm người dùng</strong></h2>\n<p>Thay vì chạy theo những công nghệ phô trương, <strong>Dibao</strong> Gogo Crown lựa chọn cách tiếp cận thực tế hơn: trang bị những gì người dùng thật sự cần trong quá trình sử dụng hàng ngày.</p>\n<p>Không gian cốp xe dung tích khoảng 18–20 lít đủ để chứa mũ bảo hiểm cùng các vật dụng cá nhân cơ bản như áo mưa, túi xách. Hệ thống đèn LED được trang bị đồng bộ giúp tăng khả năng chiếu sáng và nhận diện khi di chuyển vào ban đêm, mang lại cảm giác an tâm hơn trong điều kiện thiếu sáng.</p>\n<p>Một số phiên bản còn được tích hợp remote và khóa thông minh, giúp người dùng mở khóa, tìm xe từ xa nhanh chóng – một tiện ích nhỏ nhưng cực kỳ hữu ích trong môi trường đô thị đông đúc.</p>\n<p>Tổng thể, mọi trang bị trên xe đều hướng đến sự đơn giản, dễ dùng và hiệu quả. Không dư thừa, không rườm rà, nhưng đủ để phục vụ tốt nhu cầu thực tế mỗi ngày.</p>\n<h2><strong>Hệ thống an toàn ổn định, dễ kiểm soát trong mọi tình huống</strong></h2>\n<p>Bên cạnh sự tiện dụng, Dibao Gogo Crown cũng được chú trọng ở yếu tố an toàn – đặc biệt là trong môi trường giao thông đô thị đông đúc.</p>\n<p>Xe được trang bị phanh đĩa phía trước kết hợp phanh cơ phía sau, mang lại khả năng kiểm soát tốc độ ổn định và đáng tin cậy. Cảm giác phanh được tinh chỉnh ở mức vừa phải, không quá gắt nhưng vẫn đủ lực, giúp người mới cũng có thể dễ dàng làm quen.</p>\n<p>Kết hợp với đó là bộ lốp không săm kích thước 10–12 inch, giúp tăng độ bám đường và hạn chế rủi ro khi đi dưới trời mưa hoặc đường trơn trượt.</p>\n<p>Trong điều kiện sử dụng hàng ngày, hệ thống này không chỉ “đủ dùng” mà còn tạo được sự yên tâm — một yếu tố quan trọng mà người dùng phổ thông luôn đặt lên hàng đầu.</p>\n<h2><strong>Giá chỉ từ 20 triệu – khoản đầu tư nhỏ, giá trị dài hạn</strong></h2>\n<p>Một trong những lý do lớn nhất khiến Dibao Gogo Crown trở nên hấp dẫn chính là mức giá. Chỉ với khoảng 20–22 triệu đồng, người dùng đã có thể sở hữu một chiếc xe điện hoàn chỉnh, đáp ứng tốt nhu cầu di chuyển hàng ngày.</p>\n<p>Nhưng điều đáng nói không chỉ nằm ở giá mua ban đầu, mà còn ở giá trị sử dụng lâu dài. Khi chi phí sạc điện thấp, bảo dưỡng đơn giản và gần như không phát sinh nhiều khoản phụ, tổng chi phí vận hành của xe giảm đi đáng kể theo thời gian.</p>\n<p>Chính vì vậy, với cùng một số tiền, Gogo Crown không chỉ là một chiếc xe để đi lại, mà còn là một giải pháp tiết kiệm lâu dài. Đây cũng là lý do vì sao ngày càng nhiều người lựa chọn chuyển từ xe xăng sang xe điện trong phân khúc này.</p>\n<p>Dibao Gogo Crown không cố gắng trở thành chiếc xe nổi bật nhất. Nhưng nó làm rất tốt vai trò của mình: một chiếc <strong>xe máy điện dễ dùng</strong>, bền bỉ, tiết kiệm và đủ đẹp để sử dụng lâu dài. Với động cơ 1600W, tốc độ tối đa 60 km/h, quãng đường lên đến 100km mỗi lần sạc và mức giá chỉ khoảng 20 triệu đồng, đây là một trong những lựa chọn “an toàn nhưng đáng tiền” nhất trong phân khúc.</p>\n<p>Nếu bạn đang tìm một chiếc xe điện để dùng mỗi ngày mà không cần phải đắn đo quá nhiều, thì Dibao Gogo Crown gần như là câu trả lời hợp lý ngay từ đầu.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-gogo-moon-doi-moi-nhat', 'Xe Máy Điện Dibao Gogo Moon Đời Mới Nhất', 'dibao', '[\"xe-may-dien\"]', 17190000, 17190000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-6.webp\"]', '[]', '[]', '[]', '<p>Nổi bật trong phân khúc xe máy điện với thiết kế hiện đại và chất lượng vượt trội, Dibao Gogo Moon đang khẳng định vị thế là một trong những lựa chọn hàng đầu trên thị trường xe điện Việt Nam. Với sự kết hợp hài hòa giữa thẩm mỹ tinh tế, hiệu suất vận hành mạnh mẽ và tiện ích thông minh, Gogo Moon hứa hẹn mang đến trải nghiệm di chuyển đẳng cấp cho người dùng.</p>\n<p>Dibao Gogo Moon chinh phục người nhìn ngay từ ánh mắt đầu tiên bởi thiết kế độc đáo, lấy cảm hứng từ vẻ đẹp mềm mại và tròn đầy của mặt trăng. Khác biệt hoàn toàn so với những mẫu xe điện truyền thống, Gogo Moon sở hữu những đường nét bo tròn tinh tế, tạo nên sự uyển chuyển và cuốn hút. Phần đầu xe có nét vuông vắn khỏe khoắn, kết hợp hài hòa với tổng thể bo tròn mềm mại, mang đến một diện mạo vừa hiện đại, vừa sang trọng.</p>', '<p>Nổi bật trong phân khúc xe máy điện với thiết kế hiện đại và chất lượng vượt trội, Dibao Gogo Moon đang khẳng định vị thế là một trong những lựa chọn hàng đầu trên thị trường xe điện Việt Nam. Với sự kết hợp hài hòa giữa thẩm mỹ tinh tế, hiệu suất vận hành mạnh mẽ và tiện ích thông minh, Gogo Moon hứa hẹn mang đến trải nghiệm di chuyển đẳng cấp cho người dùng.</p>\n<h2>Thiết Kế Độc Đáo, Lấy Cảm Hứng Từ Mặt Trăng</h2>\n<p><strong>Dibao Gogo Moon</strong> chinh phục người nhìn ngay từ ánh mắt đầu tiên bởi thiết kế độc đáo, lấy cảm hứng từ vẻ đẹp mềm mại và tròn đầy của mặt trăng. Khác biệt hoàn toàn so với những mẫu xe điện truyền thống, Gogo Moon sở hữu những đường nét bo tròn tinh tế, tạo nên sự uyển chuyển và cuốn hút. Phần đầu xe có nét vuông vắn khỏe khoắn, kết hợp hài hòa với tổng thể bo tròn mềm mại, mang đến một diện mạo vừa hiện đại, vừa sang trọng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Thương hiệu Dibao nổi tiếng với việc sử dụng chất liệu cao cấp, và Gogo Moon cũng không ngoại lệ. Toàn bộ phần vỏ xe được chế tác từ nhựa cao cấp, không chỉ tăng cường khả năng chống bụi bẩn, chống trầy xước khi va chạm mà còn góp phần kéo dài tuổi thọ của xe. Lớp sơn tĩnh điện bóng bẩy, các chi tiết kim loại được gia công sắc nét, tạo nên một tổng thể hài hòa, đẳng cấp và bền bỉ theo thời gian.</p>\n<p>Bảng màu của Dibao Gogo Moon cũng vô cùng phong phú và đa dạng, với các tùy chọn như trắng, xanh, và nhiều màu sắc khác, phù hợp với thị hiếu và sở thích của đông đảo người tiêu dùng, cũng như các yếu tố phong thủy, bản mệnh của chủ xe. Sự đa dạng này giúp người dùng dễ dàng lựa chọn được chiếc xe phản ánh đúng cá tính và phong cách riêng của mình.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2>Hiệu Suất Vận Hành Mạnh Mẽ, Tiết Kiệm Tối Ưu</h2>\n<p>Trái tim của Dibao Gogo Moon là khối động cơ không chổi than với công suất 1500W, mang đến sức mạnh vận hành ấn tượng, đảm bảo khả năng tăng tốc êm ái và di chuyển mượt mà trên mọi nẻo đường đô thị. Xe có thể đạt vận tốc tối đa từ 45-50 km/h, đủ linh hoạt cho việc di chuyển trong thành phố mà vẫn tuân thủ các quy định giao thông, đặc biệt, người dùng không cần bằng lái để vận hành xe, rất phù hợp với học sinh, sinh viên.</p>\n<p>Năng lượng cho Gogo Moon đến từ bộ 5 bình ắc quy 60V-20Ah. Hệ thống ắc quy này cho phép xe di chuyển quãng đường ấn tượng từ 70 đến 100 km sau mỗi lần sạc đầy, đáp ứng tốt nhu cầu di chuyển hàng ngày mà không cần lo lắng về việc sạc pin thường xuyên. Thời gian sạc đầy pin dao động từ 8-10 giờ, rất thuận tiện để sạc qua đêm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-moon-doi-moi-nhat-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Với mức tiêu thụ điện năng cực thấp so với xe xăng, chi phí vận hành của Dibao Gogo Moon vô cùng tiết kiệm. Chi phí sạc điện hàng tháng chỉ tương đương một phần nhỏ so với chi phí đổ xăng, giúp người dùng tiết kiệm đáng kể trong quá trình sử dụng. Bên cạnh đó, việc bảo dưỡng xe điện cũng đơn giản và ít tốn kém hơn do không có các bộ phận phức tạp như động cơ xăng.</p>\n<p>Khả năng chịu tải của xe lên đến 150kg, đảm bảo xe vẫn vận hành ổn định và êm ái ngay cả khi chở hai người hoặc mang theo nhiều hành lý.</p>\n<h2>Tiện Nghi Thông Minh và An Toàn Vượt Trội</h2>\n<p>Dibao Gogo Moon được trang bị nhiều tính năng&nbsp;của một chiếc <strong>xe máy điện&nbsp;thông minh</strong> nhằm mang đến trải nghiệm tiện lợi và an toàn nhất cho người lái.</p>\n<p>Đồng hồ hiển thị sắc nét: Bảng đồng hồ điện tử hình tròn hiển thị đầy đủ và rõ ràng các thông số quan trọng như vận tốc hiện tại, mức ắc quy còn lại, quãng đường đã đi, đèn xi nhan, và các cảnh báo khác. Màn hình có khả năng tự động điều chỉnh độ sáng theo môi trường, giúp người lái dễ dàng quan sát các thông số ngay cả dưới ánh nắng gắt hoặc trong điều kiện thiếu sáng.</p>\n<p>Hệ thống đèn LED cao cấp: Hệ thống đèn chiếu sáng của xe sử dụng đèn LED cao cấp, không chỉ mang lại khả năng chiếu sáng tuyệt vời, cải thiện tầm nhìn khi di chuyển vào ban đêm hay trong điều kiện thời tiết xấu, mà còn tiêu tốn ít điện năng, góp phần tối ưu hóa hiệu suất vận hành.</p>\n<p>An toàn tối đa với phanh đĩa: Xe được trang bị hệ thống phanh đĩa cả ở bánh trước và bánh sau, mang lại khả năng phanh vượt trội, giúp xe dừng lại nhanh chóng, an toàn và ổn định ngay cả khi di chuyển ở tốc độ cao hoặc trong các tình huống khẩn cấp, hạn chế tối đa nguy cơ trượt bánh.</p>\n<p>Sàn để chân rộng rãi và cốp xe tiện dụng: Thiết kế sàn để chân rộng rãi mang lại tư thế ngồi thoải mái và linh hoạt cho người lái, đồng thời tạo không gian tiện lợi để đặt đồ dùng cá nhân. Cốp xe dung tích lớn cũng là một điểm cộng, cho phép người dùng cất giữ mũ bảo hiểm, túi xách hoặc các vật dụng cần thiết khác một cách an toàn và tiện lợi.</p>\n<h2>Đối Tượng Phù Hợp và Cơ Hội Sở Hữu</h2>\n<p>Với thiết kế thời trang, vận hành êm ái, an toàn, tiết kiệm chi phí và không yêu cầu bằng lái, Dibao Gogo Moon là lựa chọn hoàn hảo cho nhiều đối tượng người dùng:</p>\n<p>+ Học sinh, sinh viên: Xe nhỏ gọn, dễ điều khiển, chi phí vận hành thấp, thiết kế trẻ trung năng động.</p>\n<p>+ Nhân viên văn phòng: Phương tiện di chuyển tiện lợi, tiết kiệm thời gian và chi phí trong giờ cao điểm, cốp xe rộng rãi để mang theo đồ dùng cá nhân.</p>\n<p>+ Các bà nội trợ: Xe nhẹ nhàng, dễ dắt, sàn để chân rộng rãi để chở đồ đi chợ, vận hành êm ái, không gây tiếng ồn.</p>\n<p>+ Người yêu thích công nghệ và thời trang: Sở hữu thiết kế độc đáo, nhiều tính năng hiện đại, là điểm nhấn phong cách trên phố.</p>\n<p>Hiện nay, Dibao Gogo Moon đang có mức giá rất hấp dẫn, chỉ 14.500.000 VNĐ.&nbsp;Mức giá này được đánh giá là cực kỳ cạnh tranh so với trang bị \"full option\" và chất lượng nhập khẩu cao cấp mà xe mang lại, thấp hơn đáng kể so với các mẫu xe tương đương trên thị trường.</p>\n<p>Bên cạnh đó, các nhà phân phối uy tín như Yên Thoa còn mang đến chính sách bảo hành vượt trội, có thể lên đến 3 năm cho ắc quy và động cơ, kèm theo các ưu đãi như lỗi hỏng đổi mới nhanh chóng. Sự cam kết này thể hiện chất lượng sản phẩm và dịch vụ hậu mãi đẳng cấp, mang lại sự an tâm tuyệt đối cho người tiêu dùng.</p>\n<p>Sở hữu&nbsp;<strong>xe&nbsp;Dibao</strong> Gogo Moon không chỉ là sở hữu một phương tiện di chuyển, mà còn là đầu tư thông minh cho một tương lai di chuyển bền vững, tiết kiệm và đầy phong cách. Để trải nghiệm trực tiếp và nhận tư vấn chi tiết, bạn có thể liên hệ với các đại lý ủy quyền của Dibao.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc', 'Xe Máy Điện Dibao Gogo S4 Càng Đúc Chân Chống Đúc', 'dibao', '[\"xe-may-dien\"]', 18100000, 18100000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s4-cang-duc-chan-chong-duc-4.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia', 'Xe Máy Điện Dibao Gogo S5 Càng Nhôm Đúc - 2 Phanh Đĩa', 'dibao', '[\"xe-may-dien\"]', 18200000, 18200000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Dibao Gogo S5 càng nhôm đúc với hệ thống 2 phanh đĩa là một trong những mẫu xe máy điện được yêu thích nhất trên thị trường hiện nay nhờ sự kết hợp hoàn hảo giữa thiết kế hiện đại, động cơ mạnh mẽ và tính năng an toàn tối ưu. Bài viết dưới đây sẽ cung cấp cho bạn cái nhìn chi tiết về các đặc điểm nổi bật, công nghệ áp dụng, lợi ích khi sở hữu Dibao Gogo S5 càng nhôm đúc cùng hướng dẫn chọn mua và bảo dưỡng đúng chuẩn.</p>\n<p>Trước khi đi sâu vào từng chi tiết, có thể thấy Dibao Gogo S5 được định vị trong phân khúc xe máy điện tầm trung cao cấp, hướng đến nhóm người dùng trẻ, đặc biệt là học sinh, sinh viên và những người thường xuyên di chuyển trong đô thị.</p>', '<p>Xe máy điện Dibao Gogo S5 càng nhôm đúc với hệ thống 2 phanh đĩa là một trong những mẫu xe máy điện được yêu thích nhất trên thị trường hiện nay nhờ sự kết hợp hoàn hảo giữa thiết kế hiện đại, động cơ mạnh mẽ và tính năng an toàn tối ưu. Bài viết dưới đây sẽ cung cấp cho bạn cái nhìn chi tiết về các đặc điểm nổi bật, công nghệ áp dụng, lợi ích khi sở hữu Dibao Gogo S5 càng nhôm đúc cùng hướng dẫn chọn mua và bảo dưỡng đúng chuẩn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Tổng quan về xe máy điện Dibao Gogo S5 càng nhôm đúc</strong></h2>\n<p>Trước khi đi sâu vào từng chi tiết, có thể thấy <strong>Dibao Gogo S5</strong> được định vị trong phân khúc xe máy điện tầm trung cao cấp, hướng đến nhóm người dùng trẻ, đặc biệt là học sinh, sinh viên và những người thường xuyên di chuyển trong đô thị.</p>\n<p>Xe sở hữu kích thước tổng thể 1710mm x 705mm x 1030mm, mang lại sự cân đối giữa tính linh hoạt và độ ổn định. Với kích thước này, người dùng có thể dễ dàng điều khiển xe trong các tuyến phố đông đúc mà vẫn đảm bảo sự thoải mái khi sử dụng hàng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Trọng lượng xe dao động khoảng 90 đến 95kg giúp việc dắt xe, quay đầu hay điều khiển trở nên nhẹ nhàng hơn, đặc biệt phù hợp với người có vóc dáng nhỏ. Tải trọng tối đa lên tới 130kg cũng cho phép xe chở hai người một cách thoải mái mà không ảnh hưởng đến hiệu suất vận hành.</p>\n<h2><strong>Thiết kế hiện đại, kiểu dáng gọn gàng</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, Dibao Gogo S5 đã tạo được thiện cảm nhờ phong cách thiết kế trẻ trung, hiện đại nhưng không quá phô trương. Các đường nét được bo tròn mềm mại, tạo cảm giác thanh thoát nhưng vẫn giữ được sự chắc chắn cần thiết.</p>\n<p>Phần đầu xe được thiết kế gọn gàng với cụm đèn nổi bật, thân xe liền mạch và các chi tiết được hoàn thiện khá tỉ mỉ. Tổng thể chiếc xe mang lại cảm giác hài hòa, phù hợp với nhiều đối tượng người dùng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-gogo-s5-cang-nhom-duc-2-phanh-dia-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Một điểm cộng lớn là xe có nhiều phiên bản màu sắc đa dạng từ trung tính đến nổi bật như đen, xanh, vàng – đen hay xanh pastel. Điều này giúp người dùng dễ dàng lựa chọn theo phong cách cá nhân, từ nhẹ nhàng đến cá tính.</p>\n<p>Phần vỏ xe được làm từ nhựa ABS – PP cao cấp, có khả năng chịu lực tốt, chống trầy xước hiệu quả và giữ được độ bền đẹp trong quá trình sử dụng lâu dài.</p>\n<h2><strong>Càng nhôm đúc nguyên khối – điểm nâng cấp đáng giá</strong></h2>\n<p>Nếu chỉ nhìn bên ngoài, nhiều người có thể chưa nhận ra điểm khác biệt lớn nhất của Dibao Gogo S5 lại nằm ở phần kết cấu bên trong. Xe được trang bị càng sau bằng nhôm đúc nguyên khối, thay vì sử dụng càng sắt hàn truyền thống như nhiều mẫu xe khác.</p>\n<p>Chi tiết này mang lại lợi ích rõ rệt về độ bền và khả năng vận hành. Nhôm đúc giúp tăng độ cứng cáp, hạn chế rung lắc khi di chuyển, đặc biệt là trên những đoạn đường xấu hoặc khi chở nặng.</p>\n<p>Bên cạnh đó, càng nhôm đúc còn góp phần nâng cao tính thẩm mỹ cho xe, giúp phần gầm trở nên gọn gàng, hiện đại và cao cấp hơn so với các dòng xe cùng phân khúc.</p>\n<h2><strong>Trang bị an toàn và tiện ích hiện đại</strong></h2>\n<p>Không chỉ chú trọng vào thiết kế, <strong>xe Dibao</strong> Gogo S5 còn được đầu tư mạnh về trang bị nhằm mang lại trải nghiệm sử dụng tiện lợi và an toàn hơn cho người dùng.</p>\n<p>Xe được trang bị hệ thống phanh đĩa cho cả bánh trước và bánh sau, giúp tăng lực phanh và độ kiểm soát khi di chuyển. Nhờ đó, người lái có thể xử lý tốt hơn trong các tình huống phanh gấp hoặc khi di chuyển trên đường trơn trượt.</p>\n<p>Hệ thống đèn LED bi cầu được sử dụng cho toàn bộ cụm đèn, mang lại ánh sáng mạnh, rõ và tiết kiệm điện năng. Điều này giúp tăng khả năng quan sát khi di chuyển vào ban đêm hoặc trong điều kiện thời tiết xấu.</p>\n<p>Ngoài ra, xe còn được trang bị lốp không săm giúp tăng độ bám đường và giảm nguy cơ xì lốp đột ngột. Cốp xe rộng rãi cũng là một điểm cộng lớn, cho phép người dùng mang theo nhiều vật dụng cá nhân khi di chuyển.</p>\n<h2><strong>Động cơ mạnh mẽ, vận hành ổn định</strong></h2>\n<p>Bên cạnh ngoại hình và trang bị, khả năng vận hành chính là yếu tố quyết định đến trải nghiệm thực tế của người dùng. Dibao Gogo S5 được trang bị động cơ điện có công suất lên đến 1500W, đủ mạnh để đáp ứng nhu cầu di chuyển hàng ngày.</p>\n<p>Xe có khả năng tăng tốc mượt mà, không bị ì khi chở nặng và vận hành ổn định trong môi trường đô thị. Đây là điểm rất quan trọng đối với những người thường xuyên di chuyển trong thành phố.</p>\n<p>Hệ thống ắc quy 60V 23Ah giúp xe có thể di chuyển quãng đường từ 80 đến 90km chỉ sau một lần sạc đầy. Thời gian sạc khoảng 6 đến 8 tiếng, phù hợp với thói quen sạc qua đêm của người dùng.</p>\n<p>Tốc độ tối đa khoảng 50km/h giúp xe di chuyển linh hoạt mà vẫn đảm bảo an toàn và phù hợp với quy định hiện hành.</p>\n<h2><strong>Trải nghiệm vận hành êm ái, phù hợp di chuyển hàng ngày</strong></h2>\n<p>Khi sử dụng thực tế, Dibao Gogo S5 mang lại cảm giác lái khá dễ chịu nhờ hệ thống giảm xóc thủy lực hoạt động hiệu quả. Xe hấp thụ tốt các rung động từ mặt đường, giúp hạn chế tình trạng xóc nảy khi đi qua ổ gà hoặc đường gồ ghề.</p>\n<p>Nhờ thiết kế gọn gàng và trọng lượng hợp lý, người dùng có thể dễ dàng điều khiển xe trong các tình huống giao thông đông đúc. Việc quay đầu, dắt xe hay di chuyển trong không gian hẹp cũng trở nên đơn giản hơn.</p>\n<p>Đây là mẫu xe phù hợp để sử dụng hàng ngày, từ đi học, đi làm cho đến các nhu cầu di chuyển ngắn trong đô thị.</p>\n<h2><strong>Lợi ích khi sở hữu Dibao Gogo S5 càng nhôm đúc</strong></h2>\n<p>Sở hữu Dibao Gogo S5 không chỉ mang lại sự tiện lợi trong di chuyển mà còn giúp người dùng tiết kiệm đáng kể chi phí sử dụng. So với xe xăng, chi phí vận hành của xe điện thấp hơn rất nhiều khi không cần đổ xăng, không cần thay dầu máy và ít phát sinh chi phí bảo dưỡng.</p>\n<p>Ngoài ra, xe vận hành êm ái, không gây tiếng ồn và không phát thải khí độc hại, góp phần bảo vệ môi trường và nâng cao chất lượng cuộc sống.</p>\n<p>Thiết kế hiện đại cũng giúp người dùng tự tin hơn khi sử dụng, đặc biệt là với giới trẻ yêu thích phong cách năng động và cá tính.</p>\n<p>Tổng thể, Dibao Gogo S5 càng nhôm đúc là một mẫu<strong> xe máy điện</strong> hội tụ đầy đủ các yếu tố từ thiết kế, vận hành cho đến độ an toàn và tiện ích. Với mức giá hợp lý, khả năng vận hành ổn định và chi phí sử dụng thấp, đây là lựa chọn rất đáng cân nhắc trong phân khúc xe điện hiện nay.</p>\n<p>Nếu bạn đang tìm kiếm một chiếc xe vừa đẹp, vừa bền, lại dễ sử dụng và phù hợp với nhu cầu di chuyển hàng ngày, Dibao Gogo S5 chắc chắn là cái tên không nên bỏ qua.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-ls007', 'Xe Máy Điện Dibao LS007', 'dibao', '[\"xe-may-dien\"]', 22990000, 22990000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-6.webp\"]', '[]', '[]', '[]', '<p>Không khó để nhận ra xu hướng thiết kế xe điện hiện nay đang dần tiệm cận với kiểu dáng xe máy quen thuộc, đặc biệt là những mẫu tay ga phổ biến như Vision. Sự kết hợp giữa ngoại hình thanh thoát, gọn gàng cùng công nghệ vận hành bằng điện mang đến một lựa chọn vừa quen mắt, vừa hiện đại. Xe Máy Điện Dibao LS007 là một mẫu xe đi theo hướng đó, mang dáng dấp của một chiếc xe máy truyền thống, nhưng vận hành êm ái và tiết kiệm theo đúng tinh thần xe điện.</p>\n<p>Ấn tượng đầu tiên khi tiếp cận xe máy điện Dibao LS007 đến từ tổng thể thiết kế mang hơi hướng hiện đại pha chút thể thao. Xe không đi theo phong cách bo tròn mềm mại như nhiều mẫu xe phổ thông, mà chọn những đường nét rõ ràng, dứt khoát hơn để tạo cảm giác mạnh mẽ và cá tính.</p>', '<p>Không khó để nhận ra xu hướng thiết kế xe điện hiện nay đang dần tiệm cận với kiểu dáng xe máy quen thuộc, đặc biệt là những mẫu tay ga phổ biến như Vision. Sự kết hợp giữa ngoại hình thanh thoát, gọn gàng cùng công nghệ vận hành bằng điện mang đến một lựa chọn vừa quen mắt, vừa hiện đại. Xe Máy Điện Dibao LS007 là một mẫu xe đi theo hướng đó, mang dáng dấp của một chiếc xe máy truyền thống, nhưng vận hành êm ái và tiết kiệm theo đúng tinh thần xe điện.</p>\n<p><strong><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-7.webp\" alt=\"Xe Máy Điện Dibao LS007\" loading=\"lazy\"></strong></p>\n<h2><strong>Dibao LS007 có ngoại hình hiện đại, kích thước tối ưu</strong></h2>\n<p>Ấn tượng đầu tiên khi tiếp cận <strong>xe máy điện</strong> Dibao LS007 đến từ tổng thể thiết kế mang hơi hướng hiện đại pha chút thể thao. Xe không đi theo phong cách bo tròn mềm mại như nhiều mẫu xe phổ thông, mà chọn những đường nét rõ ràng, dứt khoát hơn để tạo cảm giác mạnh mẽ và cá tính.</p>\n<p>Kích thước tổng thể của xe ở mức khá lớn trong phân khúc xe điện, mang lại sự đầm chắc khi vận hành. Tuy nhiên, điều đáng nói là sự “to” này không gây cảm giác cồng kềnh. Nhờ cách bố trí khung sườn hợp lý, xe vẫn giữ được khả năng xoay trở linh hoạt trong điều kiện đường phố đông đúc – yếu tố rất quan trọng tại các đô thị lớn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-8.webp\" alt=\"Xe Máy Điện Dibao LS007\" loading=\"lazy\"></p>\n<p>Chiều cao yên được thiết kế ở mức phù hợp với vóc dáng người Việt, giúp người lái dễ dàng chống chân khi dừng xe. Đây là chi tiết tưởng nhỏ nhưng lại ảnh hưởng trực tiếp đến sự tự tin khi điều khiển, đặc biệt với người mới làm quen xe điện.</p>\n<p>Bánh xe kích thước lớn là một điểm cộng rõ rệt. Không chỉ giúp tổng thể xe cân đối hơn, bánh lớn còn hỗ trợ vượt chướng ngại vật tốt hơn khi đi qua ổ gà, gờ giảm tốc hoặc các đoạn đường xấu. Kết hợp với lốp không săm chất lượng cao, xe giữ được độ bám đường ổn định ngay cả khi di chuyển trong điều kiện trời mưa.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-ls007-9.webp\" alt=\"Xe Máy Điện Dibao LS007\" loading=\"lazy\"></p>\n<p>Ngoài ra, vành đúc nguyên khối và càng sau bằng hợp kim giúp tăng độ cứng cáp cho khung xe. Đây là những chi tiết thể hiện sự đầu tư nghiêm túc về mặt kết cấu, không chỉ để đẹp mà còn phục vụ trực tiếp cho độ bền lâu dài.</p>\n<p>Màu sắc đa dạng cũng giúp Xe Máy Điện Dibao LS007 tiếp cận nhiều nhóm người dùng hơn. Từ những gam màu trung tính đến các lựa chọn nổi bật, người dùng có thể dễ dàng chọn phiên bản phù hợp với phong cách cá nhân.</p>\n<h2><strong>Không chỉ ngoại hình, động như cũng chạy như xe máy</strong></h2>\n<p>Điểm khiến Xe Máy Điện <strong>Dibao LS007</strong> nổi bật so với nhiều đối thủ cùng phân khúc chính là động cơ công suất lớn. Với mức công suất lên tới 2800W, xe mang lại cảm giác tăng tốc rõ rệt ngay từ những cú vặn ga đầu tiên.</p>\n<p>Tuy mạnh mẽ, nhưng cách xe truyền tải sức mạnh lại khá mượt mà. Người lái không bị “giật” hay mất kiểm soát khi tăng tốc đột ngột. Đây là sự cân bằng quan trọng, giúp xe vừa mang lại cảm giác mạnh mẽ, vừa giữ được sự an toàn và dễ làm quen.</p>\n<p>Trong điều kiện di chuyển thực tế, xe đạt tốc độ tối đa khoảng 60 km/h – mức tốc độ khá cao đối với xe điện. Điều này cho phép xe dễ dàng hòa vào dòng giao thông, không bị “tụt lại” như một số mẫu xe công suất thấp.</p>\n<p>Khả năng tải trọng lớn cũng là một lợi thế đáng kể. Xe có thể chở hai người cùng nhiều đồ dùng mà vẫn giữ được sự ổn định. Khi chở nặng, xe không có cảm giác ì hay hụt lực, cho thấy động cơ hoạt động hiệu quả và bền bỉ.</p>\n<p>Một điểm đáng chú ý khác là khả năng leo dốc. Trong các tình huống như lên cầu vượt hoặc dốc hầm, xe vẫn duy trì lực kéo tốt, không bị giảm hiệu suất đột ngột. Điều này giúp người dùng yên tâm hơn khi sử dụng trong môi trường đô thị có nhiều địa hình khác nhau.</p>\n<h2><strong>Dibao LS007 được chú trọng đến yếu tố an toàn</strong></h2>\n<p>Hệ thống phanh đĩa trước và sau kết hợp công nghệ EABS giúp phân bổ lực phanh hợp lý. Khi phanh gấp, xe hạn chế tình trạng bó cứng bánh, giảm nguy cơ trượt ngã. Đây là trang bị thường thấy trên các dòng xe cao cấp, mang lại lợi thế lớn cho LS007 trong phân khúc.</p>\n<p>Giảm xóc thủy lực trước sau giúp xe vận hành êm ái hơn trên các đoạn đường gồ ghề. Khi đi qua ổ gà hoặc gờ giảm tốc, lực chấn động được hấp thụ hiệu quả, hạn chế rung lắc truyền lên tay lái và yên xe.</p>\n<p>Lốp không săm bản lớn giúp tăng độ bám đường và giảm nguy cơ xì hơi đột ngột. Đây là yếu tố quan trọng khi di chuyển trong điều kiện đường trơn trượt hoặc thời tiết xấu.</p>\n<p>Khung xe chắc chắn kết hợp với trọng lượng hợp lý giúp xe giữ được độ đầm khi chạy ở tốc độ cao. Người lái sẽ cảm nhận rõ sự ổn định, không bị “bồng bềnh” hay mất cân bằng khi di chuyển trên đường dài.</p>\n<p>Một trong những điểm mạnh đáng chú ý của Xe Máy Điện Dibao LS007 nằm ở hệ thống năng lượng. Xe sử dụng bộ ắc quy dung lượng lớn, cho phép di chuyển quãng đường lên tới khoảng 100 km sau mỗi lần sạc đầy.</p>\n<p>Với quãng đường này, người dùng có thể sử dụng xe trong nhiều ngày mà không cần sạc lại. Đây là lợi thế lớn đối với những người có lịch trình bận rộn hoặc không tiện sạc xe thường xuyên.</p>\n<p>Thời gian sạc đầy tương đối dài, nhưng lại phù hợp với thói quen sạc qua đêm. Bộ sạc thông minh tích hợp cơ chế tự ngắt khi đầy giúp bảo vệ ắc quy và tăng độ an toàn khi sử dụng.</p>\n<p>Chi phí sạc điện thấp hơn nhiều so với chi phí xăng dầu, giúp người dùng tiết kiệm đáng kể trong dài hạn. Ngoài ra, xe điện không yêu cầu bảo dưỡng phức tạp như thay dầu hay bảo trì động cơ, giúp giảm thêm chi phí sử dụng.</p>\n<p>Hệ thống pin và điện được thiết kế chống nước tốt, cho phép xe vận hành ổn định trong điều kiện mưa hoặc đường ngập nhẹ. Đây là yếu tố rất quan trọng trong điều kiện thời tiết tại Việt Nam.</p>\n<h2><strong>Công nghệ thông minh hỗ trợ người dùng</strong></h2>\n<p>Một điểm khiến Xe Máy Điện Dibao LS007 trở nên hấp dẫn hơn là các tính năng công nghệ đi kèm. Xe không tích hợp quá nhiều công nghệ phức tạp, nhưng những gì có đều phục vụ trực tiếp cho trải nghiệm sử dụng.</p>\n<p>Khóa thẻ từ NFC giúp mở khóa nhanh chóng và tăng tính bảo mật. Người dùng không cần mang theo chìa khóa cơ, giảm nguy cơ mất chìa hoặc bị sao chép.</p>\n<p>Khả năng kết nối với ứng dụng trên điện thoại giúp người dùng theo dõi tình trạng xe, kiểm tra dung lượng pin và các thông số quan trọng. Đây là bước tiến đáng kể, đưa xe điện tiến gần hơn đến xu hướng “smart mobility”.</p>\n<p>Bảng đồng hồ LCD hiển thị rõ ràng các thông tin như tốc độ, quãng đường và mức pin. Giao diện trực quan giúp người lái dễ quan sát ngay cả khi đang di chuyển. Hệ thống đèn LED toàn phần không chỉ tiết kiệm điện mà còn tăng khả năng nhận diện trong giao thông. Ánh sáng mạnh, rõ giúp người lái tự tin hơn khi di chuyển vào ban đêm.</p>\n<h2><strong>Chính sách bảo hành tạo sự yên tâm</strong></h2>\n<p>Một trong những yếu tố giúp Xe Máy Điện Dibao LS007 ghi điểm với người dùng là chính sách bảo hành rõ ràng. Khung xe, động cơ và hệ thống pin đều được bảo hành trong thời gian dài, thể hiện sự tự tin của nhà sản xuất vào chất lượng sản phẩm.</p>\n<p>Đối với người dùng, đặc biệt là những người lần đầu chuyển sang xe điện, chính sách này mang lại sự yên tâm lớn. Họ không phải lo lắng quá nhiều về chi phí sửa chữa hoặc rủi ro trong quá trình sử dụng.</p>\n<p><strong>Xe Dibao</strong> LS007 là mẫu xe hội tụ nhiều yếu tố quan trọng: thiết kế hiện đại, động cơ mạnh mẽ, quãng đường dài và các trang bị an toàn, công nghệ hợp lý. Đây không phải là chiếc xe chỉ để “gây ấn tượng ban đầu”, mà là phương tiện được xây dựng để phục vụ lâu dài.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-mxs', 'Xe máy điện Dibao MXS', 'dibao', '[\"xe-may-dien\"]', 15690000, 15690000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-6.webp\"]', '[]', '[]', '[]', '<p>Với đa số người dùng, một chiếc xe thực sự đáng giá lại là chiếc xe có thể phục vụ tốt cuộc sống hằng ngày: dễ điều khiển, vận hành ổn định, chi phí hợp lý và không phát sinh quá nhiều phiền toái sau thời gian dài sử dụng. Xe máy điện Dibao MXS là một trong số ít những mẫu xe đi đúng hướng đó, vì thế mà được nhiều người lựa chọn làm phương tiện di chuyển hằng ngày. Hãy cùng tìm hiểu thêm về những điểm giúp Dibao MXS ghi điểm trong lòng người dùng nhé!</p>\n<p>Trong bối cảnh giao thông đô thị ngày càng đông đúc, một chiếc xe nhỏ gọn không còn là “lựa chọn phụ”, mà đã trở thành ưu tiên hàng đầu. Xe máy điện cho nữ Dibao MXS được thiết kế với kích thước tối ưu để giải quyết chính bài toán này.</p>', '<p>Với đa số người dùng, một chiếc xe thực sự đáng giá lại là chiếc xe có thể phục vụ tốt cuộc sống hằng ngày: dễ điều khiển, vận hành ổn định, chi phí hợp lý và không phát sinh quá nhiều phiền toái sau thời gian dài sử dụng. Xe máy điện Dibao MXS là một trong số ít những mẫu xe đi đúng hướng đó, vì thế mà được nhiều người lựa chọn làm phương tiện di chuyển hằng ngày. Hãy cùng tìm hiểu thêm về những điểm giúp Dibao MXS ghi điểm trong lòng người dùng nhé!</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-7.webp\" alt=\"Xe máy điện Dibao MXS\" loading=\"lazy\"></p>\n<h2><strong>Lựa chọn xe nhỏ gọn thì không nên bỏ qua Dibao MXS</strong></h2>\n<p>Trong bối cảnh giao thông đô thị ngày càng đông đúc, một chiếc xe nhỏ gọn không còn là “lựa chọn phụ”, mà đã trở thành ưu tiên hàng đầu. <strong>Xe máy điện cho nữ</strong> Dibao MXS được thiết kế với kích thước tối ưu để giải quyết chính bài toán này.</p>\n<p>Xe không quá dài, không cồng kềnh, giúp người dùng dễ dàng di chuyển trong những con phố chật hẹp, quay đầu nhanh trong không gian nhỏ và đặc biệt thuận tiện khi dắt xe hoặc gửi xe ở những khu vực đông người. Đây là điều mà những dòng xe lớn thường khiến người dùng cảm thấy “ngại” trong quá trình sử dụng hàng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-8.webp\" alt=\"Xe máy điện Dibao MXS\" loading=\"lazy\"></p>\n<p>Tuy nhiên, điểm đáng nói là Dibao MXS không đi theo hướng “thu nhỏ tối đa” như một số dòng xe đạp điện. Thay vào đó, xe vẫn giữ được tỷ lệ cân đối của một chiếc xe máy điện đúng nghĩa. Phần đầu xe thiết kế gọn nhưng chắc, thân xe liền mạch, không bị cảm giác rời rạc hay yếu ớt.</p>\n<p>Chính sự cân bằng giữa nhỏ gọn và chắc chắn này tạo nên một trải nghiệm rất riêng: người dùng cảm thấy linh hoạt khi điều khiển, nhưng vẫn có sự yên tâm về độ ổn định khi vận hành.</p>\n<h2><strong>Nhỏ gọn nhưng không đánh đổi cảm giác lái</strong></h2>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-mxs-9.webp\" alt=\"Xe máy điện Dibao MXS\" loading=\"lazy\"></p>\n<p>Một trong những vấn đề thường gặp ở các mẫu xe điện nhỏ là cảm giác lái không chắc chắn: xe nhẹ nhưng thiếu đầm, dễ rung khi chạy nhanh hoặc khi đi qua đường xấu. Xe máy điện <strong>Dibao MXS</strong> đã xử lý khá tốt điểm này.</p>\n<p>Khung xe được thiết kế chắc chắn, kết hợp với hệ thống giảm xóc phù hợp giúp xe giữ được độ ổn định khi di chuyển. Khi chạy ở tốc độ trung bình, xe không có hiện tượng “lắc” hay mất cân bằng – điều mà người dùng sẽ cảm nhận rõ ràng ngay từ những lần sử dụng đầu tiên.</p>\n<p>Cảm giác ga cũng là một điểm cộng lớn. Xe phản hồi nhanh nhưng không bị giật, giúp người lái dễ kiểm soát trong mọi tình huống. Dù là người mới hay đã quen với xe điện, bạn đều có thể làm chủ chiếc xe này một cách dễ dàng.</p>\n<h2><strong>Hiệu năng đủ mạnh, không ì ga khi tăng tốc</strong></h2>\n<p>Thay vì chạy theo những con số “ấn tượng trên giấy”, Xe máy điện Dibao MXS tập trung vào hiệu năng phù hợp với nhu cầu sử dụng thực tế. Xe có khả năng tăng tốc mượt, không bị trễ khi vặn ga. Điều này đặc biệt hữu ích khi di chuyển trong thành phố – nơi bạn thường xuyên phải dừng, đi chậm và tăng tốc lại liên tục. Một chiếc xe phản hồi tốt sẽ giúp việc di chuyển trở nên thoải mái và ít căng thẳng hơn.</p>\n<p>Khi chở hai người, xe vẫn giữ được sự ổn định, không bị ì máy. Khả năng leo dốc nhẹ cũng được đảm bảo, phù hợp với điều kiện đường xá tại Việt Nam. Điều quan trọng là mọi thứ đều được “tinh chỉnh vừa đủ”: không quá yếu để gây khó chịu, cũng không quá mạnh để khiến xe trở nên khó kiểm soát. Đây là một hướng đi thông minh, đặc biệt phù hợp với người dùng phổ thông.</p>\n<h2><strong>Quãng đường 80km/lần sạc, giảm áp lực sử dụng</strong></h2>\n<p>Một chiếc xe điện tốt không chỉ nằm ở việc chạy được xa, mà còn ở cách nó giúp người dùng “quên đi” việc phải sạc xe liên tục. Xe máy điện Dibao MXS làm khá tốt điều này. Với khả năng đáp ứng quãng đường di chuyển dài trong một lần sạc, xe phù hợp với nhu cầu đi học, đi làm hoặc di chuyển hằng ngày trong thành phố. Người dùng không cần phải lo lắng về việc “hết pin giữa đường” nếu sử dụng đúng cách.</p>\n<p>Thói quen sử dụng cũng rất đơn giản: sạc qua đêm và dùng vào ngày hôm sau. Không cần tính toán phức tạp, không cần canh thời gian – mọi thứ diễn ra tự nhiên như cách bạn sử dụng một chiếc điện thoại. Chính sự tiện lợi này giúp xe trở nên “dễ sống” hơn trong thời gian dài, thay vì tạo thêm áp lực cho người dùng.</p>\n<p>Không giống nhiều mẫu xe cố gắng nhồi nhét thật nhiều tính năng, Xe máy điện Dibao MXS chọn cách trang bị có chọn lọc. Hệ thống đèn LED được tối ưu để đảm bảo độ sáng khi đi ban đêm, đồng thời tiết kiệm điện năng. Màn hình hiển thị rõ ràng, cung cấp đầy đủ thông tin cần thiết mà không gây rối mắt.</p>\n<p>Khóa xe được thiết kế theo hướng tiện lợi, giúp người dùng thao tác nhanh chóng trong quá trình sử dụng hằng ngày. Đây là những chi tiết nhỏ nhưng lại ảnh hưởng rất lớn đến trải nghiệm thực tế.</p>\n<p>Hệ thống phanh hoạt động ổn định, mang lại cảm giác an toàn khi cần xử lý tình huống bất ngờ. Đây là yếu tố quan trọng nhưng thường bị bỏ qua khi người dùng chỉ nhìn vào thiết kế hoặc công suất.</p>\n<h2><strong>Xe máy điện cỡ nhỏ cho những bạn nấm lùn</strong></h2>\n<p>Chiều cao yên hợp lý giúp người dùng dễ chống chân, đặc biệt phù hợp với học sinh hoặc người có chiều cao trung bình. Sàn để chân rộng, tạo tư thế ngồi thoải mái khi di chuyển lâu.</p>\n<p>Yên xe được thiết kế đủ rộng cho hai người, không gây cảm giác chật chội. Khi di chuyển qua những đoạn đường xấu, hệ thống giảm xóc hoạt động hiệu quả, giúp giảm rung lắc và tăng độ êm ái.</p>\n<p>Đây là những yếu tố không quá “nổi bật” khi nhìn vào thông số, nhưng lại là thứ quyết định trải nghiệm sử dụng lâu dài. Một chiếc xe tốt không chỉ cần hoạt động tốt khi mới mua, mà còn phải giữ được sự ổn định sau thời gian dài sử dụng. Xe máy điện Dibao MXS được xây dựng theo hướng này.</p>\n<p>Khung xe chắc chắn giúp hạn chế tình trạng xuống cấp nhanh. Các chi tiết được hoàn thiện ở mức tốt trong tầm giá, giảm thiểu hiện tượng lỏng lẻo hoặc rung lắc sau một thời gian sử dụng. Hệ thống vận hành ổn định, không yêu cầu bảo trì phức tạp. Điều này giúp người dùng tiết kiệm chi phí và thời gian trong quá trình sử dụng lâu dài.</p>\n<p><br><strong>Xe máy điện Dibao</strong> MXS là một lựa chọn dành cho những ai hiểu rõ mình cần gì ở một chiếc xe điện: sự đơn giản, ổn định và hiệu quả. Nhỏ gọn nhưng không yếu, đủ mạnh nhưng vẫn dễ kiểm soát, trang bị vừa đủ nhưng không thiếu – tất cả kết hợp lại tạo nên một chiếc xe phù hợp với cuộc sống đô thị hiện đại.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-pansy-s3-2-phanh-dia', 'Xe Máy Điện Dibao Pansy S3 2 Phanh Đĩa', 'dibao', '[\"xe-may-dien\"]', 18690000, 18690000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Dibao\"},{\"label\":\"Xuất xứ\",\"value\":\"Đài Loan\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Bảo hành Pin\",\"value\":\"2 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1.760mm x 710mm x 1.140mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"760mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"3.50-10 TL\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"1350W (Max 1500W)\"},{\"label\":\"Vận hành\",\"value\":\"Tự động\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50-55km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"98kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"80-90km/ 1 lần sạc đầy (điều kiện tiêu chuẩn)\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình acquy 20Ah\"},{\"label\":\"Thời gian sạc\",\"value\":\"10 - 12 tiếng\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực. Phuộc sau: Lò so trụ đơn, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, chống trộm, sổ bảo hành\"}]}]', '<p>Xe máy điện Dibao Pansy S3 2 phanh đĩa không chỉ là một mẫu xe mới được ra mắt mà còn là sự kết hợp hoàn hảo giữa thiết kế thời thượng, hiệu suất vận hành ấn tượng và chi phí sử dụng hợp lý. Được sản xuất bởi hãng Dibao đến từ Đài Loan - nơi có kinh nghiệm lâu năm trong lĩnh vực sản xuất xe điện, mẫu xe này đã nhanh chóng chiếm được lòng tin của hàng ngàn khách hàng tại Việt Nam, đặc biệt là phái nữ và những người mới bắt đầu làm quen với xe điện. Bài viết này sẽ đi sâu vào phân tích chi tiết từng yếu tố của Dibao Pansy S3, giúp bạn có cái nhìn tổng quan và đưa ra quyết định mua xe phù hợp nhất với nhu cầu.</p>\n<p>Một trong những điểm mạnh lớn nhất của Dibao Pansy S3 chính là thiết kế ngoại hình mang đậm nét cổ điển của dòng xe Vespa, kết hợp với những chi tiết hiện đại, tạo nên vẻ ngoài sang trọng, tinh tế và không bao giờ lỗi mốt.</p>', '<p>Xe máy điện Dibao Pansy S3 2 phanh đĩa không chỉ là một mẫu xe mới được ra mắt mà còn là sự kết hợp hoàn hảo giữa thiết kế thời thượng, hiệu suất vận hành ấn tượng và chi phí sử dụng hợp lý. Được sản xuất bởi hãng Dibao đến từ Đài Loan - nơi có kinh nghiệm lâu năm trong lĩnh vực sản xuất xe điện, mẫu xe này đã nhanh chóng chiếm được lòng tin của hàng ngàn khách hàng tại Việt Nam, đặc biệt là phái nữ và những người mới bắt đầu làm quen với xe điện. Bài viết này sẽ đi sâu vào phân tích chi tiết từng yếu tố của Dibao Pansy S3, giúp bạn có cái nhìn tổng quan và đưa ra quyết định mua xe phù hợp nhất với nhu cầu.</p>\n<h2>Ngoại Hình: Thiết Kế Cổ Điển Sang Trọng, Phù Hợp Với Tất Cả Đối Tượng</h2>\n<p>Một trong những điểm mạnh lớn nhất của <strong>Dibao Pansy S3</strong> chính là thiết kế ngoại hình mang đậm nét cổ điển của dòng xe Vespa, kết hợp với những chi tiết hiện đại, tạo nên vẻ ngoài sang trọng, tinh tế và không bao giờ lỗi mốt.</p>\n<h3>Kích Thước Và Trọng Lượng Dễ Điều Khiển</h3>\n<p>Xe có kích thước tổng thể 1.760mm x 710mm x 1.140mm, với chiều rộng chỉ 710mm giúp xe dễ dàng luồn lách trong các con phố đông đúc, dễ dàng di chuyển và tìm chỗ đỗ ngay cả ở những khu vực hẹp. Trọng lượng xe chỉ khoảng 98kg, rất nhẹ nhàng cho người dùng, đặc biệt là phái nữ, có thể dễ dàng dắt xe, đỗ xe và điều khiển trên mọi nẻo đường.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Chiều cao yên xe là 760mm, một chiều cao lý tưởng phù hợp với đại đa số người dùng tại Việt Nam, kể cả những bạn có chiều cao khiêm tốn. Yên xe được bọc da nhân tạo kết hợp nỉ bền bỉ, mang lại cảm giác ngồi thoải mái, êm ái trong suốt quá trình di chuyển, không bị mỏi lưng ngay cả sau những chuyến đi dài.</p>\n<h3>Thiết Kế Chi Tiết Đầy Nét Sáng Tạo</h3>\n<p>Đầu xe nổi bật với cụm đèn LED hai tầng có viền mạ nhôm sáng bóng, không chỉ làm tăng tính thẩm mỹ mà còn giúp đèn chiếu sáng rộng rãi, góc chiếu lớn mà không gây chói mắt cho người đối diện, đảm bảo an toàn khi di chuyển vào ban đêm. Đèn xi nhan trước và sau được tích hợp hài hòa với tổng thể thiết kế, không làm phá vỡ vẻ ngoài cân đối của xe.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Mặt đồng hồ kỹ thuật số chống chói hiển thị rõ ràng các thông số vận hành quan trọng như tốc độ, lượng pin, đèn tín hiệu, quãng đường di chuyển ngay cả dưới ánh sáng mặt trời gay gắt. Điểm đặc biệt là dải LED báo hiệu vận tốc thay đổi màu sắc theo từng mức tốc độ: đỏ khi mở máy, xanh lá khi bắt đầu hoạt động, vàng khi chạy ở 20km/h, xanh dương ở 30km/h và tím khi đạt tốc độ tối đa, giúp người lái dễ dàng theo dõi tốc độ mà không cần tập trung quá nhiều.</p>\n<p>Cốp xe được thiết kế theo hai tầng: cốp lớn dưới yên đủ sức chứa một mũ bảo hiểm cả đầu, áo mưa, túi xách hoặc các vật dụng cá nhân khác, và cốp nhỏ phía trước rất tiện lợi để đựng ví, điện thoại, giấy tờ xe, thẻ xe hay các vật dụng nhỏ cần sử dụng thường xuyên.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s3-2-phanh-dia-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<h3>Màu Sắc Đa Dạng, Phù Hợp Với Phong Cách Cá Nhân</h3>\n<p>Dibao Pansy S3 có sẵn đủ màu sắc, cho phép người dùng dễ dàng lựa chọn theo sở thích và phong cách cá nhân. Từ các tông màu trung tính thanh lịch như trắng, đen, xám đến các màu sắc tươi sáng, nổi bật như đỏ, xanh lam, xanh lá, vàng, mọi người đều có thể tìm được màu sắc phù hợp với mình.</p>\n<h2>Hiệu Suất Vận Hành: Mạnh Mẽ, Êm Ái Và An Toàn</h2>\n<p>Không chỉ đẹp về ngoại hình, Dibao Pansy S3 còn được trang bị hệ thống vận hành mạnh mẽ, đảm bảo hiệu suất ổn định và an toàn trong mọi điều kiện di chuyển.</p>\n<h3>Cơ Điện Mạnh Mẽ</h3>\n<p>Xe sử dụng động cơ điện có công suất 1350W, với công suất tối đa có thể lên tới 1500W. Động cơ này giúp xe đạt vận tốc tối đa khoảng 50-55km/h, hoàn toàn phù hợp với nhu cầu di chuyển trong đô thị, cho phép người lái dễ dàng vượt qua các phương tiện khác trên đường phố. Khả năng tăng tốc của xe mượt mà, không bị giật cục khi tăng hoặc giảm ga đột ngột nhờ hệ truyền động cải tiến, mang lại cảm giác lái thoải mái và tự tin.</p>\n<h3>Hệ Thống Giảm Chấn Và Phanh An Toàn</h3>\n<p>Dibao Pansy S3 được trang bị hệ thống giảm chấn thủy lực ở cả bánh trước và bánh sau:</p>\n<p>Phuộc trước ống lồng: Giúp chống rung lắc hiệu quả khi di chuyển trên các đoạn đường xấu, gồ ghề, giảm sự rung lắc cho người lái và hành khách.</p>\n<p>Phuộc sau lò xo trụ đơn: Cung cấp độ bền và khả năng điều chỉnh linh hoạt, giúp xe giữ ổn định ngay cả khi tải trọng thay đổi.</p>\n<p>Điểm cộng lớn nhất của phiên bản này là được trang bị phanh đĩa trước và sau, một tính năng rất hiếm thấy ở các mẫu xe máy điện cùng phân khúc. Phanh đĩa có ưu điểm vượt trội về hiệu suất phanh, mang lại khả năng dừng xe nhanh chóng, an toàn và đáng tin cậy trong mọi điều kiện thời tiết, đặc biệt là khi cần xử lý các tình huống bất ngờ. Lốp xe không săm với kích thước 3.50-10 TL giúp độ bám đường tốt, hạn chế tối đa nguy cơ xì hơi đột ngột và mang lại cảm giác lái chắc chắn, an toàn.</p>\n<h3>Tải Trọng Và Trọng Lượng Xe</h3>\n<p>Xe có tải trọng cho phép lên tới 130 - 150kg, đủ để chở hai người lớn một cách thoải mái. Trọng lượng xe chỉ 98kg giúp xe đầm chắc hơn khi vận hành, không bị ảnh hưởng nhiều bởi gió tạt ngang, đặc biệt phù hợp với những người sử dụng xe trên các tuyến đường cao tốc hay có gió mạnh.</p>\n<h2>Hệ Thống Pin: Dung Lượng Cao, Phạm Vi Di Chuyển Tốt Và Tiết Kiệm Năng Lượng</h2>\n<p>Pin là trái tim của bất kỳ loại xe điện nào, và Dibao Pansy S3 được trang bị hệ thống ắc quy chất lượng, mang lại hiệu suất hoạt động đáng nể.</p>\n<p>Xe sử dụng tổ hợp 5 bình ắc quy 12V, tổng dung lượng 23Ah, được đánh giá là một cấu hình ổn định và hiệu quả cho các dòng xe máy điện trong phân khúc này. Hệ thống ắc quy được thiết kế bền bỉ, chống sụt áp và chống quá dòng, giúp bảo vệ tuổi thọ pin và hạn chế hao mòn nhanh qua thời gian.</p>\n<p>Với một lần sạc đầy, Dibao Pansy S3 có thể di chuyển trong khoảng 80-90km trong điều kiện vận hành tiêu chuẩn, bao gồm tốc độ trung bình 30-40km/h và tải trọng khoảng 100kg. Con số này có thể thay đổi tùy thuộc vào nhiều yếu tố như tốc độ di chuyển, tải trọng, địa hình và cách sử dụng của người dùng, nhưng vẫn đủ đáp ứng nhu cầu đi lại hàng ngày của đại đa số người dùng tại các khu vực đô thị, từ việc đi học, đi làm, đi chợ hay đưa đón con nhỏ mà không cần quá lo lắng về việc hết pin giữa đường.</p>\n<p>Thời gian sạc đầy cho hệ thống ắc quy này dao động từ 10 - 12 tiếng, khá phù hợp để sạc xe qua đêm hoặc trong khoảng thời gian nhàn rỗi ban ngày, đảm bảo xe luôn sẵn sàng cho những chuyến đi tiếp theo.</p>\n<p>Ngoài ra, Dibao Pansy S3 còn được trang bị cổng sạc USB tiện lợi ngay trong cốp phụ phía trước, giống như một cục sạc dự phòng di động, cho phép người dùng sạc điện thoại, sạc pin dự phòng hoặc các thiết bị điện tử khác bất cứ lúc nào, rất hữu ích cho giới trẻ và những người thường xuyên di chuyển.</p>\n<h2>Tính Năng Thông Minh Và Tiện Ích Vượt Trội</h2>\n<p>Dibao Pansy S3 không chỉ dừng lại ở ngoại hình đẹp và động cơ tốt, mà còn tích hợp nhiều tính năng của một chiếc <strong>xe máy điện thông minh</strong>, tiện ích, nâng cao trải nghiệm sử dụng hàng ngày.</p>\n<p>Xe được trang bị hệ thống chống trộm tích hợp sẵn, giúp tăng cường an ninh, bảo vệ tài sản của người dùng. Hệ thống này có thể kích hoạt khi khóa xe, phát ra âm thanh cảnh báo nếu có người cố gắng di chuyển hay đột nhập vào xe, giúp ngăn chặn các hành vi trộm cắp.</p>\n<p>Từ việc bố trí cốp xe khoa học, sàn để chân rộng rãi cho đến hệ thống đèn chiếu sáng LED hiệu quả, tất cả đều được thiết kế nhằm mang lại sự tiện dụng và thoải mái tối đa cho người dùng. Sàn để chân được thiết kế chống trơn trượt, giúp người lái giữ vững chân khi dừng xe hay phanh thắng gấp, tránh các rủi ro không đáng có.</p>\n<p>Vành xe được làm từ thép đúc, đảm bảo độ bền và khả năng chịu lực cao, không dễ bị gãy gụng khi va chạm hoặc lái qua các chướng ngại vật. Lốp xe không săm 3.50-10 TL giúpđộ bám đường tốt, hạn chế tối đa nguy cơ xì hơi đột ngột, giảm chi phí bảo trì và thay thế lốp trong quá trình sử dụng.</p>\n<h2>Đối Tượng Sử Dụng Phù Hợp</h2>\n<p>Với những đặc điểm nổi bật về thiết kế, vận hành và tính năng, Dibao Pansy S3 2 phanh đĩa là lựa chọn lý tưởng cho nhiều đối tượng người dùng:</p>\n<p>+ Học sinh, sinh viên: Kích thước nhỏ gọn, dễ điều khiển, vận tốc phù hợp và chi phí hợp lý là những yếu tố quan trọng thu hút đối tượng này.</p>\n<p>+ Phái nữ: Thiết kế thời trang, sang trọng, yên xe êm ái, màu sắc đa dạng và trọng lượng nhẹ nhàng khiến Pansy S3 trở thành một phụ kiện thời trang không thể thiếu.</p>\n<p>+ Người làm công sở, nội trợ: Nhu cầu di chuyển trong đô thị, đi làm, đi chợ, đưa đón con nhỏ được đáp ứng tốt nhờ sự tiện lợi, tiết kiệm chi phí và khả năng vận hành êm ái.</p>\n<p>+ Người mới bắt đầu làm quen với xe điện: Chế độ vận hành tự động, phanh đĩa an toàn và các tính năng hỗ trợ thông minh giúp người dùng dễ dàng làm quen và điều khiển xe.</p>\n<p><strong>Xe máy điện Dibao</strong> Pansy S3 2 phanh đĩa thực sự là một lựa chọn đáng cân nhắc trong thị trường xe máy điện hiện nay. Với sự kết hợp hài hòa giữa phong cách thiết kế thời thượng, hiệu suất vận hành mạnh mẽ, an toàn, cùng các tính năng tiện ích thông minh và mức giá cạnh tranh, mẫu xe này không chỉ đáp ứng tốt nhu cầu di chuyển hàng ngày mà còn là một tuyên ngôn về phong cách và sự lựa chọn thông minh, bền vững cho người tiêu dùng.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-pansy-s4-2-phanh-dia', 'Xe Máy Điện Dibao Pansy S4 2 Phanh Đĩa', 'dibao', '[\"xe-may-dien\"]', 19190000, 19190000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Dibao\"},{\"label\":\"Xuất xứ\",\"value\":\"Đài Loan\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Bảo hành Pin\",\"value\":\"2 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1.760mm x 710mm x 1.140mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"760mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"3.50-10 TL\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"1350W (Max 1500W)\"},{\"label\":\"Vận hành\",\"value\":\"Tự động\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50-55km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"98kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"80-90km/ 1 lần sạc đầy (điều kiện tiêu chuẩn)\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình acquy 20Ah\"},{\"label\":\"Thời gian sạc\",\"value\":\"10 - 12 tiếng\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực. Phuộc sau: Lò so trụ đơn, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, chống trộm, sổ bảo hành\"}]}]', '<p>Không phải ai chọn xe điện cũng vì công nghệ hay tốc độ. Nhiều người hiện nay đơn giản chỉ muốn một chiếc xe khiến việc đi học, đi làm hay dạo phố mỗi ngày trở nên nhẹ nhàng và dễ chịu hơn. Xe máy điện Dibao Pansy Neo S4 mang đúng tinh thần đó khi kết hợp giữa thiết kế mang hơi hướng cổ điển, khả năng vận hành ổn định và những tiện ích phục vụ sát nhu cầu sử dụng thực tế trong đô thị.</p>\n<p>Điểm khiến xe máy điện Dibao Pansy Neo S4 dễ tạo thiện cảm nằm ở phong cách thiết kế mềm mại và thanh lịch. Tổng thể xe mang hơi hướng scooter cổ điển với phần đầu bo tròn, thân xe đầy đặn và các đường nét được hoàn thiện theo hướng tối giản thay vì quá cầu kỳ.</p>', '<p>Không phải ai chọn xe điện cũng vì công nghệ hay tốc độ. Nhiều người hiện nay đơn giản chỉ muốn một chiếc xe khiến việc đi học, đi làm hay dạo phố mỗi ngày trở nên nhẹ nhàng và dễ chịu hơn. Xe máy điện Dibao Pansy Neo S4 mang đúng tinh thần đó khi kết hợp giữa thiết kế mang hơi hướng cổ điển, khả năng vận hành ổn định và những tiện ích phục vụ sát nhu cầu sử dụng thực tế trong đô thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-7.webp\" alt=\"Xe Máy Điện Dibao Pansy Neo S4\" loading=\"lazy\"></p>\n<h2><strong>Hơi thở cổ điển nhưng không hề lỗi thời</strong></h2>\n<p>Điểm khiến <strong>xe máy điện</strong> Dibao Pansy Neo S4 dễ tạo thiện cảm nằm ở phong cách thiết kế mềm mại và thanh lịch. Tổng thể xe mang hơi hướng scooter cổ điển với phần đầu bo tròn, thân xe đầy đặn và các đường nét được hoàn thiện theo hướng tối giản thay vì quá cầu kỳ.</p>\n<p>Chính điều này giúp chiếc xe tạo cảm giác sang hơn nhiều mẫu xe điện phổ thông hiện nay. Dù xuất hiện trên phố hay trong khuôn viên trường học, Pansy Neo S4 vẫn mang lại nét riêng khá dễ nhận ra.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-8.webp\" alt=\"Xe Máy Điện Dibao Pansy Neo S4\" loading=\"lazy\"></p>\n<p>Kiểu dáng của xe cũng được thiết kế theo hướng thân thiện với nhiều nhóm người dùng khác nhau. Từ học sinh, sinh viên cho tới nhân viên văn phòng hoặc người nội trợ đều có thể dễ dàng làm quen và sử dụng hằng ngày.</p>\n<p>Bên cạnh đó, chiều cao yên hợp lý kết hợp phần sàn để chân rộng giúp tư thế ngồi trở nên thoải mái hơn khi phải di chuyển lâu trong thành phố. Đây là chi tiết tuy nhỏ nhưng ảnh hưởng khá nhiều tới trải nghiệm thực tế.</p>\n<h2><strong>Hệ thống đèn và mặt nạ tạo điểm nhấn hiện đại</strong></h2>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-s4-2-phanh-dia-9.webp\" alt=\"Xe Máy Điện Dibao Pansy Neo S4\" loading=\"lazy\"></p>\n<p>Dù mang phong cách cổ điển, xe máy điện Dibao Pansy Neo S4 vẫn được bổ sung nhiều chi tiết hiện đại để phù hợp hơn với thị hiếu hiện nay. Nổi bật nhất là cụm đèn trước với kiểu tạo hình vuông bo mềm khá lạ mắt. Thiết kế này giúp phần đầu xe trông cá tính hơn nhưng vẫn giữ được sự hài hòa với tổng thể mềm mại của thân xe.</p>\n<p>Xe sử dụng hệ thống đèn LED giúp khả năng chiếu sáng ổn định hơn khi di chuyển buổi tối, đồng thời tiết kiệm điện năng trong quá trình sử dụng. Dải LED định vị bao quanh cụm đèn cũng tạo cảm giác hiện đại hơn khi nhìn trực diện.</p>\n<p>Phần mặt nạ trước được tinh chỉnh theo hướng gọn gàng hơn so với nhiều dòng xe điện cổ điển trước đây. Các chi tiết crom kết hợp cùng đường nét mềm tạo cảm giác khá sang và phù hợp với phong cách thanh lịch mà mẫu xe này hướng tới. Ngoài ra, cụm đồng hồ điện tử trung tâm cũng giúp người dùng dễ quan sát các thông số như vận tốc, quãng đường hay mức pin còn lại trong quá trình di chuyển.</p>\n<h2><strong>Khả năng vận hành phù hợp với nhu cầu đi lại hàng ngày</strong></h2>\n<p>Xe máy điện <strong>Dibao Pansy Neo S4</strong> không hướng tới cảm giác tăng tốc quá mạnh hay tốc độ quá cao. Mẫu xe này tập trung nhiều hơn vào sự ổn định, dễ điều khiển và phù hợp với môi trường đô thị.</p>\n<p>Xe sử dụng động cơ có công suất tối đa khoảng 1500W, cho khả năng vận hành khá mượt khi đi trong phố. Tốc độ khoảng 50–55 km/h đủ để người dùng di chuyển linh hoạt mà vẫn giữ được cảm giác an toàn và dễ kiểm soát.</p>\n<p>Điểm đáng chú ý là xe vận hành khá êm. Khi đi qua các đoạn đường đông hoặc di chuyển trong khu dân cư, cảm giác nhẹ nhàng và ít tiếng ồn của xe giúp trải nghiệm sử dụng trở nên dễ chịu hơn rất nhiều.</p>\n<p>Ngoài ra, hệ thống chống nước tiêu chuẩn cũng giúp người dùng yên tâm hơn khi đi dưới trời mưa hoặc qua những đoạn đường ngập nhẹ – điều khá thường gặp tại nhiều thành phố lớn hiện nay.</p>\n<h2><strong>Quãng đường dài giúp xe điện trở nên thực tế hơn</strong></h2>\n<p>Một trong những yếu tố khiến nhiều người cân nhắc khi chọn xe điện chính là khả năng di chuyển sau mỗi lần sạc. Với xe máy điện Dibao Pansy Neo S4, quãng đường khoảng 80–90 km/lần sạc được xem là khá thoải mái cho nhu cầu sử dụng hàng ngày. Người dùng có thể đi học, đi làm hoặc di chuyển trong nội thành nhiều ngày liên tục mà không cần quá lo lắng chuyện sạc pin thường xuyên.</p>\n<p>Hệ thống sạc của xe cũng được thiết kế theo hướng thuận tiện hơn cho người dùng đô thị. Bộ sạc có chức năng tự ngắt khi đầy giúp tăng độ an toàn và hạn chế ảnh hưởng tới tuổi thọ ắc quy. Đây là điểm khá quan trọng bởi với nhiều người hiện nay, xe điện không còn là phương tiện phụ mà đã trở thành lựa chọn chính trong cuộc sống hàng ngày.</p>\n<h2><strong>Những trang bị thực tế giúp nâng cao trải nghiệm sử dụng</strong></h2>\n<p>Xe máy điện Dibao Pansy Neo S4 được đầu tư khá nhiều ở các chi tiết phục vụ trải nghiệm thực tế thay vì chỉ tập trung vào ngoại hình. Xe trang bị hệ thống phanh đĩa giúp việc giảm tốc ổn định hơn khi đi trong phố đông hoặc gặp tình huống cần xử lý gấp. Bộ lốp không săm kết hợp giảm xóc thủy lực cũng giúp xe vận hành êm hơn trên những đoạn đường xấu.</p>\n<p>Không gian chứa đồ là điểm khá tiện lợi trên mẫu xe này. Cốp dưới yên rộng giúp người dùng dễ mang theo các vật dụng cá nhân hằng ngày. Ngoài ra, móc treo đồ và cổng sạc USB cũng hỗ trợ khá tốt cho nhu cầu sử dụng hiện đại. Yên xe được thiết kế rộng và êm, tạo cảm giác thoải mái kể cả khi chở thêm người hoặc di chuyển quãng đường dài hơn bình thường.</p>\n<p>Điều khiến xe máy điện Dibao Pansy Neo S4 tạo được sức hút không nằm ở việc cố trở thành mẫu xe mạnh nhất hay công nghệ nhất thị trường. Giá trị của chiếc xe này đến từ sự cân bằng giữa thiết kế, trải nghiệm sử dụng và tính thực tế.</p>\n<p>Xe có ngoại hình đẹp nhưng không quá phô trương. Vận hành nhẹ nhàng nhưng vẫn đủ linh hoạt cho nhu cầu hàng ngày. Quãng đường di chuyển đủ dài để người dùng cảm thấy thoải mái hơn khi chọn xe điện làm phương tiện chính.</p>\n<p>Trong bối cảnh các đô thị đang dần hướng tới giao thông xanh, những mẫu xe như <strong>xe máy điện Dibao</strong> Pansy Neo S4 cho thấy xe điện hiện nay không chỉ là giải pháp tiết kiệm chi phí, mà còn trở thành lựa chọn thể hiện phong cách sống hiện đại, tinh tế và bền vững hơn mỗi ngày.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021', 'Xe Máy Điện Dibao Pansy SQ 2 phanh đĩa 2021', 'dibao', '[\"xe-may-dien\"]', 17890000, 17890000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-pansy-sq-2-phanh-dia-2021-6.webp\"]', '[]', '[]', '[]', '<p>Hiện nay các mẫu xe của hãng Dibao đang nhận được nhiều sự quan tâm hơn cả từ các bạn trẻ bởi kiểu dáng thời trang và mức giá cực yêu. Mới đây hãng cũng tung ra thị trường một mẫu xe mới chiều lòng những bạn trẻ yêu thích phong cách hiện đại, trẻ trung, phá cách, tất cả hội tụ ở mẫu Xe máy điện Dibao Pansy SQ.</p>\n<p>Vẻ đẹp cổ điển giữa lòng thành phố hiện đại thật thú vị, bạn chọn tận hưởng điều thú vị đó theo cách nào? Hành trình sẽ thật trọn vẹn nếu bạn đồng hành cùng chiếc Dibao Pansy SQ. Tổng thể thiết kế xe sang trọng như những chiếc Vespa cao cấp với lớp sơn cao cấp trên nền nhựa ABS bóng mượt và nổi bật. Kích thước xe là 1.750mm x 710mm x 1.110mm, phù hợp với chiều cao của đại đa số người Việt Nam.</p>', '<p><strong>Hiện nay các mẫu xe của hãng Dibao đang nhận được nhiều sự quan tâm hơn cả từ các bạn trẻ bởi kiểu dáng thời trang và mức giá cực yêu. Mới đây hãng cũng tung ra thị trường một mẫu xe mới chiều lòng những bạn trẻ yêu thích phong cách hiện đại, trẻ trung, phá cách, tất cả hội tụ ở mẫu&nbsp;Xe máy điện Dibao Pansy SQ.</strong></p>\n<h2><strong>THIẾT KẾ LẠ MẮT, MANG HƠI HƯỚNG CỔ ĐIỂN</strong></h2>\n<p>Vẻ đẹp cổ điển giữa lòng thành phố hiện đại thật thú vị, bạn chọn tận hưởng điều thú vị đó theo cách nào? Hành trình sẽ thật trọn vẹn nếu bạn đồng hành cùng chiếc Dibao Pansy SQ. Tổng thể thiết kế xe sang trọng như những chiếc Vespa cao cấp với lớp sơn cao cấp trên nền nhựa ABS bóng mượt và nổi bật. Kích thước xe là 1.750mm x 710mm x 1.110mm, phù hợp với chiều cao của đại đa số người Việt Nam.</p>\n<p>Xe được thiết kế khá mềm mại, khung xe được làm từ thép không gỉ bền và chắc chắn. Gương xe cực kỳ đáng yêu với kích thước vừa đủ và dễ quan sát.</p>\n<h2><strong>ĐÈN LED SIÊU NỔI BẬT</strong></h2>\n<p>Đèn pha của xe được thiết kế khá vuông, toát lên vẻ mạnh mẽ, cực kỳ nổi bật. Công nghệ LED chiếu đèn sáng rõ trong đêm, ánh sáng tỏa rộng đảm bảo an toàn và cực kỳ dễ chịu cho người lái cũng như người đi đối diện. Viền mạ crom càng làm nổi bật thêm vẻ đẹp sang trọng và hiện đại của xe. Đây là một trong những phần mới lạ nhất, bởi hầu hết những mẫu&nbsp;<strong>xe máy điện</strong>&nbsp;Vespa đó đều thiết kế đèn tròn cực kỳ phổ thông.</p>\n<p>Bên dưới là cụm hai đèn xi nhan góp phần hoàn thiện mặt trước của xe, thiết kế cũng như kích thước khá nổi bật, trang bị dải Demi LED siêu sáng, phát tín hiệu an toàn, giúp người tham gia giao thông dễ dàng quan sát.</p>\n<p>Phần đuôi xe được thiết kế với bố cụ bắt mắt và hợp lý đến từng chi tiết, đèn hậu hình vuông đồng bộ giống phần đầu xe trong khi hai đèn xi nhan đối xứng hai bên tạo hình thức cân đối.</p>\n<h2><strong>CỐP XE VÀ SÀN ĐỂ CHÂN SIÊU RỘNG</strong></h2>\n<p>Cốp xe có thể tích khá lớn, giúp bạn có thể mang theo nhiều món đồ bên mình mỗi khi ra ngoài. Ví dụ như mũ bảo hiểm, áo mưa, túi ví,... Yên xe rộng và dài đủ cho hai người ngồi, lớp đệm êm ái cho cảm giác ngồi thư giãn, khoảng cách từ sàn để chân đến yên xe hợp lý cho tư thế ngồi chuẩn, ngồi lâu mà không bị mỏi. Đế để chân rộng giúp người lái ngồi tự tin và thoải mái hơn.</p>\n<h2><strong>ĐỘNG CƠ KHỎE MẠNH, KHÔNG NGẠI THỬ THÁCH</strong></h2>\n<p>Với sự mệnh bứt phá và dẫn đầu, mẫu xe Dibao Pansy SQ hoàn toàn không làm các bạn thất vọng. Được trang bị hệ thống động cơ mạnh mẽ loại 60V (5x12) 20Ah cho công suất động cơ đạt 1500W. Ứng dụng công nghệ hiện đại sạc nhanh và tiết kiệm năng lượng nên sau mỗi lần sạc đầy xe đi được 80km, vận tốc tối đa của xe đạt 55 km/h, nhanh hơn so với những mẫu xe điện và xe ga 50cc thông thường. Xe cũng được đánh giá cao về khả năng bứt tốc nhanh và mượt mà. Trọng tải của xe là 200kg, cho bạn vi vu khắp chốn cùng người thân và bạn bè.</p>\n<p>Về độ bền, độ ổn định của động cơ xe thì hãng&nbsp;<strong>xe điện Dibao</strong>&nbsp;chưa bao giờ làm khách hàng thất vọng. Luôn là hãng xe dẫn đầu xu hướng có chất lượng động cơ tốt nhất ở thị trường Việt Nam. Đặc biệt khả năng chống nước cũng thuộc top đầu hiện nay. Cam kết chạy xe điện Dibao bạn sẽ cực kỳ thích xe chạy êm, nhẹ nhàng, động cơ mượt khoẻ giúp bạn tha hồ chinh phục mọi nẻo đường.</p>\n<h2><strong>HỆ THỐNG AN TOÀN ĐÁNG TIN CẬY</strong></h2>\n<p>Cùng với hệ thống động cơ siêu khỏe, chiếc xe này cũng được trang bị thêm hệ thống đảm bảo an toàn cho người lái cực kỳ hiệu quả. Xe có vận tốc tối đa cao nên trang bị phanh kèm theo có thể giúp người lái yên tâm vững tay lái, với hệ thống phanh đĩa trước sau hoạt động nhịp nhàng và vô cùng nhạy bén. Thiết kế bánh xe là lốp không săm, có diện tích tiếp xúc mặt đường lớn tăng ma sát và độ bám đường, vận hành an toàn và chắc chắn hơn. Trọng tải lớn cũng giúp bảo vệ động cơ trong quá trình sử dụng lâu dài. Hệ thống giảm xóc là ống lồng, lò xo trụ đơn giảm chấn thủy lực hoạt động giúp xe chạy êm ái trên khắp nẻo đường.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-tesla-dio-e', 'Xe Máy Điện Dibao Tesla Dio E', 'dibao', '[\"xe-may-dien\"]', 17990000, 17990000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-6.webp\"]', '[]', '[]', '[]', '<p>Không phải chiếc xe nhanh nhất hay nhiều công nghệ nhất, nhưng Dibao Tesla Dio E lại là cái tên đang được nhiều người nhắc đến khi tìm xe điện đi phố. Điều gì khiến một mẫu xe không quá “ồn ào” lại dần trở thành lựa chọn phổ biến? Câu trả lời nằm ở cách Dibao hiểu người dùng – không chạy theo xu hướng, mà tập trung vào những gì thực sự cần thiết mỗi ngày.</p>\n<p>Trước đây, khi lựa chọn xe điện, nhiều người thường bị thu hút bởi những yếu tố dễ thấy như tốc độ tối đa, thiết kế bắt mắt hay các tính năng “nghe có vẻ hiện đại”. Tuy nhiên, sau một thời gian sử dụng, người dùng bắt đầu nhận ra rằng những yếu tố đó không phải lúc nào cũng mang lại giá trị thực tế.</p>', '<p>Không phải chiếc xe nhanh nhất hay nhiều công nghệ nhất, nhưng Dibao Tesla Dio E lại là cái tên đang được nhiều người nhắc đến khi tìm xe điện đi phố. Điều gì khiến một mẫu xe không quá “ồn ào” lại dần trở thành lựa chọn phổ biến? Câu trả lời nằm ở cách Dibao hiểu người dùng – không chạy theo xu hướng, mà tập trung vào những gì thực sự cần thiết mỗi ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thị trường thay đổi và người dùng ngày càng thực tế hơn</strong></h2>\n<p>Trước đây, khi lựa chọn <strong>xe điện</strong>, nhiều người thường bị thu hút bởi những yếu tố dễ thấy như tốc độ tối đa, thiết kế bắt mắt hay các tính năng “nghe có vẻ hiện đại”. Tuy nhiên, sau một thời gian sử dụng, người dùng bắt đầu nhận ra rằng những yếu tố đó không phải lúc nào cũng mang lại giá trị thực tế.</p>\n<p>Một chiếc xe chạy quá nhanh nhưng phanh không đủ tốt sẽ trở nên nguy hiểm. Một chiếc xe có nhiều tính năng nhưng ít khi dùng đến lại khiến chi phí tăng cao mà không cần thiết. Và một chiếc xe đẹp nhưng khó sử dụng hàng ngày cũng không thể trở thành lựa chọn lâu dài.</p>\n<p>Chính vì vậy, xu hướng hiện nay đang chuyển dần sang những mẫu xe có tính “cân bằng” – không cần quá nổi bật, nhưng phải đáp ứng tốt nhu cầu sử dụng hàng ngày.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-8.webp\" alt=\"xe điện dibao dio e\" loading=\"lazy\"></p>\n<p>Dibao Tesla Dio E xuất hiện đúng thời điểm này, khi người dùng bắt đầu tìm kiếm một chiếc xe “dễ sống chung” hơn là “gây ấn tượng ban đầu”.</p>\n<h2><strong>Không chạy theo tốc độ nhưng lại đúng với điều kiện đô thị</strong></h2>\n<p>Một trong những điểm đặc trưng của Dibao Tesla Dio E là mức tốc độ vận hành khoảng 45–55km/h. Nếu so với nhiều mẫu xe quảng cáo tốc độ cao, đây không phải là con số nổi bật. Nhưng khi đặt vào điều kiện giao thông tại Việt Nam, đặc biệt là các thành phố lớn, đây lại là mức tốc độ hợp lý.</p>\n<p>Đường phố đông đúc, nhiều phương tiện, nhiều tình huống bất ngờ – từ người đi bộ, xe máy đến ô tô – khiến việc chạy quá nhanh không những không giúp tiết kiệm thời gian mà còn tăng nguy cơ va chạm.</p>\n<p>Một chiếc xe có tốc độ vừa phải sẽ giúp người lái kiểm soát tốt hơn, phản ứng nhanh hơn và giảm thiểu rủi ro. Đây chính là yếu tố khiến nhiều người lựa chọn Dibao Tesla Dio E: không cần nhanh nhất, chỉ cần an toàn và dễ kiểm soát.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-dio-e-9.webp\" alt=\"xe điện dibao dio e\" loading=\"lazy\"></p>\n<h2><strong>Quãng đường phù hợp với thói quen sử dụng</strong></h2>\n<p>Một yếu tố khác khiến Dibao Tesla Dio E được ưa chuộng là khả năng di chuyển từ 60 đến 90km sau mỗi lần sạc. Đây là con số rất phù hợp với nhu cầu thực tế của người dùng tại Việt Nam. Phần lớn người dùng chỉ di chuyển trong nội thành, với quãng đường mỗi ngày khoảng 20–30km. Điều này có nghĩa là họ không cần <strong>sạc xe điện</strong> mỗi ngày.</p>\n<p>Việc có thể sử dụng xe trong 2–3 ngày mới cần sạc lại mang đến sự tiện lợi rõ rệt. Người dùng không bị “phụ thuộc” vào việc sạc pin, không phải lo lắng khi quên sạc, và có thể chủ động hơn trong lịch trình di chuyển.</p>\n<p>So với những mẫu xe quảng cáo quãng đường rất lớn nhưng không thực sự cần thiết, Dibao Tesla Dio E thể hiện rõ triết lý: <strong>đủ dùng mới là tối ưu</strong>.</p>\n<h2><strong>Trải nghiệm lái nhẹ nhàng phù hợp số đông</strong></h2>\n<p>Không phải ai cũng cần một chiếc xe mạnh mẽ hay tăng tốc nhanh. Đối với phần lớn người dùng, đặc biệt là học sinh, sinh viên hoặc người đi làm, điều quan trọng hơn là một chiếc xe <strong>dễ điều khiển, dễ làm quen và không gây áp lực khi sử dụng</strong>.</p>\n<p><strong>Dibao Tesla Dio E</strong> mang lại cảm giác lái khá “hiền”. Xe không giật, không quá bốc, phản hồi ga mượt và dễ kiểm soát. Điều này giúp người mới sử dụng nhanh chóng làm quen, đồng thời tạo cảm giác thoải mái khi di chuyển trong thời gian dài.</p>\n<p>Trong điều kiện giao thông đông đúc, việc điều khiển một chiếc xe dễ dùng giúp giảm căng thẳng đáng kể. Người lái không cần phải tập trung quá nhiều vào việc kiểm soát xe mà vẫn có thể di chuyển an toàn.</p>\n<h2><strong>Thiết kế hướng đến sự tiện dụng&nbsp;</strong><strong>lâu dài</strong></h2>\n<p>Dibao Tesla Dio E không lựa chọn thiết kế quá phá cách. Thay vào đó là phong cách trung hòa, dễ nhìn và phù hợp với nhiều đối tượng.</p>\n<p>Kiểu dáng gọn gàng giúp xe dễ dàng di chuyển trong các con phố nhỏ, quay đầu nhanh và tìm chỗ đỗ dễ dàng. Đây là những yếu tố tưởng chừng nhỏ nhưng lại ảnh hưởng rất lớn đến trải nghiệm sử dụng hàng ngày.</p>\n<p>Cụm đèn pha tròn kết hợp công nghệ LED không chỉ tạo điểm nhấn thẩm mỹ mà còn đảm bảo khả năng chiếu sáng tốt. Các chi tiết viền mạ crom giúp xe trông cao cấp hơn mà không cần quá cầu kỳ.</p>\n<p>Thiết kế này giúp xe không bị lỗi thời nhanh, đồng thời phù hợp với nhiều nhóm người dùng khác nhau.</p>\n<h2><strong>Hệ thống an toàn phù hợp với hiệu năng</strong></h2>\n<p>Một điểm quan trọng khiến Dibao Tesla Dio E được đánh giá cao là sự cân bằng giữa hiệu năng và hệ thống an toàn.</p>\n<p>Xe được trang bị phanh đĩa phía trước và phanh cơ phía sau – một cấu hình đủ tốt trong phân khúc. Khi kết hợp với mức tốc độ 45–55km/h, hệ thống này hoàn toàn đáp ứng nhu cầu sử dụng hàng ngày.</p>\n<p>Lốp không săm giúp tăng độ bám đường và giảm nguy cơ xịt lốp đột ngột. Hệ thống giảm xóc giúp xe vận hành êm ái hơn khi đi qua ổ gà hoặc đường xấu.</p>\n<p>Quan trọng hơn, toàn bộ hệ thống vận hành được thiết kế trong giới hạn an toàn. Xe không vượt quá khả năng kiểm soát của người lái, điều mà nhiều mẫu xe chạy quá nhanh thường gặp phải.</p>\n<h2><strong>Chi phí vận hành thấp – lợi thế lớn trong dài hạn</strong></h2>\n<p>Một trong những lý do khiến xe điện ngày càng phổ biến là chi phí vận hành thấp. Và Dibao Tesla Dio E tận dụng rất tốt lợi thế này.</p>\n<p>Người dùng không cần đổ xăng, chỉ cần sạc điện với chi phí thấp hơn rất nhiều. Điều này đặc biệt có ý nghĩa trong bối cảnh giá nhiên liệu thường xuyên biến động.</p>\n<p>Ngoài ra, xe vận hành ổn định giúp hạn chế hỏng vặt, từ đó giảm chi phí sửa chữa. Đây là lợi ích mà người dùng sẽ cảm nhận rõ sau một thời gian sử dụng.</p>\n<h2><strong>Hậu mãi và chế độ bảo hành giúp người dùng yên tâm sử dụng lâu dài</strong></h2>\n<p>Bên cạnh yếu tố vận hành và thiết kế, một trong những lý do quan trọng khiến Dibao Tesla Dio E được nhiều người lựa chọn chính là hệ thống hậu mãi và chế độ bảo hành rõ ràng, minh bạch. Trong thực tế, không ít người dùng e ngại khi mua xe điện bởi lo lắng về việc sửa chữa, thay thế linh kiện sau một thời gian sử dụng. Đây cũng là điểm mà Dibao tập trung cải thiện để tạo sự khác biệt trên thị trường.</p>\n<p>Dibao Tesla Dio E được áp dụng chính sách bảo hành lên đến 36 tháng, một khoảng thời gian đủ dài để người dùng yên tâm trải nghiệm và kiểm chứng chất lượng sản phẩm. Trong quá trình sử dụng, nếu phát sinh vấn đề kỹ thuật, người dùng có thể dễ dàng tiếp cận hệ thống hỗ trợ mà không phải lo lắng về chi phí sửa chữa quá cao trong giai đoạn đầu.</p>\n<p>Sự thành công của Dibao Tesla Dio E không đến từ việc nó là chiếc xe nhanh nhất hay nhiều công nghệ nhất. Thay vào đó, nó đến từ việc chiếc xe này hiểu đúng nhu cầu của người dùng. Trong một thị trường ngày càng cạnh tranh, nơi người tiêu dùng trở nên thông minh hơn, những sản phẩm thực dụng, dễ sử dụng và ổn định sẽ có lợi thế lớn hơn.</p>\n<p>Dibao Tesla Dio E là một mẫu xe như vậy. Không quá ồn ào, không quá nổi bật, nhưng lại đủ tốt để đồng hành mỗi ngày. Và đôi khi, chính sự “vừa đủ” đó lại là lý do khiến một chiếc xe được săn đón nhiều hơn bất kỳ lời quảng cáo nào.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-tesla-e-den-vuong', 'Xe Máy Điện Dibao Tesla E Đèn Vuông', 'dibao', '[\"xe-may-dien\"]', 17490000, 17490000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-6.webp\"]', '[]', '[]', '[]', '<p>Dibao Tesla Dio Đèn Vuông mang phong cách tối giản, hiện đại, khác biệt trong phân khúc xe máy điện, nổi bật với hình dáng cứng cáp cùng chi tiết đèn pha vuông vắn độc đáo. Mẫu xe này khẳng định gu thẩm mỹ mạnh mẽ, dứt khoát của người dùng. Tesla Dio Đèn Vuông mang đến sự kết hợp hoàn hảo giữa công nghệ điện tiên tiến và trải nghiệm lái xe an toàn, kiểm soát.</p>\n<p>Tesla Dio Đèn Vuông ngay lập tức tạo ấn tượng mạnh mẽ với ngôn ngữ thiết kế góc cạnh, gọn gàng, thoát ly khỏi những đường cong mềm mại thường thấy ở các dòng xe điện phổ thông. Ngoại hình xe mang tính hình học cao, tạo cảm giác hiện đại, cá tính và vô cùng mạnh mẽ, rất phù hợp với những người yêu thích sự đơn giản, dứt khoát.</p>', '<p><strong>Dibao Tesla Dio Đèn Vuông</strong>&nbsp;mang phong cách tối giản, hiện đại, khác biệt trong phân khúc xe máy điện, nổi bật với hình dáng cứng cáp cùng chi tiết đèn pha vuông vắn độc đáo. Mẫu xe này khẳng định gu thẩm mỹ mạnh mẽ, dứt khoát của người dùng. Tesla Dio Đèn Vuông mang đến sự kết hợp hoàn hảo giữa công nghệ điện tiên tiến và trải nghiệm lái xe an toàn, kiểm soát.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-7.webp\" alt=\"Xe Máy Điện Dibao Tesla Dio Đèn Vuông\" loading=\"lazy\"></p>\n<h2><br>Thiết kế hình học độc quyền</h2>\n<p><br><strong>Tesla Dio Đèn Vuông</strong>&nbsp;ngay lập tức tạo ấn tượng mạnh mẽ với ngôn ngữ thiết kế góc cạnh, gọn gàng, thoát ly khỏi những đường cong mềm mại thường thấy ở các dòng xe điện phổ thông. Ngoại hình xe mang tính hình học cao, tạo cảm giác hiện đại, cá tính và vô cùng mạnh mẽ, rất phù hợp với những người yêu thích sự đơn giản, dứt khoát.</p>\n<p><br>Điểm nhấn thị giác đắt giá nhất là cụm đèn pha LED hình vuông lớn, một chi tiết khác biệt hoàn toàn so với các đối thủ cùng phân khúc. Thiết kế đèn vuông này không chỉ mang lại nguồn sáng mạnh mẽ, tập trung, mà còn tạo nên nét đặc trưng riêng, giúp chiếc xe nổi bật và dễ nhận diện từ xa. Hệ thống chiếu sáng toàn bộ sử dụng công nghệ LED, đảm bảo độ bền và tiết kiệm điện năng.</p>\n<p>&nbsp;<img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-8.webp\" alt=\"Xe Máy Điện Dibao Tesla Dio Đèn Vuông\" loading=\"lazy\"></p>\n<p><br>Mặt đồng hồ hiển thị là màn hình điện tử LCD lớn, được thiết kế tối giản, cung cấp mọi thông số vận hành như vận tốc, quãng đường, và dung lượng pin một cách rõ ràng. Yên xe được thiết kế bè ra, tạo cảm giác ngồi vững chãi, thoải mái. Sự kết hợp giữa các chi tiết vuông vắn và vật liệu nhựa ABS bền bỉ đã tạo nên một tổng thể vững chắc, thu hút.</p>\n<h2><br><strong>Đối tượng người dùng tiềm năng</strong></h2>\n<p><br>Đối tượng khách hàng của <strong>Tesla Dio Đèn Vuông</strong> là nhóm người trẻ tuổi, không chỉ giới hạn ở học sinh cấp 3, mà còn mở rộng sang sinh viên và người đi làm trong độ tuổi từ 18 đến 30, đặc biệt là những người chưa có hoặc không cần bằng lái A1. Họ là những người có phong cách sống độc lập, ưa chuộng sự tối giản và muốn thể hiện cá tính riêng biệt qua phương tiện di chuyển.</p>\n<p><br>Chiếc xe này hấp dẫn những người tìm kiếm sự khác biệt, không muốn chiếc xe của mình bị hòa lẫn vào đám đông xe ga có thiết kế bo tròn. Yếu tố thiết kế đèn vuông táo bạo đáp ứng nhu cầu thể hiện gu thẩm mỹ mạnh mẽ, vượt ra ngoài khuôn khổ truyền thống.</p>\n<p>&nbsp;<img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-e-den-vuong-9.webp\" alt=\"Xe Máy Điện Dibao Tesla Dio Đèn Vuông\" loading=\"lazy\"></p>\n<p><br><strong>Dibao Tesla Dio</strong> cũng là lựa chọn thông minh cho những người làm việc trong môi trường sáng tạo, đòi hỏi sự linh hoạt cao trong di chuyển nội đô, như các nhà thiết kế, lập trình viên hay các chuyên gia marketing trẻ, những người đánh giá cao sự tiện nghi của <strong>xe máy điện</strong> nhưng không muốn mất đi phong cách cá nhân.</p>\n<h2><br><strong>Lực đẩy điện năng dồi dào</strong></h2>\n<p><br>Tesla Dio Đèn Vuông được trang bị khối động cơ điện không chổi than BLDC có công suất định mức mạnh mẽ, thường nằm trong khoảng 1500W - 1800W. Mức công suất này đảm bảo xe có khả năng tăng tốc nhanh, dứt khoát và duy trì tốc độ ổn định, dễ dàng vượt qua các đoạn dốc và cầu vượt mà không gặp khó khăn.</p>\n<p><br>Động cơ BLDC mang lại ưu thế lớn về sự yên tĩnh tuyệt đối, xe vận hành gần như không phát ra tiếng ồn. Điều này tạo ra một không gian di chuyển thư thái, giúp người lái tận hưởng sự tĩnh lặng, tách biệt khỏi sự ồn ào của phố thị. Khả năng vận hành êm ái là một yếu tố quan trọng, nâng cao trải nghiệm lái xe hàng ngày.</p>\n<p><br>Vận tốc tối đa của xe thường đạt khoảng 50 - 55 km/h. Tốc độ này đáp ứng hoàn hảo nhu cầu di chuyển nhanh chóng trong thành phố. Khối động cơ được Dibao tối ưu hóa về hiệu suất, đảm bảo sự bền bỉ và tiết kiệm năng lượng điện tối đa.</p>\n<h2><br><strong>Kiến tạo hệ thống phanh hoàn hảo</strong></h2>\n<p><br>Khác biệt với cấu hình phanh phổ thông, <strong>Tesla Dio Đèn Vuông</strong> được Dibao trang bị một hệ thống phanh hiệu suất cao, được thiết kế để mang lại khả năng kiểm soát tốc độ tối ưu. Xe sử dụng phanh đĩa thủy lực cho cả hai bánh trước và sau. Sự hiện diện của phanh đĩa kép là cam kết về khả năng giảm tốc an toàn và chính xác.</p>\n<p><br>Phanh đĩa thủy lực hoạt động dựa trên áp suất chất lỏng, cung cấp lực hãm mạnh mẽ, nhạy bén và độ chính xác vượt trội hơn hẳn so với phanh cơ. Công nghệ này cho phép người lái kiểm soát lực phanh một cách tinh tế, giảm thiểu quãng đường phanh một cách đáng kể.</p>\n<p><br>Hệ thống phanh này mang lại lợi thế kiểm soát lớn trong các tình huống khẩn cấp, đặc biệt khi di chuyển trong điều kiện trời mưa hoặc đường trơn trượt. Việc lắp đặt phanh đĩa ở cả hai bánh xe đảm bảo sự phân bổ lực phanh đồng đều, giúp chiếc xe không bị trượt hoặc mất kiểm soát khi phanh gấp.</p>\n<h2><br><strong>Khoảng cách dịch chuyển thực tế</strong></h2>\n<p><br><strong>Tesla Dio Đèn Vuông</strong> thường được trang bị hệ thống ắc quy chì-axit (thường là 5 bình 20Ah) với dung lượng điện năng lớn, là nền tảng vững chắc cho khả năng di chuyển xa. Hệ thống ắc quy chất lượng cao này đảm bảo sự ổn định và bền bỉ trong quá trình sử dụng.</p>\n<p><br>Nhờ sự cân bằng lý tưởng giữa hiệu suất động cơ và dung lượng ắc quy, Dibao Tesla Dio có thể đạt quãng đường di chuyển ấn tượng từ 80km đến 100km cho mỗi lần sạc đầy (tùy thuộc vào điều kiện vận hành). Quãng đường rộng rãi này mang lại sự tự chủ tuyệt đối cho người dùng, giúp họ thoải mái hoạch định những chuyến đi dài hơn.</p>\n<p><br>Thời gian để nạp đầy năng lượng cho bộ ắc quy thường mất khoảng 8 – 10 tiếng. Xe được trang bị bộ sạc thông minh với cơ chế tự ngắt điện khi pin đầy, một tính năng bảo vệ thiết yếu giúp kéo dài tuổi thọ của ắc quy và đảm bảo sự an toàn điện.</p>\n<h2><br><strong>Tiện ích và tính đa năng</strong></h2>\n<p><br><strong>Xe máy điện Dibao Tesla Dio</strong> được trang bị những tiện ích thiết thực, nâng cao tối đa trải nghiệm người dùng đô thị. Khoang chứa đồ dưới yên xe có dung tích lớn, một ưu điểm đáng giá, đủ sức chứa hai mũ bảo hiểm nửa đầu và nhiều vật dụng cá nhân khác, giải quyết tốt nhu cầu mang vác đồ đạc hàng ngày.</p>\n<p><br>Xe thường được trang bị hệ thống Smartkey (tùy phiên bản), một tính năng chống trộm hiệu quả và mang lại sự tiện lợi vượt trội. Smartkey tích hợp các chức năng như khởi động không cần chìa và báo động chống trộm từ xa, giúp tăng cường bảo mật cho chiếc xe.</p>\n<p><br>Ngoài ra, sàn để chân của xe rộng rãi, xe còn được trang bị hộc chứa đồ nhỏ gọn ở phía trước yếm xe và cổng sạc USB (tùy phiên bản), rất tiện lợi để cất giữ và sạc lại điện thoại khi đang di chuyển.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-tesla-sd-phanh-dia-2022', 'XE MÁY ĐIỆN DIBAO TESLA SD PHANH ĐĨA 2022', 'dibao', '[\"xe-may-dien\"]', 17390000, 17390000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Dibao Tesla SD với kiểu dáng sành điệu và sang chảnh đang được nhiều bạn trẻ yêu thích. Thuộc phân khúc xe máy điện cao cấp của Dibao, mẫu xe này sở hữu nhiều ưu điểm về thiết kế, độ an toàn, vận hành,...Những bạn trẻ chưa đuổi tuổi đi xe máy nhưng cần một phương tiện đi lại nhanh, dễ sử dụng và thời trang sẽ thích phiên bản này. Dự báo đây sẽ là mẫu xe máy điện làm mưa làm gió thị trường trong năm nay.</p>\n<p>Xe máy điện Dibao Tesla SD có kích cỡ 1.750mm x 710mm x 1.110mm với tải trọng 130kg. Nhiều người nhận xét rằng xe máy điện Dibao Tesla SD có thiết kế tinh tế, vừa cổ điển vừa hiện đại.</p>', '<p><strong>Xe máy điện Dibao Tesla SD</strong>&nbsp;với kiểu dáng sành điệu và sang chảnh đang được nhiều bạn trẻ yêu thích. Thuộc phân khúc xe máy điện cao cấp của Dibao, mẫu xe này sở hữu nhiều ưu điểm về thiết kế, độ an toàn, vận hành,...Những bạn trẻ chưa đuổi tuổi đi xe máy nhưng cần một phương tiện đi lại nhanh, dễ sử dụng và thời trang sẽ thích phiên bản này. Dự báo đây sẽ là mẫu xe máy điện làm mưa làm gió thị trường trong năm nay.&nbsp;</p>\n<h2><strong>Thiết kế trẻ trung và hấp dẫn&nbsp;</strong></h2>\n<p><strong>Xe máy điện Dibao Tesla SD</strong>&nbsp;có kích cỡ 1.750mm x 710mm x 1.110mm với tải trọng 130kg. Nhiều người nhận xét rằng xe máy điện Dibao Tesla SD có thiết kế tinh tế, vừa cổ điển vừa hiện đại.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-7.webp\" alt=\"Xe máy điện Dibao Tesla SD thiết kế trẻ trung\" loading=\"lazy\"><br></p>\n<p><em>Xe máy điện Dibao Tesla SD thiết kế trẻ trung</em></p>\n<p>Mẫu này có thiết kế khiến bạn liên tưởng đến phiên bản Tesla S đã ra mắt trước đó. Phần đầu xe tạo điểm nhấn nhờ kiểu dáng khá giống mẫu Vespa đắt đỏ. Đèn pha và đèn xi nhan có thiết kế hiện đại và hút mắt.&nbsp;</p>\n<h2><strong>Đèn LED siêu đẹp, ánh sáng dịu mắt</strong></h2>\n<p>Dibao Tesla SD được trang bị cụm đèn LED siêu đẹp theo phong cách trẻ trung và hiện đại. Ánh sáng đèn dịu mắt và góc sáng rộng. Đây là điểm cộng lớn, bạn có thể yên tâm chạy xe vào những hôm thời tiết xấu hoặc điều kiện ánh sáng kém. Cụm đồng hồ của xe được thiết kế với những đường vuốt nhẹ nhàng, bạn có thể quan sát các thông số về vận tốc, quãng đường, pin,... một cách đơn giản.&nbsp;</p>\n<h2><strong>Yên cỡ lớn, cốp rộng rãi</strong></h2>\n<p>Yên xe cỡ lớn với chất liệu da cao cấp, vừa vặn hai người lớn ngồi rất thoải mái.&nbsp;<strong>Dibao</strong>&nbsp;đã đầu tư loại da cao cấp cho Dibao Tesla SD, dù chạy đường dài thì người lái xe và người ngồi sau vẫn cảm thấy êm ái suốt chặng đường. Bên cạnh đó, cốp xe siêu rộng, bạn có thể chứa những đồ vặt cá nhân như: mũ bảo hiểm, túi, ví tiền,...Sàn để chân không quá rộng nhưng bạn vẫn có thể chở đồ. Người lái xe có thể co duỗi chân thoải mái.&nbsp;</p>\n<h2><strong>Động cơ khỏe, tăng tốc nhanh</strong></h2>\n<p>Nếu bạn đang tìm kiếm một mẫu xe máy điện có khả năng vận hành tốt với khả năng tăng tốc nhanh thì không nên bỏ qua Dibao Tesla SD. Phiên bản này sử dụng động cơ điện công suất 1.460W, Ắc quy 60V (5x12V) 21.6Ah. Bạn có thể tăng tốc nhanh và cực êm khi lái Dibao Tesla SD, vận tốc tối đa là 55km.&nbsp;</p>\n<p>Một điểm cộng cực lớn của Dibao Tesla SD chính là khả năng tiết kiệm nhiên liệu, bạn có thể chạy xe khoảng 90km với mỗi lần sạc. Thời gian để sạc đầy là 12 tiếng.&nbsp;</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-8.webp\" alt=\"Xe máy điện Dibao Tesla SD\" loading=\"lazy\"><br></p>\n<p><em>Động cơ khỏe, tăng tốc nhanh</em></p>\n<p>Hệ thống an toàn được trang bị đầy đủ. Vì xe máy điện Dibao Tesla SD là dòng xe hướng đến đối tượng là những bạn trẻ, học sinh, sinh viên, giáo viên,... nên hệ thống an toàn là yếu tố được quan tâm hàng đầu. Xe máy điện Dibao Tesla SD được trang bị lốp không săm 90/90 - 10 với độ bám đường cao, đảm bảo an toàn khi di chuyển ở những khu vực có điều kiện địa hình xấu. Ngoài ra, xe được trang bị đầy đủ phanh đĩa trước và phanh đĩa sau. Những bậc phụ huynh có thể an tâm khi con em mình sử dụng Dibao Tesla SD đến trường.&nbsp;</p>\n<h2><strong>Giá rẻ, nhiều khuyến mại</strong></h2>\n<p>Hiện nay trên thị trường có vô số hãng bán xe đạp điện,&nbsp;<strong>xe máy điện</strong>. Mỗi thương hiệu lại có những dòng xe với các đặc trưng riêng. Dibao là một trong những thương hiệu lâu đời chuyên phân phối xe điện giá rẻ. Dibao có rất nhiều loại xe máy điện và xe máy xăng khác nhau, mỗi dòng xe lại có những ưu điểm riêng. Mẫu xe đang nhận được khá nhiều sự quan tâm gần đây chính là xe máy điện Dibao Tesla SD - kiểu dáng như những chiếc Vespa Ý thời thượng.&nbsp;</p>\n<p><em><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dibao-tesla-sd-phanh-dia-2022-9.webp\" alt=\"Xe máy điện Dibao Tesla SD\" loading=\"lazy\"></em></p>\n<p><em>Giá rẻ, nhiều khuyến mại</em></p>\n<p>Phiên bản xe máy điện Dibao Tesla SD của Dibao hiện đang có giá dưới 20 triệu. So với những chiếc xe điện cùng chức năng và trang bị về động cơ tương tự thì Dibao Tesla SD thực sự đáng đồng tiền bát gạo.&nbsp;</p>\n<p>Những bạn trẻ yêu thích xe máy điện thời trang với thiết kế sang chảnh chắc chắn sẽ không muốn bỏ lỡ Tesla SD. Để mua xe, bạn hãy chọn những đại lý chính thức của Dibao. Không nên mua xe tại những cơ sở không có tên tuổi và không có giấy tờ kiểm định xuất xứ và nguồn gốc của xe.&nbsp;</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dibao-xman-neo', 'Xe Máy Điện Dibao Xman Neo', 'dibao', '[\"xe-may-dien\"]', 15490000, 15490000, '/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-dibao-xman-neo-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-crea-mono', 'Xe Máy Điện DK Crea Mono', 'dk', '[\"xe-may-dien\"]', 15990000, 15990000, '/sites/yenthoa/img/sp/xe-may-dien-dk-crea-mono-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-crea-mono-1.webp\"]', '[]', '[]', '[]', '', '<h2><strong>Xe Máy Điện DK Crea Mono</strong></h2>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-gogo-super', 'Xe Máy Điện DK GoGo Super', 'dk', '[\"xe-may-dien\"]', 18500000, 18500000, '/sites/yenthoa/img/sp/xe-may-dien-dk-gogo-super-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-gogo-super-1.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-lyva-moda-chay-90km-lan-sac', 'Xe Máy Điện DK Lyva Moda (Chạy: 90km/ lần sạc)', 'dk', '[\"xe-may-dien\"]', 16500000, 16500000, '/sites/yenthoa/img/sp/xe-may-dien-dk-lyva-moda-chay-90km-lan-sac-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-lyva-moda-chay-90km-lan-sac-1.webp\"]', '[]', '[]', '[]', '<p>DK Lyva Moda là một mẫu xe máy điện được thiết kế nhằm tôn vinh sự thanh lịch, sang trọng trong phong cách di chuyển đô thị, mang đậm cảm hứng từ những chiếc scooter cổ điển Châu Âu. Chiếc xe này được chăm chút tỉ mỉ từ lớp sơn ngoài cho đến từng chi tiết công nghệ tích hợp. Lyva Moda là sự lựa chọn hoàn hảo cho những người dùng đề cao vẻ ngoài duyên dáng, tinh tế mà vẫn yêu cầu hiệu suất điện năng ổn định.</p>\n<p>Lyva Moda sở hữu phom dáng tròn trịa, bầu bĩnh đặc trưng của dòng scooter cổ điển, nhưng được tinh chỉnh với các đường nét dứt khoát và hiện đại hơn. Sự kết hợp giữa nét hoài cổ và xu hướng thiết kế mới tạo nên một tổng thể hài hòa, không bị lỗi thời theo thời gian. Màu sắc xe thường được lựa chọn theo tông pastel hoặc các màu sơn bóng cao cấp, tăng thêm vẻ sang trọng.</p>', '<p><strong>DK Lyva Moda</strong> là một mẫu <strong>xe máy điện</strong> được thiết kế nhằm tôn vinh sự thanh lịch, sang trọng trong phong cách di chuyển đô thị, mang đậm cảm hứng từ những chiếc scooter cổ điển Châu Âu. Chiếc xe này được chăm chút tỉ mỉ từ lớp sơn ngoài cho đến từng chi tiết công nghệ tích hợp. Lyva Moda là sự lựa chọn hoàn hảo cho những người dùng đề cao vẻ ngoài duyên dáng, tinh tế mà vẫn yêu cầu hiệu suất điện năng ổn định.</p>\n\n<h2><br><strong>Phom dáng \"tân cổ giao duyên\"</strong></h2>\n<p><br><strong>Lyva Moda</strong> sở hữu phom dáng tròn trịa, bầu bĩnh đặc trưng của dòng scooter cổ điển, nhưng được tinh chỉnh với các đường nét dứt khoát và hiện đại hơn. Sự kết hợp giữa nét hoài cổ và xu hướng thiết kế mới tạo nên một tổng thể hài hòa, không bị lỗi thời theo thời gian. Màu sắc xe thường được lựa chọn theo tông pastel hoặc các màu sơn bóng cao cấp, tăng thêm vẻ sang trọng.</p>\n<p><br>Tâm điểm của phần đầu xe là cụm đèn pha LED lớn, hình tròn hoặc oval, được bao quanh bởi viền mạ chrome sáng bóng, tạo điểm nhấn lấp lánh và nổi bật. Toàn bộ hệ thống chiếu sáng sử dụng công nghệ LED tiên tiến, cung cấp nguồn sáng mạnh mẽ, rõ nét, đồng thời tối thiểu hóa mức tiêu thụ điện năng.</p>\n\n<p><br>Mặt đồng hồ hiển thị của Lyva Moda là một màn hình LCD kỹ thuật số lớn, cung cấp đầy đủ thông số vận hành như vận tốc, quãng đường đã đi, và đặc biệt là dung lượng pin còn lại được hiển thị một cách trực quan, dễ dàng quan sát ngay cả dưới ánh nắng gắt. Giao diện này mang lại cảm giác hiện đại, dễ dàng kiểm soát mọi trạng thái của chiếc xe.</p>\n<h2><br><strong>Đơn vị truyền tải mô-men</strong></h2>\n<p><br><strong>DK Lyva Moda</strong> được trang bị khối động cơ điện BLDC có công suất định mức được tối ưu hóa cho môi trường đô thị, thường nằm trong khoảng 1000W - 1200W. Động cơ này được lắp đặt ở bánh sau, đảm bảo sự truyền tải lực trực tiếp và hiệu suất cao.</p>\n<p><br>Điểm mạnh của động cơ này là khả năng sản sinh mô-men xoắn tức thời ổn định, giúp xe có khả năng tăng tốc mượt mà, không bị giật. Sự êm ái, gần như không tiếng ồn khi vận hành là một ưu thế vượt trội của xe điện, tạo ra trải nghiệm di chuyển thư thái, ít gây ô nhiễm tiếng ồn.</p>\n\n<p><br>Vận tốc tối đa của<strong> Lyva Moda</strong> thường được giới hạn ở ngưỡng 45 – 50 km/h. Tốc độ này được thiết lập để đảm bảo sự cân bằng giữa tính linh hoạt và sự an toàn khi di chuyển trong khu vực thành phố, đáp ứng tốt nhu cầu đi lại hàng ngày.</p>\n<h2><br><strong>Kiến trúc ắc quy tiếp cận</strong></h2>\n<p><br><strong>Lyva Moda</strong> thường sử dụng hệ thống ắc quy chì-axit (thường là 5 bình 20Ah) được bố trí gọn gàng, kín đáo bên dưới sàn để chân hoặc dưới yên xe. Vị trí đặt ắc quy được tính toán để giữ trọng tâm xe ở mức thấp, góp phần tăng cường sự ổn định khi vào cua hoặc phanh gấp.</p>\n<p><br>Với kiến trúc pin tối ưu, chiếc xe này có khả năng đạt được quãng đạo hành trình đáng tin cậy, thường dao động từ 60km đến 80km cho mỗi lần nạp đầy. Quãng đường này là đủ để đáp ứng nhu cầu di chuyển hàng ngày, đi học hoặc đi làm trong phạm vi thành phố.</p>\n<p><br>Thời gian để nạp đầy năng lượng cho bộ ắc quy thường mất khoảng 6 – 8 tiếng. Xe được trang bị bộ sạc thông minh với cơ chế ngắt điện tự động, giúp bảo vệ tuổi thọ của ắc quy và đảm bảo an toàn điện.</p>\n<h2><br><strong>Hệ thống hãm tốc cân bằng</strong></h2>\n<p><br>Để đảm bảo an toàn tuyệt đối trong mọi tình huống, <strong>xe điện DK Bike</strong> <strong>Lyva Moda</strong> áp dụng một hệ thống hãm tốc cân bằng, sử dụng phanh đĩa cho bánh trước và phanh tang trống (phanh cơ) cho bánh sau. Sự kết hợp này mang lại khả năng kiểm soát tốc độ chính xác và ổn định.</p>\n<p><br>Phanh đĩa phía trước cung cấp lực triệt tiêu nhạy bén, có độ phản hồi cao, đóng vai trò chủ đạo trong việc giảm tốc và dừng xe an toàn. Hệ thống thủy lực của phanh đĩa đảm bảo sự truyền lực hiệu quả, giảm thiểu quãng đường phanh cần thiết.</p>\n<p><br>Phanh tang trống phía sau mang lại sự bổ trợ lực hãm, đồng thời có ưu điểm về độ bền bỉ và dễ bảo trì. Sự phối hợp giữa hai loại phanh này giúp xe duy trì sự ổn định thân xe khi phanh đồng thời, giảm thiểu nguy cơ trượt bánh, đặc biệt là khi đường ướt.</p>\n<h2><br><strong>Tiện nghi phụ trợ thông minh</strong></h2>\n<p><br><strong>Lyva Moda</strong> được tích hợp các tiện ích thông minh, phục vụ tối đa trải nghiệm người dùng hiện đại. Xe được trang bị khóa điện tử đa chức năng hoặc hệ thống khóa thông minh Smartkey (tùy phiên bản), tích hợp các tính năng bảo mật cao như báo động chống trộm và khởi động không cần chìa.</p>\n<p><br>Khoang chứa đồ dưới yên xe có dung tích lớn, là một ưu điểm nổi bật của dòng xe ga điện, đủ sức chứa mũ bảo hiểm và nhiều vật dụng cá nhân. Sự rộng rãi này giúp giải quyết nhu cầu mang vác đồ đạc hàng ngày một cách tiện lợi.</p>\n<p><br>Đặc biệt, xe được trang bị cổng sạc USB (thường nằm trong hộc chứa đồ phía trước) để người dùng có thể nạp lại pin điện thoại hoặc các thiết bị ngoại vi khi đang di chuyển. Sự tiện ích này là một chi tiết nhỏ nhưng vô cùng hữu dụng trong cuộc sống kết nối.</p>\n<h2><br><strong>Cảm quan hệ thống treo êm ái</strong></h2>\n<p><br>Hệ thống treo của <strong>Lyva Moda</strong> được tinh chỉnh để mang lại cảm giác lái êm ái, nhẹ nhàng, phù hợp với phong cách xe ga đô thị. Xe được trang bị phuộc ống lồng thủy lực phía trước và cặp giảm xóc lò xo trụ giảm chấn thủy lực phía sau.</p>\n<p><br>Phuộc trước được thiết kế để hấp thụ hiệu quả các rung động từ mặt đường, đảm bảo tay lái luôn vững vàng. Hệ thống treo sau hoạt động mượt mà, giúp xe lướt nhẹ nhàng qua các đoạn đường gồ ghề, không gây ra cảm giác xóc nảy khó chịu cho người ngồi trên xe.</p>\n<p><br>Xe sử dụng bộ vành đúc thẩm mỹ, đồng thời góp phần tăng độ cứng vững của bánh xe, giúp xe bám đường tốt và ổn định hơn khi vào cua. Lốp không săm là một yếu tố an toàn quan trọng, giảm thiểu rủi ro khi cán phải vật nhọn.</p>\n<p><br><strong>DK Lyva Moda</strong> là sự lựa chọn hoàn hảo cho những ai tìm kiếm một phương tiện điện năng có sự kết hợp tinh tế giữa thời trang và công nghệ. Với thiết kế duyên dáng, động cơ ổn định, và hệ thống tiện ích thông minh, chiếc xe này nâng tầm trải nghiệm di chuyển hàng ngày. Mẫu <strong>xe máy điện</strong> khẳng định cá tính của người sở hữu, đồng thời đảm bảo sự an toàn và hiệu suất năng lượng vượt trội trong môi trường đô thị.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-roma-doi-moi', 'Xe Máy Điện Dk Roma Đời Mới', 'dk', '[\"xe-may-dien\"]', 21690000, 21690000, '/sites/yenthoa/img/sp/xe-may-dien-dk-roma-doi-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-doi-moi-1.webp\"]', '[]', '[]', '[]', '<p>Phiên bản mới nhất của DK Roma là sự tái hiện hoàn hảo của phong cách Ý lãng mạn trên nền tảng công nghệ điện. Chiếc xe này định hình cho phân khúc người dùng yêu thích sự thanh lịch, đòi hỏi cao về chất lượng và hiệu năng bền bỉ. Kiểu dáng cổ điển kết hợp cấu hình mạnh mẽ giúp xe khẳng định vị thế như một lựa chọn đẳng cấp. Xe dễ dàng chinh phục mọi cung đường đô thị với sự êm ái tuyệt đối.</p>\n<p>DK Roma new được trang bị động cơ điện công suất 1500W, một con số vượt trội so với các mẫu xe cùng phân khúc. Mức công suất này đảm bảo xe có khả năng vận hành mạnh mẽ, tăng tốc nhanh chóng và duy trì sự ổn định ngay cả khi leo dốc hoặc chở tải tối đa. Việc sử dụng động cơ được tinh chỉnh cho phép xe đạt tốc độ tối đa ấn tượng, dao động từ 55 đến 60 km/h.</p>', '<p>Phiên bản mới nhất của <strong>DK Roma</strong> là sự tái hiện hoàn hảo của phong cách Ý lãng mạn trên nền tảng công nghệ điện. Chiếc xe này định hình cho phân khúc người dùng yêu thích sự thanh lịch, đòi hỏi cao về chất lượng và hiệu năng bền bỉ. Kiểu dáng cổ điển kết hợp cấu hình mạnh mẽ giúp xe khẳng định vị thế như một lựa chọn đẳng cấp. Xe dễ dàng chinh phục mọi cung đường đô thị với sự êm ái tuyệt đối.</p>\n\n<h2><br><strong>Trái tim điện tử: Động cơ và công suất</strong></h2>\n<p><br><strong>DK Roma new</strong> được trang bị động cơ điện công suất 1500W, một con số vượt trội so với các mẫu xe cùng phân khúc. Mức công suất này đảm bảo xe có khả năng vận hành mạnh mẽ, tăng tốc nhanh chóng và duy trì sự ổn định ngay cả khi leo dốc hoặc chở tải tối đa. Việc sử dụng động cơ được tinh chỉnh cho phép xe đạt tốc độ tối đa ấn tượng, dao động từ 55 đến 60 km/h.</p>\n<p><br>Mức tốc độ 55-60 km/h giúp Roma new vượt qua giới hạn của một chiếc xe máy điện thông thường, tiến gần hơn đến hiệu suất của xe ga chạy xăng. Điều này mang lại sự linh hoạt cao cho người dùng, cho phép xe di chuyển thông suốt cùng dòng xe cơ giới khác mà không gây cản trở. Khả năng vận hành mượt mà, không tiếng ồn là ưu điểm nổi trội của công nghệ điện.</p>\n\n<p><br>Xe được thiết kế để chịu tải trọng tối đa lên đến 160 kg. Khả năng chịu tải cao này thể hiện sự vững chắc của khung gầm và sức kéo bền bỉ của động cơ 1500W. Dù chở hai người lớn, xe vẫn duy trì được hiệu suất ổn định và tốc độ tối ưu, khẳng định độ bền bỉ và tính đa dụng của một phương tiện di chuyển cao cấp.</p>\n<h2><br><strong>Hệ thống năng lượng: Ắc quy và phạm vi</strong></h2>\n<p><br>Nguồn năng lượng cấp cho động cơ 1500W là hệ thống ắc quy chì axit dạng kín khí, bao gồm 5 bình 12V20Ah, tạo thành bộ nguồn 60V/20A. Cấu hình này là sự lựa chọn tối ưu về mặt kinh tế và hiệu suất, cung cấp điện năng ổn định cho các chuyến đi dài hàng ngày.</p>\n<p><br>Với bộ ắc quy này, <strong>xe điện DK Roma</strong> có khả năng di chuyển quãng đường lên đến 80 km cho mỗi lần sạc đầy, trong điều kiện tiêu chuẩn. Quãng đường này là một lợi thế lớn, giúp người dùng không cần bận tâm quá nhiều về việc sạc pin thường xuyên. Phạm vi 80 km là hoàn toàn đáp ứng được nhu cầu di chuyển nội đô, thậm chí là các chuyến đi ngắn ngoại thành.</p>\n\n<p><br>Quá trình sạc điện diễn ra trong khoảng 8 đến 10 giờ, sử dụng dòng sạc 60V/20A với dòng sạc 2.8-3A. Tính năng tự động ngắt khi ắc quy đầy là trang bị thiết yếu, giúp bảo vệ ắc quy khỏi tình trạng quá tải, kéo dài tuổi thọ sử dụng và mang lại sự tiện lợi khi người dùng có thể cắm sạc qua đêm. Ắc quy cũng được hưởng chính sách bảo hành ưu đãi lên tới 18 tháng.</p>\n<h2><br><strong>Cơ cấu hãm tốc: Phanh đĩa kép</strong></h2>\n<p><br>Một trong những cải tiến đáng giá nhất của <strong>Roma</strong> là việc nâng cấp hệ thống phanh lên cấu hình phanh đĩa kép, được áp dụng cho cả bánh trước và bánh sau. Phanh trước sử dụng phanh đĩa kết hợp đầu dầu thủy lực, cung cấp lực phanh mạnh mẽ, chính xác và độ nhạy vượt trội.</p>\n<p><br>Phanh sau cũng được trang bị phanh đĩa 1 piston. Việc sử dụng phanh đĩa cho bánh sau giúp tối ưu hóa khả năng kiểm soát tốc độ tổng thể của xe, đặc biệt quan trọng khi xe đạt vận tốc 60 km/h. Hệ thống phanh đĩa kép này mang lại hiệu suất dừng xe vượt trội, rút ngắn quãng đường phanh và đảm bảo an toàn tuyệt đối cho người điều khiển.</p>\n<p><br>Sự kết hợp của phanh đĩa trước và sau tạo nên một hệ thống kiểm soát tốc độ cân bằng và đáng tin cậy. Khi cần giảm tốc đột ngột, lực phanh được phân bổ đều, giúp xe không bị trượt hay mất lái. Cấu hình phanh đĩa kép là minh chứng cho việc nhà sản xuất đã chú trọng đầu tư vào yếu tố an toàn, đặt sự yên tâm của người dùng lên hàng đầu.</p>\n<h2><br><strong>Hình học ngoại quan: Vóc dáng thanh thoát</strong></h2>\n<p><br><strong>DK Roma</strong> sở hữu kích thước tổng thể (dài x rộng x cao) là 1720 mm x 700 mm x 1000 mm. Các thông số này tạo ra một vóc dáng nhỏ gọn nhưng vẫn giữ được sự thanh thoát, phù hợp với phong cách tay ga cổ điển. Kích thước này tối ưu hóa cho việc di chuyển trong các con phố nhỏ và không gian đô thị chật hẹp.</p>\n<p><br>Chiều cao yên xe được thiết lập ở mức 750 mm. Đây là một con số thân thiện, cho phép người dùng với vóc dáng trung bình hoặc hơi khiêm tốn đều có thể dễ dàng chống chân và làm chủ chiếc xe. Chiều cao yên hợp lý này góp phần tạo nên sự thoải mái và tự tin cho người điều khiển, đặc biệt khi dừng xe giữa dòng người.</p>\n<p><br>Trọng lượng xe khi không có ắc quy là 55 kg, và khi lắp ắc quy là 90 kg. Trọng lượng nhẹ giúp xe trở nên linh hoạt và dễ dàng dắt, quay đầu. Tổng thể hình học của Roma 2024 là sự cân bằng giữa sự nhẹ nhàng cần thiết cho một chiếc xe điện và sự đầm chắc, vững vàng cần có khi vận hành ở tốc độ cao.</p>\n<h2><br><strong>Đảm bảo tiếp xúc: Lốp vành cao cấp</strong></h2>\n<p><br>Xe được trang bị vành hợp kim đúc, với kích thước vành trước và vành sau đồng nhất là MT 2.15x10 inch. Vành hợp kim đúc không chỉ tăng tính thẩm mỹ, mà còn cung cấp độ cứng và độ bền vượt trội so với vành nan hoa, giúp xe chịu lực tốt hơn và giảm thiểu biến dạng khi gặp va chạm.</p>\n<p><br>Bộ lốp của xe là lốp KENDA 3.00-10, thuộc loại lốp không săm. KENDA là thương hiệu lốp xe nổi tiếng, đảm bảo chất lượng và độ bám đường cao. Lốp không săm là một trang bị an toàn hiện đại, giúp giảm thiểu rủi ro xẹp lốp đột ngột và cho phép người lái có thể tiếp tục di chuyển quãng ngắn để tìm nơi vá lốp.</p>\n<p><br>Lốp KENDA 3.00-10 có độ rộng hợp lý, kết hợp với các rãnh gai được thiết kế tối ưu, giúp xe bám đường hiệu quả. Khả năng bám đường tốt là yếu tố quan trọng, đặc biệt khi kết hợp với hệ thống phanh đĩa kép, đảm bảo xe vận hành ổn định, an toàn trên cả mặt đường khô và ướt.</p>\n<h2><br><strong>Tiện ích tinh tế: Công nghệ hỗ trợ</strong></h2>\n<p><br>Xe được trang bị đầy đủ các công tắc hỗ trợ, gia tăng sự an toàn và tiện lợi cho người dùng. Các tính năng bao gồm công tắc đèn chiếu xa/gần, công tắc đèn ưu tiên, công tắc xi nhan và nút Stop. Đặc biệt, công tắc đèn ưu tiên là một tính năng hữu ích khi xe cần dừng lại giữa đường do sự cố hoặc cảnh báo các phương tiện khác.</p>\n<p><br>Hệ thống vận hành của xe là tự động hoàn toàn, người lái chỉ cần vặn ga để di chuyển. Sự đơn giản này giúp mọi đối tượng, từ người trẻ đến người lớn tuổi, đều có thể dễ dàng làm chủ chiếc <strong>xe may dien</strong>. Việc khởi động xe cũng được hỗ trợ bằng chìa khóa thông minh, tăng tính bảo mật và sự tiện lợi.</p>\n<p><br>DK Bike cam kết chất lượng sản phẩm qua chính sách bảo hành hào phóng: Khung xe được bảo hành 3 năm, động cơ 2 năm và ắc quy được bảo hành lên đến 18 tháng. Chính sách bảo hành thể hiện sự tự tin của hãng vào chất lượng lắp ráp và nguồn linh kiện, mang lại sự yên tâm tuyệt đối cho người sở hữu.</p>\n<p><br><strong>DK Roma new</strong> là sự giao thoa hoàn hảo giữa nét cổ điển thanh lịch và công nghệ điện mạnh mẽ 1500W. Với phanh đĩa kép an toàn, quãng đường di chuyển 80km và lốp KENDA không săm, chiếc xe này là một lựa chọn đáng giá. Roma đã khẳng định vị thế là phương tiện di chuyển đô thị tin cậy, tiện nghi và đầy phong cách.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-roma-lite-den-vuong-moi-nhat', 'Xe Máy Điện DK Roma Lite Đèn Vuông Mới Nhất', 'dk', '[\"xe-may-dien\"]', 17900000, 17900000, '/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-den-vuong-moi-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-den-vuong-moi-nhat-1.webp\"]', '[]', '[]', '[]', '<p>DK Roma Lite đèn vuông ghi điểm tuyệt đối nhờ sự hòa quyện giữa ngôn ngữ thiết kế Ý sang trọng và khối động cơ BLDC 3 pha mạnh mẽ lên tới 1800W. Chiếc xe định nghĩa lại chuẩn mực di chuyển thông minh với khả năng đạt tốc độ 60km/h cùng quãng đường hành trình dài 80km bền bỉ. Mọi chi tiết từ hệ thống đèn vuông sắc sảo đến càng đúc nguyên khối đều phản ánh sự tỉ mỉ, mang lại trải nghiệm lái đẳng cấp và khác biệt.</p>\n<p>DK Roma Lite đèn vuông là thành quả của sự hợp tác công nghệ Việt Nhật, đảm bảo dây chuyền sản xuất hiện đại và quy trình kiểm soát chất lượng nghiêm ngặt. Sự bảo chứng từ thương hiệu DK Bike giúp người dùng yên tâm về độ bền bỉ của linh kiện cũng như tính ổn định của hệ thống điện trong mọi điều kiện vận hành.</p>', '<p><strong>DK Roma Lite đèn vuông</strong> ghi điểm tuyệt đối nhờ sự hòa quyện giữa ngôn ngữ thiết kế Ý sang trọng và khối động cơ BLDC 3 pha mạnh mẽ lên tới 1800W. Chiếc xe định nghĩa lại chuẩn mực di chuyển thông minh với khả năng đạt tốc độ 60km/h cùng quãng đường hành trình dài 80km bền bỉ. Mọi chi tiết từ hệ thống đèn vuông sắc sảo đến càng đúc nguyên khối đều phản ánh sự tỉ mỉ, mang lại trải nghiệm lái đẳng cấp và khác biệt.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-den-vuong-moi-nhat-2.webp\" alt=\"Xe Máy Điện DK Roma Lite Đèn Vuông Mới Nhất\" loading=\"lazy\"></p>\n<h2><br><strong>Uy tín thương hiệu Việt Nhật, nền tảng hậu mãi vững chắc</strong></h2>\n<p><br><strong>DK Roma Lite đèn vuông</strong>&nbsp;là thành quả của sự hợp tác công nghệ Việt Nhật, đảm bảo dây chuyền sản xuất hiện đại và quy trình kiểm soát chất lượng nghiêm ngặt. Sự bảo chứng từ thương hiệu DK Bike giúp người dùng yên tâm về độ bền bỉ của linh kiện cũng như tính ổn định của hệ thống điện trong mọi điều kiện vận hành.</p>\n<p><br>Chế độ bảo hành khung xe kéo dài tới 3 năm là một lời khẳng định đanh thép về sự kiên cố của cấu trúc cơ khí cốt lõi. Bên cạnh đó, các bộ phận thiết yếu như động cơ được bảo vệ trong 2 năm, cùng 1 năm bảo hành cho ắc quy và pin, tạo nên sự bao quát tuyệt vời cho quyền lợi khách hàng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-den-vuong-moi-nhat-3.webp\" alt=\"Xe Máy Điện DK Roma Lite Đèn Vuông Mới Nhất\" loading=\"lazy\"></p>\n<p><br>Sổ bảo hành đi kèm không chỉ là giấy tờ pháp lý mà còn là cầu nối giúp bạn tiếp cận dịch vụ chăm sóc kỹ thuật chuyên sâu. Việc minh bạch trong chính sách hậu mãi giúp mẫu xe giữ vững giá trị và sự tin cậy qua thời gian dài sử dụng.</p>\n<h2><br><strong>Sức mạnh động cơ BLDC 1800W đầy nội lực</strong></h2>\n<p><br>Trái tim của xe là hệ thống động cơ BLDC 3 pha một chiều không chổi than với công suất ấn tượng 1800W. Công nghệ này giúp xe vận hành cực kỳ êm ái, tối ưu hóa hiệu suất năng lượng và giảm thiểu tối đa tiếng ồn cơ khí khi lăn bánh.</p>\n<p><br>Khả năng vận hành của&nbsp;<strong>DK Roma Lite</strong> hoàn toàn tự động mang lại sự thư thái tuyệt đối, cho phép người lái kiểm soát tay ga một cách mượt mà và nhạy bén. Bạn sẽ cảm nhận được lực kéo dồi dào ngay từ những nhịp ga đầu tiên, giúp xe thoát đi nhanh chóng trong các dòng người đông đúc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-den-vuong-moi-nhat-4.webp\" alt=\"Xe Máy Điện DK Roma Lite Đèn Vuông Mới Nhất\" loading=\"lazy\"></p>\n<p><br>Vận tốc tối đa đạt ngưỡng 55-60km/h đưa Roma Lite trở thành phương tiện di chuyển nhanh nhẹn hàng đầu trong phân khúc. Mức tốc độ này đáp ứng hoàn hảo nhu cầu đi lại linh hoạt, giúp tiết kiệm thời gian đáng kể cho những hành trình xuyên đô thị mỗi ngày.</p>\n<h2><br><strong>Nguồn năng lượng bền bỉ cho những chặng đường xa</strong></h2>\n<p><br>Hệ thống lưu trữ năng lượng sử dụng dạng chì A Xít kín khí gồm 5 bình 12V24Ah cao cấp, đảm bảo dòng xả ổn định. Sự phân bổ điện năng thông minh giúp động cơ duy trì phong độ tốt nhất ngay cả khi bình điện đang ở mức năng lượng thấp.</p>\n<p><br>Quãng đường di chuyển 80km cho mỗi chu kỳ sạc đầy là một con số cực kỳ ấn tượng, loại bỏ hoàn toàn nỗi lo gián đoạn hành trình. Khả năng lưu trữ vượt trội này biến&nbsp;<strong>DK Roma Lite</strong> thành người bạn đồng hành tin cậy cho cả những chuyến đi chơi xa vùng ngoại ô.</p>\n<p><br>Cơ chế sạc thông minh với dòng sạc 2.8-3A giúp rút ngắn thời gian nạp điện xuống còn từ 8 đến 10 tiếng. Tính năng tự động ngắt điện khi đầy bình là chốt chặn an toàn quan trọng, bảo vệ ắc quy khỏi tình trạng quá nhiệt và kéo dài tuổi thọ hệ thống.</p>\n<h2><br><strong>Kiến trúc khung gầm đầm chắc, càng đúc nguyên khối</strong></h2>\n<p><br>Thông số kích thước 1720mm x 700mm x 1000mm tạo nên một phom dáng cân đối, toát lên vẻ ngoài sành điệu và chắc chắn. Chiều cao yên 760mm là mức lý tưởng để người lái có tư thế ngồi thẳng, tôn dáng và dễ dàng làm chủ xe khi dừng đỗ.</p>\n<p><br>Càng sau được chế tác từ nhôm đúc nguyên khối không chỉ tăng tính thẩm mỹ mà còn nâng cao khả năng chịu lực cho dàn chân. Sự kết hợp giữa vành đúc 10 inch và khung sườn thép giúp xe đạt độ ổn định cao, không hề có cảm giác rung lắc khi đi ở tốc độ lớn.</p>\n<p><br>Trọng lượng <strong>xe dien&nbsp;dap&nbsp;DK Roma Lite</strong> 85kg mang lại độ đầm cần thiết, giúp xe bám đường tốt hơn nhưng vẫn đủ linh hoạt để bạn quay đầu trong không gian hẹp. Tải trọng lên tới 160kg cho phép xe chở hai người lớn cùng vật dụng cá nhân một cách dễ dàng mà không làm giảm hiệu suất máy.</p>\n<h2><br><strong>Giải pháp an toàn tối ưu với hệ thống giảm chấn thủy lực</strong></h2>\n<p><br>Bánh trước được trang bị phanh đĩa kết hợp dầu thủy lực hiện đại, cung cấp lực hãm tức thì và cực kỳ an toàn. Bánh sau sử dụng phanh tang trống bền bỉ, tạo nên hệ thống phanh kép giúp bạn kiểm soát mọi tình huống bất ngờ trên đường.</p>\n<p><br>Trang bị giảm xóc giảm chấn thủy lực ở cả hai trục bánh xe giúp triệt tiêu hiệu quả các xung lực từ bề mặt đường gồ ghề. Những đoạn đường xấu hay gờ giảm tốc không còn là trở ngại, bởi hệ thống treo này luôn mang lại sự êm ái tối đa cho người ngồi.</p>\n<p><br>Lốp không săm cao cấp giúp tăng cường độ bám đường và giảm thiểu rủi ro khi vô tình cán phải vật nhọn. Độ bền của lốp cũng được cải thiện đáng kể, đảm bảo sự an tâm cho người dùng trong suốt thời gian dài vận hành thường nhật.</p>\n<h2><br><strong>Tiện ích hiện đại hỗ trợ người dùng toàn diện</strong></h2>\n<p><br>Hệ thống phụ kiện đi kèm theo xe rất đầy đủ với gương chiếu hậu thời trang, bộ sạc tiêu chuẩn và sổ bảo hành chính hãng. Các phím chức năng trên tay lái được bố trí tối ưu, giúp việc thao tác đèn, còi hay xi nhan trở nên tự nhiên và dễ dàng.</p>\n<p><br>Bảng màu sắc đa dạng sẵn có giúp khách hàng thoải mái chọn lựa tông màu phù hợp với cung mệnh hoặc sở thích cá nhân. Lớp sơn tĩnh điện cao cấp không chỉ đẹp mà còn có khả năng chống trầy xước và chịu được sự tác động của thời tiết nóng ẩm.</p>\n<p><br><strong>DK Roma Lite đèn vuông</strong> không đơn thuần là phương tiện di chuyển mà còn là biểu tượng của phong cách sống năng động, xanh và sạch. Với chi phí vận hành thấp và tính ứng dụng cao, đây chắc chắn là sự đầu tư thông minh cho tương lai di chuyển của bạn.</p>\n<p><br><strong>DK Roma Lite đèn vuông</strong> là sự lựa chọn không thể bỏ qua cho những ai đang tìm kiếm một chiếc xe điện mạnh mẽ và thời trang. Khối động cơ 1800W kết hợp cùng hệ thống an toàn phanh đĩa và giảm chấn thủy lực đã tạo nên một chuẩn mực mới về sự êm ái. Từng đường nét thiết kế đều mang đậm dấu ấn hiện đại, sẵn sàng cùng bạn tỏa sáng trên mọi cung đường đô thị. Đầu tư vào mẫu <strong>xe may dien</strong> này chính là khẳng định gu thẩm mỹ tinh tế và chọn lựa một hành trình an toàn, bền bỉ mỗi ngày.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-roma-lite-moi-nhat', 'Xe Máy Điện DK Roma Lite Mới Nhất', 'dk', '[\"xe-may-dien\"]', 17900000, 17900000, '/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-moi-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-moi-nhat-1.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện DK Roma Lite là tuyệt phẩm công nghệ từ liên doanh Việt Nhật, sở hữu diện mạo sang trọng cùng hiệu năng bứt phá. Với khối động cơ BLDC 1800W mạnh mẽ và hệ thống 5 bình ắc quy 20Ah, mẫu xe này thiết lập tiêu chuẩn mới về sự bền bỉ cho dòng xe điện thời thượng. Đây là phương tiện di chuyển thông minh giúp bạn tự tin làm chủ mọi hành trình phố thị một cách phong cách nhất.</p>\n<p>DK Roma Lite tự hào là sản phẩm của sự hợp tác Việt Nhật, kết hợp dây chuyền lắp ráp hiện đại với quy trình kiểm định khắt khe. Linh kiện đồng bộ giúp xe vận hành ổn định trong điều kiện khí hậu nóng ẩm, đảm bảo tuổi thọ tối ưu cho toàn bộ hệ thống điện. Việc ưu tiên chất lượng nội địa hóa mang lại lợi thế về chi phí và sự thuận tiện khi khách hàng cần bảo trì định kỳ.</p>', '<p><strong>Xe máy điện DK Roma Lite</strong> là tuyệt phẩm công nghệ từ liên doanh Việt Nhật, sở hữu diện mạo sang trọng cùng hiệu năng bứt phá. Với khối động cơ BLDC 1800W mạnh mẽ và hệ thống 5 bình ắc quy 20Ah, mẫu xe này thiết lập tiêu chuẩn mới về sự bền bỉ cho dòng xe điện thời thượng. Đây là phương tiện di chuyển thông minh giúp bạn tự tin làm chủ mọi hành trình phố thị một cách phong cách nhất.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-moi-nhat-2.webp\" alt=\"Xe máy điện DK Roma Lite mới nhất\" loading=\"lazy\"></p>\n<h2><br><strong>Nguồn gốc liên doanh đi kèm cam kết bảo trì dài hạn</strong></h2>\n<p><br><strong>DK Roma Lite</strong> tự hào là sản phẩm của sự hợp tác Việt Nhật, kết hợp dây chuyền lắp ráp hiện đại với quy trình kiểm định khắt khe. Linh kiện đồng bộ giúp xe vận hành ổn định trong điều kiện khí hậu nóng ẩm, đảm bảo tuổi thọ tối ưu cho toàn bộ hệ thống điện. Việc ưu tiên chất lượng nội địa hóa mang lại lợi thế về chi phí và sự thuận tiện khi khách hàng cần bảo trì định kỳ.</p>\n<p><br>Khung sườn xe nhận chế độ bảo hành lên tới 3 năm, khẳng định độ vững chãi của cấu trúc thép cường lực qua thời gian sử dụng. Động cơ được hãng cam kết bảo vệ trong 2 năm, giúp người dùng hoàn toàn yên tâm tận hưởng sức mạnh vận hành mà không lo hỏng hóc. Chính sách này tạo nên rào chắn an toàn, giúp bạn luôn thấy khoản đầu tư cho phương tiện di chuyển là hoàn toàn xứng đáng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-moi-nhat-3.webp\" alt=\"Xe máy điện DK Roma Lite mới nhất\" loading=\"lazy\"></p>\n<p><br>Bộ phận lưu trữ năng lượng gồm ắc quy và pin được hỗ trợ kỹ thuật chính hãng xuyên suốt 12 tháng đầu tiên. Mạng lưới hậu mãi chuyên nghiệp sẵn sàng đáp ứng mọi nhu cầu sửa chữa nhanh chóng, giúp xe luôn trong trạng thái sẵn sàng lăn bánh. Khách hàng sẽ cảm nhận được sự tận tâm và trách nhiệm từ nhà sản xuất ngay từ những ngày đầu sở hữu siêu phẩm 2024 này.</p>\n<h2><br><strong>Động cơ BLDC 1800W bứt phá vận tốc mượt mà</strong></h2>\n<p><br>Trái tim của xe là khối động cơ BLDC 3 pha một chiều không chổi than sở hữu công suất định danh lên đến 1800W cực kỳ mạnh mẽ. Công nghệ không chổi than giúp triệt tiêu tiếng ồn cơ học, tối ưu hóa điện năng và ngăn chặn tình trạng quá nhiệt khi chạy liên tục. Bạn sẽ cảm nhận được lực kéo tức thì, hỗ trợ xe vượt dốc dễ dàng mà không hề có hiện tượng trễ ga hay hụt hơi.</p>\n<p><br>Cơ chế vận hành tự động hoàn toàn biến việc điều khiển phương tiện trở nên đơn giản, phù hợp cho mọi đối tượng khách hàng. Người lái chỉ cần điều phối tay ga nhịp nhàng để đạt vận tốc tối đa trong khoảng 55-60 km/h một cách ổn định trên phố. Sự tinh giản trong thao tác giúp bạn giữ được tinh thần thoải mái, tập trung quan sát đường đi vào những khung giờ giao thông đông đúc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-moi-nhat-4.webp\" alt=\"Xe máy điện DK Roma Lite mới nhất\" loading=\"lazy\"></p>\n<p><br>Mức vận tốc ấn tượng cho phép bạn di chuyển linh hoạt và nhanh chóng đến mọi điểm hẹn học tập hay làm việc trong thành phố. Khả năng duy trì tốc độ đều đặn giúp việc tính toán thời gian đi lại trở nên chính xác, đảm bảo lịch trình cá nhân luôn đúng hạn. Roma Lite chứng minh hiệu năng thực thụ không chỉ là con số mà là sự ổn định bỉ xuyên suốt hành trình mỗi ngày.</p>\n<h2><br><strong>Hệ thống 5 bình ắc quy kiến tạo quãng đường 80km</strong></h2>\n<p><br>Nguồn năng lượng dồi dào đến từ dàn 5 bình ắc quy axit chì 12V20Ah kín khí, đảm bảo dòng điện luôn ở trạng thái ổn định. Dung lượng lớn giúp xe đạt được quãng đường di chuyển ấn tượng lên tới 80km sau mỗi lần sạc đầy trong điều kiện tiêu chuẩn. Đây là bước tiến quan trọng giúp người dùng chủ động hơn cho các hành trình xa mà không phải lo lắng về việc hết điện giữa chừng.</p>\n<p><br>Bộ sạc thông minh tích hợp tính năng tự động ngắt điện khi đầy bình, bảo vệ hệ thống khỏi các rủi ro cháy nổ do quá tải. Thời gian nạp điện dao động từ 8 đến 10 tiếng, vô cùng thuận tiện để bạn sạc xe qua đêm và sẵn sàng cho ngày mới.</p>\n<p><br>Tính năng cứu trợ khẩn cấp trên cụm công tắc giúp người lái xử lý các sự cố điện bất ngờ để di chuyển thêm một đoạn ngắn. Tiện ích độc đáo này mang lại sự an tâm tuyệt đối, giúp bạn không bao giờ phải rơi vào tình huống dắt bộ mệt mỏi trên đường. Roma Lite ưu tiên trải nghiệm người dùng thông qua những giải pháp công nghệ thực tế và đầy thông minh trong mọi hoàn cảnh.</p>\n<h2><br><strong>Diện mạo Roma sang trọng tôn vinh vóc dáng</strong></h2>\n<p><br>Kích thước tổng thể 1720 x 700 x 1000 (mm) mang lại phom dáng cân đối, thanh thoát và đậm chất thời trang phong cách Ý. Đường nét bo tròn tinh tế kết hợp cùng bảng màu sắc đa dạng giúp chủ sở hữu tự tin khẳng định cá tính riêng biệt trên phố. Thiết kế này tối ưu hóa khí động học, hỗ trợ xe lướt đi nhẹ nhàng và tiết kiệm năng lượng điện tối đa trong mọi điều kiện.</p>\n<p><br>Chiều cao yên xe 760mm được tính toán chuẩn xác, giúp người lái dễ dàng chống chân và giữ thăng bằng một cách tự tin nhất. Tầm nhìn thoáng đãng từ vị trí ngồi kết hợp cùng sàn để chân rộng rãi mang lại cảm giác lái thư thái dù đi đoạn đường dài.</p>\n<p><br>Bảng điều khiển tích hợp đầy đủ công tắc đèn ưu tiên, đèn chiếu xa gần và xi nhan giúp việc thao tác trở nên trực quan. Hệ thống đèn Stop thông minh hỗ trợ cảnh báo an toàn cho các phương tiện phía sau khi bạn thực hiện việc dừng đỗ hay phanh gấp. Mỗi chi tiết ngoại hình đều toát lên vẻ cao cấp, biến mỗi chuyến đi của bạn trở thành một trải nghiệm nghệ thuật đầy hứng khởi.</p>\n<h2><br><strong>An toàn tuyệt đối nhờ phanh đĩa thủy lực</strong></h2>\n<p><br>Hệ thống phanh trước <strong>xe máy điện</strong> <strong>DK Roma Lite&nbsp;</strong>sử dụng đĩa dầu thủy lực hiện đại mang lại lực hãm cực kỳ chính xác và nhạy bén trong mọi tình huống. Phanh sau dạng tang trống truyền thống hỗ trợ giữ ổn định thân xe, ngăn chặn tình trạng trượt bánh khi bạn cần dừng xe đột ngột.</p>\n<p><br>Lốp không săm KENDA 3.00-10 kích cỡ lớn kết hợp cùng vành xe đúc nguyên khối tăng cường khả năng bám đường vượt trội. Thiết kế này giảm thiểu rủi ro khi không may cán phải vật sắc nhọn, cho phép bạn di chuyển thêm một đoạn để tìm chỗ sửa chữa. Dàn chân cứng cáp đảm bảo xe vận hành ổn định trên các bề mặt đường trơn trượt hoặc khi di chuyển dưới trời mưa lớn.</p>\n<p><br>Bộ giảm xóc thủy lực cao cấp phía trước và phía sau đóng vai trò triệt tiêu rung động, mang lại cảm giác lái êm ái nhất. Ngay cả khi vượt qua các gờ giảm tốc hay đoạn đường lồi lõm, xe vẫn giữ được sự vững chãi và bảo vệ cột sống người ngồi. Trải nghiệm thực tế cho thấy Roma Lite sở hữu độ đầm chắc tuyệt vời, xóa tan mọi lo ngại về sự rung lắc cơ học thường thấy.</p>\n<h2><br><strong>Tiện ích thông minh cùng sức chịu tải 160kg</strong></h2>\n<p><br>Mỗi chiếc xe xuất xưởng đều đi kèm đầy đủ bộ gương chiếu hậu, sạc chính hãng và sổ bảo hành giúp bạn sẵn sàng lăn bánh. Gương có diện tích quan sát rộng hỗ trợ người lái kiểm soát tốt không gian phía sau để chuyển làn hay rẽ hướng một cách an toàn. Nhà sản xuất chú trọng đến từng phụ kiện nhỏ nhất để hoàn thiện trải nghiệm sử dụng trọn vẹn và chuyên nghiệp cho khách hàng.</p>\n<p><br>Càng sau đúc nguyên khối siêu bền cho phép xe chịu được tải trọng lên tới 160kg mà vẫn giữ được hiệu suất vận hành mượt mà. Bạn có thể thoải mái chở thêm người thân hoặc mang theo đồ đạc cá nhân nặng mà không lo lắng về việc ảnh hưởng đến khung gầm. Trọng lượng xe 85kg được phân bổ cân bằng giúp việc dắt xe hay quay đầu trong bãi đỗ chật hẹp trở nên vô cùng nhẹ nhàng.</p>\n<p><br>Giấy tờ pháp lý minh bạch cùng hồ sơ lắp ráp rõ ràng giúp quá trình đăng ký và lưu thông của bạn diễn ra thuận lợi nhất. Đầu tư vào DK Roma Lite là lựa chọn thông thái cho một phương tiện di chuyển xanh, bền bỉ và vô cùng tiết kiệm điện. Mẫu xe này hội tụ đủ các tiêu chuẩn khắt khe nhất để trở thành biểu tượng mới của dòng xe điện cao cấp tại Việt Nam.</p>\n<p><br><strong>DK Roma Lite</strong> thực sự là một cột mốc mới trong làng <strong>xe máy điện</strong> với sự hài hòa tuyệt đối giữa công nghệ BLDC mạnh mẽ và thiết kế Roma quý phái. Với quãng đường 80km bền bỉ cùng hệ thống an toàn tối ưu, sản phẩm cam kết mang lại những hành trình đầy cảm hứng và an tâm cho chủ sở hữu. Đừng bỏ lỡ cơ hội làm chủ \"chiến mã\" đầy ấn tượng này để mỗi chuyến đi của bạn đều trở nên khác biệt và tỏa sáng.</p>', 1);
