INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-roma-lite-s-den-luc-giac', 'Xe Máy Điện DK Roma Lite S Đèn Lục Giác', 'dk', '[\"xe-may-dien\"]', 18900000, 18900000, '/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-s-den-luc-giac-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-lite-s-den-luc-giac-1.webp\"]', '[]', '[]', '[]', '<p>DK Roma Lite S với điểm nhấn là cụm đèn lục giác độc đáo, đã khẳng định vị thế của DK Bike trong phân khúc xe điện cao cấp. Mẫu xe này là sự kết hợp tinh tế giữa phong cách Ý lãng mạn và tinh thần cải tiến không ngừng, mang đến một trải nghiệm lái xe vừa sang trọng, vừa tiện nghi. Roma Lite S không chỉ là một phương tiện di chuyển mà còn là biểu tượng của gu thẩm mỹ hiện đại. Đây là lựa chọn hoàn hảo cho những người tìm kiếm sự khác biệt, đồng thời đề cao hiệu suất và độ an toàn.</p>\n<p>Điểm thu hút ánh nhìn đầu tiên của DK Roma Lite S chính là cụm đèn pha LED hình lục giác, một đột phá trong ngôn ngữ thiết kế xe điện. Chi tiết này không chỉ mang tính thẩm mỹ cao, tạo nên vẻ ngoài cá tính và khác biệt, mà còn tối ưu hóa khả năng chiếu sáng, cung cấp vùng ánh sáng rộng và rõ, nâng cao sự an toàn khi di chuyển trong điều kiện thiếu sáng.</p>', '<p><strong>DK Roma Lite S</strong> với điểm nhấn là cụm đèn lục giác độc đáo, đã khẳng định vị thế của DK Bike trong phân khúc xe điện cao cấp. Mẫu xe này là sự kết hợp tinh tế giữa phong cách Ý lãng mạn và tinh thần cải tiến không ngừng, mang đến một trải nghiệm lái xe vừa sang trọng, vừa tiện nghi. Roma Lite S không chỉ là một phương tiện di chuyển mà còn là biểu tượng của gu thẩm mỹ hiện đại. Đây là lựa chọn hoàn hảo cho những người tìm kiếm sự khác biệt, đồng thời đề cao hiệu suất và độ an toàn.</p>\n\n<h2><br><strong>Nét tinh hoa thiết kế: Tuyệt tác đèn lục giác</strong></h2>\n<p><br>Điểm thu hút ánh nhìn đầu tiên của <strong>DK Roma Lite S</strong> chính là cụm đèn pha LED hình lục giác, một đột phá trong ngôn ngữ thiết kế xe điện. Chi tiết này không chỉ mang tính thẩm mỹ cao, tạo nên vẻ ngoài cá tính và khác biệt, mà còn tối ưu hóa khả năng chiếu sáng, cung cấp vùng ánh sáng rộng và rõ, nâng cao sự an toàn khi di chuyển trong điều kiện thiếu sáng.</p>\n<p><br>Tổng thể ngoại hình của xe được thừa hưởng đường nét mềm mại, cổ điển từ dòng xe ga châu Âu, nhưng được tinh chỉnh để trở nên gọn gàng và trẻ trung hơn (Kích thước: 1720mm x 700mm x 1000mm). Chiều cao yên 750mm rất phù hợp với vóc dáng của người Việt, giúp người lái dễ dàng chống chân và làm chủ phương tiện.</p>\n\n<p><br>Vỏ xe được chế tạo từ nhựa ABS/PP cao cấp, có độ bền cơ học và khả năng chịu va đập tốt, đồng thời được phủ lớp sơn tĩnh điện bóng bẩy, bền màu. Sự trau chuốt trong chất liệu và hoàn thiện cho thấy sự nghiêm túc của DK Bike trong việc xây dựng một sản phẩm chất lượng, đồng hành cùng người dùng qua nhiều năm sử dụng.</p>\n<h2><br><strong>Động lực mạnh mẽ: Công nghệ BLDC 3 pha</strong></h2>\n<p><br>Sức mạnh vận hành của <strong>DK Roma Lite S</strong> đến từ khối động cơ điện BLDC 3 pha mạnh mẽ, với công suất tối đa lên tới 1800W. Công suất này vượt xa mức tiêu chuẩn, đảm bảo xe có thể dễ dàng vượt qua các dốc cao hay tăng tốc nhanh chóng khi cần thiết, mang lại sự linh hoạt tối đa trong môi trường giao thông đô thị phức tạp.</p>\n<p><br>Động cơ BLDC 3 pha giúp xe đạt vận tốc tối đa ấn tượng 58km/h. Tốc độ này không chỉ đáp ứng tốt nhu cầu di chuyển hàng ngày mà còn mang lại cảm giác lái phấn khích. Tuy nhiên, quan trọng là động cơ vẫn duy trì được sự êm ái, gần như không gây tiếng ồn, tạo nên trải nghiệm di chuyển thư thái.</p>\n\n<p><br>Hệ thống điều khiển thông minh được tích hợp để quản lý năng lượng và quá trình tăng/giảm tốc. Bộ điều khiển tối ưu hóa hiệu suất, đảm bảo việc truyền lực mượt mà, không bị giật cục. Với tải trọng lên tới 160kg, động cơ 1800W này chứng minh được khả năng chịu tải vượt trội và ổn định.</p>\n<h2><br><strong>Dự trữ năng lượng: Quãng đường 80km bền bỉ</strong></h2>\n<p><br><strong>Xe điện DK Roma Lite S</strong> sử dụng bộ ắc quy thông thường gồm 5 bình 12V20Ah (Dạng chì A xít, kín khí). Đây là nguồn năng lượng đã được chứng minh về độ bền và tính ổn định. Với dung lượng này, xe có thể di chuyển được quãng đường lên đến 80km sau mỗi lần sạc đầy (theo điều kiện tiêu chuẩn), đáp ứng thoải mái nhu cầu di chuyển trong ngày mà không lo lắng về vấn đề sạc pin.</p>\n<p><br>Thời gian sạc đầy cho bộ ắc quy là khoảng 8-10 giờ với dòng sạc 2.8-3A (tùy phiên bản), cho phép người dùng sạc xe qua đêm một cách thuận tiện. Hãng xe đã trang bị tính năng tự động ngắt khi ắc quy đầy, một cơ chế an toàn cần thiết, giúp bảo vệ tuổi thọ của ắc quy và ngăn ngừa các sự cố về điện.</p>\n<p><br>Chính sách bảo hành ắc quy lên đến 18 tháng (tùy phiên bản) từ DK Bike thể hiện sự tự tin vào chất lượng linh kiện, mang lại sự an tâm tuyệt đối cho người dùng về khoản đầu tư dài hạn này. Việc quản lý năng lượng hiệu quả giúp Roma Lite S trở thành một lựa chọn kinh tế và bền vững.</p>\n<h2><br><strong>Cảm giác lái, độ bám: Vành đúc, lốp không săm</strong></h2>\n<p><br>Hệ thống khung sườn của <strong>DK Roma Lite S</strong> được làm từ vật liệu thép chịu lực cao, đảm bảo độ vững chắc và an toàn tối đa cho người lái. Cùng với hệ thống giảm xóc thủy lực cao cấp (phuộc trước và giảm chấn thủy lực sau), xe có khả năng hấp thụ xung lực tốt, giúp xe vận hành êm ái, đầm chắc trên mọi loại địa hình.</p>\n<p><br>Xe được trang bị phanh đĩa ở bánh trước và phanh tang trống (hoặc phanh đĩa 1 piston tùy phiên bản) ở bánh sau, tạo thành một hệ thống phanh phối hợp hiệu quả. Phanh đĩa cung cấp lực phanh chính xác và mạnh mẽ, tối ưu hóa khả năng dừng xe trong mọi tình huống khẩn cấp, tăng cường sự an toàn.</p>\n<p><br>DK Roma Lite S sử dụng lốp KENDA không săm, kích thước 3.00-10. Lốp KENDA nổi tiếng về chất lượng và độ bám đường cao. Lốp không săm giúp giảm thiểu rủi ro bị xì hơi đột ngột và tăng tuổi thọ lốp, đảm bảo hành trình luôn suôn sẻ. Vành xe đúc bằng hợp kim nhôm (tùy phiên bản) không chỉ nhẹ mà còn tăng tính thẩm mỹ và độ bền cấu trúc.</p>\n<h2><br><strong>Tiện ích thông minh: Công nghệ hỗ trợ vận hành</strong></h2>\n<p><br><strong>DK Roma Lite S</strong> được tích hợp nhiều tiện ích thông minh, nâng cao trải nghiệm người dùng. Xe có màn hình đồng hồ hiển thị kỹ thuật số hiện đại, hiển thị rõ ràng và đầy đủ các thông số quan trọng như tốc độ, quãng đường, và đặc biệt là dung lượng ắc quy còn lại. Giao diện trực quan giúp người lái dễ dàng theo dõi tình trạng xe.</p>\n<p><br>Xe được trang bị nhiều công tắc chức năng hữu ích. Điển hình là công tắc đèn chiếu xa/gần, công tắc xi nhan, công tắc cứu trợ (tăng tốc khẩn cấp), và đặc biệt là Nút Stop (ngắt điện khẩn cấp), cho phép người lái dừng xe ngay lập tức khi cần xử lý tình huống bất ngờ.</p>\n<p><br>Không gian lưu trữ của Roma Lite S cũng được tối ưu. Cốp xe dưới yên có dung tích vừa đủ để chứa mũ bảo hiểm nửa đầu và các vật dụng cá nhân nhỏ khác. Thêm vào đó, hộc đựng đồ phía trước cùng móc treo đồ tiện lợi hỗ trợ người dùng mang theo nhiều đồ đạc hơn trong các chuyến đi hàng ngày.</p>\n<h2><br><strong>Giá trị bền vững: Cam kết bảo hành chính hãng</strong></h2>\n<p><br><strong>DK Bike</strong> cam kết chất lượng thông qua chính sách bảo hành rõ ràng: Khung xe được bảo hành tới 3 năm, động cơ 1 năm và ắc quy lên đến 18 tháng. Những cam kết này khẳng định độ tin cậy và sự bền bỉ vượt thời gian của DK Roma Lite S.</p>\n<p><br>Xe được lắp ráp theo tiêu chuẩn Việt Nhật, tuân thủ quy trình kiểm tra chất lượng nghiêm ngặt, đảm bảo mỗi chiếc xe xuất xưởng đều đạt chất lượng cao nhất. Khả năng chống nước tốt của toàn bộ hệ thống điện cũng là một ưu điểm lớn, giúp xe hoạt động ổn định trong điều kiện mưa bão thường gặp ở Việt Nam.</p>\n<p><br>Việc đầu tư vào DK Roma Lite S là một quyết định thông minh về kinh tế. Chi phí sạc điện thấp, chi phí bảo dưỡng gần như không đáng kể so với xe xăng truyền thống. Roma Lite S mang lại hiệu quả kinh tế lâu dài, đồng thời góp phần bảo vệ môi trường, phù hợp với xu hướng phát triển bền vững.</p>\n<p><br><strong>Xe máy điện DK Roma Lite S đèn lục giác</strong> là sự lựa chọn hoàn hảo cho những ai tìm kiếm sự kết hợp giữa vẻ đẹp thời trang và sức mạnh công nghệ. Với động cơ 1800W, phanh đĩa an toàn, quãng đường di chuyển 80km và thiết kế đèn lục giác độc đáo, Roma Lite S xứng đáng là người bạn đồng hành tin cậy, giúp bạn tự tin và nổi bật trên mọi hành trình.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-roma-sx-v-new-the-he-moi', 'Xe Máy Điện DK Roma SX V New Thế Hệ Mới', 'dk', '[\"xe-may-dien\"]', 19690000, 19690000, '/sites/yenthoa/img/sp/xe-may-dien-dk-roma-sx-v-new-the-he-moi-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-roma-sx-v-new-the-he-moi-1.webp\"]', '[]', '[]', '[]', '<p>DK Roma SX V New Thế Hệ Mới là sự giao thoa nghệ thuật giữa phong thái lãng mạn, kinh điển của Ý và công nghệ truyền động điện tiên tiến. Chiếc xe này được thiết kế để tôn vinh sự thanh lịch, quý phái. Roma SX V New hướng đến những người dùng đang tìm kiếm một phương tiện cá nhân có hiệu suất vận hành êm ái, bền bỉ và đặc biệt là độ tin cậy cao, đồng thời mong muốn sở hữu một thiết kế ngoại thất vượt thời gian.</p>\n<p>Roma SX V New thừa hưởng trọn vẹn triết lý hình thái học của dòng scooter huyền thoại, nổi bật với những đường cong mềm mại, tròn trịa được kéo dài một cách hoàn hảo từ mặt nạ trước đến đuôi xe. Toàn bộ thân xe được chế tạo từ nhựa ABS có độ bền cơ học cao, kết hợp cùng lớp sơn bóng hoặc nhám cao cấp, tạo nên một vẻ ngoài lôi cuốn, có chiều sâu.</p>', '<p><strong>DK Roma SX V New Thế Hệ Mới</strong> là sự giao thoa nghệ thuật giữa phong thái lãng mạn, kinh điển của Ý và công nghệ truyền động điện tiên tiến. Chiếc xe này được thiết kế để tôn vinh sự thanh lịch, quý phái. Roma SX V New hướng đến những người dùng đang tìm kiếm một phương tiện cá nhân có hiệu suất vận hành êm ái, bền bỉ và đặc biệt là độ tin cậy cao, đồng thời mong muốn sở hữu một thiết kế ngoại thất vượt thời gian.</p>\n\n<h2><br><strong>Ngoại hình và triết lý hình thái học</strong></h2>\n<p><br><strong>Roma SX V New</strong> thừa hưởng trọn vẹn triết lý hình thái học của dòng scooter huyền thoại, nổi bật với những đường cong mềm mại, tròn trịa được kéo dài một cách hoàn hảo từ mặt nạ trước đến đuôi xe. Toàn bộ thân xe được chế tạo từ nhựa ABS có độ bền cơ học cao, kết hợp cùng lớp sơn bóng hoặc nhám cao cấp, tạo nên một vẻ ngoài lôi cuốn, có chiều sâu.</p>\n<p><br>Điểm nhấn trung tâm là cụm đèn pha LED kích thước lớn, được bao bọc trong một viền chrome tinh xảo, duy trì hình dáng tròn cổ điển nhưng được nâng cấp bằng công nghệ chiếu sáng hiện đại. Hệ thống đèn LED toàn xe, từ đèn pha đến đèn hậu và đèn báo rẽ, không chỉ đảm bảo hiệu quả chiếu sáng tối ưu mà còn thể hiện sự tinh tế trong từng chi tiết thiết kế.</p>\n\n<p><br>Khu vực điều khiển được trang bị màn hình LCD toàn phần, hiển thị mọi thông số vận hành một cách sắc nét và trực quan. Giao diện số hóa này cung cấp thông tin chi tiết về vận tốc, quãng đường, trạng thái pin, và chế độ lái, giúp người điều khiển dễ dàng kiểm soát mọi trạng thái của xe mà không bị phân tâm.</p>\n<h2><br><strong>Trái tim động lực: Đơn vị vận hành điện</strong></h2>\n<p><br>Nguồn sức mạnh của <strong>Roma SX V New</strong> đến từ khối Động cơ Hub Motor mạnh mẽ, được tích hợp gọn gàng vào trục bánh sau, với công suất định mức thường đạt 1000W (hoặc cao hơn tùy phiên bản, có thể đạt đỉnh 1500W). Đơn vị truyền động điện này là chìa khóa cho trải nghiệm lái xe êm ái, gần như không phát ra tiếng ồn.</p>\n<p><br>Động cơ điện cung cấp mô-men xoắn tức thời lớn ngay từ khi khởi động, giúp chiếc xe bứt tốc mượt mà, linh hoạt và vượt trội khi tham gia giao thông từ trạng thái đứng yên. Khả năng tăng tốc tuyến tính, không bị ngắt quãng bởi tiếng động cơ, tạo nên một cảm giác lái thư thái và sang trọng.</p>\n\n<p><br><strong>DK Roma SX V New</strong> được trang bị các chế độ lái có thể tùy chỉnh, cho phép người dùng lựa chọn giữa khả năng di chuyển xa (chế độ Eco) và hiệu suất vận hành mạnh mẽ hơn (chế độ Sport). Vận tốc tối đa của xe được kiểm soát, thường đạt mức 50 - 55 km/h, phù hợp tuyệt đối với điều kiện giao thông đô thị.</p>\n<h2><br><strong>Cấu trúc nguồn điện: Hệ thống ắc quy 60V-20Ah</strong></h2>\n<p><br>Đúng với cấu hình kỹ thuật đã được xác minh, <strong>Roma SX V New</strong> sử dụng Hệ thống Ắc quy Chì-Axit với tổng điện áp 60V (5 bình 12V) và dung lượng 20Ah. Sự lựa chọn ắc quy chì-axit mang lại những lợi thế riêng biệt về sự ổn định cơ học và chi phí thay thế.</p>\n<p><br>Ắc quy Chì-Axit được đánh giá cao về độ tin cậy trong môi trường khí hậu nhiệt đới. Việc đặt bộ ắc quy ở vị trí thấp trong khung sườn giúp xe duy trì trọng tâm thấp, qua đó gia tăng sự ổn định động học và cải thiện khả năng giữ cân bằng, đặc biệt khi vào cua hoặc di chuyển qua các bề mặt không bằng phẳng.</p>\n<p><br>Với cấu hình năng lượng 60V-20Ah, chiếc xe có thể đạt được phạm vi hành trình ấn tượng. Quãng đường di chuyển sau mỗi lần nạp đầy năng lượng thường dao động từ 80km đến 100km (tùy thuộc vào điều kiện vận hành thực tế). Phạm vi này vượt xa nhu cầu đi lại hàng ngày trong thành phố của đa số người dùng.</p>\n<p><br>Việc nạp lại năng lượng cho bộ ắc quy được thực hiện bằng bộ sạc tiêu chuẩn. Thời gian nạp đầy thường mất khoảng 8 đến 10 tiếng. Mặc dù thời gian sạc tương đối dài, chi phí thay thế ắc quy chì-axit lại kinh tế hơn đáng kể so với pin Lithium, mang lại lợi ích tài chính dài hạn.</p>\n<h2><br><strong>Cơ chế Triệt tiêu Lực: Phối hợp đĩa/tang trống</strong></h2>\n<p><br>Để đảm bảo khả năng kiểm soát tốc độ một cách an toàn và chính xác, <strong>xe máy điện DK Roma SX V New</strong> áp dụng cơ chế triệt tiêu lực lai bao gồm phanh đĩa thủy lực ở bánh trước và phanh tang trống (phanh cơ) ở bánh sau.</p>\n<p><br>Phanh đĩa phía trước đóng vai trò chủ đạo, cung cấp một lực hãm tức thời với độ phản hồi cực kỳ nhạy bén. Hệ thống thủy lực đảm bảo sự truyền tải lực phanh hiệu quả, giúp người lái kiểm soát lực bóp phanh tinh tế, rút ngắn quãng đường dừng xe.</p>\n<p><br>Phanh tang trống phía sau đảm nhiệm chức năng bổ trợ, mang lại sự ổn định cơ học cho bánh sau, đặc biệt khi xe giảm tốc độ từ từ. Sự kết hợp lực phanh hợp lý giữa hai bánh xe cùng với bộ vành đúc hợp kim 10 inch (hoặc 12 inch) giúp chiếc xe duy trì sự cân bằng tối ưu, giảm thiểu nguy cơ trượt bánh.</p>\n<h2><br><strong>Tiện ích số hóa và công thái học</strong></h2>\n<p><br><strong>DK Roma SX V New</strong> được trang bị các tiện ích số hóa nâng cao nhằm tối ưu hóa trải nghiệm người dùng. Chiếc xe được tích hợp khóa Smartkey, cho phép người dùng khởi động xe không cần chìa vật lý, kích hoạt tính năng chống trộm từ xa và định vị xe. Tính năng này tăng cường đáng kể tính an ninh và sự tiện lợi.</p>\n<p><br>Về mặt công thái học, xe được thiết kế với yên đôi lớn, bọc đệm dày và êm ái, mang lại sự thoải mái tuyệt đối cho cả người lái và người ngồi sau. Chiều cao yên xe được cân chỉnh phù hợp với vóc dáng người Việt Nam.</p>\n<p><br>Khoang chứa đồ dưới yên xe có dung tích lớn, là một ưu điểm vượt trội của dòng xe ga điện. Không gian này đủ sức chứa hai mũ bảo hiểm nửa đầu và nhiều vật dụng cá nhân khác. Sàn để chân được thiết kế rộng rãi và bằng phẳng, tạo sự thoải mái tối đa cho đôi chân người lái.</p>\n<h2><br><strong>Chi phí vận hành và quỹ đạo kinh tế</strong></h2>\n<p><br>Khả năng đạt được quỹ đạo kinh tế tối ưu là lợi thế then chốt của <strong>Roma SX V New</strong>. Việc sử dụng động cơ điện loại bỏ hoàn toàn nhu cầu về xăng dầu, chi phí năng lượng để nạp đầy ắc quy và di chuyển quãng đường 80-100km là rất nhỏ, thấp hơn nhiều lần so với xe máy xăng.</p>\n<p><br>Chi phí bảo dưỡng của hệ thống truyền động điện cũng được giảm thiểu đáng kể; không cần thay dầu nhớt, không cần bảo trì bộ chế hòa khí. Tổng chi phí sở hữu phương tiện được giữ ở mức cực kỳ hấp dẫn, biến Roma SX V New thành một khoản đầu tư thông minh, bền vững về mặt tài chính.</p>\n<p><br><strong>DK Roma SX V New Thế Hệ Mới</strong> là sự khẳng định về một tiêu chuẩn mới cho <strong>xe máy điện</strong>, nơi sự thanh lịch vượt thời gian hòa quyện cùng công nghệ điện năng hiệu suất cao. Khối động cơ 1000W êm ái, kết hợp với hệ thống ắc quy 60V-20Ah ổn định, mang lại phạm vi di chuyển rộng rãi và độ tin cậy cơ học đáng ngưỡng mộ. Chiếc xe này cung cấp một giải pháp giao thông kinh tế, hiệu quả, thể hiện gu thẩm mỹ tinh tế và lựa chọn sống hiện đại, bền vững của người sở hữu.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-dk-xmen-one', 'Xe Máy Điện DK Xmen One', 'dk', '[\"xe-may-dien\"]', 15990000, 15990000, '/sites/yenthoa/img/sp/xe-may-dien-dk-xmen-one-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-dk-xmen-one-1.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda H12 Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 17800000, 17800000, '/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-h12-chinh-hang-honda-nhat-ban-5.webp\"]', '[]', '[]', '[]', '<p>Được nhập khẩu nguyên chiếc, cùng sở hữu nhiều công nghệ đẳng cấp mà không nhiều dòng xe máy điện có được. Tiện ích cho cuộc sống, chống “đau ví” khi cứ chu kỳ 10 ngày giá xăng tăng một lần thì xe máy điện Sundiro Honda H12 ắt hẳn là sự lựa chọn mà bạn nên cân nhắc ngay hôm nay.</p>\n<p>Xe máy điện Sundiro Honda H12, hay còn có tên gọi thân thương khác mà nhiều người hay ưu ái khi gọi dòng xe này đó là xe máy điện phiên bản Honda Lead. Nếu đã từng nhìn thấy chiếc Honda Lead gây sốt trong thị trường xe xăng phân khối lớn thì chắc bạn sẽ không khó hình dung ra tổng thể ngoại hình chiếc Sundiro Honda H12.</p>', '<p><em>Được nhập khẩu nguyên chiếc, cùng sở hữu nhiều công nghệ đẳng cấp mà không nhiều dòng xe máy điện có được. Tiện ích cho cuộc sống, chống “đau ví” khi cứ chu kỳ 10 ngày giá xăng tăng một lần thì&nbsp;xe máy điện Sundiro Honda H12&nbsp;ắt hẳn là sự lựa chọn mà bạn nên cân nhắc ngay hôm nay.</em></p>\n<h2><strong>TỔNG QUAN VỀ XE MÁY ĐIỆN SUNDIRO HONDA H12</strong></h2>\n<p>Xe máy điện Sundiro Honda H12, hay còn có tên gọi thân thương khác mà nhiều người hay ưu ái khi gọi dòng xe này đó là xe máy điện phiên bản Honda Lead. Nếu đã từng nhìn thấy chiếc Honda Lead gây sốt trong thị trường xe xăng phân khối lớn thì chắc bạn sẽ không khó hình dung ra tổng thể ngoại hình chiếc Sundiro Honda H12.</p>\n<p>Khách quan mà nói thì dòng xe máy điện này do có thiết kế đặc trưng to bè ở phần hông giống xe Honda Lead nên trông cũng không quá nhỏ gọn như các thiết kế xe máy điện cùng hãng trước đó. Nhưng đây không phải nhược điểm vì một chiếc xe trông chắc chắn khi di chuyển sẽ an toàn, vững chải, không dễ bị ngã đổ hơn. Theo trải nghiệm của những người đã sử dụng qua Sundiro Honda H12 thì xe dễ dắt dẫn và phù hợp sử dụng đối với cả nữ giới. Nên nếu bạn là nữ thì hoàn toàn không có gì cần lo lắng hay lăn tăn khi có ý định mua xe máy điện Sundiro Honda H12 cả.</p>\n<p>Dàn áo xe cũng được làm chất liệu tốt từ nhựa ABS cao cấp cùng khung xe cứng cáp. Bên cạnh đó, xe sử dụng công nghệ sơn tĩnh điện bền màu, bóng sáng với đủ màu sắc đa dạng khác nhau, dễ dàng chọn lựa, trông thời trang và vô cùng bắt mắt chắc chắn sẽ làm hài lòng ngay cả những khách hàng khó tính nhất.</p>\n<h2><strong>NỔI BẬT CÙNG NHIỀU CÔNG NGHỆ ĐỘC ĐÁO CỦA XE MÁY ĐIỆN SUNDIRO HONDA H12</strong></h2>\n<h3><strong>Hệ thống đèn xe kết hợp tối ưu</strong></h3>\n<p>Đèn Led có ưu điểm lớn là bền, khả năng chiếu sáng tốt, có nhiều màu sắc đa dạng để chọn lựa, nhưng giá thành khá cao, cả việc lắp đặt và bảo trì, sửa chữa cũng khá tốn kém, do đó với cả phần đèn chiếu sáng và đèn pha to đùng mà sử dụng hết bằng đèn Led thì thật lãng phí, mà cũng đẩy giá thành xe máy điện Sundiro Honda H12 lên quá cao. Để tối ưu hóa trải nghiệm của người dùng nhưng vẫn đảm bảo xe có một mức giá dễ chịu thì riêng phần đèn chiếu sáng thiết kế dọc, dài nằm ở đầu xe thì hãng sử dụng đèn Led, còn đèn pha và xi nhan được thiết kế với hình dáng lạ mắt hơn nằm ở phần dàn áo trước của xe thì hãng dùng đèn Halogen, chiếu sáng tốt không thua gì đèn Led mà giá thành lại mềm hơn rất nhiều.</p>\n<p>Khi bật công tắc đèn lên thì cả đèn chiếu sáng lẫn đèn pha này sẽ sáng cùng một lúc, trông rất là bắt mắt và có cảm giác như đây là một chiếc xe xăng phân khối lớn thật thụ. Không tinh mắt thì cũng khó phát hiện ra Sundiro Honda H12 là xe máy điện bởi đã có rất nhiều khách hàng hỏi chúng tôi rằng đây có phải là xe máy xăng không.</p>\n<h3><strong>Mặt đồng hồ có nút Ready cực lạ</strong></h3>\n<p>Khi khởi động thì ngoài việc hiển thị các thông số quan trọng của xe như mức điện năng, đèn xi nhan trái phải, đèn pha có đang bật không, thì mặt đồng hồ này còn có nút Ready có nghĩa là ”sẵn sàng”. Mặt chữ có màu xanh lá cây, hiển thị cùng lúc, báo hiệu là xe đã chuẩn bị xong cho một trình mới bắt đầu. Đồng hồ xe là sự kế hợp tinh tế giữa các thông số tín hiện điển tử với kim chỉ vận tốc, thiết kế này vừa quen thuộc với số đông người sử dụng đồng thời thể hiện sự hiện đại cùng tín hiệu điện tử. Với mặt đồng hồ dễ thu hút ánh nhìn kiểu này thì chắc chắn là giúp người điều khiển dễ dàng quan sát hơn rất nhiều trong cả quá trình khởi động và di chuyển rồi.</p>\n<h3><strong>Tay lái có cụm công tắc 2 tính năng</strong></h3>\n<p>Nhìn chung thì tay lái xe máy điện Sundiro Honda H12 không khác gì mấy so với các thiết kế tay lái xe điện khác. Đặc biệt giống thiết kế tay lái xe Honda Lead với phần tay lái trái là công tắc xi nhan trái phải và tín hiệu còi, còn tay lái phải là công tắc bật đèn pha và đề. Thêm vào đó thì gần ở phần công tắc bên phải này còn thêm một cụm công tắc 2 nút liền kề với 2 tính năng đối nghịch nhau.</p>\n<p>Khi bậc nút có chữ H là từ viết tắt của chữ High (cao) thì xe sẽ chạy với tốc độ cao lên max tốc độ, còn nút L là Low (thấp) chạy với tốc độ chậm và tiết kiệm điện năng hơn. Nhờ vào đặc điểm này mà những người mới làm quen với xe cũng có thể sử dụng dễ dàng.</p>\n<h3><strong>Hiện đại với hộp chứa đồ đa năng</strong></h3>\n<p>Hiện không nhiều dòng xe máy điện được trang bị hộp chứa đồ mà có thể vừa chứa được đồ dùng cá nhân vừa có cổng sạc USB để sạc cả điện thoại như xe máy điện Sundiro Honda H12. Nếu có thì chỉ có thể đựng được bao tay, các vật dụng linh tinh nhỏ khác chứ không thể sạc điện được. Đây cũng là một thiết kế độc đáo vừa nổi bật vừa mang lại tiện nghi của một chiếc&nbsp;xe máy điện&nbsp;nên khi sử dụng Sundiro Honda H12 thì không bao giờ lo điện thoại bị cạn pin rồi.</p>\n<p>Ngoài ra, gần khu vực hộp chứa đồ đa năng này thì hãng có trang bị cho xe một móc đồ nho nhỏ nhưng đảm bảo là treo đồ nặng trên cả kí lô cũng không sao cả, rất là tiện lợi.</p>\n<h3><strong>Cụm chìa khóa độc đáo với 2 nút an toàn</strong></h3>\n<p>Nếu để xe bên ngoài, lo sợ xe bị mất thì bạn chỉ cần bấm vào nút phía trên của chìa khóa, xe sẽ ngay lập tức khởi động còi chống trộm khi có ai đó vô tình chạm vào chiếc xe của bạn. Nhưng đôi khi, xe cứ hú hoài rất là phiền và gây sự chú ý không đáng có nên chiếc chìa khóa này có thêm nút bấm bên hông để bạn dùng khi không quá cần thiết đảm bảo an toàn cho xe nữa, như là dựng xe trong nhà, nhà xe, nơi có người trông cẩn thận như ở chỗ làm,… thì sẽ không phát ra tiếng nữa. Những công nghệ này là được trang bị sẳn trên xe, được điều khiển qua chìa khóa khóa từ.</p>\n<p>Nếu không quá sơ hở thì rất khó mất xe vì thêm vào đó xe có phần thiết kế nút khởi động có phần đóng mở ổ khóa cùng tính năng khóa cổ. Ngoài ra, nắp đóng mở này cũng hỗ trợ rất tốt khi bạn rửa xe, không cần phải dùng băng keo bịt kín lại để chống thấm nước nữa.</p>\n<h2><strong>AN TOÀN VÀ VẬN HÀNH ỔN ÁP VỚI ĐỘNG CƠ</strong><strong><em>&nbsp;</em></strong><strong>BOSCH</strong><strong>&nbsp;</strong><strong>SIÊU KHỎE CỦA XE MÁY ĐIỆN SUNDIRO HONDA H12</strong></h2>\n<h3><strong>Xe máy điện trang bị phanh đĩa</strong></h3>\n<p>Xe máy điện Sundiro Honda H12 có phanh đĩa trước, phanh cơ sau, vành thép đúc cứng cáp 5 chấu họa tiếp đẹp. Xe sử dụng lốp không săm đảm bảo chống trơn trượt rất tốt, đồng thời an toàn khi xe lỡ cán phải đinh cũng không lo là bị xẹp lốp ngay lập tức. Với hệ thống giảm xóc trước ống lồng giảm chấn thủy lực, giảm xóc sau lò xo trụ giảm chấn thủy lực thì lại hỗ trợ người dùng tối đa trên những chặng đường có địa hình xấu, nhiều gồ ghề ổ voi, ổ gà. Đặc biệt là phần bánh xe của dòng xe máy điện Sundiro Honda H12 này thì cực kỳ dễ tìm kiếm và thay thế bởi chúng được ứng dụng phổ biến hiện nay.</p>\n<h3><strong>Động cơ điện đến từ hãng Bosch Đức nổi tiếng</strong></h3>\n<p>Nói đến các sản phẩm Bosch Đức thì rất là nổi tiếng rồi, nhất là trong lĩnh vực công nghệ dành cho xe ô tô, xe máy điện bởi các sản phẩm này cực kỳ thân thiện với môi trường mà lại còn chống nước cực tốt nữa. Xe máy điện Sundiro Honda H12 cũng được hãng trang bị và sử dụng mô tơ điện Bosch Đức cho công suất xe ổn định và có thể thay đổi được công suất theo ý muốn.</p>\n<p>Như đã nói ở trên thì với mô tơ điện 1 chiều không chổi than, công suất lúc bình thường là 1.200W, mức cực đại lên đến 1.500W thì xe vận hành khá ổn và khỏe, chạy đường dài hay chở nặng vi vu mà không lo xe bị chậm máy, hay xuống cấp, giảm tuổi thọ gì cả. Vận tốc tối đa của xe ở mức 50km/giờ với quãng đường di chuyển tối đa trong một lần sạc lên đến 80km, thì người dùng hoàn toàn có thể yên tâm sử dụng xe mà không lo trễ giờ hay đi xa không được nhé.</p>\n<p>Dù mang trong mình nhiều công nghệ phải nói là tối tân, đáng gờm bậc nhất hiện nay nhưng xe vẫn có đầy đủ sàn để chân rộng rãi, yên xe thoải mái, cốp xe dưới yên xe thì rất to có thể chứa được ít nhất là một mũ bảo hiểm và áo khoác, phù hợp cho cả những dịp muốn đi xa thì chứa đồ vào đây rất gọn. Đuôi xe cũng có phần đèn hậu sáng rõ với bố trí khá đơn giản. Và để hổ trợ dẫn dắt, xoay trở đầu xe khi vào khu vực nội thành đông dân cư thì chắc chắn không thể không nhắc đến chiếc chân chống chịu lực rất tốt cùng phân tay lái siêu êm.</p>\n<p>Với nhiều công nghệ độc đáo, tối tân nhất hiện nay, ngoại hình lại ổn, động cơ vận hành mạnh mẽ thì không có lý do gì để không chọn mua xe máy điện Sundiro Honda H12 khi có nhu cầu mua xe máy điện cả. Xe hiện được bán tại chuỗi cửa hàng Yên Thoa – một trong top 4 chuỗi cửa hàng bán xe điện uy tín nhất toàn quốc. Nếu muốn xem mẫu trưng bày hay mua ngay thì bạn nên đến các cửa hàng của chúng tôi để xem xe nhé.</p>\n&nbsp;', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda Joker - Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 17500000, 17500000, '/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-joker-chinh-hang-honda-nhat-ban-6.webp\"]', '[]', '[]', '[]', '<p>NĂM 2020 HONDA QUAY TRỞ LẠI THỊ TRƯỜNG VIỆT NAM VỚI NHIỀU MẪU XE MÁY ĐIỆN ĐÌNH ĐÁM HONDA VSUN, MONO, JOKER ... VỚI MỨC GIÁ ƯU ĐÃI LỚN GIẢM 10.000.000 Đ / 1 xe ĐỂ GIỚI THIỆU SẢN PHẨM ĐẾN NGƯỜI TIÊU DÙNG VIỆT NAM.</p>\n<p>Xuất hiện từ năm 2013 với những dòng sản phẩm cực kỳ chất lượng đến kinh ngạc, thực ra Honda thì đã quá nổi tiếng ở Việt Nam và được rất nhiều người yêu thích vì sự bền bỉ . Đúng như vậy Yên Thoa đã kinh doanh những sản phẩm của hãng Honda đến 10 năm nay số lượng xe bán ra trên 20.000 chiếc nhưng cho đến tận bây giờ chưa thấy 1 chiếc nào quay lại bảo hành. Nhưng những chiếc xe máy điện Honda rất kén khách hàng vì nó quá đắt mà theo suy nghĩ chung của mọi người những năm 2013-2015 thì chỉ mua để đi tạm vài năm chứ không có định hướng lâu dài.</p>', '<p><strong><em>NĂM 2020 HONDA QUAY TRỞ LẠI THỊ TRƯỜNG VIỆT NAM VỚI NHIỀU MẪU&nbsp;XE MÁY ĐIỆN&nbsp;ĐÌNH ĐÁM HONDA VSUN, MONO, JOKER ... VỚI MỨC GIÁ ƯU ĐÃI LỚN GIẢM 10.000.000 Đ / 1 xe ĐỂ GIỚI THIỆU SẢN PHẨM ĐẾN NGƯỜI TIÊU DÙNG VIỆT NAM.</em></strong></p>\n<em>Xe máy điện Honda đã trở lại Việt Nam - Honda VSUN V2</em>\n<p>Xuất hiện từ năm 2013 với những dòng sản phẩm cực kỳ chất lượng đến kinh ngạc, thực ra Honda thì đã quá nổi tiếng ở Việt Nam và được rất nhiều người yêu thích vì sự bền bỉ . Đúng như vậy Yên Thoa đã kinh doanh những sản phẩm của hãng Honda đến 10 năm nay số lượng xe bán ra trên 20.000 chiếc nhưng cho đến tận bây giờ chưa thấy 1 chiếc nào quay lại bảo hành. Nhưng những chiếc&nbsp;<strong>xe máy điện Honda</strong>&nbsp;rất kén khách hàng vì nó quá đắt mà theo suy nghĩ chung của mọi người những năm 2013-2015 thì chỉ mua để đi tạm vài năm chứ không có định hướng lâu dài.&nbsp;</p>\n<em>Xe máy điện Honda Joker</em>\n<p>Năm 2016 Honda ra mắt sản phẩm Honda Prinz đẹp hoàn hảo đến từng chi tiết và rất được lòng mọi người, nhưng tại thời điểm đó với mức giá không hề dễ chịu chút nào 28.500.000 đ thì honda prinz có thể nói là chỉ dành cho giới nhà giàu chứ không phải là đại đa số người dân ở Việt Nam.</p>\nXe máy điện Honda Q2\n<p>Với Quyết tâm đi vào được thị trường Xe Máy Điện tại Việt Nam và các nước khu vực Châu Á mà ngon nhất là đất nước Tỷ Dân Trung Quốc, 2019 Honda tiếp tục nâng cấp bản Honda Prinz thành xe máy điện Honda Vsun V2 với ngoại hình giống hệt nhưng toàn bộ hệ thống điện tử trên xe được trang bị công nghệ tiên tiến hiện đại hơn giúp xe vận hành nhẹ nhàng êm ái hơn. Nhưng với giá cũng không được thực sự gọi là tốt cho lắm vẫn rơi vào tầm 25 triệu đồng và hãng vẫn quy định mức giá bán chung là 28.500.000 đ thì nó vẫn là 1 dòng xe kén khách không phải vì kiểu dáng, chất lượng hay bất kể 1 điểm gì vì xe của Honda thì không thể chê được điểm nào nhưng tại gía thành của nó cao quá không thể tới tay đại đa số người tiêu dùng.</p>\n<p><em>&gt;&gt;&gt;Ngoài ra bạn có thể tham khảo thêm sản phẩm:&nbsp;<strong>Xe máy điện Honda Joker</strong></em></p>\nXe tay ga 50cc Honda Toyday&nbsp;\n&nbsp;\n<p>Đầu năm 2020 Yên Thoa quyết tâm chơi lớn 1 lần, nhập trên 3000 chiếc xe máy điện các loại của Honda và Ra mắt thêm 1 số sản phẩm&nbsp;<strong>xe máy 50cc nhập khẩu</strong>&nbsp;chính hãng từ Honda Nhật bản sản xuất cho thị trường nội địa là Honda Today. Và chúng tôi sẽ áp dụng mức giá gây sốc toàn phần giảm giá 10.000.000 đ / 1 sản phẩm và áp dụng bước 1 chấp nhận lỗ lớn bán sản phẩm với mức giá không thể tin nổi 18.000.000 đ cho Honda Vsun V2 - Và từ 13 đến 16 triệu cho các sản phẩm loại khác cùng của chính hãng Honda như Joker, Mono và 38 triệu đồng cho chiếc xe máy honda today là 1 mức gía ở Việt Nam không ai có thể bán được.</p>\n<em>Xe máy điện Honda Mono</em>\n<em><br></em>\n<h2><strong><em>Top 8 lý do nên chọn mua xe điện, xe ga 50cc của Honda</em></strong></h2>\n<p>1 : Về kiểu dáng thì Honda Vsun V2 ăn đứt tất cả các loại xe khác có mặt trên thị trường</p>\n<p>2 : Về thương hiệu thì các hãng xe điện dù là lớn nhất vẫn chỉ là hạt cát trong xa mạc.</p>\n<p>3 : Về chất lượng bền bỉ kinh khủng, trong 5 năm đầu sử dụng mà các bạn sử dụng xe bị lỗi thì TGXĐ tặng luôn xe. Tất nhiên hãng sản xuất nào cũng có xác xuất nhưng tỷ lệ xe lỗi của honda rất rất nhỏ chỉ 1/100.000 chiếc. Mà với xe điện thì siêu bền bỉ có những chiếc xe TGXĐ sử dụng cho nhân viên đi cứu hộ vứt quăng quật mưa nắng chạy ròng dã suốt ngày đêm mà đến nay 10 năm vẫn bền bỉ với thời gian.</p>\n<em>Xe máy điện Honda Q1</em>\n<em><br></em>\n<p>4 : Về cảm giác lái thì chiếc xe của Honda cực kỳ dễ lái, lái rất êm, mượt và nhẹ nhàng rất thích. Lái xe hàng trăm km mà vẫn thấy thoải mái, và người ta nói vui với nhau rằng nếu chưa dùng thử xe điện của Honda thì chưa biết gì về xe 2 bánh.</p>\n<p>5 : An toàn tuyệt đối vì chiếc xe được thiết kế kiểu xe ga dễ sử dụng, trọng tâm thấp khó đổ xe hơn, tiết kiệm tuyệt đối chạy 1 năm khéo mất 1-200.000 đ tiền điện so với 15 triệu / 1 năm nếu sử dụng xe máy xăng.&nbsp;</p>\n<p>6 : Và chiếc xe này còn có thể dành cho cả nhà sử dụng, rất tiện lợi. Ở Việt Nam mỗi nhà nên có 1 chiếc</p>\n<p>7 : Quãng đường đi được lên tới gần 100km/1 lần sạc nên bạn yên tâm đi thoải mái mà không phải lo hết điện.</p>\n<p>8 : Công nghệ cao , sản xuất chắc chắn, bạn sẽ cảm nhận ngay được 1 chiếc xe tốt khi nhìn thấy, chạm vào, và ngồi lái thử.</p>\n<p><em>Xe đạp điện Honda M8 chính hãng</em></p>\n<p>Yên Thoa CAM KẾT SẢN PHẨM ĐƯỢC NHẬP KHẨU 100% VỚI GIẤY TỜ CHÍNH HÃNG HONDA NHẬT BẢN, ĐẦY ĐỦ GIẤY TỜ NHẬP KHẨU VÀ HOÁ ĐƠN VAT 10% DO NHÀ MÁY HONDA CUNG CẤP. NẾU QUÝ KHÁCH PHÁT HIỆN 1 LINH KIỆN TRÊN XE KHÔNG PHẢI CỦA CHÍNH HÃNG HONDA CTY CHÚNG TÔI XIN ĐỀ QUÝ KHÁCH 1 TỶ ĐỒNG.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda Mono - Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 18500000, 18500000, '/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-mono-chinh-hang-honda-nhat-ban-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Honda Mono là mẫu phương tiện đô thị được Honda Nhật Bản phát triển theo định hướng gọn gàng, dễ sử dụng và phù hợp với nhịp sống hiện đại. Ngay từ cái nhìn đầu tiên, mẫu xe này tạo thiện cảm nhờ kiểu dáng cân đối, vận hành thuần điện và hướng đến sự an toàn trong trải nghiệm hằng ngày. Honda Mono không chạy theo xu hướng phô trương, thay vào đó tập trung vào sự bền bỉ, ổn định và cảm giác lái thân thiện.</p>\n<p>Honda Mono sở hữu thiết kế gọn gàng, phù hợp với môi trường giao thông đông đúc. Kiểu dáng xe thiên về sự tối giản, các đường nét được tiết chế vừa đủ để tạo cảm giác thanh thoát và dễ nhìn. Tổng thể xe không quá to, giúp người lái linh hoạt khi di chuyển trong các con phố hẹp hoặc khu dân cư đông người.</p>', '<p><strong>Xe máy điện Honda Mono</strong> là mẫu phương tiện đô thị được Honda Nhật Bản phát triển theo định hướng gọn gàng, dễ sử dụng và phù hợp với nhịp sống hiện đại. Ngay từ cái nhìn đầu tiên, mẫu xe này tạo thiện cảm nhờ kiểu dáng cân đối, vận hành thuần điện và hướng đến sự an toàn trong trải nghiệm hằng ngày. Honda Mono không chạy theo xu hướng phô trương, thay vào đó tập trung vào sự bền bỉ, ổn định và cảm giác lái thân thiện.</p>\n\n<h2><br><strong>Thiết kế tổng thể nhỏ gọn, tối ưu cho đô thị</strong></h2>\n<p><br><strong>Honda Mono</strong> sở hữu thiết kế gọn gàng, phù hợp với môi trường giao thông đông đúc. Kiểu dáng xe thiên về sự tối giản, các đường nét được tiết chế vừa đủ để tạo cảm giác thanh thoát và dễ nhìn. Tổng thể xe không quá to, giúp người lái linh hoạt khi di chuyển trong các con phố hẹp hoặc khu dân cư đông người.</p>\n<p><br>Tư thế ngồi trên Honda Mono được tính toán hợp lý, tạo cảm giác thoải mái khi sử dụng trong thời gian dài. Yên xe có độ cao vừa phải, giúp người lái dễ chống chân và kiểm soát xe tốt hơn khi dừng đỗ. Ghi đông đặt ở vị trí tự nhiên, hạn chế mỏi tay khi di chuyển liên tục.</p>\n\n<p><br>Ngoại hình của <strong>Honda Mono</strong> phù hợp với nhiều đối tượng sử dụng khác nhau, từ học sinh, sinh viên đến người đi làm. Thiết kế trung tính giúp xe dễ tiếp cận, ít lỗi mốt và phù hợp với nhiều phong cách sử dụng trong cuộc sống hằng ngày.</p>\n<h2><br><strong>Động cơ điện 1200W, khả năng vận hành</strong></h2>\n<p><br><strong>Xe máy điện Honda Mono</strong> được trang bị động cơ điện công suất 1200W, mang lại khả năng vận hành ổn định trong điều kiện giao thông đô thị. Động cơ hoạt động êm, phản hồi ga mượt và hạn chế tối đa tiếng ồn khi di chuyển. Đây là điểm cộng rõ rệt khi sử dụng xe trong khu dân cư hoặc vào ban đêm.</p>\n<p><br>Honda Mono sử dụng cơ chế vận hành tự động hoàn toàn, giúp người dùng dễ làm quen ngay từ lần đầu sử dụng. Việc điều khiển xe không đòi hỏi nhiều thao tác phức tạp, phù hợp với cả người mới chuyển sang sử dụng xe điện. Cảm giác lái nhẹ nhàng, dễ kiểm soát trong các tình huống dừng – chạy liên tục.</p>\n\n<p><br>Vận tốc tối đa của xe đạt khoảng 60 km/h, đáp ứng tốt nhu cầu di chuyển hằng ngày trong thành phố. Ở dải tốc độ trung bình, xe duy trì độ ổn định tốt, không tạo cảm giác rung lắc hay mất cân bằng khi chạy đều ga.</p>\n<h2><br><strong>Khả năng di chuyển, hiệu suất sử dụng điện</strong></h2>\n<p><br><strong>Honda Mono</strong> có khả năng di chuyển khoảng 70 km sau mỗi lần sạc đầy trong điều kiện tiêu chuẩn. Quãng đường này đủ đáp ứng nhu cầu đi học, đi làm gần hoặc di chuyển nội đô trong nhiều ngày liên tiếp. Người dùng không cần sạc xe quá thường xuyên, giúp tiết kiệm thời gian sử dụng.</p>\n<p><br>Hệ thống sạc của xe được thiết kế an toàn, có khả năng tự động ngắt khi ắc quy đầy. Điều này giúp hạn chế tình trạng quá tải, đồng thời góp phần kéo dài tuổi thọ của hệ thống điện. Người dùng có thể yên tâm sạc xe qua đêm mà không lo phát sinh rủi ro.</p>\n<p><br>Với mức tiêu thụ điện hợp lý, Honda Mono giúp giảm chi phí vận hành so với các dòng xe sử dụng nhiên liệu truyền thống. Đây là lợi thế rõ rệt trong bối cảnh người dùng ngày càng quan tâm đến yếu tố tiết kiệm và thân thiện với môi trường.</p>\n<h2><br><strong>Hệ thống ắc quy, trọng lượng, tải trọng</strong></h2>\n<p><br>Xe sử dụng bộ ắc quy dung lượng 48V – 20Ah, cấu hình phổ biến trên các dòng <strong>xe máy điện</strong> đô thị. Nguồn điện được cung cấp ổn định, đảm bảo xe vận hành mượt mà trong suốt quá trình sử dụng. Việc bảo dưỡng và thay thế ắc quy cũng khá thuận tiện.</p>\n<p><br>Trọng lượng xe khoảng 97 kg, mang lại cảm giác đầm chắc khi vận hành nhưng vẫn đủ nhẹ để người dùng thao tác linh hoạt. Việc dắt xe, quay đầu hoặc di chuyển trong không gian hẹp không gây nhiều khó khăn, kể cả với người dùng nữ.</p>\n<p><br>Tải trọng tối đa lên đến 180 kg cho thấy Honda Mono có khả năng chịu tải tốt trong phân khúc. Xe vẫn giữ được sự ổn định khi chở thêm người hoặc mang theo đồ dùng cá nhân phục vụ sinh hoạt hằng ngày.</p>\n<h2><br><strong>Hệ thống phanh, bánh xe và độ an toàn</strong></h2>\n<p><br><strong>Honda Mono</strong> được trang bị phanh đĩa cho bánh trước và bánh sau, giúp nâng cao hiệu quả kiểm soát tốc độ. Lực phanh phản hồi rõ ràng, dễ điều chỉnh và phù hợp với điều kiện giao thông đông đúc. Khi cần giảm tốc đột ngột, xe cho cảm giác dừng gọn và ổn định.</p>\n<p><br>Bánh xe có kích thước phù hợp với thiết kế tổng thể, giúp xe bám đường tốt hơn khi di chuyển trên mặt đường bằng phẳng. Sự cân đối giữa bánh trước và bánh sau mang lại cảm giác lái chắc chắn, hạn chế hiện tượng trượt bánh khi vào cua nhẹ.</p>\n<p><br>Tổng thể hệ thống an toàn của Honda Mono hướng đến sự đơn giản và hiệu quả. Các trang bị được lựa chọn vừa đủ để phục vụ nhu cầu di chuyển hằng ngày, ưu tiên cảm giác dễ kiểm soát và giảm rủi ro trong quá trình sử dụng.</p>\n<h2><br><strong>Tiện ích sử dụng, giá trị thương hiệu Honda</strong></h2>\n<p><br><strong>Honda Mono</strong> được trang bị các tiện ích cơ bản phục vụ nhu cầu sử dụng thường ngày. Các chi tiết trên xe được hoàn thiện gọn gàng, chắc chắn, mang lại cảm giác yên tâm khi vận hành trong thời gian dài. Xe đi kèm các phụ kiện cần thiết như sạc và gương chiếu hậu.</p>\n<p><br>Chế độ bảo hành thể hiện cam kết chất lượng từ thương hiệu Honda Nhật Bản. Khung xe được bảo hành 3 năm, động cơ 3 năm và ắc quy 1 năm, giúp người dùng an tâm hơn trong quá trình sử dụng lâu dài.</p>\n<p><br>Giá trị lớn nhất của Honda Mono nằm ở sự ổn định và uy tín thương hiệu. Với kinh nghiệm lâu năm trong lĩnh vực phương tiện di chuyển, Honda mang đến một mẫu xe điện hướng đến trải nghiệm bền bỉ, dễ sử dụng và phù hợp với nhiều đối tượng người dùng.</p>\n<p><br><strong>Xe máy điện Honda Mono</strong> là lựa chọn phù hợp cho người dùng đang tìm kiếm một phương tiện di chuyển thuần điện, gọn gàng và ổn định trong môi trường đô thị. Thiết kế tối giản, động cơ 1200W vận hành êm và quãng đường di chuyển hợp lý mang lại giá trị sử dụng thực tế. Các trang bị an toàn cùng chính sách bảo hành rõ ràng giúp người dùng yên tâm trong quá trình sử dụng. Với dấu ấn từ Honda Nhật Bản, Mono là mẫu xe điện đáng cân nhắc trong phân khúc phổ thông.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda Q1 - Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 13800000, 13800000, '/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q1-chinh-hang-honda-nhat-ban-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Honda Q1 đại diện cho hướng đi thực tế và bền vững trong phân khúc xe điện đô thị. Sản phẩm được nhập khẩu nguyên chiếc từ Nhật Bản, đảm bảo tính đồng bộ cao về kỹ thuật lẫn chất lượng hoàn thiện. Ngay từ những thông số ban đầu, Honda Q1 đã cho thấy định hướng tập trung vào độ ổn định và sự an tâm khi sử dụng lâu dài. Đây là mẫu xe phù hợp với người dùng đề cao trải nghiệm êm ái và tính bền bỉ theo thời gian.</p>\n<p>Honda Q1 sở hữu kiểu dáng nhỏ gọn, thân thiện với người dùng đô thị. Kích thước tổng thể 1595mm x 680mm x 1025mm giúp xe linh hoạt khi di chuyển trong đường phố đông đúc. Nhờ đó, việc quay đầu hay luồn lách trong hẻm nhỏ trở nên nhẹ nhàng và dễ kiểm soát hơn.</p>', '<p><strong>Xe máy điện Honda Q1</strong> đại diện cho hướng đi thực tế và bền vững trong phân khúc xe điện đô thị. Sản phẩm được nhập khẩu nguyên chiếc từ Nhật Bản, đảm bảo tính đồng bộ cao về kỹ thuật lẫn chất lượng hoàn thiện. Ngay từ những thông số ban đầu, Honda Q1 đã cho thấy định hướng tập trung vào độ ổn định và sự an tâm khi sử dụng lâu dài. Đây là mẫu xe phù hợp với người dùng đề cao trải nghiệm êm ái và tính bền bỉ theo thời gian.</p>\n\n<h2><br><strong>Dấu ấn thiết kế gọn gàng, dễ làm quen</strong></h2>\n<p><br><strong>Honda Q1</strong> sở hữu kiểu dáng nhỏ gọn, thân thiện với người dùng đô thị. Kích thước tổng thể 1595mm x 680mm x 1025mm giúp xe linh hoạt khi di chuyển trong đường phố đông đúc. Nhờ đó, việc quay đầu hay luồn lách trong hẻm nhỏ trở nên nhẹ nhàng và dễ kiểm soát hơn.</p>\n<p><br>Đường nét thân xe được xử lý mềm mại, thiên về sự tối giản và cân đối. Phần đầu xe không phô trương nhưng vẫn đủ tạo điểm nhấn nhờ bố cục hài hòa. Thiết kế này mang lại cảm giác gần gũi, không gây “ngợp” cho người mới sử dụng xe điện.</p>\n\n<p><br>Bảng màu đa dạng như bạc, đen, hồng đỏ, trắng, vàng, xanh lá và xanh da trời mang đến nhiều lựa chọn cá nhân hóa. Mỗi gam màu đều được hoàn thiện gọn gàng, giữ được vẻ thanh lịch vốn có của Honda. Nhờ đó, Q1 dễ dàng phù hợp với nhiều độ tuổi và phong cách khác nhau.</p>\n<h2><br><strong>Động cơ 1200W cho trải nghiệm vận hành mượt mà</strong></h2>\n<p><br><strong>Honda Q1</strong> được trang bị động cơ điện công suất 1200W, 3 pha, một chiều, sử dụng công nghệ không chổi than. Cấu hình này giúp xe vận hành ổn định và hạn chế ma sát trong quá trình hoạt động. Nhờ đó, động cơ duy trì hiệu suất tốt trong thời gian dài sử dụng.</p>\n<p><br>Vận tốc tối đa khoảng 40–50km/h đáp ứng tốt nhu cầu đi lại trong thành phố. Xe tăng tốc đều, không gây cảm giác giật hay hụt ga khi khởi hành. Điều này đặc biệt phù hợp với người cần sự an toàn và kiểm soát tốc độ tốt.</p>\n\n<p><br>Hệ thống vận hành tự động giúp người lái thao tác đơn giản hơn mỗi ngày. Chỉ cần vặn ga, <strong>xe máy điện</strong> phản hồi ngay với cảm giác mượt mà và dễ chịu. Trải nghiệm lái vì thế trở nên nhẹ nhàng, phù hợp với nhịp sống đô thị hiện đại.</p>\n<h2><br><strong>Khả năng di chuyển và tối ưu năng lượng</strong></h2>\n<p><br><strong>Honda Q1</strong> có thể di chuyển quãng đường lên đến khoảng 80km sau mỗi lần sạc đầy. Con số này đáp ứng trọn vẹn nhu cầu đi học, đi làm hay di chuyển cá nhân trong ngày. Người dùng có thể yên tâm sử dụng mà không phải sạc xe quá thường xuyên.</p>\n<p><br>Xe sử dụng bộ ắc quy gồm 5 bình 20A, được thiết kế để cung cấp nguồn điện ổn định. Khả năng duy trì điện áp tốt giúp xe vận hành đều ngay cả khi tải nặng.</p>\n<p><br>Thời gian sạc đầy khoảng hơn 10 giờ, phù hợp với thói quen sạc ban đêm. Xe được tích hợp chế độ tự ngắt khi ắc quy đầy nhằm tăng độ an toàn. Đây là chi tiết nhỏ nhưng mang lại sự yên tâm rõ rệt cho người sử dụng.</p>\n<h2><br>Hệ thống an toàn cho cảm lái lái yên tâm</h2>\n<p><br>Honda Q1 được trang bị phanh đĩa phía trước kết hợp phanh cơ phía sau. Cấu hình này mang lại khả năng hãm tốc ổn định trong điều kiện giao thông đô thị. Cảm giác phanh rõ ràng giúp người lái xử lý tình huống linh hoạt hơn. Nhờ khả năng kiểm soát lực phanh tốt, người dùng dễ chủ động khi gặp các tình huống bất ngờ.</p>\n<p><br>Lốp không săm là trang bị đáng giá trên mẫu xe này. Khi gặp vật sắc nhọn, lốp có xu hướng xì hơi chậm, hạn chế nguy cơ mất lái đột ngột. Mức độ an toàn trong quá trình sử dụng hằng ngày vì thế được nâng lên rõ rệt. Trang bị này đặc biệt phù hợp với điều kiện mặt đường đô thị thường xuyên thay đổi.</p>\n<p><br>Trọng lượng xe khoảng 94kg kết hợp tải trọng lên đến 200kg tạo nên sự đầm chắc khi vận hành. Xe giữ được độ ổn định tốt ngay cả khi chở hai người. Cảm giác lái vì thế trở nên vững vàng và tự tin hơn. Sự cân đối tổng thể giúp xe ít bị chòng chành khi tăng tốc hoặc phanh gấp.</p>\n<h2><br><strong>Tiện ích sử dụng thực tế, thân thiện hằng ngày</strong></h2>\n<p><br><strong>Honda Q1</strong> được thiết kế hướng đến sự đơn giản trong thao tác sử dụng. Các nút điều khiển được bố trí khoa học, dễ quan sát và dễ làm quen. Người dùng có thể nhanh chóng thích nghi chỉ sau thời gian ngắn làm quen. Cách sắp xếp này mang lại cảm giác thân thiện ngay từ lần đầu cầm lái.</p>\n<p><br>Xe đi kèm đầy đủ phụ kiện cần thiết như gương chiếu hậu, bộ sạc chính hãng và khóa báo động chống trộm. Những trang bị này phục vụ trực tiếp cho nhu cầu sử dụng thực tế. Người dùng không cần đầu tư thêm các phụ kiện cơ bản khi mua xe. Mọi chi tiết đều được đồng bộ để đảm bảo khả năng vận hành ổn định lâu dài.</p>\n<p><br>Tính năng tự ngắt sạc khi ắc quy đầy giúp bảo vệ hệ thống điện hiệu quả. Việc kiểm soát dòng sạc tốt giúp hạn chế tình trạng quá tải. Tuổi thọ của bộ ắc quy nhờ đó được duy trì ổn định hơn theo thời gian. Người sử dụng có thể an tâm sạc xe qua đêm trong sinh hoạt hằng ngày.</p>\n<h2><br><strong>Uy tín thương hiệu, chính sách bảo hành</strong></h2>\n<p><br><strong>Honda Q1</strong> được nhập khẩu nguyên chiếc từ Nhật Bản, đảm bảo tiêu chuẩn chất lượng khắt khe. Thương hiệu Honda từ lâu đã tạo dựng được niềm tin lớn với người tiêu dùng Việt. Điều này giúp Q1 có lợi thế rõ rệt về độ tin cậy.</p>\n<p><br>Chính sách bảo hành được công bố rõ ràng với khung xe 3 năm, động cơ 2 năm và ắc quy 1 năm. Thời gian bảo hành này phản ánh sự tự tin của nhà sản xuất về chất lượng sản phẩm. Người dùng vì thế có thể an tâm hơn trong quá trình sử dụng lâu dài.</p>\n<p><br>Sự kết hợp giữa thông số hợp lý, độ hoàn thiện cao và giá trị thương hiệu tạo nên sức hút riêng cho Honda Q1. Mẫu xe này phù hợp với người ưu tiên tính ổn định và bền bỉ. Đây là lựa chọn đáng cân nhắc trong phân khúc xe máy điện đô thị.</p>\n<p><br><strong>Xe may dien Honda Q1</strong> mang đến giải pháp di chuyển ổn định và thân thiện cho môi trường đô thị. Thiết kế gọn gàng, động cơ 1200W mượt mà cùng khả năng di chuyển hợp lý giúp xe đáp ứng tốt nhu cầu hằng ngày. Khi đặt trong tổng thể thương hiệu và chính sách bảo hành rõ ràng, Honda Q1 thể hiện giá trị sử dụng lâu dài. Đây là mẫu xe phù hợp cho người tìm kiếm sự an tâm và bền vững.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda Q2 - Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 19800000, 19800000, '/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-q2-chinh-hang-honda-nhat-ban-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Honda Q2, mẫu xe được sản xuất dưới sự giám sát chất lượng nghiêm ngặt của Honda Nhật Bản, là đại diện tiêu biểu cho sự chuyển đổi giao thông cá nhân hướng tới năng lượng sạch. Sản phẩm này tập trung vào việc mang lại trải nghiệm di chuyển tin cậy, an toàn và bền bỉ, đáp ứng nhu cầu đi lại hàng ngày trong khu vực thành phố.</p>\n<p>Thay vì chỉ là một phương tiện di chuyển, Honda Q2 được thiết kế để trở thành một tài sản lâu dài, sở hữu sự kết hợp tuyệt vời giữa công nghệ động cơ hiệu suất cao và hệ thống quản lý năng lượng được tối ưu hóa, khẳng định đẳng cấp từ một thương hiệu xe máy hàng đầu thế giới.</p>', '<p><strong>Xe máy điện Honda Q2</strong>, mẫu xe được sản xuất dưới sự giám sát chất lượng nghiêm ngặt của Honda Nhật Bản, là đại diện tiêu biểu cho sự chuyển đổi giao thông cá nhân hướng tới năng lượng sạch. Sản phẩm này tập trung vào việc mang lại trải nghiệm di chuyển tin cậy, an toàn và bền bỉ, đáp ứng nhu cầu đi lại hàng ngày trong khu vực thành phố.</p>\n\n<p><br>Thay vì chỉ là một phương tiện di chuyển, Honda Q2 được thiết kế để trở thành một tài sản lâu dài, sở hữu sự kết hợp tuyệt vời giữa công nghệ động cơ hiệu suất cao và hệ thống quản lý năng lượng được tối ưu hóa, khẳng định đẳng cấp từ một thương hiệu xe máy hàng đầu thế giới.</p>\n<h2><br><strong>Sức mạnh ẩn sau 1200W</strong></h2>\n<p><br><strong>Honda Q2</strong> được trang bị động cơ điện công suất 1200W, sử dụng công nghệ 3 pha, một chiều không chổi than. Đây là loại động cơ có hiệu suất chuyển đổi năng lượng vượt trội, giảm thiểu tối đa hao phí điện năng trong quá trình vận hành. Công suất 1200W cung cấp đủ lực kéo cần thiết để xe dễ dàng khởi động, tăng tốc mượt mà và vượt qua các đoạn dốc hay chở tải nặng một cách hiệu quả, khác biệt rõ rệt so với các dòng xe điện công suất thấp thông thường.</p>\n<p><br>Cấu trúc động cơ không chổi than giúp loại bỏ ma sát cơ học, từ đó xe vận hành vô cùng êm ái và ít tạo ra tiếng ồn. Độ bền của động cơ cũng được tăng cường đáng kể do không có các bộ phận cơ khí dễ mài mòn như chổi than. Đặc tính này làm giảm nhu cầu bảo dưỡng định kỳ, tiết kiệm chi phí vận hành cho người sử dụng trong suốt thời gian dài. Động cơ còn được hãng cam kết bảo hành lên đến 2 năm, chứng minh cho sự tự tin vào chất lượng sản xuất tại Nhật Bản.</p>\n\n<p><br>Mặc dù có công suất lớn, động cơ 1200W vẫn cho phép xe đạt tốc độ tối đa từ 40 đến 50km/h. Phạm vi tốc độ này là hợp lý và an toàn cho việc di chuyển trong các khu vực đông đúc, đảm bảo người lái có thể duy trì sự linh hoạt cần thiết mà vẫn tuân thủ các quy tắc giao thông đô thị. Hệ thống vận hành được thiết lập ở chế độ tự động hoàn toàn, giúp mọi người, từ học sinh, sinh viên đến người lớn tuổi, đều có thể dễ dàng làm quen và điều khiển xe.</p>\n<h2><br><strong>80km – Tầm vóc cho hành trình dài</strong></h2>\n<p><br>Một trong những điểm mạnh nhất của <strong>Honda Q2</strong> là khả năng di chuyển ấn tượng với quãng đường lên đến 80km sau mỗi lần sạc đầy. Con số này vượt xa mức trung bình của nhiều xe máy điện phổ thông, giúp người dùng an tâm thực hiện các chuyến đi xa hơn, hoặc sử dụng xe liên tục trong nhiều ngày mà không cần phải sạc lại thường xuyên, giảm bớt sự lo lắng về năng lượng.</p>\n<p><br>Để đạt được hiệu suất này, xe sử dụng hệ thống 5 ắc quy 20A. Việc lựa chọn ắc quy dung lượng lớn cho thấy Honda đã tối ưu hóa khả năng tích trữ điện năng, đảm bảo nguồn cung cấp ổn định cho động cơ 1200W. Bộ ắc quy được đặt ở vị trí an toàn, được bảo vệ khỏi các yếu tố môi trường bên ngoài, góp phần kéo dài tuổi thọ sử dụng và duy trì hiệu suất năng lượng qua thời gian.</p>\n\n<p><br>Tuy nhiên, do sử dụng hệ thống ắc quy axit-chì dung lượng cao, thời gian sạc đầy của Honda Q2 khá dài, dao động từ 10 đến 12 tiếng. Người dùng nên tận dụng thời gian nghỉ buổi tối để nạp đầy pin cho xe, đảm bảo xe luôn sẵn sàng cho hành trình vào ngày hôm sau. Hệ thống sạc còn được trang bị tính năng tự động ngắt khi ắc quy đầy, một tính năng an toàn cơ bản giúp bảo vệ ắc quy khỏi hư hỏng do quá tải nhiệt hoặc quá áp.</p>\n<h2><br><strong>Vóc dáng Nhật, đường nét tinh giản</strong></h2>\n<p><br><strong>Honda Q2</strong> sở hữu kích thước tổng thể cân đối với Chiều dài x Chiều rộng x Chiều cao là 1595mm x 680mm x 1025mm. Kích thước này mang lại sự ổn định cần thiết khi xe chạy tốc độ cao, đồng thời vẫn giữ được sự gọn gàng, giúp người lái dễ dàng luồn lách trong điều kiện giao thông đông đúc. Thiết kế xe theo phong cách tối giản, thừa hưởng sự tinh tế đặc trưng của các sản phẩm Honda.</p>\n<p><br>Trọng lượng <strong>xe máy điện</strong> đạt 94kg, đây là một trọng lượng vừa phải đối với một chiếc xe máy điện, tạo cảm giác đầm chắc khi lái. Trọng lượng này giúp xe bám đường tốt hơn so với các xe đạp điện nhẹ cân khác, mang lại cảm giác an toàn và kiểm soát tốt hơn, đặc biệt khi vào cua hoặc phanh gấp. Thiết kế của Q2 không chỉ hướng đến hiệu suất mà còn đảm bảo tính thẩm mỹ, phù hợp với gu của nhiều đối tượng khách hàng.</p>\n<p><br>Thiết kế ngoại hình của Q2 có nhiều màu sắc cơ bản để lựa chọn, giúp người dùng dễ dàng lựa chọn màu sắc theo sở thích cá nhân. Đường kính bánh xe là 80/100-10, đây là kích thước lốp tiêu chuẩn, đảm bảo khả năng vận hành ổn định trên nhiều loại địa hình. Sự kết hợp giữa vóc dáng cân đối và các chi tiết được hoàn thiện tỉ mỉ tạo nên một tổng thể hài hòa và chất lượng.</p>\n<h2><br><strong>Kiểm soát an toàn cùng phanh kép CBS</strong></h2>\n<p><br><strong>Honda Q2</strong> được trang bị hệ thống phanh cao cấp nhằm đảm bảo an toàn tối đa cho người lái. Xe sử dụng phanh đĩa cho bánh trước, cung cấp lực hãm mạnh mẽ và chính xác, giúp giảm tốc độ nhanh chóng và hiệu quả. Phanh đĩa có khả năng tản nhiệt tốt, duy trì hiệu suất ổn định ngay cả khi phải phanh liên tục.</p>\n<p><br>Điểm đặc biệt là hệ thống phanh sau được trang bị công nghệ Phanh CBS. Đây là một hệ thống phanh kết hợp, khi người lái bóp phanh sau, hệ thống sẽ tự động phân bổ một phần lực phanh đến bánh trước. Cơ chế này giúp tối ưu hóa hiệu suất phanh, giảm nguy cơ trượt bánh hoặc mất kiểm soát, đặc biệt quan trọng khi người lái phản xạ không kịp trong các tình huống bất ngờ.</p>\n<p><br>Xe sử dụng loại lốp không săm, một trang bị tiêu chuẩn trên các dòng xe máy điện hiện đại. Lốp không săm có độ bền cao, an toàn hơn vì khi cán phải vật nhọn sẽ không bị xì hơi đột ngột như lốp có săm. Điều này giúp người lái có đủ thời gian để tìm đến nơi sửa chữa an toàn. Sự kết hợp giữa phanh đĩa trước, phanh CBS sau và lốp không săm tạo nên một lớp bảo vệ toàn diện cho người sử dụng trong mọi điều kiện di chuyển.</p>\n<h2><br><strong>Sự tiện dụng của 200kg tải trọng</strong></h2>\n<p><br>Khả năng chịu tải của Honda Q2 lên đến 200kg, một con số ấn tượng đối với một chiếc <strong>xe máy điện</strong> có kích thước nhỏ gọn. Mức tải trọng lớn này giúp xe có thể chở thoải mái hai người lớn cùng hành lý mà vẫn đảm bảo hiệu suất vận hành ổn định. Đây là một lợi thế lớn, giúp xe không chỉ phục vụ nhu cầu đi lại cá nhân mà còn đáp ứng tốt các hoạt động chở người, chở đồ cho gia đình.</p>\n<p><br>Ngoài tải trọng lớn, tính tiện dụng của <strong>Q2</strong> còn được thể hiện qua các chi tiết thiết kế thông minh. Xe được trang bị đầy đủ các phụ kiện cần thiết như sạc và khóa báo động chống trộm, tăng cường tính an toàn khi dừng đỗ. Khóa chống trộm là một tính năng thiết thực, giúp người dùng an tâm hơn khi gửi xe ở nơi công cộng, giảm thiểu rủi ro mất cắp.</p>\n<p><br>Vận tốc tối đa 40-50km/h mang lại tính linh hoạt cao trong môi trường giao thông đô thị. Tốc độ này đủ nhanh để hòa vào dòng chảy xe cộ mà vẫn đảm bảo tiết kiệm năng lượng. Trọng lượng 94kg của xe cũng góp phần vào tính tiện dụng, giúp người lái dễ dàng dắt, đẩy hoặc xoay sở xe trong các không gian hẹp như bãi đỗ xe hoặc góc nhà.</p>\n<h2><br><strong>Lời hứa 3 năm, độ tin cậy Honda</strong></h2>\n<p><br><strong>Honda Q2</strong> được nhập khẩu chính hãng từ Nhật Bản, đi kèm là các chính sách bảo hành rõ ràng và minh bạch, khẳng định cam kết về chất lượng sản phẩm. Chính sách hậu mãi này là yếu tố then chốt tạo nên sự an tâm cho người mua khi đầu tư vào một phương tiện giao thông chạy điện.</p>\n<p><br>Khung xe được hưởng chế độ bảo hành dài nhất, lên đến 3 năm. Sự cam kết này cho thấy độ bền và tính ổn định vượt trội của bộ khung chịu lực chính, được chế tạo từ vật liệu chất lượng cao, có khả năng chống chịu tốt dưới các tác động ngoại cảnh và sự mài mòn theo thời gian. Đây là minh chứng rõ ràng cho tiêu chuẩn kỹ thuật hàng đầu của Honda.</p>\n<p><br>Các bộ phận quan trọng khác của xe cũng có thời hạn bảo hành cụ thể: động cơ 2 năm và ắc quy 1 năm. Việc bảo hành động cơ trong thời gian dài là lời khẳng định về công nghệ 1200W đáng tin cậy. Dù ắc quy có thời hạn bảo hành ngắn hơn, đây vẫn là một chính sách tiêu chuẩn đối với linh kiện hao mòn này, cho phép người dùng yên tâm sử dụng trong năm đầu tiên mà không lo lắng về các sự cố kỹ thuật.</p>\n<p><br><strong>Xe máy điện Honda Q2</strong> là lựa chọn sáng suốt cho người tìm kiếm sự kết hợp giữa chất lượng Nhật Bản và hiệu suất di chuyển điện. Quãng đường 80km vượt trội và động cơ 1200W mạnh mẽ đáp ứng hoàn hảo nhu cầu đi lại hàng ngày. Hệ thống phanh CBS và tải trọng 200kg là các ưu điểm thiết thực, nâng cao cả độ an toàn và tính tiện dụng của xe.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban', 'Xe Máy Điện Honda VSUN V2 - Chính Hãng Honda Nhật Bản', 'honda', '[\"xe-may-dien\"]', 15800000, 15800000, '/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-honda-vsun-v2-chinh-hang-honda-nhat-ban-6.webp\"]', '[]', '[]', '[]', '<p>Honda thương hiệu xe điện rất là nổi tiếng trong những năm trước 2013-2017. Thời điểm đó các dòng xe điện Honda luôn thuộc top 1 các mẫu xe tốt, chất lượng và đặc biệt cực kỳ bền bỉ. Trong năm 2020 hãng Honda đã trở lại thị trường Việt Nam với hàng loạt mẫu xe máy điện cao cấp với nhiều công nghệ mới cải tiến mới. Tiêu biết nhất phải kể đến chiếc xe máy điện Honda Vsun V2.</p>\n<p>Xe máy điện Honda Vsun V2 chính hãng 2020</p>', '<p><em>Honda thương hiệu xe điện rất là nổi tiếng trong những năm trước 2013-2017. Thời điểm đó các dòng xe điện Honda luôn thuộc top 1 các mẫu xe tốt, chất lượng và đặc biệt cực kỳ bền bỉ. Trong năm 2020 hãng Honda đã trở lại thị trường Việt Nam với hàng loạt mẫu xe máy điện cao cấp với nhiều công nghệ mới cải tiến mới. Tiêu biết nhất phải kể đến chiếc&nbsp;<strong>xe máy điện Honda Vsun V2</strong>.</em></p>\n<p><em>Xe máy điện Honda Vsun V2 chính hãng 2020</em></p>\n<h2><strong>THIẾT KẾ XE MÁY ĐIỆN HONDA VSUN V2 CỰC KỲ ĐẲNG CẤP</strong></h2>\n<p>Có thể nói đây là mẫu xe máy điện có kiểu dáng đẹp chất như một dòng xe tay ga vậy. Kế thừa từ ưu điểm dòng Air Blake dòng&nbsp;<strong>Honda Vsun V2</strong>&nbsp;này đã tạo ngay ấn tượng với người mua với cái nhìn đầu tiên.</p>\n<h3><strong>Hệ thống đèn pha siêu to</strong></h3>\n<p>Bộ đèn pha to được viền kim loại sáng bóng nhìn rất hiện đại, sang trọng. Đây là dòng xe máy điện được trang bị tới 3 bóng đèn pha phân biệt ở chính giữa là một bộ đèn Led cho khả năng chiếu xa và ở mép trên chính là 2 bộ đèn trợ sáng giúp xe chiếu sáng tốt khi di chuyển trong điều kiện thiếu sáng.</p>\n<p><em>Hệ thống đèn pha xe điện Honda Vsun V2</em></p>\n<p>Và đặc biệt tất cả đều là công nghệ Led mới nhất của Nhật bản, khả năng chiếu sáng phải nói là cực đỉnh hiếm có mẫu xe máy điện nào trang bị bộ đèn chất như mẫu&nbsp;<strong>Honda Vsun V2</strong>&nbsp;này. Để biết khả năng chiếu sáng của nó mạnh như thế nào tốt như thế nào hãy tham khảo video sau:</p>\n<h3><strong>Phần đầu xe điện Honda Vsun V2 cá tính độc đáo</strong></h3>\n<p>Ở phần trên cùng chính là đầu xe được làm nổi bật một tấm mặt nạ chắn gió trong suốt cực bắt mắt. Và trên phần mặt nạ này được in lên thương hiệu Honda. Đây cũng là điểm giúp bạn nhận biết xe nào fake xe nào chính hãng. Vì logo honda này được in trực tiếp lên chiếc mặt nạ chắn gió nên bạn không thể bóc ra được.</p>\n<p><em>Phần đầu thiết kế độc đáo mới mẻ</em></p>\n<p>Ngoài ra dưới phần tay lái chính là hệ thống xi nhan trước khá lấp lánh giúp bạn dễ dàng di chuyển và điều khiển xe hơn rất nhiều.</p>\n<h3><strong>Dàn áo, khung xe máy điện rất bền bỉ cao cấp</strong></h3>\n<p>Honda được biết đến với ưu điểm và sự bền bỉ lâu dài với thời gian. Hầu hết các mẫu&nbsp;<em><strong>xe điện Honda</strong></em>&nbsp;trước đây đều có độ bền cực cao. Và ở phiên bản&nbsp;<strong>xe máy điện Honda Vsun V2</strong>&nbsp;này cũng không ngoại lệ thậm chí còn được cải tiến tốt hơn nữa.</p>\n<p><em>Xe máy điện Honda Vsun V2 siêu bền</em></p>\n<p>Minh chứng tốt nhất ở đây chính là chiếc Honda Prinz là phiên bản trước của dòng&nbsp;<strong>Honda Vsun V2</strong>&nbsp;này đã được Yên Thoa sử dụng làm phương tiện cứu hộ trong suốt gần 10 năm qua mà vẫn hoạt động tốt. Đi mưa, đi nắng chợ acquy nặng suốt ngày mà trong 10 năm sử dụng xe vẫn hoạt động tốt chưa 1 lần bị gãy khung càng gì cả. Nếu như với các dòng xe khác thì tầm 2-3 năm tốt thì 5 năm khung càng sẽ xuống cấp không còn chắc chắn nữa.</p>\n<p><em>Hiện trạng mẫu xe điện Honda Prinz hiện nay</em></p>\n<p>Vì thế từ khung càng xe được làm từ hợp kim cao cấp chống gỉ dựa trên công nghệ mới nhất từ Nhật Bản. Cùng dàn áo làm từ nhựa ABS tổng hợp chịu và đập tốt, thích ứng tốt các điều kiện khắc nghiệt của thời tiết. Do đó độ bền của&nbsp;<strong>xe máy điện Honda Vsun V2</strong>&nbsp;lên tới 5-10 năm là điều rất hiển nhiên.</p>\n<p><em>Dàn áo xe máy điện Honda Vsun V2 chất lượng cao</em></p>\n<h2><strong>ĐỒNG HỒ ĐIỆN TỬ HIỆN THỊ SẮC NÉT TO RÕ CÙNG CỤM CÔNG TẮC CHUẨN KHÔNG CẦN CHỈNH</strong></h2>\n<p>Nhìn lướt qua thì bạn có thể thấy tay lái thiết kế rất hiện đại thời thượng. Kết hợp với cụm công tắc chia đều 2 bên và chính giữa là một chiếc đồng hồ điện tử hiển thị to rõ nét.</p>\n<h3><strong>Về chiếc đồng điện tử:</strong></h3>\n<p>Bạn có thể dễ dàng thấy được mọi thông số từ vận tốc mức pin, đèn xi nhan thậm chí cả quãng đường đã đi được của xe nữa. Điều đáng nói nhất là chiếc đồng hồ này không khác gì với các dòng xe máy tay ga cao cấp của Honda cả. Đi nắng, trời tối thì độ hiển thị của nó vẫn đảm bảo tốt, luôn hiển thị rõ mọi thông số một cách chính xác.</p>\n<p><em>Đồng hồ hiển thị trên xe máy điện Honda Vsun V2</em></p>\n<h3><strong>Cụm công tắc bên trái: Bạn có thể thấy có 3 nút công tắc</strong></h3>\n<p>Nút trên cùng ở bên cụm công tắc trái chính là hệ thống Cos pha của đèn</p>\n<p>Nút dưới là hệ thống xi nhan trái phải cả trước và sau. Hỗ trợ tốt cho bạn trong các trường hợp cần rẽ, quay đầu xe.</p>\n<p>Và nút cuối cùng chính là hệ thống còi.</p>\n<p><em>Cụm công tắc trái của xe máy điện Honda Vsun V2</em></p>\n<h3><strong>Cụm công tắc bên phải của xe máy điện Honda Vsun V2:</strong></h3>\n<p>Bên phải thì nút công tắc ít hơn và chức năng sử dụng cũng ít hơn chỉ có 2 cụm công tắc.</p>\n<p>Cụm công tắc thứ nhất chính là bật đèn pha cho xe.</p>\n<p>Cụm công tắc thứ 2 nằm dưới chính là công tắc điều kiển tốc độ.&nbsp;<strong>Xe máy điện Honda Vsun V2&nbsp;</strong>này có thể chạy với 2 tốc độ. Tốc độ 1 vận tốc 35km/h. Tốc độ 2 vận tốc lên tới 60km/h.</p>\n<p><em>Cụm công tắc phải xe điện Honda Vsun V2</em></p>\n<p>&gt;&gt;&gt;Bạn có thể thấy phần tay lái và tay ga&nbsp;được thiết kế nhám giúp hút mồ hôi khi chúng ta di chuyển trên chiếc Hoda Vsun V2 này. Giúp tay bạn lúc nào cũng khô ráo, hạn chế bị trơn trượt trước những tình huống phanh gấp, bất ngờ.</p>\n<h2><strong>ĐỘNG CƠ 1200W KHỎE NHẤT TRONG PHÂN KHÚC XE MÁY ĐIỆN HIỆN NAY</strong></h2>\n<p>Xe máy điện trên thị trường hiện nay đa số các dòng xe tốt thì 1000W, xe điện phổ thông thì từ 500-800W. Còn với mẫu&nbsp;<strong>xe máy điện Honda Vsun V2</strong>&nbsp;này lại trang bị lên tới 12000W siêu khẻo. Do đó việc đạt vận tốc 60km/h sẽ không khó với mẫu&nbsp;<em>xe điện honda cao cấp</em>&nbsp;này. Thoải mái chở 2 leo dốc cực khỏe vận hành không thua gì các dòng xe tay ga cả.</p>\n<p><em>Động cơ xe thuộc TOP 1 hiện nay với công suất 1200W</em></p>\n<p>Kết hợp với bộ 5 acquy 20Ah cho xe đi được quãng đường 80km/1 lần sạc. Đáp ứng tốt nhu cầu di chuyển hiện nay của mọi người. Bộ sạc 60V 20Ah chính hãng Honda có chức năng tự ngắt khi sạc đầy, sạc điện tốt vừa tiết kiệm điện vừa bảo quản acquy khỏi bị chai phù.</p>\n<p><em>Bộ Sạc xe máy điện Honda Vsun V2</em></p>\n<h3><strong>Đảm bảo vận hành an toàn với hệ thống phanh đĩa trước:</strong></h3>\n<p>Động cơ khỏe cho khả năng vận hành nhanh kèm với đó nguy hiểm cũng nâng cao. Do đó hãng honda rất chú trọng trong việc này. Hãng đã trang bị hệ thống phanh đĩa trước, phanh cơ sau lực ma sát lớn giúp xe luôn đảm bảo an toàn trước mọi tình huống.</p>\n<p><em>Hệ thống phanh đĩa trước</em></p>\n<p>Kết hợp với hệ thống bánh to lốp không săm cho khả năng bám đường tốt, hạn chế tối đa tình trạng văng, lết bánh khi phanh gấp, dừng đột ngột.</p>\n<h3><strong>Hệ thống giảm xóc dầu cả trước và sau:</strong></h3>\n<p>Hệ thống giảm xóc có nhiệm vụ giúp xe di chuyển êm, thoải mái qua mọi nẻo đường. Giúp người lái cả người ngồi luôn có cảm giác thoải mái khi di chuyển trên xe không bị sóc, nảy khi đi qua các đoạn đường xấu.</p>\n<p><em>Phuộc dầu trước xe điện Honda Vsun V2</em></p>\n<p>Và ở mẫu&nbsp;<strong>Honda Vsun V2</strong>&nbsp;này được trang bị hệ thống phuộc dầu trước cao cấp và bộ lò xo trụ giảm xóc dầu sau cao cấp. Giúp xe vận hành mượt, êm trên mọi nẻo đường.</p>\n<p><em>Giảm xóc dầu sau của xe điện Honda Vsun V2</em></p>\n<h2><strong>MỘT SỐ ĐIỂM TIỆN ÍCH Ở MẪU XE MÁY ĐIỆN HONDA VSUN V2 CAO CẤP:</strong></h2>\n<p>Ngoài những điểm nổi bật trên cùng động cơ khỏe thì chiếc&nbsp;<strong>Honda Vsun V2 chính hãng 2020</strong>&nbsp;còn có một số tiện ích khác mà bạn khó bỏ qua:</p>\n<p><strong>Yên xe thiết kế rộng, cốp to thoải mái chứa đồ:</strong></p>\n<p>Để tạo cảm giác thoải mái nhất cho người ngồi hãng đã trang bị cho xe một chiếc yên dài ngồi 2 người cực thoải mái với chất liệu cao su cao cấp nên ngồi rất thích nhất là khi di chuyển xa.</p>\n<p><em>Yên xe máy điện Honda Vsun V2 chính hãng</em></p>\n<p><em>Cốp rộng sâu nên bạn thoải mái chứa đồ như bỏ nón bảo hiểm, áo mua, cục sạc, túi sách…Khà là tiện phải không nào.</em></p>\n<p><strong>Sàn để chân xe thiết kế rộng bề mặt nhám chông trơn trợt:</strong></p>\n<p>Sàn để chân của xe thiết kế rộng, bạn thoải mái để chân. Kết hợp với bề mặt nhám chống trơn trợt rất tốt cùng với các khe rãnh thoát nước giúp xe thoát nước nhanh không bị ứ động khi di chuyển trời mưa<em></em></p>\n<p><em>Sàn để chân rộng, chống trơn trợt</em></p>\n<h3><strong>Có trang bị bộ khóa điều kiển từ xa</strong></h3>\n<p>Bộ điều khiển từ xa hay còn gọi là bộ khóa chống trộm cũng được trang bị cho chiếc Honda Vsun V2 này. Bạn có thể mở khóa mà không cần chìa, tìm xe ở bãi đỗ dễ dàng. Và đặc biệt khóa chống trộm an toàn nếu ai đụng vào hay dắt xe đi thì xe sẽ báo động và khóa bánh.</p>\n<p>Với hàng loạt điểm nổi bật của mẫu&nbsp;<em><strong>xe máy điện Honda Vsun V2</strong></em>&nbsp;chắc hẳn các bạn nghĩ chiếc xe này phải có giá 20 mấy triệu phải không nào. Vì xe honda ngoài chất lượng cao thì giá thành nó cũng không hề rẻ. Tuy vậy tại Yên Thoa mẫu xe Honda Vsun V2 này có rất tốt khuyến mãi chỉ còn 18.500.000vnđ trong khí giá niêm yết 28.500.000vnđ.</p>\n<p>Cam kết chỉ bán sản phẩm chính hãng Honda chất lượng cao hàng đầu Việt Nam. Mẫu Honda Vsun V2 này là sản phẩm nhập khẩu nguyên chiếc 100% chứ không phải hàng láp rạp tại Việt Nam. Có đầy đủ giấy tờ hải quan, kiểm tra chất lượng hẳn hoi.</p>\n<p><em>Giấy kiểm tra chất lượng xe điện honda vsun v2</em></p>\n<p><em>Giấy hải quan nhập xe máy điện Honda Vsun V2</em></p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-motor-thai-spaly', 'Xe Máy Điện Motor Thái Spaly', 'motor-thai', '[\"xe-may-dien\"]', 18500000, 18500000, '/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-6.webp\"]', '[]', '[]', '[]', '<p>Có một điều dễ nhận ra trong vài năm gần đây: ngày càng nhiều người bắt đầu cân nhắc đổi từ xe xăng sang xe điện. Không hẳn vì “xu hướng”, mà đơn giản là thấy hợp lý hơn – đi êm, ít tốn tiền và không phải lo mấy khoản bảo dưỡng lặt vặt. Trong số những lựa chọn đang được quan tâm, Motor Thái Spaly là cái tên được nhắc đến khá nhiều bởi sự đơn giản, dễ dùng và phù hợp với nhu cầu di chuyển hàng ngày của đa số người Việt.</p>\n<p>Không phải ngẫu nhiên mà những mẫu xe nhỏ gọn luôn được ưa chuộng tại Việt Nam. Với hệ thống đường phố đông đúc, nhiều ngõ nhỏ và mật độ phương tiện cao, một chiếc xe linh hoạt sẽ mang lại lợi thế rất lớn trong quá trình sử dụng hàng ngày.</p>', '<p>Có một điều dễ nhận ra trong vài năm gần đây: ngày càng nhiều người bắt đầu cân nhắc đổi từ xe xăng sang xe điện. Không hẳn vì “xu hướng”, mà đơn giản là thấy hợp lý hơn – đi êm, ít tốn tiền và không phải lo mấy khoản bảo dưỡng lặt vặt. Trong số những lựa chọn đang được quan tâm, Motor Thái Spaly là cái tên được nhắc đến khá nhiều bởi sự đơn giản, dễ dùng và phù hợp với nhu cầu di chuyển hàng ngày của đa số người Việt.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h3>Nhỏ gọn nhưng “có võ” – Sinh ra để đi phố</h3>\n<p>Không phải ngẫu nhiên mà những mẫu xe nhỏ gọn luôn được ưa chuộng tại Việt Nam. Với hệ thống đường phố đông đúc, nhiều ngõ nhỏ và mật độ phương tiện cao, một chiếc xe linh hoạt sẽ mang lại lợi thế rất lớn trong quá trình sử dụng hàng ngày.</p>\n<p><strong>Motor Thái Spaly</strong> sở hữu kích thước khoảng 1780 x 720 x 1120 mm – vừa đủ để tạo cảm giác chắc chắn khi chạy, nhưng vẫn đảm bảo sự linh hoạt khi di chuyển. Khi đi vào những con phố nhỏ hoặc quay đầu trong không gian hẹp, bạn sẽ thấy rõ sự “nhẹ nhàng” mà chiếc xe này mang lại.</p>\n<p>Chiều cao yên khoảng 750–760 mm là một điểm cộng đáng kể. Với vóc dáng phổ biến của người Việt, người dùng có thể chống chân dễ dàng, không bị chới với khi dừng xe. Điều này đặc biệt quan trọng với người mới sử dụng xe điện hoặc học sinh.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Sàn để chân được thiết kế phẳng và rộng, giúp việc mang theo balo, túi xách hoặc đồ cá nhân trở nên tiện lợi hơn rất nhiều. Đây là chi tiết nhỏ nhưng lại cực kỳ thực tế, nhất là với những ai thường xuyên sử dụng xe cho nhu cầu hàng ngày.</p>\n<h3>Không cần quá mạnh – chỉ cần đủ dùng là hợp lý</h3>\n<p>Một sai lầm phổ biến khi chọn xe là nghĩ rằng công suất càng lớn càng tốt. Nhưng thực tế trong đô thị, một chiếc xe “vừa đủ” lại mang đến trải nghiệm an toàn và dễ sử dụng hơn.</p>\n<p>Motor Thái Spaly được trang bị động cơ khoảng 1000W, cho tốc độ tối đa tầm 40–50 km/h. Đây là mức tốc độ phù hợp để di chuyển trong thành phố, vừa đảm bảo nhanh chóng, vừa giữ được sự an toàn cần thiết.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-motor-thai-spaly-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Xe tăng tốc êm, không bị giật, rất dễ làm quen. Chỉ cần vài phút là người mới cũng có thể điều khiển thành thạo. Điều này đặc biệt phù hợp với học sinh, sinh viên hoặc những ai lần đầu chuyển từ xe xăng sang xe điện.</p>\n<p>Khi vận hành, <strong>xe máy điện</strong> gần như không phát ra tiếng ồn, mang lại cảm giác nhẹ nhàng và thoải mái. Đi trong phố đông hay buổi tối yên tĩnh đều không gây khó chịu như xe xăng.</p>\n<h3>Đi ít hay đi nhiều – Spaly đều có cách đáp ứng</h3>\n<p>Một điểm khiến Motor Thái Spaly được đánh giá cao là khả năng linh hoạt trong lựa chọn pin, giúp người dùng tùy chỉnh theo nhu cầu thực tế.</p>\n<p>Nếu bạn chỉ cần đi học, đi làm gần nhà, phiên bản 5 bình 20Ah là lựa chọn hợp lý. Xe có thể đi được khoảng 80–90 km sau mỗi lần sạc, tương đương 2–3 ngày sử dụng thông thường mới cần cắm điện.</p>\n<p>Còn nếu bạn di chuyển nhiều hơn, phiên bản pin lithium 60V – 30Ah sẽ phù hợp hơn với quãng đường lên tới 110–130 km/lần sạc. Với mức này, việc đi lại cả ngày gần như không phải lo hết pin.</p>\n<p>Thời gian sạc trung bình từ 6–8 tiếng, chỉ cần cắm qua đêm là sáng hôm sau xe lại sẵn sàng. Không cần phải canh thời gian hay sạc nhiều lần trong ngày.</p>\n<h3>Càng sử dụng lâu càng thấy lợi</h3>\n<p>Điểm khiến nhiều người “ở lại” với xe điện không phải là giá mua ban đầu, mà là chi phí sử dụng về lâu dài. Với Motor Thái Spaly, mỗi lần sạc đầy chỉ tốn khoảng 3.000–6.000 đồng tiền điện. Trong khi đó, nếu dùng xe xăng, cùng quãng đường có thể tiêu tốn 50.000–70.000 đồng. Tính ra, bạn có thể tiết kiệm tới 60–70% chi phí nhiên liệu.</p>\n<p>Nếu mỗi tháng đi khoảng 800–1000 km, số tiền tiết kiệm được không hề nhỏ. Sau một năm sử dụng, bạn sẽ thấy sự khác biệt rất rõ.</p>\n<p>Chưa kể, xe điện không cần thay dầu, không có bugi, không có hệ thống xả nên gần như không phát sinh chi phí bảo dưỡng phức tạp. Việc chăm sóc xe đơn giản hơn rất nhiều so với xe xăng.</p>\n<h3>Một chiếc xe “dễ sống” cho cuộc sống hàng ngày</h3>\n<p>Motor Thái Spaly được hoàn thiện theo hướng đơn giản nhưng tiện lợi. Tay lái gọn, góc đánh rộng giúp quay đầu dễ trong phố đông. Cụm đồng hồ điện tử hiển thị rõ tốc độ và mức pin, dễ quan sát cả ngày lẫn đêm.</p>\n<p>Cốp yên đủ dùng cho áo mưa, sạc hoặc đồ cá nhân nhỏ. Xe sử dụng cổng sạc trực tiếp, thời gian sạc khoảng 6–8 tiếng là đầy pin, rất tiện sạc qua đêm.</p>\n<p>Hệ thống phanh đĩa trước kết hợp phanh cơ sau giúp kiểm soát tốt, đi cùng lốp bám đường và giảm xóc êm nên chạy ổn định ngay cả khi qua đoạn đường xấu.</p>\n<h3>Dễ tiếp cận hơn&nbsp;nhờ chính sách hỗ trợ</h3>\n<p>Một yếu tố quan trọng khiến xe điện ngày càng phổ biến là các chính sách hỗ trợ từ nhà nước. Tại Hà Nội, người dân dự kiến có thể được hỗ trợ khoảng 20% giá trị xe, tối đa 5 triệu đồng khi chuyển sang xe điện. Với mức giá phổ biến của Motor Thái Spaly khoảng 12–18 triệu đồng, chi phí thực tế người mua bỏ ra có thể giảm xuống chỉ còn khoảng 10–13 triệu.</p>\n<p>Ngoài ra, các đại lý còn có nhiều ưu đãi như tặng mũ bảo hiểm, miễn phí vận chuyển, bảo hành lên tới 2–3 năm, hỗ trợ cứu hộ… giúp người dùng yên tâm hơn khi lựa chọn.</p>\n<h3>Vì sao Spaly lại hợp với số đông?</h3>\n<p>Không phải ai cũng cần một chiếc xe đắt tiền hay quá nhiều công nghệ. Điều người dùng cần nhất là một chiếc xe phù hợp với cuộc sống hàng ngày.</p>\n<p><strong>Motor Thái</strong> Spaly đáp ứng điều đó bằng sự cân bằng:<br>+ không quá mạnh nhưng đủ dùng<br>+ không quá đắt nhưng hợp lý<br>+ không quá phức tạp nhưng dễ sử dụng</p>\n<p>Chính sự “vừa đủ” này khiến xe phù hợp với rất nhiều người, đặc biệt là những ai muốn chuyển sang xe điện mà không muốn thay đổi quá nhiều thói quen.</p>\n<p>Motor Thái Spaly không phải mẫu xe nổi bật nhất về thiết kế hay công nghệ, nhưng lại là một trong những lựa chọn thực tế nhất cho người dùng Việt. Với chi phí hợp lý, vận hành ổn định và dễ sử dụng, đây là mẫu xe phù hợp để bắt đầu hành trình chuyển đổi sang phương tiện xanh một cách nhẹ nhàng và hiệu quả.</p>\n<p>Nếu bạn đang tìm một chiếc xe “mua về là dùng ngay, không phải suy nghĩ nhiều”, thì Spaly thực sự là cái tên đáng để cân nhắc.</p>', 1);
