INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-osakar-xmen-sport', 'Xe Máy Điện Osakar Xmen Sport', 'osakar', '[\"xe-may-dien\"]', 16500000, 16500000, '/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-osakar-xmen-sport-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-f52-6-binh-22-3ah', 'Xe Máy Điện Tailg F52 6 bình 22.3Ah', 'tailg', '[\"xe-may-dien\"]', 21850000, 21850000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-6.webp\"]', '[]', '[]', '[]', '<p>Trong khi các mẫu xe máy điện đang ngày càng an toàn với những thiết kế thiên về sự mềm mại, trung tính và dễ tiếp cận số đông, Tailg F52 xuất hiện như một kẻ phá cách thực thụ. Mẫu xe này không cố gắng làm hài lòng tất cả mọi người. Thay vào đó, F52 lựa chọn một con đường rất riêng: mạnh mẽ hơn, cá tính hơn và đậm chất cơ khí hơn bất kỳ mẫu xe điện phổ thông nào hiện nay.</p>\n<p>Tailg F52 mang dáng dấp của một chiếc minibike “lai phượt”, nơi tinh thần naked bike được thu nhỏ, kết hợp cùng công nghệ xe điện hiện đại. Chính sự khác biệt này đã giúp F52 nhanh chóng thu hút nhóm khách hàng trẻ yêu thích cảm giác lái thể thao, phong cách bụi bặm và mong muốn sở hữu một chiếc xe điện thật sự không đụng hàng.</p>', '<p>Trong khi các mẫu xe máy điện đang ngày càng an toàn với những thiết kế thiên về sự mềm mại, trung tính và dễ tiếp cận số đông, Tailg F52 xuất hiện như một kẻ phá cách thực thụ. Mẫu xe này không cố gắng làm hài lòng tất cả mọi người. Thay vào đó, F52 lựa chọn một con đường rất riêng: mạnh mẽ hơn, cá tính hơn và đậm chất cơ khí hơn bất kỳ mẫu xe điện phổ thông nào hiện nay.</p>\n<p>Tailg F52 mang dáng dấp của một chiếc minibike “lai phượt”, nơi tinh thần naked bike được thu nhỏ, kết hợp cùng công nghệ xe điện hiện đại. Chính sự khác biệt này đã giúp F52 nhanh chóng thu hút nhóm khách hàng trẻ yêu thích cảm giác lái thể thao, phong cách bụi bặm và mong muốn sở hữu một chiếc xe điện thật sự không đụng hàng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế naked bike thu nhỏ – Cá tính lộ diện ngay từ ánh nhìn đầu tiên</strong></h2>\n<p>Ấn tượng đầu tiên khi nhìn vào <strong>Tailg F52</strong> chính là sự thô ráp có chủ đích. Xe không sử dụng lớp vỏ nhựa bao kín như các mẫu xe điện truyền thống mà để lộ rõ kết cấu khung sườn, động cơ và hệ thống treo. Đây là phong cách đặc trưng của dòng naked bike, nơi vẻ đẹp đến từ cấu trúc cơ khí chứ không phải những chi tiết trang trí cầu kỳ.</p>\n<p>Phần khung sườn của F52 được thiết kế chắc chắn, góc cạnh, tạo cảm giác vững chãi và bền bỉ. Nhìn từ bên hông, xe gợi liên tưởng đến những mẫu minibike nổi tiếng như Honda MSX hay Grom, nhưng được tinh chỉnh để phù hợp hơn với nhu cầu di chuyển hằng ngày tại đô thị Việt Nam.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Tư thế lái cũng là một điểm cộng lớn. Ghi đông cao và rộng mang đến cảm giác điều khiển thoải mái, phóng khoáng, giúp người lái dễ dàng kiểm soát xe trong nhiều tình huống khác nhau. Đây là kiểu tư thế thường thấy trên các dòng xe phượt hoặc naked bike, cho phép người điều khiển không bị gò bó, đặc biệt khi di chuyển quãng đường dài.</p>\n<h2><strong>Hệ thống chiếu sáng và chi tiết ngoại hình mang đậm dấu ấn công nghệ</strong></h2>\n<p>Tailg F52 được trang bị hệ thống đèn full LED toàn xe, vừa mang tính thẩm mỹ cao vừa đảm bảo hiệu quả chiếu sáng thực tế. Cụm đèn pha LED dạng thấu kính tròn tạo điểm nhấn mạnh mẽ ở phần đầu xe, kết hợp với ánh sáng trắng hiện đại giúp tăng khả năng quan sát vào ban đêm.</p>\n<p>Đèn xi-nhan LED nhỏ gọn, sắc nét, bố trí gọn gàng hai bên thân xe, trong khi đèn hậu LED được tạo hình cá tính, hài hòa với tổng thể thiết kế thể thao. Những chi tiết này không chỉ giúp xe nổi bật hơn khi di chuyển trên đường mà còn góp phần nâng cao độ an toàn trong điều kiện thiếu sáng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-f52-6-binh-22-3ah-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Bộ vành đúc hợp kim đa chấu kết hợp cùng lốp không săm bản lớn là một trong những yếu tố tạo nên vẻ ngoài “cơ bắp” cho F52. Lốp béo với bề mặt tiếp xúc rộng giúp xe bám đường tốt hơn, mang lại cảm giác lái đầm chắc và ổn định, đặc biệt khi vào cua hoặc di chuyển trên mặt đường không bằng phẳng.</p>\n<h2><strong>Động cơ QS Motor 72V – Sức mạnh đến từ sự bền bỉ</strong></h2>\n<p>Ẩn sau vẻ ngoài gai góc của Tailg F52 là khối động cơ điện QS Motor danh tiếng. Đây là thương hiệu động cơ điện được đánh giá cao về độ bền và hiệu suất, thường xuất hiện trên các dòng xe điện cao cấp và xe độ.</p>\n<p>Động cơ điện một chiều không chổi than công suất 1500W giúp F52 đạt vận tốc tối đa lên đến khoảng 65km/h. Đây là mức tốc độ rất ấn tượng đối với một mẫu <strong>XE MAY DIEN</strong>, đủ để đáp ứng nhu cầu di chuyển nhanh trong đô thị cũng như những chuyến đi xa hơn ngoài trung tâm thành phố.</p>\n<p>Một điểm đáng chú ý khác là khả năng chống nước đạt chuẩn IP67. Nhờ đó, xe có thể vận hành ổn định trong điều kiện mưa lớn hoặc khi đi qua những đoạn đường ngập nước nhẹ, phù hợp với đặc thù thời tiết và hạ tầng giao thông tại Việt Nam.</p>\n<p>Động cơ QS Motor không chỉ mạnh mà còn vận hành êm ái, ít tiếng ồn và tiết kiệm năng lượng. Tuổi thọ cao cùng chính sách bảo hành dài hạn giúp người dùng yên tâm sử dụng lâu dài mà không phải lo lắng về chi phí sửa chữa hay thay thế.</p>\n<h2><strong>Quãng đường di chuyển lên đến 100km – Xóa bỏ nỗi lo pin yếu</strong></h2>\n<p>Một trong những yếu tố khiến Tailg F52 thực sự khác biệt so với nhiều mẫu xe điện khác chính là khả năng di chuyển xa vượt trội. Xe được trang bị tới 6 bình ắc quy 72V dung lượng 22.3Ah từ thương hiệu Tianneng, mang lại nguồn năng lượng dồi dào cho mọi hành trình.</p>\n<p>Với cấu hình này, F52 có thể di chuyển quãng đường lên đến khoảng 100km chỉ sau một lần sạc đầy. Đây là con số rất ấn tượng trong phân khúc xe máy điện, đặc biệt phù hợp với những người thường xuyên đi làm xa, chạy dịch vụ hoặc có nhu cầu di chuyển nhiều trong ngày.</p>\n<p>Thời gian sạc của xe dao động khoảng 5 đến 6 tiếng, khá nhanh so với dung lượng pin lớn mà xe sở hữu. Hệ thống sạc thông minh có khả năng tự động ngắt khi pin đầy, giúp bảo vệ ắc quy, kéo dài tuổi thọ và đảm bảo an toàn cho người sử dụng.</p>\n<h2><strong>Trải nghiệm lái đầm chắc, linh hoạt trong mọi tình huống</strong></h2>\n<p>Tailg F52 mang đến cảm giác lái rất khác so với các mẫu xe điện thông thường. Trọng tâm xe được đặt thấp, kết hợp cùng khung sườn cứng cáp giúp xe vận hành ổn định và chắc chắn ngay cả khi chạy ở tốc độ cao.</p>\n<p>Hệ thống treo được thiết kế theo hướng thể thao, giúp xe hấp thụ tốt rung động từ mặt đường, mang lại sự êm ái cần thiết nhưng vẫn giữ được độ “thật” của cảm giác lái. Khi di chuyển trong phố đông, ghi đông cao rộng giúp người lái dễ dàng xoay sở, luồn lách và kiểm soát xe một cách linh hoạt.</p>\n<p>Khả năng tải trọng lên đến khoảng 180kg cho phép F52 đáp ứng tốt nhu cầu chở người hoặc mang theo hành lý. Hệ thống phanh đĩa trước và sau mang lại lực hãm ổn định, giúp người lái luôn chủ động trong các tình huống phanh gấp hay đường trơn trượt.</p>\n<h2><strong>Tiện ích và trang bị hướng đến người dùng thực tế</strong></h2>\n<p>Bên cạnh thiết kế và hiệu năng, Tailg F52 còn được trang bị nhiều tiện ích thiết thực phục vụ nhu cầu sử dụng hằng ngày. Màn hình LCD hiển thị rõ ràng các thông số như tốc độ, mức pin, quãng đường, giúp người lái dễ dàng theo dõi tình trạng xe trong suốt quá trình vận hành.</p>\n<p>Hệ thống khóa thông minh kết hợp báo động chống trộm giúp tăng độ an tâm khi đỗ xe tại nơi công cộng. Ngoài ra, xe còn được tích hợp các tính năng bảo vệ như chống sụt áp, chống quá tải, giúp động cơ và hệ thống điện hoạt động ổn định, bền bỉ hơn theo thời gian.</p>\n<h2><strong>Vậy, Có Nên Sở Hữu Tailg F52?</strong></h2>\n<p>Với phong cách thiết kế độc đáo, phạm vi di chuyển 100km ấn tượng, hiệu năng động cơ mạnh mẽ và loạt trang bị công nghệ cao cấp, <strong>Xe máy điện Tailg</strong>&nbsp;F52 là một lựa chọn \"đáng đồng tiền bát gạo\" nếu bạn là:</p>\n<p>+ Người trẻ cá tính: Yêu thích sự khác biệt, muốn thể hiện phong cách mạnh mẽ và độc đáo.</p>\n<p>+ Người cần di chuyển xa: Tìm kiếm một chiếc xe điện có khả năng đi được quãng đường dài mà không muốn kiểu dáng xe ga truyền thống.</p>\n<p>+ Người đam mê công nghệ: Đánh giá cao các trang bị hiện đại như đèn LED, màn hình LCD, phanh đĩa đôi.</p>\n<br>\n<p>Nếu bạn đang tìm kiếm một mẫu xe máy điện không đi theo lối mòn, vừa có thiết kế đậm chất naked bike, vừa sở hữu hiệu năng ấn tượng và quãng đường di chuyển dài, Tailg F52 chắc chắn là cái tên rất đáng để cân nhắc. Không chỉ là phương tiện đi lại, F52 còn là tuyên ngôn về phong cách sống tự do, năng động và không ngại khác biệt.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-gogo-r31-chinh-hang', 'Xe Máy Điện Tailg Gogo R31 Chính Hãng', 'tailg', '[\"xe-may-dien\"]', 16400000, 16400000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-6.webp\"]', '[]', '[]', '[]', '<p>Tailg Gogo R31 là biểu tượng của sự giao thoa giữa phong cách thanh lịch châu Âu và công nghệ vận hành bền bỉ của thế kỷ 21. Mẫu xe này nhanh chóng chinh phục người dùng bởi ngoại hình tinh tế cùng khả năng di chuyển linh hoạt, an toàn vượt trội. Với phiên bản Chính Hãng, Gogo R31 mang đến một trải nghiệm xe điện là phương tiện, đồng thời là phụ kiện thời trang.</p>\n<p>Gogo R31 sở hữu đường nét thiết kế hiện đại, thanh thoát, tập trung vào sự tối giản nhưng không kém phần nổi bật. Từng chi tiết trên xe được Tailg trau chuốt tỉ mỉ, từ phần đầu xe vuốt nhọn khí động học đến thân xe thon gọn, tạo nên một tổng thể hài hòa, thu hút mọi ánh nhìn khi di chuyển trên phố.</p>', '<p><strong>Tailg Gogo R31</strong> là biểu tượng của sự giao thoa giữa phong cách thanh lịch châu Âu và công nghệ vận hành bền bỉ của thế kỷ 21. Mẫu xe này nhanh chóng chinh phục người dùng bởi ngoại hình tinh tế cùng khả năng di chuyển linh hoạt, an toàn vượt trội. Với phiên bản Chính Hãng, Gogo R31 mang đến một trải nghiệm xe điện là phương tiện, đồng thời là phụ kiện thời trang.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-7.webp\" alt=\"Xe Máy Điện Tailg Gogo R31 Chính Hãng\" loading=\"lazy\"></p>\n<h2><br><strong>Diện mạo tao nhã: Cảm hứng thiết kế từ tương lai</strong></h2>\n<p><br><strong>Gogo R31</strong> sở hữu đường nét thiết kế hiện đại, thanh thoát, tập trung vào sự tối giản nhưng không kém phần nổi bật. Từng chi tiết trên xe được Tailg trau chuốt tỉ mỉ, từ phần đầu xe vuốt nhọn khí động học đến thân xe thon gọn, tạo nên một tổng thể hài hòa, thu hút mọi ánh nhìn khi di chuyển trên phố.</p>\n<p><br>Hệ thống chiếu sáng của <strong>xe điện Tailg</strong> là một điểm nhấn công nghệ. <strong>Gogo R31</strong> được trang bị đèn pha LED lớn, thiết kế độc đáo, cung cấp luồng ánh sáng mạnh và rõ, đảm bảo tầm nhìn tối ưu cho người lái vào ban đêm. Đèn hậu và xi-nhan cũng sử dụng công nghệ LED, tiết kiệm điện năng, tăng tính an toàn, giúp các phương tiện phía sau dễ dàng nhận diện tín hiệu.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-8.webp\" alt=\"Xe Máy Điện Tailg Gogo R31 Chính Hãng\" loading=\"lazy\"></p>\n<p><br>Màu sắc xe được phủ bằng lớp sơn cao cấp, có độ bóng sâu và bền màu theo thời gian. Kích thước xe (1775mm x 720mm x 1155mm) và chiều cao yên chỉ 740mm rất lý tưởng cho vóc dáng người Việt, đặc biệt là các bạn học sinh, sinh viên và phụ nữ. Trọng lượng xe nhẹ (95kg) kết hợp với tải trọng ấn tượng lên tới 180kg, cho thấy sự cân bằng hoàn hảo giữa tính linh hoạt và khả năng chịu tải.</p>\n<h2><br><strong>Năng lượng thông minh: Động cơ BLDC không chổi than</strong></h2>\n<p><br>Sức mạnh của <strong>Tailg Gogo R31</strong> đến từ khối động cơ điện một chiều không chổi than công suất 800W. Đây là một động cơ được đánh giá cao về hiệu suất và độ bền, cung cấp năng lượng ổn định, giúp xe vận hành mượt mà và êm ái.</p>\n<p><br>Ưu điểm vượt trội của động cơ BLDC là khả năng vận hành gần như không gây tiếng ồn, mang lại trải nghiệm di chuyển thư thái, thân thiện với môi trường đô thị. Công suất 800W giúp Gogo R31 đạt vận tốc tối đa 50km/h một cách dễ dàng và ổn định, tuân thủ quy định giao thông, phù hợp với mọi đối tượng người dùng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-gogo-r31-chinh-hang-9.webp\" alt=\"Xe Máy Điện Tailg Gogo R31 Chính Hãng\" loading=\"lazy\"></p>\n<p><br>Động cơ được đặt ở bánh sau, truyền động trực tiếp, giúp tối ưu hóa hiệu suất truyền tải lực, giảm thiểu hao phí năng lượng. Bộ điều khiển thông minh tích hợp đảm bảo quá trình tăng tốc diễn ra nhẹ nhàng, không bị giật, cho phép người lái dễ dàng làm chủ tốc độ trong mọi tình huống giao thông.</p>\n<h2><br><strong>Quãng đường vượt trội: Ắc quy, hệ thống sạc</strong></h2>\n<p><br><strong>Gogo R31</strong> được trang bị 5 bình ắc quy 23Ah (hoặc 22.3Ah tùy phiên bản), là nguồn năng lượng dồi dào, đảm bảo quãng đường di chuyển ấn tượng. Xe có thể đi được khoảng 80-90km sau mỗi lần sạc đầy (theo điều kiện tiêu chuẩn). Quãng đường này đáp ứng dư thừa nhu cầu đi lại hàng ngày, học tập hay làm việc trong thành phố.</p>\n<p><br>Thời gian sạc đầy cho bộ ắc quy là từ 5 - 6 tiếng, một con số khá nhanh so với nhiều mẫu xe điện khác. Điều này cho phép người dùng sạc xe qua đêm hoặc tranh thủ sạc trong giờ nghỉ trưa, đảm bảo xe luôn sẵn sàng cho hành trình tiếp theo.</p>\n<p><br>Điểm quan trọng trong công nghệ sạc của Tailg là tính năng tự động ngắt khi ắc quy đầy. Chức năng này giúp bảo vệ ắc quy khỏi tình trạng sạc quá mức, kéo dài tuổi thọ của pin và ngăn ngừa các nguy cơ chập cháy điện, mang lại sự an tâm tuyệt đối cho người sử dụng.</p>\n<h2><br><strong>Độ bám đường, an toàn phanh đĩa</strong></h2>\n<p><br><strong>Tailg Gogo R31</strong> được trang bị hệ thống an toàn đáng tin cậy. Xe điện sử dụng phanh đĩa trước, cung cấp lực phanh mạnh mẽ, phản ứng nhanh, đặc biệt quan trọng trong những tình huống khẩn cấp hay khi di chuyển dưới trời mưa trơn trượt.</p>\n<p><br>Bánh sau của xe sử dụng phanh tang trống, giúp cân bằng lực phanh và tăng độ ổn định cho xe khi giảm tốc. Sự kết hợp 2 phanh tạo sự an toàn hiệu quả, dễ dàng kiểm soát đối với người mới làm quen với xe điện.</p>\n<p><br>Xe sử dụng lốp Kenda không săm chất lượng cao, kích thước 90/90-12 (hoặc 300-10 tùy phiên bản) cho bánh trước và sau. Lốp không săm giúp tăng cường khả năng bám đường, đồng thời giảm thiểu rủi ro bị xì hơi đột ngột khi cán phải vật nhọn, nâng cao sự an toàn và tiện lợi. Vành xe hợp kim đúc nguyên khối cũng góp phần tăng độ bền và vẻ ngoài mạnh mẽ cho xe.</p>\n<h2><br><strong>Trang bị các tiện nghi, trải nghiệm lái mượt</strong></h2>\n<p><br><strong>Gogo R31</strong> được xây dựng dựa trên nguyên tắc công thái học, mang lại sự thoải mái tối đa cho người lái. Chiều cao yên 740mm kết hợp với sàn để chân rộng rãi, tạo tư thế ngồi tự nhiên, giúp người lái thư giãn ngay cả trong những chuyến đi dài. Sàn xe phẳng cũng rất tiện lợi cho việc chở thêm đồ đạc nhỏ.</p>\n<p><br>Cốp xe dưới yên có dung tích lớn, cho phép người dùng thoải mái chứa mũ bảo hiểm, áo mưa và các vật dụng cá nhân khác. Bên cạnh đó, xe còn được trang bị hộc chứa đồ nhỏ phía trước tiện dụng cùng móc treo đồ, giúp người dùng sắp xếp hành lý gọn gàng và dễ dàng lấy ra.</p>\n<p><br>Bảng đồng hồ hiển thị của xe là màn hình kỹ thuật số hiện đại, hiển thị rõ ràng các thông số vận hành như tốc độ, mức pin còn lại, và chế độ lái. Thiết kế này vừa đẹp mắt, vừa giúp người lái dễ dàng theo dõi tình trạng xe, đảm bảo luôn chủ động trên mọi hành trình.</p>\n<h2><br><strong>Cam kết chất lượng, sự bền bỉ của thương hiệu</strong></h2>\n<p><br>Tailg là một thương hiệu xe điện uy tín, với <strong>Gogo R31</strong>, hãng cam kết về chất lượng và độ bền vượt trội. Chính sách bảo hành khung xe 3 năm, động cơ 2 năm, và ắc quy/pin 2 năm thể hiện sự tự tin của nhà sản xuất vào sản phẩm của mình, mang lại sự an tâm tuyệt đối cho người tiêu dùng.</p>\n<p><br>Khung xe được chế tạo từ vật liệu chịu lực cao, cùng với hệ thống giảm xóc thủy lực cao cấp, giúp xe duy trì sự ổn định và bền bỉ qua thời gian. Khả năng chống chịu tải trọng lớn (180kg) chứng minh Gogo R31 được thiết kế để phục vụ nhu cầu di chuyển đa dạng và lâu dài.</p>\n<p><br><strong>Gogo R31</strong> là một lựa chọn kinh tế tuyệt vời. Chi phí năng lượng để sạc đầy ắc quy rất thấp, chi phí bảo trì cũng giảm thiểu đáng kể nhờ vào thiết kế động cơ không chổi than. Điều này làm cho Gogo R31 là phương tiện di chuyển, đồng thời là một khoản đầu tư thông minh và bền vững.</p>\n<p><br><strong>Tailg Gogo R31</strong> Chính Hãng là một chiếc <strong>xe máy điện</strong> hoàn hảo, kết hợp giữa phong cách tao nhã và hiệu suất ấn tượng. Xe mang lại trải nghiệm di chuyển an toàn, êm ái, với quãng đường đi vượt trội và nhiều tiện ích thông minh. Gogo R31 xứng đáng là người bạn đồng hành tin cậy, nâng tầm phong cách sống hiện đại của bạn.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-nova', 'Xe Máy Điện Tailg Nova', 'tailg', '[\"xe-may-dien\"]', 16400000, 16400000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-nova-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-r53-6-ac-quy-23a', 'Xe Máy Điện Tailg R53 6 Ắc Quy 23A', 'tailg', '[\"xe-may-dien\"]', 20800000, 20800000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-6.webp\"]', '[]', '[]', '[]', '<p>Tailg R53 là một \"bản tuyên ngôn nữ tính\" trong phân khúc xe máy điện, kết hợp sự thanh lịch, mềm mại của thiết kế scooter cổ điển với sức mạnh bền bỉ của công nghệ điện hiện đại. Được trang bị 6 ắc quy 23a, mẫu xe này mang lại một phạm vi di chuyển đáng tin cậy, xóa tan mọi lo lắng về năng lượng. R53 là sự lựa chọn hoàn hảo cho những người dùng nữ giới, ưu tiên tính thẩm mỹ duyên dáng, sự nhẹ nhàng trong vận hành và tính kinh tế dài hạn.</p>\n<p>R53 chinh phục ngay từ ánh nhìn đầu tiên nhờ \"tinh hoa thiết kế\" được tập trung vào sự mềm mại và quyến rũ. Chiếc xe sở hữu những đường cong tròn trịa, uốn lượn nhẹ nhàng từ mặt nạ trước, kéo dài dọc theo thân xe đến phần đuôi, tạo nên một tổng thể duyên dáng và thanh lịch. Phong cách này gợi nhớ đến những dòng xe ga Ý cổ điển, nhưng đã được Tailg làm mới với các chi tiết hiện đại.</p>', '<p><strong>Tailg R53</strong> là một \"bản tuyên ngôn nữ tính\" trong phân khúc xe máy điện, kết hợp sự thanh lịch, mềm mại của thiết kế scooter cổ điển với sức mạnh bền bỉ của công nghệ điện hiện đại. Được trang bị 6 ắc quy 23a, mẫu xe này mang lại một phạm vi di chuyển đáng tin cậy, xóa tan mọi lo lắng về năng lượng. R53 là sự lựa chọn hoàn hảo cho những người dùng nữ giới, ưu tiên tính thẩm mỹ duyên dáng, sự nhẹ nhàng trong vận hành và tính kinh tế dài hạn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-7.webp\" alt=\"Xe Máy Điện Tailg Venus R53\" loading=\"lazy\"></p>\n<h2><br><strong>Tinh hoa thiết kế: Sự mềm mại và quyến rũ</strong></h2>\n<p><br><strong>R53</strong> chinh phục ngay từ ánh nhìn đầu tiên nhờ \"tinh hoa thiết kế\" được tập trung vào sự mềm mại và quyến rũ. Chiếc xe sở hữu những đường cong tròn trịa, uốn lượn nhẹ nhàng từ mặt nạ trước, kéo dài dọc theo thân xe đến phần đuôi, tạo nên một tổng thể duyên dáng và thanh lịch. Phong cách này gợi nhớ đến những dòng xe ga Ý cổ điển, nhưng đã được Tailg làm mới với các chi tiết hiện đại.</p>\n<p><br>Thân vỏ xe được chế tạo từ nhựa abs-pp chất lượng cao, mang lại độ dẻo dai và khả năng chống chịu va đập vật lý vượt trội. Bề mặt sơn được xử lý bằng công nghệ tiên tiến, tạo ra độ bóng sâu và khả năng bền màu cao, giữ cho chiếc xe luôn rạng rỡ, sang trọng theo thời gian.</p>\n<p><br>Điểm nhấn thị giác mạnh mẽ là cụm đèn pha được thiết kế hình tròn lớn, thường sử dụng công nghệ chiếu sáng led, đảm bảo cường độ ánh sáng mạnh mẽ, an toàn khi di chuyển ban đêm. Đèn báo rẽ được tạo hình tinh xảo, hài hòa với đường nét tổng thể, góp phần hoàn thiện vẻ đẹp nữ tính.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-8.webp\" alt=\"Xe Máy Điện Tailg Venus R53\" loading=\"lazy\"></p>\n<p><br>Khu vực điều khiển của R53 được trang bị màn hình điện tử sắc nét, hiển thị đầy đủ và rõ ràng các thông số vận hành quan trọng. Giao diện số hóa này cung cấp thông tin về vận tốc, dung lượng ắc quy còn lại, chế độ lái và quãng đường đã đi, giúp người lái kiểm soát mọi trạng thái của xe một cách trực quan.</p>\n<h2><br><strong>Cấu trúc điện năng: Hệ thống 6 ắc quy 23A</strong></h2>\n<p><br><strong>Tailg R53</strong> đặc trưng bởi \"cấu trúc điện năng\" vững vàng, sử dụng hệ thống 6 ắc quy chì-axit, mỗi bình có dung lượng 23ah, hoạt động ở tổng điện áp cao. Sự sắp xếp này là một \"bảo chứng về quãng đường\", giúp chiếc xe đạt được phạm vi di chuyển ấn tượng.</p>\n<p><br>Với cấu hình 6 ắc quy 23ah tiêu chuẩn, chiếc xe có thể đạt quãng đường di chuyển dao động từ 100km đến 120km sau mỗi lần nạp đầy năng lượng. Quãng đường này vượt xa nhu cầu di chuyển hàng ngày trong thành phố của đa số người dùng, giúp bạn hoàn toàn yên tâm khi lên lịch trình cho cả tuần.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r53-6-ac-quy-23a-9.webp\" alt=\"Xe Máy Điện Tailg Venus R53\" loading=\"lazy\"></p>\n<p><br>Hệ thống ắc quy được bố trí khoa học dưới sàn để chân và yên xe, giúp chiếc xe duy trì được trọng tâm thấp. Điều này cực kỳ quan trọng, nó không chỉ tăng cường sự ổn định khi vận hành mà còn giúp người lái dễ dàng kiểm soát xe, đặc biệt trong các tình huống dừng đỗ hoặc dắt xe.</p>\n<p><br>Thời gian nạp đầy cho bộ ắc quy này thường mất khoảng 8 đến 10 giờ, tiện lợi để chúng ta sạc qua đêm. Chi phí vận hành của <strong>R53</strong> là cực kỳ kinh tế, bởi chi phí điện năng để đi 100km thấp hơn nhiều lần so với chi phí xăng dầu.</p>\n<h2><br><strong>Lực đẩy và cảm giác lái: Sự êm ái tuyệt đối</strong></h2>\n<p><br>Động cơ của <strong>Tailg R53</strong> thường có công suất định mức khoảng 1000w đến 1200w. Khối motor hub này được tích hợp gọn gàng ở trục bánh sau, tạo ra một \"lực kéo mượt mà\" đặc trưng của xe điện.</p>\n<p><br>Trải nghiệm lái R53 là sự hòa quyện giữa sự êm ái và sự linh hoạt. Xe tăng tốc nhẹ nhàng, mượt mà và hầu như không phát ra tiếng ồn cơ khí. Đặc tính vận hành này làm cho việc di chuyển trở nên thư thái hơn, giảm thiểu tối đa sự căng thẳng khi tham gia giao thông.</p>\n<p><br>Chiếc xe thường được trang bị 3 chế độ lái khác nhau, cho phép người dùng tùy chỉnh hiệu suất. Từ chế độ tiết kiệm năng lượng eco cho quãng đường dài đến chế độ mạnh mẽ hơn (sport) khi cần vượt dốc hoặc tăng tốc nhanh, R53 đều đáp ứng một cách linh hoạt. Vận tốc tối đa của xe được kiểm soát ở ngưỡng 45 - 50 km/h, đảm bảo sự an toàn và tuân thủ các quy định giao thông.</p>\n<h2><br><strong>Cân bằng động học và hệ thống treo tối ưu</strong></h2>\n<p><br><strong>R53</strong> được trang bị hệ thống treo được tinh chỉnh đặc biệt để mang lại \"trải nghiệm lướt êm\" trên mọi bề mặt đường. Cấu hình giảm xóc của xe bao gồm phuộc ống lồng thủy lực ở phía trước và giảm xóc lò xo trụ giảm chấn thủy lực ở phía sau.</p>\n<p><br>Phuộc trước được tối ưu hóa để hấp thụ hiệu quả các xung động nhỏ từ mặt đường, đảm bảo tay lái luôn giữ được sự nhẹ nhàng và mang lại cảm giác dễ chịu cho người lái. Toàn bộ hệ thống treo hoạt động đồng bộ, giúp thân xe duy trì được tính ổn định cần thiết, đặc biệt khi di chuyển qua các đoạn đường gồ ghề hoặc ổ gà.</p>\n<p><br>Về hệ thống hãm tốc, R53 thường sử dụng phanh đĩa thủy lực ở bánh trước, phanh tang trống ở bánh sau. Đây là một sự kết hợp an toàn và hiệu quả, đảm bảo khả năng triệt tiêu tốc độ một cách nhạy bén và đáng tin cậy. Phanh đĩa phía trước cung cấp lực hãm chính, trong khi phanh tang trống phía sau tăng cường độ ổn định tổng thể.</p>\n<p><br>Chiếc xe sử dụng bộ vành đúc hợp kim với thiết kế tinh tế, đi kèm với lốp không săm. Vành đúc không chỉ tăng cường vẻ ngoài cao cấp mà còn cải thiện khả năng bám đường và sự an toàn cơ bản, giảm thiểu nguy cơ xịt hơi đột ngột.</p>\n<h2><br><strong>Công thái học vị nữ giới và tiện ích thông minh</strong></h2>\n<p><br><strong>Xe điện Tailg&nbsp;R53</strong> được thiết kế dựa trên \"công thái học vị nữ giới\", chú trọng vào sự nhẹ nhàng, dễ dàng sử dụng và sự thoải mái. Yên xe được thiết kế vừa phải, bọc đệm êm ái, đảm bảo sự thoải mái tối đa. Chiều cao yên được cân chỉnh hợp lý, giúp người dùng dễ dàng chống chân và kiểm soát xe.</p>\n<p><br>Khoang chứa đồ dưới yên xe có dung tích ấn tượng, là nơi lý tưởng để cất giữ mũ bảo hiểm và nhiều vật dụng cá nhân khác. Bên cạnh đó, xe còn được trang bị hộc chứa đồ phụ phía trước tiện lợi.</p>\n<p><br>Một tiện ích không thể thiếu là sự tích hợp của cổng sạc usb, giúp duy trì kết nối liên tục cho các thiết bị di động của bạn. Sàn để chân được thiết kế phẳng và rộng, tối đa hóa sự thoải mái cho đôi chân người lái trong suốt hành trình. Xe còn có hệ thống khóa chống trộm điện tử tiên tiến, giúp tăng cường tính an ninh cho chiếc xe một cách hiệu quả.</p>\n<h2><br><strong>Góc nhìn kinh tế: Khoản đầu tư thông minh</strong></h2>\n<p><br><strong>Tailg R53 6 ắc quy 23A</strong> là một \"khoản đầu tư thông minh\" về giao thông cá nhân. Chi phí điện năng để vận hành chiếc xe này cực kỳ thấp, tạo nên một lợi ích tài chính rõ rệt so với xe máy xăng.</p>\n<p><br>Mặc dù chi phí đầu tư ban đầu cho hệ thống 6 ắc quy cao hơn các mẫu 4 ắc quy, nhưng lợi ích từ quãng đường di chuyển rộng rãi và độ bền bỉ của ắc quy 23ah đã chứng minh sự xứng đáng của nó. Chi phí bảo trì của xe điện cũng giữ ở mức tối thiểu, bởi động cơ điện không cần thay dầu nhớt và ít có bộ phận cơ khí hao mòn phức tạp.</p>\n<p><br><strong>Tailg R53</strong> là sự kết tinh giữa vẻ đẹp thanh lịch, nữ tính và sức mạnh bền bỉ của một chiếc xe điện 6 ắc quy cao cấp. Với khả năng đạt quãng đường di chuyển lên đến 120km, chiếc <strong>xe điện</strong> này xóa bỏ mọi rào cản về năng lượng, mang lại sự tự do tối đa trong đô thị. Từ thiết kế công thái học thân thiện đến hệ thống an toàn đáng tin cậy, R53 thể hiện sự chu đáo tuyệt đối trong từng chi tiết. Mẫu xe này hoàn toàn xứng đáng là một sự lựa chọn tinh tế.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-r60', 'Xe Máy điện Tailg R60', 'tailg', '[\"xe-may-dien\"]', 16840000, 16840000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Tailg R60 là mẫu xe mới nổi bật như một lựa chọn cân bằng giữa công nghệ, thẩm mỹ và nhu cầu di chuyển thực tế, mang đến một cách tiếp cận mới mẻ cho phân khúc xe điện phổ thông. Không chạy theo những khuôn mẫu truyền thống, Tailg R60 hướng đến trải nghiệm sử dụng trọn vẹn – nơi mỗi chi tiết trên xe đều phục vụ trực tiếp cho cuộc sống hàng ngày của người dùng thành phố.</p>\n<p>Tailg R60 không cố gắng trở thành một mẫu xe hầm hố hay quá cầu kỳ về hình thức. Thay vào đó, xe được xây dựng theo triết lý thiết kế đô thị hiện đại: gọn gàng, linh hoạt, dễ hòa nhập với nhiều phong cách sống khác nhau. Tổng thể thân xe có kích thước khoảng 1720 x 690 x 1090 mm, chiều cao yên khoảng 760 mm, giúp người điều khiển cảm thấy nhẹ nhàng ngay từ thao tác dắt xe, quay đầu hoặc luồn lách trong các tuyến phố đông.</p>', '<p>Xe máy điện Tailg R60 là mẫu xe mới nổi bật như một lựa chọn cân bằng giữa công nghệ, thẩm mỹ và nhu cầu di chuyển thực tế, mang đến một cách tiếp cận mới mẻ cho phân khúc xe điện phổ thông. Không chạy theo những khuôn mẫu truyền thống, Tailg R60 hướng đến trải nghiệm sử dụng trọn vẹn – nơi mỗi chi tiết trên xe đều phục vụ trực tiếp cho cuộc sống hàng ngày của người dùng thành phố.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Ngôn ngữ thiết kế mang tinh thần đô thị hiện đại</strong></h2>\n<p>Tailg R60 không cố gắng trở thành một mẫu xe hầm hố hay quá cầu kỳ về hình thức. Thay vào đó, xe được xây dựng theo triết lý thiết kế đô thị hiện đại: gọn gàng, linh hoạt, dễ hòa nhập với nhiều phong cách sống khác nhau. Tổng thể thân xe có kích thước khoảng 1720 x 690 x 1090 mm, chiều cao yên khoảng 760 mm, giúp người điều khiển cảm thấy nhẹ nhàng ngay từ thao tác dắt xe, quay đầu hoặc luồn lách trong các tuyến phố đông.</p>\n<p>Các chi tiết trên xe được hoàn thiện theo hướng tối giản nhưng sắc nét, tạo cảm giác cao cấp hơn so với nhiều mẫu <strong>xe máy điện</strong> phổ thông. Từ cách bo góc thân xe, thiết kế tay lái cho đến bố cục phần đuôi đều mang tính liền mạch, tạo nên một tổng thể hài hòa thay vì những chi tiết rời rạc. Khung xe thép chịu lực chắc chắn cho khả năng tải trọng lên đến 180 kg, đáp ứng tốt nhu cầu di chuyển hai người hoặc mang theo nhiều vật dụng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Trải nghiệm lái hướng đến sự thoải mái lâu dài</strong></h2>\n<p>Điều làm nên sự khác biệt của Tailg R60 không nằm ở những con số quảng cáo mà ở cảm giác sử dụng trong thời gian dài. Xe được trang bị động cơ điện công suất 1000W, công suất tối đa khoảng 1500W, cho khả năng vận hành ổn định trong điều kiện giao thông đô thị với tốc độ tối đa khoảng 50–55 km/h.</p>\n<p>Chiều cao yên được tính toán phù hợp với vóc dáng người Việt, giúp việc chống chân trở nên tự nhiên hơn, đặc biệt hữu ích khi dừng đèn đỏ nhiều lần. Phần sàn để chân rộng và phẳng giúp người lái có thể thay đổi tư thế linh hoạt, giảm cảm giác mỏi trong các chuyến đi dài. Hệ thống giảm xóc thủy lực trước và lò xo đôi phía sau giúp xe vận hành êm ái, hạn chế rung lắc khi đi qua các đoạn đường gồ ghề.</p>\n<h2><strong>Một phương tiện phù hợp với nhịp sống linh hoạt</strong></h2>\n<p>Cuộc sống đô thị hiện đại đòi hỏi phương tiện di chuyển phải linh hoạt và thích nghi nhanh với nhiều tình huống khác nhau. Tailg R60 sử dụng bộ ắc quy 60V – 23Ah, cho quãng đường di chuyển trung bình 80 – 90 km mỗi lần sạc, đáp ứng tốt nhu cầu đi học, đi làm hoặc di chuyển nhiều ngày liên tục mà không cần sạc thường xuyên. Thời gian sạc đầy khoảng 8 – 10 giờ, phù hợp với thói quen sạc qua đêm của người dùng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r60-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Khoảng không gian chứa đồ được bố trí hợp lý, với cốp xe dung tích khoảng 20 lít, giúp người dùng dễ dàng mang theo áo mưa, túi xách hoặc vật dụng cá nhân trong ngày.</p>\n<h2><strong>Chi phí sử dụng – yếu tố khiến xe điện ngày càng được ưa chuộng</strong></h2>\n<p>Khi chi phí sinh hoạt tại đô thị ngày càng tăng, người dùng bắt đầu chú trọng hơn đến bài toán kinh tế lâu dài của phương tiện di chuyển. Với mức tiêu thụ điện năng thấp cho mỗi lần sạc, Tailg R60 giúp tiết kiệm đáng kể chi phí vận hành hàng tháng so với xe xăng truyền thống. Đồng thời, cấu tạo động cơ điện đơn giản, không cần thay dầu nhớt định kỳ cũng giúp giảm đáng kể chi phí bảo dưỡng.</p>\n<h2><strong>Công nghệ dần trở thành tiêu chuẩn mới trong phương tiện cá nhân</strong></h2>\n<p>Sự phát triển mạnh mẽ của công nghệ đã thay đổi cách người dùng lựa chọn phương tiện di chuyển, đặc biệt trong phân khúc xe máy điện. Không chỉ đơn thuần là phương tiện đi lại, các dòng xe hiện đại ngày nay còn được tích hợp nhiều công nghệ thông minh nhằm nâng cao trải nghiệm sử dụng, tăng tính an toàn và tối ưu hiệu suất vận hành. <strong>Tailg R60</strong> là một trong những mẫu xe thể hiện rõ xu hướng này khi được trang bị hàng loạt giải pháp công nghệ thực tế, hướng đến nhu cầu sử dụng hằng ngày của người dùng đô thị.</p>\n<p>Hệ thống màn hình điện tử LCD thế hệ mới giúp hiển thị đầy đủ các thông số vận hành như tốc độ, dung lượng pin, quãng đường di chuyển và trạng thái xe với độ sắc nét cao, dễ quan sát ngay cả dưới ánh nắng mạnh. Đây là chi tiết nhỏ nhưng mang lại sự tiện lợi lớn, giúp người lái chủ động kiểm soát hành trình và lên kế hoạch sạc pin hợp lý.</p>\n<p>Bên cạnh đó, công nghệ quản lý pin thông minh BMS (Battery Management System) đóng vai trò quan trọng trong việc đảm bảo tuổi thọ và độ an toàn của bộ pin. Hệ thống này có khả năng tự động cân bằng dòng điện, kiểm soát nhiệt độ, chống quá tải, quá áp và ngắn mạch, từ đó giúp pin hoạt động ổn định hơn trong thời gian dài. Nhờ sự hỗ trợ của BMS, hiệu suất sử dụng năng lượng được tối ưu, giảm thiểu tình trạng chai pin và tiết kiệm chi phí vận hành cho người dùng.</p>\n<p>Tailg R60 cũng được tích hợp hệ thống khóa điện tử thông minh kết hợp chống trộm, mang lại sự an tâm khi đỗ xe tại nơi công cộng. Khi có tác động bất thường, xe sẽ phát tín hiệu cảnh báo ngay lập tức, giúp hạn chế rủi ro mất cắp. Cùng với đó, hệ thống đèn LED toàn xe không chỉ giúp tiết kiệm điện năng mà còn cải thiện khả năng chiếu sáng, tăng độ an toàn khi di chuyển vào ban đêm.</p>\n<p>Có thể thấy rằng, công nghệ không còn là yếu tố bổ trợ mà đang dần trở thành tiêu chuẩn mới trong thiết kế phương tiện cá nhân. Việc ứng dụng các giải pháp công nghệ thông minh trên Tailg R60 không chỉ nâng cao trải nghiệm người dùng mà còn góp phần định hình xu hướng xe điện hiện đại: an toàn hơn, tiện lợi hơn và tối ưu chi phí sử dụng trong dài hạn.</p>\n<h2><strong>Những tiện ích không thể thay thế giúp nâng cao tinh thần người sử dụng</strong></h2>\n<p>Tailg R60 được trang bị hệ thống đèn LED toàn bộ, màn hình hiển thị điện tử theo dõi tốc độ, quãng đường và mức pin, cùng hệ thống phanh đĩa trước – phanh cơ sau giúp đảm bảo an toàn khi vận hành. Lốp không săm kích thước 90/90-10 tăng độ bám đường và hạn chế rủi ro khi cán phải vật nhọn.</p>\n<p>Cốp xe dung tích khoảng 20 lít cho phép chứa mũ bảo hiểm nửa đầu cùng các vật dụng cá nhân như áo mưa, găng tay hoặc túi nhỏ, giúp người dùng chủ động hơn trong các tình huống di chuyển hàng ngày.</p>\n<p>Sàn để chân rộng và phẳng tạo thêm không gian đặt balo, túi xách hoặc các vật dụng mua sắm khi đi siêu thị, giúp xe trở nên linh hoạt hơn trong nhiều mục đích sử dụng. Hệ thống khóa điện an toàn kết hợp tính năng chống trộm giúp tăng khả năng bảo vệ xe khi gửi tại trường học, chung cư hoặc khu vực công cộng.</p>\n<p>Những tiện ích tưởng chừng nhỏ này lại đóng vai trò quan trọng trong trải nghiệm sử dụng thực tế, giúp Tailg R60 trở thành phương tiện di chuyển thuận tiện, dễ dùng và phù hợp với nhịp sống bận rộn của người dùng đô thị hiện đại.</p>\n<h2><strong>Phù hợp với xu hướng sống xanh và đô thị bền vững</strong></h2>\n<p>Trải qua hơn hai thập kỷ phát triển, Tailg đã xây dựng hệ thống nghiên cứu và sản xuất quy mô lớn với nhiều trung tâm công nghệ, nhà máy sản xuất hiện đại và mạng lưới phân phối tại hàng chục quốc gia.</p>\n<p>Điểm mạnh của Tailg nằm ở việc tập trung đầu tư vào công nghệ động cơ hiệu suất cao, hệ thống quản lý năng lượng tối ưu và tiêu chuẩn sản xuất đồng bộ. Nhờ đó, các mẫu xe của hãng, trong đó có Tailg R60, luôn hướng đến sự ổn định lâu dài, tiết kiệm chi phí vận hành và khả năng thích nghi tốt với điều kiện giao thông tại các quốc gia châu Á, đặc biệt là khu vực Đông Nam Á. Sự hiện diện ngày càng rộng rãi của Tailg tại Việt Nam giúp người dùng dễ dàng tiếp cận các dòng xe điện chất lượng với mức giá cạnh tranh hơn so với nhiều thương hiệu cùng phân khúc.</p>\n<p>Bên cạnh yếu tố kinh tế, nhận thức về môi trường cũng đang thay đổi mạnh mẽ trong cộng đồng người dùng trẻ. Tailg R60 vận hành hoàn toàn bằng điện, không phát thải khí trực tiếp, góp phần giảm ô nhiễm không khí và hướng đến xu hướng giao thông xanh tại các đô thị hiện đại.</p>\n<p>Yên Thoa là đơn vị phân phối Tailg R60 với mức giá chỉ 15.990.000 đồng, là một trong những <strong>mẫu xe điện hot</strong> của hãng với sự cân bằng giữa chi phí đầu tư ban đầu, hiệu suất vận hành và chi phí sử dụng lâu dài. Đây cũng là mẫu xe phù hợp với học sinh, sinh viên, nhân viên văn phòng hoặc người cần phương tiện di chuyển hằng ngày tiết kiệm và ổn định.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-r71', 'Xe Máy Điện Tailg R71', 'tailg', '[\"xe-may-dien\"]', 21500000, 21500000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-5.webp\"]', '[]', '[]', '[]', '<p>Tailg R71 - mẫu xe máy điện được mệnh danh là \"Nữ hoàng\" trong phân khúc, là một sản phẩm nhập khẩu từ thương hiệu hàng đầu Trung Quốc. Chiếc xe này là sự giao thoa hoàn hảo giữa thiết kế sang trọng, thời thượng và sức mạnh vận hành vượt trội, khẳng định vị thế của một phương tiện di chuyển điện cao cấp. R71 hướng đến những người dùng yêu thích sự thanh lịch, đặc biệt là phái nữ, đồng thời yêu cầu một chiếc xe có khả năng di chuyển xa và ổn định.</p>\n<p>Tailg R71 được trang bị động cơ điện công suất 1000W. Đây là mức công suất mạnh mẽ, đảm bảo khả năng vận hành vượt trội so với các mẫu xe điện phổ thông. Động cơ 1000W cung cấp lực kéo tức thời, giúp xe dễ dàng khởi động, tăng tốc nhanh chóng và vượt qua các đoạn dốc hay chở tải nặng mà không bị ì.</p>', '<p><strong>Tailg R71</strong> - mẫu xe máy điện được mệnh danh là \"Nữ hoàng\" trong phân khúc, là một sản phẩm nhập khẩu từ thương hiệu hàng đầu Trung Quốc. Chiếc xe này là sự giao thoa hoàn hảo giữa thiết kế sang trọng, thời thượng và sức mạnh vận hành vượt trội, khẳng định vị thế của một phương tiện di chuyển điện cao cấp. R71 hướng đến những người dùng yêu thích sự thanh lịch, đặc biệt là phái nữ, đồng thời yêu cầu một chiếc xe có khả năng di chuyển xa và ổn định.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-6.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><br><strong>Động cơ 1000W mạnh mẽ, tăng tốc ấn tượng</strong></h2>\n<p><br><strong>Tailg R71</strong> được trang bị động cơ điện công suất 1000W. Đây là mức công suất mạnh mẽ, đảm bảo khả năng vận hành vượt trội so với các mẫu xe điện phổ thông. Động cơ 1000W cung cấp lực kéo tức thời, giúp xe dễ dàng khởi động, tăng tốc nhanh chóng và vượt qua các đoạn dốc hay chở tải nặng mà không bị ì.</p>\n<p><br>Động cơ sử dụng công nghệ tiên tiến, hoạt động hoàn toàn tự động, mang lại trải nghiệm lái xe êm ái, gần như không gây ra tiếng ồn. Vận tốc tối đa xe đạt tới 60km/h. Tốc độ này không chỉ đáp ứng hoàn hảo nhu cầu di chuyển hàng ngày trong đô thị mà còn cho phép người lái duy trì sự linh hoạt và nhanh chóng trên những đoạn đường ngoại ô.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Để đảm bảo hiệu suất này, hệ thống điện được cung cấp bởi 6 bình ắc quy dung lượng lớn, 22Ah. Dung lượng ắc quy cao không chỉ là nguồn cung cấp năng lượng ổn định cho động cơ 1000W mà còn là nền tảng cho khả năng di chuyển xa, một ưu thế nổi bật của R71.</p>\n<h2><br><strong>Quãng đường 100km, tự tin di chuyển cả tuần</strong></h2>\n<p><br>Với hệ thống ắc quy 6 bình 22Ah, Tailg R71 mang lại khả năng di chuyển cực kỳ ấn tượng, lên đến 100km sau mỗi lần sạc đầy. Con số này là một bước tiến lớn, gần như xóa bỏ mọi lo lắng về năng lượng cho những người dùng cần di chuyển xa hoặc thường xuyên sử dụng xe trong nhiều ngày liên tục mà không tiện sạc.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-r71-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Thời gian sạc đầy cho hệ thống ắc quy này là khoảng 5 đến 6 tiếng. Đây là thời gian sạc hợp lý so với dung lượng ắc quy lớn, cho phép người dùng dễ dàng tận dụng thời gian nghỉ buổi tối để nạp đầy năng lượng cho hành trình ngày hôm sau.</p>\n<p><br>Tương tự các dòng xe điện cao cấp, R71 được trang bị tính năng tự động ngắt khi ắc quy đầy. Cơ chế này đóng vai trò quan trọng trong việc bảo vệ ắc quy khỏi bị sạc quá mức, giúp kéo dài tuổi thọ và duy trì hiệu suất hoạt động ổn định của hệ thống điện. Chính sách bảo hành ắc quy 2 năm cũng củng cố thêm sự an tâm này.</p>\n<h2><br><strong>Thiết kế sang trọng, chuẩn nữ hoàng đô thị</strong></h2>\n<p><br>R71 sở hữu kích thước tổng thể cân đối và thanh lịch (1740mm x 700mm x 1100mm). Vóc dáng này tạo nên sự hài hòa giữa sự ổn định cần thiết của xe máy điện và sự gọn gàng, linh hoạt của xe tay ga đô thị. Chiều cao yên xe 750mm là mức tiêu chuẩn, phù hợp với hầu hết người dùng Việt Nam, đặc biệt là nữ giới.</p>\n<p><br>Trọng lượng tịnh của xe là 98kg. Đây là trọng lượng vừa phải, mang lại cảm giác đầm chắc khi lái ở tốc độ cao, đồng thời không quá nặng nề khi cần dắt hoặc xoay trở xe. Các chi tiết ngoại hình được trau chuốt, với nhiều màu sắc cơ bản để người dùng tùy ý lựa chọn, thể hiện gu thẩm mỹ cá nhân.</p>\n<p><br>Vành xe được làm từ hợp kim nhôm đúc nguyên khối, một chi tiết đắt giá tăng tính thẩm mỹ, đồng thời đảm bảo độ bền, khả năng chịu lực vượt trội. Lốp không săm được trang bị cho cả hai bánh, tăng cường an toàn và độ bám đường, đồng thời giảm thiểu rủi ro khi cán phải vật nhọn.</p>\n<h2><br><strong>An toàn kép, kiểm soát tối ưu</strong></h2>\n<p><br>Tailg R71 được trang bị hệ thống phanh kép để đảm bảo an toàn tối đa cho người lái. Bánh trước sử dụng phanh đĩa, cung cấp lực hãm mạnh mẽ, chính xác và có độ phản hồi cao, giúp người lái kiểm soát tốc độ một cách chủ động.</p>\n<p><br>Bánh sau xe điện được trang bị phanh cơ. Sự kết hợp giữa phanh đĩa trước và phanh cơ sau tạo nên một hệ thống phanh cân bằng, tối ưu hóa lực dừng xe trong nhiều điều kiện vận hành. Phanh cơ ở bánh sau cũng giúp giảm thiểu chi phí bảo dưỡng và sửa chữa.</p>\n<p><br>Hệ thống giảm xóc của R71 sử dụng công nghệ giảm chấn thủy lực. Giảm chấn thủy lực có khả năng hấp thụ và triệt tiêu các rung động từ mặt đường hiệu quả. Điều này mang lại trải nghiệm lái xe êm ái, thoải mái, giúp người lái và người ngồi sau không bị mệt mỏi khi di chuyển trên các đoạn đường gồ ghề.</p>\n<h2><br><strong>Tải trọng lớn&nbsp;đáp ứng linh hoạt nhu cầu sử dụng</strong></h2>\n<p><br>Mặc dù mang vẻ ngoài thanh lịch, <strong>xe máy điện&nbsp;Tailg </strong>R71 lại có khả năng chịu tải lên đến 180kg. Đây là một con số ấn tượng, vượt trội hơn nhiều mẫu xe điện khác, cho phép xe chở hai người lớn và hành lý cá nhân một cách dễ dàng mà vẫn duy trì được hiệu suất và độ ổn định.</p>\n<p><br>Ngoài khả năng tải trọng, R71 còn được trang bị nhiều tiện ích thiết thực. Xe đi kèm đầy đủ gương, sạc và sổ bảo hành. Tính năng sạc tự động ngắt khi đầy là một tiện ích nhỏ nhưng vô cùng quan trọng, giúp bảo vệ ắc quy và tăng tính an toàn khi sạc điện tại nhà.</p>\n<p><br>Vành nhôm đúc nguyên khối và lốp không săm cũng là những tiện ích an toàn đáng giá, giúp người lái an tâm hơn khi di chuyển trên đường. Thiết kế tổng thể của xe còn có không gian để chân rộng rãi và yên xe dài, mang lại sự thoải mái tối đa cho cả người lái và người ngồi sau.</p>\n<h2><br><strong>Cam kết dài hạn,&nbsp;an tâm sử dụng</strong></h2>\n<p><br>Tailg R71 là sản phẩm nhập khẩu từ thương hiệu xe điện hàng đầu Trung Quốc, mang theo những cam kết chất lượng dài hạn. Chính sách bảo hành rõ ràng là yếu tố củng cố niềm tin cho người tiêu dùng khi đầu tư vào một chiếc xe điện cao cấp.</p>\n<p><br>Khung xe được hưởng chế độ bảo hành dài nhất, lên đến 3 năm. Cam kết này khẳng định độ bền và sự chắc chắn của bộ khung chịu lực, được thiết kế để chịu được tải trọng lớn và hoạt động ổn định trong nhiều năm.</p>\n<p><br>Các bộ phận quan trọng khác của xe đều được bảo hành 2 năm: động cơ, ắc quy và pin. Đặc biệt, việc bảo hành ắc quy và pin lên đến 2 năm là một ưu thế lớn so với nhiều dòng xe điện khác, giảm thiểu rủi ro tài chính liên quan đến việc thay thế linh kiện điện năng đắt tiền. Sự đồng bộ trong thời gian bảo hành các bộ phận chính là minh chứng cho sự tự tin vào chất lượng sản xuất.</p>\n<p><br>Tailg R71 là chiếc <strong>xe máy điện</strong> lý tưởng cho những ai ưu tiên sự kết hợp giữa thẩm mỹ sang trọng và hiệu suất di chuyển tối ưu. Với động cơ 1000W và quãng đường hoạt động 100km vượt trội, R71 khẳng định vị thế \"Nữ hoàng\" trong phân khúc. Phanh đĩa trước và tải trọng 180kg là những điểm cộng đắt giá, tạo nên một lựa chọn an toàn và thanh lịch cho cuộc sống đô thị hiện đại.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-t61', 'Xe Máy Điện Tailg T61', 'tailg', '[\"xe-may-dien\"]', 28840000, 28840000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t61-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-t71-8-acquy-23ah', 'Xe Máy Điện Tailg T71 8 Acquy 23Ah', 'tailg', '[\"xe-may-dien\"]', 26840000, 26840000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-6.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện Tailg T71 khẳng định vị thế dẫn đầu bằng sự kết hợp táo bạo giữa công nghệ năng lượng tương lai và ngôn ngữ thiết kế góc cạnh, đầy uy lực. Đây là lời giải cho bài toán di chuyển thông minh, nơi sự sang trọng hòa quyện cùng hiệu suất mạnh mẽ để phục vụ những khách hàng khát khao sự khác biệt. Từng thông số kỹ thuật đều cho thấy sự đầu tư nghiêm túc của nhà sản xuất trong việc tạo ra một cỗ máy bền bỉ, sẵn sàng thách thức mọi giới hạn của phân khúc xe điện đô thị hiện nay.</p>\n<p>Diện mạo của Tailg T71 toát lên vẻ mạnh mẽ với kích thước tổng thể 1955/685/1115 mm, tạo nên một hình khối vững chãi và bề thế trên đường phố. Chiều cao yên 770 mm được tính toán tỉ mỉ để phù hợp với vóc dáng người Việt, giúp người lái dễ dàng kiểm soát thân xe và giữ thăng bằng trong những tình huống giao thông phức tạp.</p>', '<p><strong>Xe máy điện Tailg T71 </strong>khẳng định vị thế dẫn đầu bằng sự kết hợp táo bạo giữa công nghệ năng lượng tương lai và ngôn ngữ thiết kế góc cạnh, đầy uy lực. Đây là lời giải cho bài toán di chuyển thông minh, nơi sự sang trọng hòa quyện cùng hiệu suất mạnh mẽ để phục vụ những khách hàng khát khao sự khác biệt. Từng thông số kỹ thuật đều cho thấy sự đầu tư nghiêm túc của nhà sản xuất trong việc tạo ra một cỗ máy bền bỉ, sẵn sàng thách thức mọi giới hạn của phân khúc xe điện đô thị hiện nay.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-7.webp\" alt=\"Xe Máy Điện Tailg T71 Vario 8 Acquy 23Ah\" loading=\"lazy\"></p>\n<h2><br><strong>Ngoại hình góc cạnh tôn vinh phong cách cá tính</strong></h2>\n<p><br>Diện mạo của <strong>Tailg T71 </strong>toát lên vẻ mạnh mẽ với kích thước tổng thể 1955/685/1115 mm, tạo nên một hình khối vững chãi và bề thế trên đường phố. Chiều cao yên 770 mm được tính toán tỉ mỉ để phù hợp với vóc dáng người Việt, giúp người lái dễ dàng kiểm soát thân xe và giữ thăng bằng trong những tình huống giao thông phức tạp.</p>\n<p><br>Hệ thống khung xe là minh chứng cho sự bền bỉ với cam kết bảo hành lên tới 3 năm, một con số đầy tự tin về chất lượng cơ khí. Điểm nhấn đắt giá nằm ở bộ vành nhôm đúc nguyên khối cùng càng sau được chế tác đồng bộ, mang lại sự cứng cáp tuyệt đối và vẻ đẹp hiện đại, thoát ly khỏi những thiết kế rời rạc thông thường.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-8.webp\" alt=\"Xe Máy Điện Tailg T71 Vario 8 Acquy 23Ah\" loading=\"lazy\"></p>\n<p><br>Sự tỉ mỉ trong thiết kế còn được thể hiện qua các phụ kiện đi kèm như gương chiếu hậu thời trang và bộ sạc thông minh đồng bộ. Từng đường nét trên thân xe đều mang dụng ý khí động học, giúp giảm sức cản không khí và tăng tính thẩm mỹ tổng thể.</p>\n<h2><br><strong>Động cơ công suất lớn, êm ái trên mọi cung đường</strong></h2>\n<p><br>Sức mạnh cốt lõi của <strong>Tailg T71 </strong>nằm ở khối động cơ điện một chiều không chổi than với công suất định danh đạt 2000W. Khả năng bứt tốc từ 0 - 60 km/h diễn ra vô cùng mượt mà, mang lại cảm giác phấn khích cho người lái mỗi khi vít ga. Động cơ thế hệ mới này loại bỏ hoàn toàn tiếng ồn khó chịu, thay vào đó là sự tĩnh lặng êm ái, giúp bạn tận hưởng trọn vẹn không gian di chuyển trên từng cây số.</p>\n<p><br>Hệ thống vận hành tự động thông minh loại bỏ những thao tác rườm rà, tập trung tối đa vào trải nghiệm lái của người dùng. Với tải trọng lên đến 220 kg, chiếc xe dễ dàng gánh vác mọi nhu cầu từ chở thêm thành viên gia đình đến vận chuyển hàng hóa mà không hề có dấu hiệu đuối sức hay hụt hơi.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t71-8-acquy-23ah-9.webp\" alt=\"Xe Máy Điện Tailg T71 Vario 8 Acquy 23Ah\" loading=\"lazy\"></p>\n<p><br>Sự kết hợp giữa công suất lớn và hệ thống điều khiển linh hoạt tạo nên một cỗ máy có khả năng leo dốc ấn tượng, điều mà nhiều dòng xe điện phổ thông thường e ngại. Trọng lượng xe được phân bổ đồng đều giúp cảm giác lái trở nên chân thực, chắc chắn, mang lại sự tin tưởng tuyệt đối cho người điều khiển.</p>\n<h2><br><strong>Công nghệ năng lượng đột phá cho hành trình dài</strong></h2>\n<p><br>Hệ thống lưu trữ điện năng của xe là một bước tiến dài với trang bị 8 bình ắc quy 22.3Ah, cung cấp nguồn năng lượng dồi dào cho quãng đường di chuyển lên tới 150 km sau một lần sạc. Chỉ số này mở ra khả năng sử dụng linh hoạt, từ đi làm hằng ngày đến những chuyến dã ngoại ngoại ô mà không phải bận tâm về vị trí trạm sạc.</p>\n<p><br>Tính năng tự động ngắt khi ắc quy đầy là một bước đi thông minh nhằm bảo vệ tài sản và sự an toàn của người dùng, ngăn chặn triệt để nguy cơ quá nhiệt hay chai pin. Thời gian sạc đầy được rút ngắn chỉ còn từ 5 đến 6 tiếng, cực kỳ phù hợp để nạp năng lượng qua đêm và bắt đầu ngày mới với đầy ắp hy vọng.</p>\n<p><br>Chính sách bảo hành 18 tháng cho ắc quy và 2 năm cho pin thể hiện sự tận tâm của Tailg trong việc chăm sóc khách hàng sau bán hàng. Nguồn năng lượng ổn định giúp các tính năng hỗ trợ trên xe luôn hoạt động chính xác, từ đèn chiếu sáng đến hệ thống báo động.</p>\n<h2><br><strong>Hệ thống an toàn đa tầng bảo vệ người lái</strong></h2>\n<p><br>An toàn được đặt lên bàn cân ưu tiên với hệ thống phanh đĩa trang bị cho cả bánh trước và bánh sau, một cấu hình thường thấy trên các dòng xe mô tô phân khối lớn. Lực phanh được phân bổ đều và nhạy bén, cho phép người lái xử lý gọn gàng các tình huống bất ngờ trên đường. Phanh đĩa của<strong>&nbsp;xe máy điện Tailg T71</strong>&nbsp;có độ bền cao, chống mài mòn tốt và giữ được hiệu suất ổn định ngay cả khi di chuyển dưới trời mưa hay đường bùn đất.</p>\n<p><br>Sự vững chãi của xe còn đến từ cặp lốp không săm chuyên dụng, với kích cỡ lốp trước 90/90-14 và lốp sau 100/80-14. Thiết kế vân lốp thông minh giúp tăng cường độ bám đường, giảm thiểu nguy cơ trượt bánh khi vào cua gấp hoặc phanh gấp. Lốp không săm mang lại lợi ích kinh tế lâu dài khi giảm thiểu sự cố thủng lốp dọc đường, giúp hành trình của bạn luôn được thông suốt và an toàn tuyệt đối.</p>\n<p><br>Hệ thống giảm xóc thủy lực cao cấp TAILG là mảnh ghép cuối cùng hoàn thiện trải nghiệm vận hành đẳng cấp của dòng xe này. Bộ giảm xóc này có khả năng hấp thụ xung lực cực tốt, triệt tiêu những rung động nhỏ nhất từ mặt đường truyền lên tay lái và yên xe. Nhờ vậy, người dùng luôn cảm thấy thư thái, ít mệt mỏi ngay cả khi phải di chuyển trên những đoạn đường xấu hoặc địa hình không bằng phẳng.</p>\n<h2><br><strong>Tiện ích hiện đại nâng tầm trải nghiệm sử dụng</strong></h2>\n<p><br><strong>Tailg T71 </strong>sở hữu những tính năng hiện đại nhằm mang lại sự tiện nghi cao nhất cho chủ sở hữu trong mọi hoàn cảnh. Bảng điều khiển hiển thị sắc nét các thông số về vận tốc và lượng điện, giúp người dùng dễ dàng theo dõi và điều chỉnh lộ trình một cách khoa học. Các phím chức năng được tối ưu hóa theo thói quen sử dụng của người dùng, mang lại sự thân thiện và dễ dàng làm quen ngay từ lần đầu cầm lái.</p>\n<p><br>Không gian để chân rộng rãi và yên xe êm ái là những điểm cộng lớn về mặt nhân trắc học, giúp tư thế ngồi luôn được thoải mái nhất. Các phụ kiện như sổ bảo hành và bộ sạc đi kèm được đóng gói chỉn chu, phản ánh sự chuyên nghiệp của một thương hiệu lớn.</p>\n<p><br>Lựa chọn <strong>Tailg T71 </strong>còn là một quyết định tài chính sáng suốt khi chi phí vận hành cho mỗi km rẻ hơn nhiều lần so với xe chạy nhiên liệu hóa thạch. Việc bảo trì định kỳ cũng trở nên đơn giản hơn do động cơ điện có ít chi tiết cơ khí phức tạp, giúp bạn tiết kiệm thời gian và tiền bạc.</p>\n<h2><br><strong>Uy tín thương hiệu số 1 và cam kết chất lượng</strong></h2>\n<p><br>Đến từ nhà sản xuất <strong>xe điện</strong> hàng đầu Trung Quốc, <strong>Tailg T71 </strong>thừa hưởng những tinh hoa công nghệ và quy trình sản xuất nghiêm ngặt nhất thế giới. Danh tiếng của hãng là lời khẳng định đanh thép cho chất lượng linh kiện cũng như độ bền của sản phẩm trong môi trường khí hậu nhiệt đới gió mùa tại Việt Nam.</p>\n<p><br>Chính sách hậu mãi ưu việt với thời gian bảo hành dài hạn cho khung xe, động cơ và pin tạo ra sự an tâm tuyệt đối cho khách hàng. Hệ thống linh kiện thay thế luôn sẵn có và đồng bộ, giúp việc sửa chữa diễn ra nhanh chóng, không làm gián đoạn kế hoạch di chuyển của người dùng. Đầu tư vào một thương hiệu lớn như Tailg đồng nghĩa với việc bạn nhận được sự hỗ trợ chuyên nghiệp và tận tâm trong suốt vòng đời của sản phẩm.</p>\n<p><br><strong>Tailg T71</strong>&nbsp;là sự hội tụ của sức mạnh, thẩm mỹ và công nghệ đỉnh cao, xứng đáng là biểu tượng mới trong làng xe máy điện. Chiếc xe đáp ứng trọn vẹn từ nhu cầu thể hiện cá tính đến yêu cầu khắt khe về hiệu suất di chuyển đường dài.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-t72-l-pin-72v48a', 'Xe Máy Điện Tailg T72 L Pin 72V48A', 'tailg', '[\"xe-may-dien\"]', 35750000, 35750000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-5.webp\"]', '[]', '[]', '[]', '<p>Xe máy điện không còn đơn thuần là phương tiện phục vụ nhu cầu di chuyển quãng ngắn như trước đây, mà đang từng bước khẳng định vị thế là giải pháp thay thế thực sự cho xe xăng trong cuộc sống hiện đại. Khi công nghệ pin ngày càng phát triển, động cơ điện ngày càng mạnh mẽ và trải nghiệm vận hành được cải thiện rõ rệt, người dùng bắt đầu nhìn nhận xe điện như một phương tiện chính, không chỉ là lựa chọn phụ.</p>\n<p>Trong bối cảnh đó, Tailg T72 L nổi lên như một trong những mẫu xe tiêu biểu cho xu hướng mới. Không chỉ sở hữu thiết kế thể thao, hiện đại, mẫu xe này còn gây ấn tượng mạnh nhờ hiệu suất vận hành vượt trội, khả năng di chuyển đường dài và độ ổn định cao. Đây là dòng xe hướng đến những người dùng thực sự muốn chuyển đổi từ xe xăng sang xe điện mà không phải đánh đổi trải nghiệm.</p>', '<p><strong>Xe máy điện</strong> không còn đơn thuần là phương tiện phục vụ nhu cầu di chuyển quãng ngắn như trước đây, mà đang từng bước khẳng định vị thế là giải pháp thay thế thực sự cho xe xăng trong cuộc sống hiện đại. Khi công nghệ pin ngày càng phát triển, động cơ điện ngày càng mạnh mẽ và trải nghiệm vận hành được cải thiện rõ rệt, người dùng bắt đầu nhìn nhận xe điện như một phương tiện chính, không chỉ là lựa chọn phụ.</p>\n<p>Trong bối cảnh đó, Tailg T72 L nổi lên như một trong những mẫu xe tiêu biểu cho xu hướng mới. Không chỉ sở hữu thiết kế thể thao, hiện đại, mẫu xe này còn gây ấn tượng mạnh nhờ hiệu suất vận hành vượt trội, khả năng di chuyển đường dài và độ ổn định cao. Đây là dòng xe hướng đến những người dùng thực sự muốn chuyển đổi từ xe xăng sang xe điện mà không phải đánh đổi trải nghiệm.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-6.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thiết kế thể thao, cứng cáp khác biệt</strong></h2>\n<p>Ngay từ cái nhìn đầu tiên, Tailg T72 L đã tạo nên sự khác biệt rõ rệt so với nhiều mẫu xe điện phổ thông trên thị trường. Nếu như trước đây, xe điện thường đi theo hướng thiết kế mềm mại, nhỏ gọn và có phần trung tính, thì T72 L lại mang phong cách mạnh mẽ, góc cạnh và đậm chất thể thao.</p>\n<p>Tổng thể thân xe được tạo hình với các đường cắt dứt khoát, gãy gọn, mang lại cảm giác cứng cáp và chắc chắn. Thiết kế này không chỉ giúp xe trông nổi bật hơn khi di chuyển trên đường phố, mà còn phù hợp với những người dùng trẻ trung, yêu thích sự cá tính và khác biệt. Đây cũng là xu hướng thiết kế đang dần phổ biến trong phân khúc xe điện hiệu suất cao.</p>\n<p>Phần đầu xe là điểm nhấn đáng chú ý khi được trang bị cụm đèn LED sắc cạnh, bố trí thấp và mở rộng sang hai bên. Cách thiết kế này không chỉ mang tính thẩm mỹ cao mà còn giúp tăng khả năng chiếu sáng theo chiều ngang, hỗ trợ người lái quan sát tốt hơn khi di chuyển vào ban đêm hoặc trong điều kiện ánh sáng yếu. Ánh sáng LED cho độ sáng ổn định, tiết kiệm năng lượng và có tuổi thọ cao hơn so với các loại đèn truyền thống.</p>\n<p>Kích thước tổng thể của xe đạt 1960 x 720 x 1100 mm, tạo nên sự cân đối giữa độ lớn và tính linh hoạt. Xe đủ đầm để vận hành ổn định ở tốc độ cao, nhưng vẫn không quá cồng kềnh khi cần xoay trở trong các con phố nhỏ hoặc khu vực đông đúc. Các chi tiết nhựa ốp được hoàn thiện tốt, lắp ráp khít và chắc chắn, mang lại cảm giác cao cấp khi sử dụng lâu dài.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Ngoài ra, xe còn có nhiều tùy chọn màu sắc như trắng, xám, đen và bạc, giúp người dùng dễ dàng lựa chọn theo phong cách cá nhân. Từ sinh viên, người đi làm đến những người yêu thích phong cách thể thao đều có thể tìm được phiên bản phù hợp.</p>\n<h2><strong>Trải nghiệm ngồi lái được tính toán kỹ</strong></h2>\n<p>Không chỉ chú trọng đến thiết kế bên ngoài, Tailg T72 L còn được đầu tư kỹ lưỡng về trải nghiệm sử dụng thực tế, đặc biệt là tư thế ngồi lái – yếu tố ảnh hưởng trực tiếp đến sự thoải mái khi di chuyển hàng ngày. Chiều cao yên xe ở mức 760 mm, một con số khá lý tưởng đối với thể trạng người Việt. Người lái có thể dễ dàng chống chân khi dừng xe, đặc biệt hữu ích trong điều kiện giao thông đô thị thường xuyên phải dừng đèn đỏ hoặc di chuyển chậm. Điều này mang lại cảm giác an toàn và tự tin hơn, nhất là với người mới làm quen với xe điện.</p>\n<p>Sàn để chân được thiết kế rộng và phẳng, cho phép người lái thay đổi tư thế linh hoạt khi di chuyển đường dài. Đây là một điểm cộng lớn khi so sánh với các dòng xe có sàn hẹp hoặc thiết kế bó chân, dễ gây mỏi khi đi lâu. Không gian này cũng thuận tiện khi chở thêm đồ hoặc balo.</p>\n<p>Yên xe dài và được bọc đệm êm ái, đủ chỗ cho hai người lớn ngồi thoải mái mà không bị gò bó. Độ đàn hồi của yên được tinh chỉnh hợp lý, không quá cứng cũng không quá mềm, giúp giảm áp lực lên cơ thể khi di chuyển liên tục trong thời gian dài.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-t72-l-pin-72v48a-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p>Trọng lượng xe khoảng 80 kg, mang lại sự cân bằng giữa độ đầm và khả năng điều khiển. Xe không quá nhẹ để bị bồng bềnh khi chạy nhanh, nhưng cũng không quá nặng khiến việc dắt xe trở nên khó khăn. Với tải trọng tối đa lên đến 200 kg, Tailg T72 L hoàn toàn đáp ứng nhu cầu chở hai người cùng hành lý mà vẫn đảm bảo hiệu suất vận hành.</p>\n<h2><strong>Động cơ qs motor 4000w: mạnh mẽ như&nbsp;</strong><strong>xe xăng</strong></h2>\n<p>Điểm nổi bật nhất của <strong>Tailg T72</strong>&nbsp;L chính là khối động cơ QS Motor công suất 4000W, một trong những mức công suất ấn tượng trong phân khúc xe máy điện hiện nay. Đây là yếu tố giúp chiếc xe này thực sự tiệm cận trải nghiệm của xe xăng truyền thống.</p>\n<p>Khả năng tăng tốc của xe rất nhanh và mượt, gần như không có độ trễ khi vặn ga. Người lái có thể cảm nhận rõ lực kéo mạnh ngay từ những giây đầu tiên, đặc biệt hữu ích khi cần vượt xe hoặc di chuyển trong điều kiện giao thông đông đúc. Ngay cả khi chở hai người hoặc leo dốc, xe vẫn giữ được sự ổn định và không bị hụt hơi.</p>\n<p>Vận tốc tối đa đạt khoảng 80 km/h, đủ để đáp ứng nhu cầu di chuyển trong đô thị và cả những tuyến đường ngoại ô. Đây là mức tốc độ giúp người dùng không bị tụt lại trong dòng xe, đồng thời vẫn đảm bảo an toàn nếu vận hành đúng cách. Hệ truyền động hoàn toàn tự động giúp việc điều khiển xe trở nên đơn giản hơn rất nhiều. Người lái không cần sang số hay lo lắng về việc điều chỉnh côn, từ đó có thể tập trung hoàn toàn vào việc quan sát và xử lý tình huống giao thông. Điều này đặc biệt phù hợp với người mới chuyển từ xe xăng sang xe điện.</p>\n<h2><strong>Pin lithium 72v48ah: hành trình dài hơi không lo lắng</strong></h2>\n<p>Nếu động cơ mang lại sức mạnh, thì pin chính là yếu tố quyết định khả năng sử dụng thực tế của xe. Tailg T72 L được trang bị pin lithium LFP 72V48Ah – một trong những công nghệ pin tiên tiến hiện nay. Với dung lượng này, xe có thể di chuyển quãng đường lên đến khoảng 130 km chỉ với một lần sạc trong điều kiện tiêu chuẩn. Đây là con số rất ấn tượng, đủ để đáp ứng nhu cầu đi làm, đi học hoặc di chuyển trong thành phố nhiều ngày mà không cần sạc lại thường xuyên.</p>\n<p>Thời gian sạc dao động từ 6 đến 8 giờ, phù hợp với thói quen sạc qua đêm của đa số người dùng. Hệ thống sạc được tích hợp cơ chế tự ngắt khi pin đầy, giúp đảm bảo an toàn và hạn chế tình trạng sạc quá mức. So với ắc quy chì truyền thống, pin lithium có nhiều ưu điểm vượt trội như trọng lượng nhẹ hơn, tuổi thọ cao hơn và khả năng duy trì hiệu suất ổn định trong thời gian dài. Nếu sử dụng đúng cách, pin có thể hoạt động tốt trong khoảng 3 đến 5 năm, giúp giảm đáng kể chi phí thay thế.</p>\n<h2><strong>Hệ thống an toàn hoàn chỉnh</strong></h2>\n<p>Bên cạnh hiệu suất và quãng đường di chuyển, Tailg T72 L cũng được trang bị đầy đủ các yếu tố an toàn cần thiết để mang lại sự yên tâm cho người sử dụng. Hệ thống phanh đĩa CBS cho cả bánh trước và sau giúp phân bổ lực phanh hợp lý, tăng khả năng kiểm soát khi phanh gấp. Điều này đặc biệt quan trọng trong môi trường giao thông đô thị đông đúc, nơi các tình huống bất ngờ có thể xảy ra bất cứ lúc nào.</p>\n<p>Bánh xe 14 inch kết hợp với lốp Kenda kích thước 90/90-14 giúp tăng độ bám đường, hạn chế trơn trượt khi đi trên mặt đường ướt hoặc gồ ghề. Vành đúc và càng sau bằng nhôm giúp tăng độ cứng vững, giảm rung lắc khi vận hành ở tốc độ cao. Hệ thống giảm chấn thủy lực 5 cấp độ hoạt động hiệu quả trong việc hấp thụ dao động từ mặt đường, mang lại cảm giác êm ái ngay cả khi đi qua các đoạn đường xấu. Đây là yếu tố giúp nâng cao đáng kể trải nghiệm lái, đặc biệt khi di chuyển đường dài.</p>\n<h2><strong>Chế độ bảo hành uy tín, yên tâm sử dụng</strong></h2>\n<p>Một điểm cộng lớn khác của Tailg T72 L là chính sách bảo hành rõ ràng và minh bạch, giúp người dùng an tâm trong quá trình sử dụng lâu dài. Khung xe được bảo hành 3 năm, trong khi pin lithium, động cơ và hệ thống điện đều được bảo hành 2 năm. Đây là mức bảo hành khá tốt trong phân khúc xe điện hiện nay, thể hiện sự cam kết của hãng đối với chất lượng sản phẩm. Chính sách này không chỉ giúp người dùng tiết kiệm chi phí sửa chữa, mà còn tạo sự tin tưởng khi quyết định chuyển đổi từ xe xăng sang xe điện.</p>\n<p>Có thể thấy, Tailg T72 L Pin 72V48A không chỉ đơn thuần là một chiếc xe điện phục vụ nhu cầu đi lại hàng ngày, mà thực sự là một phương tiện có khả năng thay thế xe xăng trong nhiều tình huống khác nhau. Từ thiết kế mạnh mẽ, động cơ hiệu suất cao cho đến quãng đường di chuyển ấn tượng và hệ thống an toàn đầy đủ, tất cả đều hướng đến trải nghiệm sử dụng toàn diện. Trong bối cảnh chi phí nhiên liệu ngày càng tăng và xu hướng sống xanh ngày càng được quan tâm, việc lựa chọn một chiếc xe điện như <strong>Tailg</strong> T72 L không chỉ giúp tiết kiệm chi phí mà còn góp phần bảo vệ môi trường. Đây là lựa chọn phù hợp cho những ai đang tìm kiếm một phương tiện hiện đại, bền bỉ và đủ mạnh để thay thế xe xăng trong cuộc sống hàng ngày.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-vespa-r52-chinh-hang', 'Xe Máy Điện Tailg Vespa R52 Chính Hãng', 'tailg', '[\"xe-may-dien\"]', 18840000, 18840000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-5.webp\"]', '[]', '[]', '[]', '<p>Tailg Vespa R52 - một đại diện từ nhà sản xuất xe điện hàng đầu Trung Quốc, là sự giao thoa giữa phong cách Ý lãng mạn và công nghệ di chuyển bền vững. Mẫu xe này mang đến một lựa chọn hoàn hảo cho những ai tìm kiếm sự sang trọng, tinh tế cùng với hiệu suất vận hành ổn định và an toàn. R52 được thiết kế để vượt qua giới hạn của một chiếc xe điện thông thường, cung cấp một giải pháp di chuyển êm ái, tiết kiệm và đáng tin cậy cho mọi hành trình đô thị.</p>\n<p>Ngay từ cái nhìn đầu tiên, Tailg Vespa R52 đã gây ấn tượng mạnh mẽ với kiểu dáng mô phỏng chiếc Vespa huyền thoại, được tinh chỉnh để phù hợp với xu hướng điện hóa. Chiếc xe có kích thước tổng thể hài hòa (1775 mm x 720 mm x 1155 mm), tạo nên sự cân đối, vừa đủ bề thế để tạo cảm giác vững chãi, lại vừa đủ gọn gàng để dễ dàng xoay trở trong phố.</p>', '<p><strong>Tailg Vespa R52</strong> - một đại diện từ nhà sản xuất xe điện hàng đầu Trung Quốc, là sự giao thoa giữa phong cách Ý lãng mạn và công nghệ di chuyển bền vững. Mẫu xe này mang đến một lựa chọn hoàn hảo cho những ai tìm kiếm sự sang trọng, tinh tế cùng với hiệu suất vận hành ổn định và an toàn. R52 được thiết kế để vượt qua giới hạn của một chiếc xe điện thông thường, cung cấp một giải pháp di chuyển êm ái, tiết kiệm và đáng tin cậy cho mọi hành trình đô thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-6.webp\" alt=\"Xe Máy Điện Tailg Vespa R52 Chính Hãng\" loading=\"lazy\"></p>\n<h2><br><strong>Vóc dáng: Tái hiện vẻ đẹp cổ điển</strong></h2>\n<p><br>Ngay từ cái nhìn đầu tiên, <strong>Tailg</strong>&nbsp;<strong>Vespa R52</strong> đã gây ấn tượng mạnh mẽ với kiểu dáng mô phỏng chiếc Vespa huyền thoại, được tinh chỉnh để phù hợp với xu hướng điện hóa. Chiếc xe có kích thước tổng thể hài hòa (1775 mm x 720 mm x 1155 mm), tạo nên sự cân đối, vừa đủ bề thế để tạo cảm giác vững chãi, lại vừa đủ gọn gàng để dễ dàng xoay trở trong phố.</p>\n<p><br>Chiều cao yên xe ở mức 740 mm, một thông số lý tưởng, giúp người lái dễ dàng đặt chân xuống đất và kiểm soát xe một cách tự tin, đặc biệt là phù hợp với vóc dáng của người Châu Á. Mặc dù trọng lượng tịnh của xe là 95kg, nó vẫn giữ được sự ổn định cần thiết khi di chuyển, đồng thời không gây quá nhiều khó khăn khi dắt hoặc đỗ xe.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-7.webp\" alt=\"Xe Máy Điện Tailg Vespa R52 Chính Hãng\" loading=\"lazy\"></p>\n<p><br>Điểm nhấn quan trọng trong thiết kế là bộ vành nhôm đúc nguyên khối. Vành đúc không chỉ tạo nên vẻ ngoài cao cấp và thể thao mà còn góp phần vào độ bền và khả năng chịu lực của bánh xe. Lốp xe là loại Kenda không săm với kích thước 90/90-12, cung cấp độ bám đường tốt, giảm thiểu rủi ro khi bị thủng lốp và tăng tính an toàn cho người sử dụng.</p>\n<h2><br><strong>Sức mạnh: Động cơ 800W và tốc độ</strong></h2>\n<p><br>Trái tim của <strong>Tailg Vespa R52</strong> là động cơ điện một chiều không chổi than (BLDC) với công suất 800W. Mức công suất này được Tailg lựa chọn cẩn thận để tối ưu hóa sự bền bỉ và hiệu suất năng lượng, cung cấp khả năng tăng tốc mượt mà và vận hành êm ái.</p>\n<p><br>Với động cơ 800W, chiếc xe có thể đạt vận tốc tối đa 50 km/h. Tốc độ này được cân bằng hoàn hảo, đáp ứng tốt nhu cầu di chuyển trong nội thành và đảm bảo sự an toàn cho người điều khiển. Cơ chế vận hành tự động giúp việc lái xe trở nên đơn giản, không cần thao tác phức tạp như chuyển số, phù hợp cho mọi đối tượng.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespa-r52-chinh-hang-8.webp\" alt=\"tailg r52\" loading=\"lazy\"></p>\n<p><br>Khả năng tải trọng của R52 đạt mức 180kg. Đây là con số khá ấn tượng, cho phép <strong>xe điện</strong> chở hai người lớn và hành lý mà vẫn duy trì được hiệu suất ổn định. Động cơ được bảo hành 2 năm, thể hiện sự tin cậy của nhà sản xuất vào chất lượng và tuổi thọ của bộ phận cốt lõi này.</p>\n<h2><br><strong>Năng lượng: Ắc quy 5 bình cho hành trình 90km</strong></h2>\n<p><br>Nguồn năng lượng của <strong>Vespa R52</strong> đến từ bộ ắc quy chì-axit thông thường, bao gồm 5 bình 23Ah. Cấu hình 5 bình lớn đảm bảo cung cấp nguồn điện dồi dào và ổn định cho động cơ 800W, giúp xe duy trì hiệu suất hoạt động tốt nhất.</p>\n<p><br>Điểm mạnh vượt trội về mặt năng lượng là khả năng di chuyển quãng đường 90km sau mỗi lần sạc đầy. Thông số này mang lại sự linh hoạt và yên tâm cho người dùng, cho phép họ thực hiện các chuyến đi xa hơn hoặc sử dụng xe nhiều ngày liên tục mà không cần lo lắng về việc sạc pin thường xuyên.</p>\n<p><br>Quá trình nạp điện cho ắc quy diễn ra nhanh chóng, chỉ mất từ 5 đến 6 tiếng để sạc đầy hoàn toàn. Thời gian sạc ngắn này giúp người dùng dễ dàng tận dụng thời gian nghỉ ngơi hoặc làm việc để nạp lại năng lượng cho xe. Bộ sạc còn được tích hợp tính năng tự động ngắt khi ắc quy đầy, bảo vệ tuổi thọ của pin và ngăn ngừa tình trạng quá tải.</p>\n<h2><br><strong>An toàn: Phanh đĩa - cơ cấu càng gắp</strong></h2>\n<p><br>Tailg đã trang bị cho <strong>Vespa R52</strong> một hệ thống an toàn chủ động, bao gồm phanh đĩa trước và phanh tang trống sau. Phanh đĩa phía trước cung cấp lực hãm mạnh mẽ và chính xác hơn, trong khi phanh tang trống phía sau mang lại độ bền cao và dễ dàng bảo trì, tạo nên sự cân bằng giữa hiệu suất và độ tin cậy.</p>\n<p><br>Hệ thống giảm xóc trên xe sử dụng công nghệ giảm chấn thủy lực cao cấp. Giảm chấn thủy lực có tác dụng triệt tiêu các rung động từ mặt đường một cách hiệu quả, giúp xe lướt êm ái qua các đoạn đường xấu, ổ gà, giữ cho người lái luôn cảm thấy thoải mái và ổn định tay lái.</p>\n<p><br>Một điểm nhấn kỹ thuật đáng chú ý khác là càng sau của xe sử dụng loại càng gắp. Cơ cấu càng gắp được thiết kế để tăng cường sự vững chắc cho bánh sau, tối ưu hóa việc truyền lực từ động cơ và nâng cao độ ổn định của xe, đặc biệt khi tăng tốc hoặc đi vào cua.</p>\n<h2><br><strong>Chất lượng: Bảo hành chính hãng Tailg</strong></h2>\n<p><br>Uy tín của <strong>xe điện Tailg</strong> được củng cố bằng chính sách bảo hành dài hạn và rõ ràng. Khung xe được bảo hành 3 năm, một minh chứng cho sự tự tin của hãng vào chất lượng vật liệu và cấu trúc chịu lực của R52. Điều này mang lại sự an tâm tuyệt đối cho người dùng về độ bền cơ học của xe.</p>\n<p><br>Các bộ phận cốt lõi khác như động cơ, ắc quy và pin đều được bảo hành 2 năm. Chính sách bảo hành đồng bộ 2 năm cho cả ba thành phần điện tử quan trọng nhất này là một cam kết rất hào phóng, vượt trội hơn so với nhiều mẫu xe cùng phân khúc. Điều này khẳng định độ tin cậy và chất lượng cao cấp của Vespa R52.</p>\n<p><br>Là sản phẩm chính hãng từ Tailg, người dùng có thể hoàn toàn yên tâm về nguồn gốc và chất lượng. Các phụ kiện đi kèm theo xe bao gồm gương chiếu hậu, bộ sạc và sổ bảo hành, đảm bảo chiếc xe được vận hành và bảo trì theo đúng tiêu chuẩn của nhà sản xuất.</p>\n<h2><br><strong>Tiện ích: Phụ kiện và bánh xe 12 inch</strong></h2>\n<p><br><strong>Vespa R52</strong> được thiết kế để mang lại sự tiện lợi tối đa cho người dùng đô thị. Bánh xe có đường kính 12 inch là một ưu điểm lớn, giúp xe vượt qua các chướng ngại vật nhỏ và duy trì sự ổn định tốt hơn so với các loại bánh nhỏ hơn, đồng thời tạo nên vẻ ngoài cân đối, hài hòa.</p>\n<p><br>Tính năng sạc điện được tích hợp cơ chế tự động ngắt khi đầy là một tiện ích quan trọng, giúp người dùng không cần phải canh thời gian sạc, đồng thời kéo dài tuổi thọ của bộ ắc quy. Sự kết hợp giữa động cơ 800W và quãng đường 90km cho thấy sự tối ưu hóa hoàn hảo giữa công suất và hiệu suất năng lượng.</p>\n<p><br>Vành nhôm đúc không chỉ đẹp mà còn có độ bền cao, phù hợp với điều kiện đường sá Việt Nam. Mọi chi tiết trên xe đều được thiết kế để phục vụ mục đích sử dụng lâu dài và tin cậy, biến Vespa R52 thành một lựa chọn thông minh và tiết kiệm về mặt lâu dài.</p>\n<p><br><strong>Tailg Vespa R52</strong> là mẫu xe máy điện phong cách, kết hợp giữa thiết kế Vespa cổ điển và công nghệ điện hiện đại. Động cơ 800W cùng ắc quy 5 bình cho phép xe đạt vận tốc 50 km/h và di chuyển quãng đường 90km sau mỗi lần sạc. Hệ thống phanh đĩa/tang trống và giảm chấn thủy lực mang lại sự an toàn và trải nghiệm lái xe êm ái, vững chắc. Chính sách bảo hành đồng bộ 2-3 năm cho các bộ phận chính là sự bảo chứng cho chất lượng và độ bền của chiếc xe.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-tailg-vespas-r51-chinh-hang', 'Xe Máy Điện Tailg Vespas R51 Chính Hãng', 'tailg', '[\"xe-may-dien\"]', 13990000, 13990000, '/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-6.webp\"]', '[]', '[]', '[]', '<p>Tailg Vespas R51 chính hãng là một lựa chọn xe máy điện đáng cân nhắc, đặc biệt với những ai yêu thích vẻ đẹp vượt thời gian của dòng xe ga cổ điển mà vẫn muốn tận hưởng sự tiện lợi và thông minh của công nghệ điện. Chiếc xe này mang lại giải pháp di chuyển sạch sẽ, tiết kiệm, đồng thời giúp người dùng thể hiện phong cách cá nhân đầy tinh tế. Với sự kết hợp giữa thiết kế cuốn hút và hiệu suất vận hành ổn định, Vespas R51 xứng đáng là người bạn đồng hành tin cậy trên mọi cung đường phố thị.</p>\n<p>Vespas R51 ngay lập tức gây ấn tượng với ngoại hình được lấy cảm hứng rõ rệt từ chiếc Vespa huyền thoại, từ những đường cong mềm mại cho đến thân xe bầu bĩnh, đầy đặn. Phần đầu xe nổi bật với cụm đèn pha tròn cổ điển, sử dụng công nghệ LED hiện đại, vừa đảm bảo khả năng chiếu sáng tốt vừa giữ được nét duyên dáng, lãng mạn. Các chi tiết kim loại mạ chrome được bố trí khéo léo, như viền đèn hay gương chiếu hậu, làm tăng thêm vẻ sang trọng, cao cấp cho chiếc xe.</p>', '<p><strong>Tailg Vespas R51 chính hãng</strong> là một lựa chọn xe máy điện đáng cân nhắc, đặc biệt với những ai yêu thích vẻ đẹp vượt thời gian của dòng xe ga cổ điển mà vẫn muốn tận hưởng sự tiện lợi và thông minh của công nghệ điện. Chiếc xe này mang lại giải pháp di chuyển sạch sẽ, tiết kiệm, đồng thời giúp người dùng thể hiện phong cách cá nhân đầy tinh tế. Với sự kết hợp giữa thiết kế cuốn hút và hiệu suất vận hành ổn định, Vespas R51 xứng đáng là người bạn đồng hành tin cậy trên mọi cung đường phố thị.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><br><strong>Thiết kế cổ điển pha nét hiện đại cuốn hút</strong></h2>\n<p><br><strong>Vespas R51</strong> ngay lập tức gây ấn tượng với ngoại hình được lấy cảm hứng rõ rệt từ chiếc Vespa huyền thoại, từ những đường cong mềm mại cho đến thân xe bầu bĩnh, đầy đặn. Phần đầu xe nổi bật với cụm đèn pha tròn cổ điển, sử dụng công nghệ LED hiện đại, vừa đảm bảo khả năng chiếu sáng tốt vừa giữ được nét duyên dáng, lãng mạn. Các chi tiết kim loại mạ chrome được bố trí khéo léo, như viền đèn hay gương chiếu hậu, làm tăng thêm vẻ sang trọng, cao cấp cho chiếc xe.</p>\n<p><br>Thân xe được thiết kế liền khối, tạo cảm giác chắc chắn và bền bỉ. Các phiên bản màu sắc của R51 rất đa dạng, từ các tông màu pastel dịu dàng đến màu sắc đậm cá tính, giúp người mua dễ dàng lựa chọn theo sở thích riêng. Kích thước tổng thể và chiều cao yên xe 740mm được nhà sản xuất tính toán hợp lý, mang lại sự thoải mái cho người lái, đặc biệt là phù hợp với vóc dáng phụ nữ Việt Nam, giúp việc điều khiển và chống chân không còn là vấn đề lớn.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Mẫu xe này còn có sàn để chân rộng rãi, được thiết kế chống trượt, mang lại không gian thoải mái cho đôi chân và tiện lợi khi cần chở thêm vật dụng. Vị trí đặt đèn xi-nhan trước và sau được bố trí gọn gàng, tách biệt, tăng cường tín hiệu nhận diện khi chuyển hướng, giúp việc tham gia giao thông an toàn hơn.</p>\n<h2><br><strong>Động cơ êm ái, tăng tốc mượt – đi phố nhẹ tênh mỗi ngày</strong></h2>\n<p><br><strong>Tailg Vespas R51</strong> được trang bị động cơ điện không chổi than BLDC công suất 800W. Đây là mức công suất được đánh giá là vừa đủ mạnh mẽ cho một chiếc xe máy điện đô thị, đảm bảo xe có thể tăng tốc mượt mà và vượt qua các đoạn dốc nhỏ hay cầu vượt trong thành phố một cách nhẹ nhàng. Động cơ được đặt ở bánh sau, giúp việc truyền lực trực tiếp và hiệu quả hơn.</p>\n<p><br>Xe có thể đạt vận tốc tối đa khoảng 48 - 50 km/h, tốc độ lý tưởng để di chuyển an toàn và không quá nhanh, hoàn toàn tuân thủ các quy định hiện hành về xe máy điện. Nhờ công nghệ động cơ hiện đại, chiếc xe hoạt động rất êm ái, gần như không phát ra tiếng ồn khó chịu, mang lại trải nghiệm lái xe thư thái, yên tĩnh.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-tailg-vespas-r51-chinh-hang-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<p><br>Khả năng chịu tải của R51 khá tốt, lên đến 180kg, điều này có nghĩa là bạn có thể chở hai người lớn và một ít đồ đạc mà xe vẫn duy trì được độ ổn định cần thiết. Bộ điều tốc của Tailg được tinh chỉnh tốt, giúp người lái kiểm soát tay ga rất dễ dàng, cảm giác tăng giảm tốc độ rất mượt mà, không hề có hiện tượng giật cục hay trễ ga.</p>\n<h2><br><strong>Sức mạnh vừa đủ, tối ưu cho nhu cầu di chuyển thực tế</strong></h2>\n<p><br>Cung cấp năng lượng cho <strong>Vespas R51</strong> là bộ ắc quy chì axit gồm 5 bình 20Ah. Đây là cấu hình pin tiêu chuẩn, đã được kiểm chứng về độ bền và khả năng cung cấp điện năng ổn định, liên tục cho động cơ hoạt động. Ắc quy được bảo vệ kỹ lưỡng trong một hộp chứa chắc chắn, đảm bảo an toàn và chống nước tốt.</p>\n<p>Bạn cũng có thể lựa chọn bộ pin thilitum 60V-30Ah với ưu điểm chạy tới quãng đường 130km với 1 lầc sạc. Bnaj có thể đi học, đi làm cả tuần mà chỉ cần sạc 1 lần. pin thilium cũng có độ bền rất cao</p>\n<p><br>Quãng đường di chuyển mà <strong>xe máy điện</strong> có thể đạt được sau mỗi lần sạc đầy rất ấn tượng, khoảng 80-90km trong điều kiện lý tưởng. Phạm vi hoạt động rộng này giúp người dùng không cần phải lo lắng về việc sạc pin thường xuyên, bạn có thể thoải mái sử dụng xe cho cả tuần đi làm hoặc đi học mà chỉ cần sạc một vài lần.</p>\n<p><br>Thời gian sạc đầy pin cho R51 thường dao động từ 6 đến 8 tiếng. Bạn nên sạc xe vào buổi tối để tận dụng thời gian nghỉ. Bộ sạc đi kèm còn có chức năng tự động ngắt điện khi pin đã đầy, tính năng này cực kỳ quan trọng vì nó giúp bảo vệ ắc quy, ngăn chặn tình trạng sạc quá mức, từ đó kéo dài đáng kể tuổi thọ sử dụng của pin.</p>\n<h2><br><strong>Hệ thống an toàn chắc chắn, vững vàng trên mọi cung đường</strong></h2>\n<p><strong>Tailg Vespas R51</strong> được trang bị hệ thống phanh đĩa ở bánh trước, mang lại khả năng hãm tốc mạnh mẽ và chính xác. Phanh đĩa hoạt động rất nhạy và hiệu quả, giúp người lái tự tin hơn khi cần giảm tốc đột ngột hoặc xử lý các tình huống bất ngờ. Bánh sau của xe sử dụng phanh cơ (tang trống), hỗ trợ phân bổ lực phanh và tăng độ ổn định khi xe dừng lại.</p>\n<p><br>Hệ thống giảm xóc của xe cũng là một điểm cộng lớn, với phuộc trước ống lồng và lò xo trụ kép phía sau, đều có tính năng giảm chấn thủy lực. Cấu hình này giúp xe vận hành cực kỳ êm ái, hạn chế tối đa các rung lắc khó chịu khi đi qua đường xấu hay ổ gà, mang lại sự thoải mái tối đa cho người lái và người ngồi sau.</p>\n<p><br>Xe sử dụng lốp không săm, một trang bị an toàn cần thiết, giúp giảm thiểu nguy cơ bị xẹp lốp đột ngột khi bị vật nhọn đâm, đảm bảo bạn có thể tiếp tục di chuyển thêm một đoạn để tìm nơi vá xe an toàn. Tay lái được thiết kế vừa tầm, giúp người lái dễ dàng kiểm soát xe, đặc biệt khi vào cua hoặc di chuyển chậm.</p>\n<h2><strong>Tiện ích đầy đủ, trải nghiệm sử dụng “xịn” hơn mong đợi</strong></h2>\n<p><br>Chiếc xe được trang bị mặt đồng hồ điện tử LED, hiển thị rõ ràng và trực quan mọi thông tin vận hành quan trọng như tốc độ, quãng đường, và đặc biệt là mức pin còn lại. Màn hình này có độ sáng tốt, giúp bạn dễ dàng quan sát ngay cả khi trời nắng gắt.</p>\n<p><br>Một trong những tiện ích được đánh giá cao là cốp xe dưới yên rất rộng rãi, đủ chỗ cho một mũ bảo hiểm nửa đầu cùng nhiều vật dụng cá nhân khác. Điều này giúp bạn giải quyết được nỗi lo mang vác đồ đạc lỉnh kỉnh khi đi học hay đi chợ. Xe còn có hộc chứa đồ nhỏ phía trước và móc treo đồ tiện lợi.</p>\n<p><strong>Vespas R51</strong> còn được trang bị hệ thống khóa chống trộm thông minh, có chức năng khóa bánh và báo động từ xa. Tính năng này giúp bảo vệ xe khỏi trộm cắp, mang lại sự yên tâm tuyệt đối cho chủ sở hữu khi phải đỗ xe ở nơi công cộng hoặc ngoài trời.</p>\n<h2><br><strong>Bảo hành chính hãng rõ ràng – dùng lâu vẫn yên tâm</strong></h2>\n<p><br>Tailg là một thương hiệu xe điện có uy tín toàn cầu, và việc mua <strong>Vespas R51 chính hãng</strong> đảm bảo bạn nhận được sản phẩm chất lượng cao, lắp ráp theo tiêu chuẩn nghiêm ngặt. Sự tin cậy này được thể hiện rõ qua chế độ hậu mãi.</p>\n<p><br>Chính sách bảo hành của hãng thường rất rõ ràng, bảo hành khung xe trong thời gian dài (thường là 3 năm), và động cơ cùng ắc quy cũng có thời gian bảo hành hợp lý (1-2 năm). Sự cam kết bảo hành này giúp người dùng hoàn toàn yên tâm về tuổi thọ và độ bền bỉ của chiếc xe.</p>\n<p><br>Hệ thống đại lý và trung tâm dịch vụ chính hãng của Tailg được phủ sóng tốt, đảm bảo bạn dễ dàng tìm kiếm nơi bảo dưỡng, sửa chữa và thay thế linh kiện chính hãng. Điều này giúp chiếc Vespas R51 của bạn luôn được chăm sóc tốt nhất, duy trì hiệu suất hoạt động tối ưu.</p>\n<p><br><strong>Xe máy điện Tailg Vespas R51 chính hãng</strong> là một lựa chọn thông minh, kết hợp tuyệt vời giữa thiết kế duyên dáng, cổ điển và công nghệ di chuyển hiện đại, tiện lợi. Chiếc xe này chắc chắn sẽ là một người bạn đồng hành đáng tin cậy, giúp bạn tự tin thể hiện phong cách riêng trên mọi nẻo đường thành phố.</p>', 1);
