INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-vespa-motor-thai-vr3', 'Xe Máy Điện Vespa Motor Thái VR3', 'motor-thai', '[\"xe-may-dien\"]', 16290000, 16290000, '/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-motor-thai-vr3-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-vespa-pansy-s2-dibao-2022', 'Xe Máy Điện Vespa Pansy S2 Dibao 2022', 'dibao', '[\"xe-may-dien\"]', 16890000, 16890000, '/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespa-pansy-s2-dibao-2022-6.webp\"]', '[]', '[]', '[]', '<p>Nếu bạn là tín đồ của những chiếc Vespa siêu xịn đang làm mưa làm gió trên thị trường thì Dibao Pansy S2 hẳn là lựa chọn ngon, rẻ không nên bỏ qua. Đây là dòng xe nổi bật trong phân khúc xe điện vì sở hữu kiểu dáng cuốn hút với nhiều điểm cộng nằm ở khả năng vận hành và an toàn. Bản nâng cấp mới nhất của dòng xe Vespa là Pansy S2 được trang bị bộ vỏ nhựa ABS 100% giúp cho vẻ đẹp của xe hoàn hảo hơn nữa.</p>\n<p>Xe máy điện Dibao Pansy S2 hướng đến thiết kế trẻ và năng động, những ai yêu thích xe Vespa cũng sẽ \"phải lòng\" Pansy S2. Phiên bản này chắc chắn sẽ đốn tim các bạn nữ bởi thiết kế hiện đại, màu sắc trẻ trung bắt trend nhất trong các dòng xe máy điện hiện nay. Xe có lớp sơn sáng bóng, bền màu, không bị loang lổ như những dòng xe điện giá rẻ khác. Màu sắc của xe rất đẹp, nhiều người đã sử dụng Pansy S2 suốt một thời gian dài và công nhận rằng đây là dòng xe hiếm hoi có độ bền màu đáng kinh ngạc.</p>', '<p><em>Nếu bạn là tín đồ của những chiếc Vespa siêu xịn đang làm mưa làm gió trên thị trường thì Dibao Pansy S2 hẳn là lựa chọn ngon, rẻ không nên bỏ qua. Đây là dòng xe nổi bật trong phân khúc xe điện vì sở hữu kiểu dáng cuốn hút với nhiều điểm cộng nằm ở khả năng vận hành và an toàn. Bản nâng cấp mới nhất của dòng xe Vespa là Pansy S2 được trang bị bộ vỏ nhựa ABS 100% giúp cho vẻ đẹp của xe hoàn hảo hơn nữa.</em></p>\n<h2><strong>KIỂU DÁNG NHƯ NHỮNG CHIẾC VESPA SANG CHẢNH</strong></h2>\n<p><strong>Xe máy điện Dibao Pansy S2</strong><strong>&nbsp;</strong>hướng đến thiết kế trẻ và năng động, những ai yêu thích xe Vespa cũng sẽ \"phải lòng\" Pansy S2. Phiên bản này chắc chắn sẽ đốn tim các bạn nữ bởi thiết kế hiện đại, màu sắc trẻ trung bắt trend nhất trong các dòng xe máy điện hiện nay. Xe có lớp sơn sáng bóng, bền màu, không bị loang lổ như những dòng xe điện giá rẻ khác. Màu sắc của xe rất đẹp, nhiều người đã sử dụng Pansy S2 suốt một thời gian dài và công nhận rằng đây là dòng xe hiếm hoi có độ bền màu đáng kinh ngạc.&nbsp;</p>\n<p>Pansy SS có kích cỡ 1.750mm x 710mm x 1.110mm với tải trọng khoảng 180kg. Những đường nét quanh thân xe là dạng bo tròn tinh tế rất phù hợp với những bạn nữ. Phần mặt nạ trước có logo thương hiệu sáng bóng, cuốn hút. Tại thân xe, cái tên Pansy S2 được sắp xếp khéo léo và nổi bật với phần viền được mạ crom sáng bóng.</p>\n<h2><strong>HỆ THỐNG ĐÈN LED TINH TẾ</strong></h2>\n<p>Hệ thống đèn gây ấn tượng bởi đèn LED dạng hai tầng được bố trí khéo léo. Phần đèn pha dạng bo tròn khiến bạn nhầm tưởng đến những mẫu Vespa kiêu sa đến từ Ý. Điểm đáng chú ý tiếp theo ở hệ thống đèn chính là đèn pha và xi nhan trước. Dibao đã đầu tư dải đèn Demi LED trắng kiểu mới giúp Pansy S2 nổi bần bật trước đám đông. Dạng đèn uốn cong nhẹ với viền tinh tế tạo thành hình chữ L cực kỳ sang trọng.</p>\n<p>Cụm đèn hậu tại hai bên hông xe đối xứng không khác gì các mẫu Vespa đắt đỏ. Phần ốp bảo vệ màu đỏ tại đuôi xe tạo điểm nhấn khiến Pansy S2 dễ dàng gây được ấn tượng với người đối diện. Đèn có khả năng chiếu sáng tốt ngay cả khi thời tiết xấu với góc nhìn rộng. Cùng với đó là mức tiêu hao năng lượng khá thấp, Dibao Pansy S2&nbsp;mang đến giải pháp tiết kiệm năng lượng toàn diện khó có thể tìm thấy ở các dòng xe cùng tầm giá.&nbsp;</p>\n<h2><strong>KHUNG XE BỀN BỈ, CHẮC CHẮN</strong></h2>\n<p>Không thua kém Gogo SS, phiên bản Pansy S2 cũng được trang bị khung xe siêu chắc chắn. Đa số phụ huynh khi mua xe điện cho con em mình đều lo lắng về tính năng an toàn, Pansy S2 với khung xe chắc chắn đảm bảo độ an toàn cho người sử dụng. Dù sử dụng khung xe chắc chắn có thể khiến trọng lượng xe tăng lên nhưng Dibao vẫn trang bị khung xe để tăng độ an toàn cho người sử dụng, đây là điểm cộng vô cùng lớn.&nbsp;</p>\n<h2><strong>YÊN VÀ CỐP XE DIBAO PANSY S2 RỘNG RÃI</strong></h2>\n<p>Yên xe được bọc da loại cao cấp, khi ngồi tạo cảm giác êm ái dễ chịu kể cả khi phải di chuyển đường dài bạn cũng không cảm thấy quá khó chịu. Thảm để chân rộng rãi cùng các G chống trượt hiện đại, bạn có thể ngồi thoải mái không lo mỏi chân.&nbsp;</p>\n<p>Cốp xe của Pansy S2 khá rộng rãi có thể chứa nhiều đồ dùng cá nhân. Đặc biệt, phần cốp xe còn được trang bị thêm một aptomat thông minh có thể ngắt điện khi xảy ra những sự cố bất ngờ. Điều năng tăng sự an toàn khi sử dụng, bạn có thể yên tâm khi di chuyển với Dibao Pansy SS.&nbsp;</p>\n<h2><strong>TAY LÁI CÓ ĐỘ BÁM CAO, ĐỒNG HỒ HIỂN THỊ SẮC NÉT</strong></h2>\n<p>Tay lái là yếu tố ít được quan tâm nhưng Dibao đã thể hiện mình là thương hiệu đi đầu trong lĩnh vực xe điện bằng cách chăm chút phần tay lái vô cùng kỹ càng. Tay lái của Dibao Pansy S2 có khả năng thấm hút mồ hôi, người lái có thể dễ dàng thực hiện các thao tác một cách đơn giản. Phần bảng đồng hồ dạng full LED cũng là chi tiết đáng quan tâm. Màu sắc hiển thị của bảng đồng hồ là xanh và đỏ khá mới lạ, bạn có thể dễ dàng quan sát các thông số ngay cả khi trời nắng chói, rất tiện lợi.</p>\n<h2><strong>ĐỘNG CƠ KHỎE, CHẠY ÊM</strong></h2>\n<p>Lốp xe của Dibao Pansy S2 có độ bám đường tốt, kích thước khoảng 10 inch khá chắc chắn. Xe có phanh đĩa trước cùng phanh cơ sau, chống sốc đầy đủ nên khá an toàn cả khi chạy ở những đoạn đường có địa hình xấu. Tốc độ tối đa là 55-60km/h, bạn có thể di chuyển khoảng 80 đến 90 km với mỗi lần sạc.&nbsp;</p>\n<p>Nếu bạn thích những mẫu&nbsp;xe máy điện&nbsp;khỏe và có kiểu dáng đẹp thì Dibao Pansy S2 là lựa chọn không tồi chút nào. Rất nhiều người lựa chọn Dibao Pansy S2 và đều rất hài lòng với khả năng vận hành của mẫu xe này. Đây sẽ là người bạn đồng hành tuyệt vời của những bạn học sinh, sinh viên trẻ trung và năng động</p>\n<p>Hiện nay, phiên bản này có giá dưới 17,5 triệu đồng. Khi lựa chọn mua xe bạn nên đến những đại lý phân phối chính hãng của Dibao để mua được những dòng xe chất lượng nhé!</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-vespro-viet-thai', 'Xe Máy Điện Vespro Việt Thái', 'viet-thai', '[\"xe-may-dien\"]', 13900000, 13900000, '/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-vespro-viet-thai-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Việt Thái\"},{\"label\":\"Xuất xứ\",\"value\":\"Liên Doanh\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Bảo hành Pin\",\"value\":\"2 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1.750mm x 710mm x 1.110mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"760mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Lốp: 406mm - Vành: 254mm\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ mầu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"800W\"},{\"label\":\"Vận hành\",\"value\":\"Tự động hoàn toàn\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50-55km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"85kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"70 - 80 km/lần sạc\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, phanh kéo sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình acquy 20Ah\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực. Phuộc sau: Lò so trụ đơn, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, chống trộm, sổ bảo hành\"}]}]', '<p>Bạn nghĩ sao về trào lưu sử dụng xe điện trong thời gian trở lại đây? Có thể thấy rõ rằng số lượng xe máy điện tại Việt Nam đã tăng lên đáng kể chỉ trong một thời gian ngắn. Dòng phương tiện này không chỉ đẹp về ngoại hình, dễ dàng sử dụng mà còn tối ưu chi phí. Bài viết ngày hôm nay sẽ giới thiệu đến bạn xe máy điện Vespro Việt Thái - một sản phẩm cao cấp của năm 2022.</p>\n<p>Xe điện Vespro Việt Thái khiến khách hàng thay đổi hoàn toàn suy nghĩ về một sản phẩm xe máy điện. Ngoại hình của sản phẩm vô cùng thời trang, phù hợp với nhu cầu thẩm mỹ của giới trẻ. Chính vì thế, chiếc xe này đã trở thành lựa chọn hàng đầu của nhiều học sinh, sinh viên và cả người đi làm.</p>', '<p><em>Bạn nghĩ sao về trào lưu sử dụng xe điện trong thời gian trở lại đây? Có thể thấy rõ rằng số lượng xe máy điện tại Việt Nam đã tăng lên đáng kể chỉ trong một thời gian ngắn. Dòng phương tiện này không chỉ đẹp về ngoại hình, dễ dàng sử dụng mà còn tối ưu chi phí. Bài viết ngày hôm nay sẽ giới thiệu đến bạn xe máy điện Vespro Việt Thái - một sản phẩm cao cấp của năm 2022.</em></p>\n<h2><strong>1. XE MÁY ĐIỆN VESPRO VIỆT THÁI DIỆN MẠO SANG CHẢNH THỜI THƯỢNG</strong></h2>\n<p>Xe điện Vespro Việt Thái khiến khách hàng thay đổi hoàn toàn suy nghĩ về một sản phẩm&nbsp;xe máy điện. Ngoại hình của sản phẩm vô cùng thời trang, phù hợp với nhu cầu thẩm mỹ của giới trẻ. Chính vì thế, chiếc xe này đã trở thành lựa chọn hàng đầu của nhiều học sinh, sinh viên và cả người đi làm.</p>\n<h3><strong>Thiết kế chỉn chu trong từng chi tiết</strong></h3>\n<p>Mời bạn ngắm nhìn tổng thể của chiếc xe máy điện Vespro Việt Thái. Thực sự là một siêu phẩm đẹp đến từng chi tiết phải không nào!</p>\n<p>Sản phẩm là “trái ngọt” của một quá trình dài dày công nghiên cứu và thiết kế. Diện mạo của nó vừa thanh thoát, trẻ trung, hiện đại, lại có chút gì đó cổ điển. Cảm hứng sáng tạo chiếc xe được dựa trên nguyên mẫu Vespa đình đám đến từ Ý. Chính vì thế mà phiên bản này vô cùng mềm mại trong từng đường nét, toát lên thần thái sang chảnh, phù hợp với xu hướng mới của thời đại.</p>\n<h3><strong>Vỏ nhựa ABS cao cấp</strong></h3>\n<p>Nhà sản xuất đã quyết định sử dụng chất liệu nhựa ABS-PP cao cấp để làm nên dàn áo cho chiếc xe. Nhờ hệ thống sản xuất hiện đại, từng bộ phận của vỏ xe đều có đường nét vô cùng mềm mại và uyển chuyển. Chúng kết hợp với nhau một cách ăn khớp đến hoàn hảo, tạo nên tổng thể vô cùng thời trang.</p>\n<p>Thiết diện dàn áo rất dày, khi gõ vào ta nghe thấy âm thanh trầm. Điểm này khác biệt hẳn so với những dòng xe giá rẻ trên thị trường. Độ dày của vỏ giúp chiếc xe trông cao cấp và cứng cáp hơn hẳn. Nó có khả năng chống chịu cực tốt với những điều kiện khắc nghiệt của môi trường cũng như hạn chế bị nứt vỡ do va đập.</p>\n<h3><strong>Công nghệ sơn tĩnh điện hiện đại</strong></h3>\n<p>Phủ ngoài chiếc xe là lớp sơn tĩnh điện theo công nghệ phun đa lớp tiên tiến. Đây là cách thường được áp dụng cho những dòng xe cao cấp. Công nghệ này mang đến cho xe máy điện Vespro Việt Thái một vẻ ngoài hoàn hảo, màu sắc tươi sáng, trong trẻo, độ đều màu tuyệt đối. Sơn không chỉ đẹp mà còn rất bền, dù xe phải làm việc trong nhiều năm liền thì nó vẫn không bị phai màu và mất đi độ bóng bẩy.</p>\n<h3><strong>Thiết kế phù hợp cho mọi dáng người</strong></h3>\n<p>Xe máy điện Vespro Việt Thái được nghiên cứu thiết kế để phù hợp với vóc dáng nhỏ nhắn của người Việt. Chính vì thế, nó là một sản phẩm nhỏ gọn với yên cao 760mm. Đệm yên siêu êm, bọc ngoài là da PU cao cấp, cộng với sàn để chân siêu rộng. Điều này giúp cho những khách hàng có chiều cao từ 1m5 trở lên đều có thể ngồi lái xe thoải mái và an toàn.</p>\n<h2><strong>2. CHẤT LƯỢNG ĐẾN TỪ HỆ THỐNG KHUNG CỨNG CHẮC</strong></h2>\n<h3><strong>Đúc nguyên khối từ thép không gỉ</strong></h3>\n<p>Xe Vespro Việt Thái được dựng lên từ bộ khung đúc nguyên khối. Nhà sản xuất quyết định sử dụng chất liệu thép không gỉ cao cấp để giúp xe cứng cáp. Từ hệ thống khung này, từng phụ tùng được lắp ráp để làm nên một tổng thể hoàn thiện như bạn đã thấy hiện nay.</p>\n<h3><strong>Tải trọng ấn tượng</strong></h3>\n<p>Sản phẩm có tải trọng lên đến 150kg. Đây là một mức ấn tượng cho một mẫu xe máy điện. Khả năng này đến từ bộ khung đúc cứng cáp cùng cách thiết kế xe hợp lý, giúp phân bố cân nặng đồng đều. Nhờ thế mà bạn hãy thoải mái sử dụng chiếc xe để đèo thêm người bạn đồng hành. Hành trình sẽ càng vui hơn khi có người sẻ chia trong từng khoảnh khắc đúng không nào!</p>\n<h3><strong>Vì sao xe máy điện Vespro Việt Thái lại nặng đến thế?</strong></h3>\n<p>So với nhiều dòng xe máy điện, có lẽ Vespro Việt Thái là một chiếc xe khá nặng. Cụ thể trọng lượng của nó là 85kg. Nguyên nhân là bởi sản phẩm này được tạo nên từ bộ khung thép đúc chất lượng, từng chi tiết linh kiện, phụ tùng đều là hàng chính hãng. Tất cả tạo nên một chiếc xe cứng cáp nhưng trọng lượng lại khá nặng.</p>\n<p>Tuy là cân nặng hơi cao nhưng điều này không làm ảnh hưởng đến quá trình lái xe. Bạn sẽ cảm thấy rõ về độ dầm và chắc chắn của sản phẩm. Chiếc xe đi êm, không hề có dấu hiệu lỏng lẻo, đảo bánh hay rung lắc nơi tay lái.</p>\n<h2><strong>3. ĐÈN LED TIÊN TIẾN</strong></h2>\n<p>Sản phẩm được trang bị hệ thống đèn LED hiện đại với thiết kế đẹp mắt. Ưu điểm của công nghệ này vượt trội hơn hẳn so với dòng đèn sợi đốt. Đèn LED tiết kiệm điện tới 90%, chất lượng ánh sáng trong trẻo nhưng không làm lóa mắt, độ bền gấp 5 lần.</p>\n<p>Phía trước đầu xe là đèn pha dáng tròn với thấu kính lồi dạng trong suốt. Nhờ thế mà độ khuếch tán ánh sáng được tăng lên đáng kể, khả năng quan sát trong đêm tối được cải thiện. Đèn xi nhan trước được bố trí đối xứng ở yếm xe với thiết kế như đôi cánh thanh thoát. Dàn đèn ở phía đuôi xe cũng có kiểu dáng tương đồng, bố trí gọn gàng để không biến chiếc xe trở nên thô kệch Ta có đèn pha hậu ốp đỏ, hai đèn xi nhan đối xứng.</p>\n<h2><strong>4. ĐỘNG CƠ MẠNH MẼ VÀ BỀN BỈ</strong></h2>\n<p>Xe máy điện Vespro Việt Thái sở hữu động cơ điện vận hành tự động 100%. Công suất của động cơ là 800W mạnh mẽ. Nhà sản xuất đã cải tiến hệ thống máy bên trong để chiếc xe làm việc tốt hơn những mẫu xe đời trước. Ngoài ra, với thiết kế khép kín ấn tượng, động cơ hoàn toàn có thể đi mưa, lội nước mà không hề bị chập điện hay chết máy.</p>\n<p>Khách hàng trải nghiệm sản phẩm đều có chung đánh giá đây là một mẫu xe điện chạy khỏe. Chỉ cần vặn tay ga, nó sẽ di chuyển ngay với khả năng tăng tốc nhanh, tốc độ max lên đến 50km/h. Có thể nói rằng đây là một trong những mẫu xe chạy bốc tại thời điểm 2022. Chiếc xe này đặc biệt phù hợp cho những người mới tập lái bởi rất dễ điều khiển, chuyển số tự động chỉ bằng cách vặn tay ga.</p>\n<h2><strong>5. BỘ 5 ẮC QUY 20AH GIÚP KÉO DÀI HÀNH TRÌNH TỚI 70KM</strong></h2>\n<p>Sản phẩm Vespro Việt Thái là phiên bản được nâng cấp về nhiều bộ phận, trong đó có hệ thống lưu trữ điện năng. Nó sở hữu 5 ắc quy 20Ah tiên tiến, chỉ cần sạc 10-12 tiếng là đi được tới 70km. Bộ sạc đi kèm xe phù hợp với hệ thống điện tại Việt Nam. Nhà sản xuất đã thiết kế chức năng tự động ngắt điện khi sạc đầy để đảm bảo an toàn tối đa cho người dùng và bảo vệ tuổi thọ của ắc quy.</p>\n<h2><strong>6. BÁNH XE CAO CẤP ĐỒNG BỘ VỚI CÔNG NGHỆ HIỆN ĐẠI</strong></h2>\n<p>Một phiên bản xe đỉnh cao chắc chắn phải có bánh xe và hệ thống phanh, giảm xóc đồng bộ tối ưu. Nhắc về điểm này, bạn khó có thể tìm thấy điểm đáng chê trên chiếc Vespro Việt Thái.</p>\n<h3><strong>Vành đúc, lốp không săm</strong></h3>\n<p>Tương tự như những mẫu xe tay ga cao cấp, chiếc xe máy điện Vespro Việt Thái cũng sở hữu bánh xe vành đúc cùng lốp không săm chất lượng. Lốp có đường kính 406mm nên khoảng không ở gầm xe được tăng lên đáng kể, hạn chế tình trạng cạ gầm khi lên vỉa hè. Vành dạng 3 chấu cắt CNC hiện đại, phủ ngoại là lớp sơn ánh bạc sáng bóng tương phản với màu lốp đen tuyền.</p>\n<p>Lốp không săm có rất nhiều ưu điểm. Trước hết, loại này có trọng lượng nhẹ nên giúp xe di chuyển tiết kiệm nhiên liệu hơn. Thứ hai, lốp không săm an toàn hơn so với loại lốp có săm truyền thống. Bộ phận này giữ vai trò quan trọng trong việc duy trì khả năng bám đường tốt, hạn chế tối đa tình trạng trượt bánh. Lốp đồng thời có khả năng giữ khí và tản nhiệt tốt, nếu vô tình đâm phải vật nhọn thì vẫn có thể tiếp tục di chuyển thêm một đoạn dài trên đường.</p>\n<h3><strong>Hệ thống phanh đĩa trước, phanh cơ sau</strong></h3>\n<p>Phiên bản được trang bị phanh đĩa trước, phanh kéo sau. Phanh đĩa có giá thành cao, khả năng làm việc linh hoạt và an toàn. Trong khi đó, phanh cơ vẫn có thể làm tốt nhiệm vụ điều chỉnh tốc độ ở bánh sau. Sự kết hợp này mang lại trải nghiệm điều chỉnh tốc độ linh hoạt và mượt mà, nhờ vậy mà vừa nâng cao trải nghiệm của người điều khiển vừa không làm giá xe tăng quá cao.</p>\n<h3><strong>Giảm xóc công nghệ giảm chấn thủy lực</strong></h3>\n<p>Kết nối đồng bộ với hai bánh xe là hệ thống giảm xóc tiên tiến. Phuộc trước là dạng phuộc nhún, phuộc sau là dạng lò xo trụ. Hai bộ phận có khả năng giữ cân bằng tối ưu cho chiếc xe khi phải chở nặng và di chuyển nơi mặt đường gồ ghề. Nhờ thế mà mỗi chuyến đi của bạn đều thật là thoải mái.</p>\n<h2><strong>CÁC TÍNH NĂNG MỚI CỦA XE MÁY ĐIỆN VESPRO VIỆT THÁI 2022:</strong></h2>\n<p>Xe trang bị bộ khoá smarkey thông minh thiết kế hiện đại thời trang không kém cạnh gì các dòng tay ga cao cấp như Abalde, Vario hay Vespa trên thị trường ngày nay cả. Viền quanh khoá có đèn báo hiển thị khá đẹp giúp bạn có thể thấy rõ các ký hiệu trên ổ khoá dễ thao tác kể cả ban ngày hay ban đêm.</p>\n<p>Một bộ khoá điện tử&nbsp;cho phép bạn mở khoá từ xa không cần chìa, chống trộm xe an toàn. Hầu hết trên thị trường xe máy điện đời mới&nbsp;đều được trang bị 1 bộ khoá điện tử như vậy.</p>\n<p>Cốp xe rộng rãi bạn có thể bỏ được nhiều đồ dùng như nón bảo hiểm áo mưa. Với một chiếc cốp rộng rãi thì đó là một điều rât tuyệt vời để bạn chứa đồ nhất là các bạn nữ sinh rất cần một chiếc xe có cốp đủ rộng để họ có thể bỏ các vật dụng cá nhân trong này. Ngoài ra phía trước yếm xe còn có 2 học chứa đồ nhỏ nằm kín bên trong có khoá an toàn nữa.</p>\n<p>Yên xe máy điện Vespro Việt Thái này khá rộng rãi ngồi 2 người rất thoải mái không hề bị gò bó chật chội. Nên việc chở người ngồi phía sau là rất thích hợp.&nbsp;</p>\n<p>Đồng hồ điện tử với các thông số to rõ ràng hiển thị đầy đủ: vận tốc, quãng đường, vạch báo pin, xi nhan, đèn...Mọi thông số đêu được hiển thị đầy đủ trên chiếc đồng hồ này kết hợp với các cụm công tắc đèn còi xi nhan, nút tốc độ, nút parking đều được tích hợp đồng bộ hiển thị trên một chiếc đồng hồ điện tử nhỏ nhắn này.</p>\n<p>Xe máy điện Vespro Việt Thái&nbsp;tạo nên một cơn sốt tại thị trường Việt Nam. Nó gây ấn tượng tốt với khách hàng, đặc biệt là học sinh, sinh viên và dân văn phòng. Với thông số kỹ thuật được cải tiến, chiếc xe này chắc chắn sẽ mang đến những hành trình tuyệt vời. Để tìm hiểu kỹ hơn về mẫu xe Vespro Việt Thái, chúng tôi mời bạn tới hệ thống cửa hàng của Yên Thoa. Chúc quý khách một ngày an lành.</p>\n&nbsp;\n<strong>Video sản phẩm:</strong>\n<br>\n<br>\n&nbsp;\nXe Máy Điện Vespro Việt Thái 2022 - Dòng Xe Điện Vespa Giá Rẻ Chất Lượng Cao', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-victoria-v38-viet-nhat', 'Xe Máy Điện Victoria V38 Việt Nhật', 'victoria', '[\"xe-may-dien\"]', 16990000, 16990000, '/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-v38-viet-nhat-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-victoria-viral-pro-the-tu-nfc', 'Xe Máy Điện Victoria Viral Pro Thẻ Từ NFC', 'victoria', '[\"xe-may-dien\"]', 17100000, 17100000, '/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-6.webp\"]', '[]', '[]', '[]', '<p>Không chỉ dừng lại ở con số ấn tượng, mẫu xe Victoria Viral Pro mang đến cho người dùng một trải nghiệm toàn diện hơn, khi kết hợp giữa thiết kế hiện đại, công nghệ pin tối ưu và hệ thống vận hành ổn định. Với những ai đang tìm kiếm một phương tiện vừa tiết kiệm, vừa tiện lợi cho cuộc sống đô thị, đây không đơn thuần là một lựa chọn mới – mà có thể là một bước nâng cấp đáng giá.</p>\n<p>Chỉ vài năm trước, xe điện thường được xem là giải pháp tạm thời, phù hợp với quãng đường ngắn và nhu cầu cơ bản. Tuy nhiên, khi giá xăng liên tục biến động và nhận thức về môi trường tăng cao, người dùng bắt đầu nhìn xe điện với một góc nhìn khác. Họ không còn chấp nhận những mẫu xe “đi gần, yếu và nhanh xuống pin”, mà đòi hỏi nhiều hơn về hiệu năng và độ tin cậy.</p>', '<p>Không chỉ dừng lại ở con số ấn tượng, mẫu xe&nbsp;Victoria Viral Pro&nbsp;mang đến cho người dùng một trải nghiệm toàn diện hơn, khi kết hợp giữa thiết kế hiện đại, công nghệ pin tối ưu và hệ thống vận hành ổn định. Với những ai đang tìm kiếm một phương tiện vừa tiết kiệm, vừa tiện lợi cho cuộc sống đô thị, đây không đơn thuần là một lựa chọn mới – mà có thể là một bước nâng cấp đáng giá.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-7.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Thị trường xe điện đang thay đổi: Người dùng không còn “dễ tính” như trước</strong></h2>\n<p>Chỉ vài năm trước, xe điện thường được xem là giải pháp tạm thời, phù hợp với quãng đường ngắn và nhu cầu cơ bản. Tuy nhiên, khi giá xăng liên tục biến động và nhận thức về môi trường tăng cao, người dùng bắt đầu nhìn xe điện với một góc nhìn khác. Họ không còn chấp nhận những mẫu xe “đi gần, yếu và nhanh xuống pin”, mà đòi hỏi nhiều hơn về hiệu năng và độ tin cậy.</p>\n<p>Chính sự thay đổi này đã tạo ra một “cuộc lọc” trên thị trường, nơi những sản phẩm thực sự chất lượng mới có thể tồn tại. Và đó cũng là lý do vì sao <strong>Victoria Viral Pro</strong> được quan tâm, khi nó giải quyết trực tiếp một trong những nỗi lo lớn nhất của người dùng: quãng đường di chuyển.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-8.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Victoria Viral Pro: Chiếc xe điện sinh ra cho nhu cầu thực tế</strong></h2>\n<p>Không phải ngẫu nhiên mà Victoria lại định hướng dòng Viral Pro cho nhóm khách hàng rộng như vậy. Từ học sinh, sinh viên, nhân viên văn phòng cho đến các gia đình nhỏ, tất cả đều có thể tìm thấy sự phù hợp trong mẫu xe này.</p>\n<p>Với những người trẻ, đây là phương tiện thể hiện phong cách sống xanh và năng động. Với dân văn phòng, đây là giải pháp tiết kiệm chi phí đi lại mỗi ngày. Còn với gia đình, đây là một phương tiện an toàn, dễ sử dụng cho nhiều mục đích khác nhau như đi chợ, đưa đón con cái hay di chuyển trong nội đô.</p>\n<p>Điểm chung của tất cả những đối tượng này là họ cần một chiếc xe “đủ tốt cho mọi nhu cầu”, và đó chính là điều mà Victoria Viral Pro hướng tới.</p>\n<p><img src=\"/sites/yenthoa/img/sp/xe-may-dien-victoria-viral-pro-the-tu-nfc-9.webp\" alt=\"\" loading=\"lazy\"></p>\n<h2><strong>Pin 130km/lần sạc: Lợi thế tạo nên khác biệt rõ ràng</strong></h2>\n<p>Một trong những điểm nổi bật nhất của Victoria Viral Pro chính là hệ thống pin có khả năng di chuyển lên đến 130km sau mỗi lần sạc đầy. Đây là con số không chỉ ấn tượng trên giấy, mà còn có ý nghĩa rất lớn trong thực tế sử dụng hàng ngày.</p>\n<p>Với quãng đường này, người dùng có thể thoải mái di chuyển trong nhiều ngày mà không cần sạc lại, đặc biệt phù hợp với những ai có lịch trình di chuyển dày đặc. Điều này giúp giảm đáng kể sự phụ thuộc vào việc tìm kiếm điểm sạc, đồng thời mang lại cảm giác tự do và chủ động hơn khi sử dụng xe điện.</p>\n<p>Hệ thống pin lithium-ion dung lượng cao còn giúp xe duy trì hiệu suất ổn định trong suốt hành trình, không bị “đuối sức” khi gần hết pin – một vấn đề thường gặp ở các dòng xe điện giá rẻ.</p>\n<h2><strong>Trải nghiệm thực tế: Đi xa không còn là nỗi lo</strong></h2>\n<p>Trong điều kiện di chuyển đô thị bình thường, <strong>Victoria</strong> Viral Pro có thể đạt quãng đường từ 125–130km khi chạy ở tốc độ ổn định. Ngay cả khi di chuyển với tốc độ cao hơn, xe vẫn đảm bảo quãng đường trên 100km – một con số đủ để đáp ứng hầu hết nhu cầu hàng ngày.</p>\n<p>Thời gian sạc từ 8–10 giờ cũng được xem là hợp lý, cho phép người dùng sạc qua đêm mà không ảnh hưởng đến lịch trình. Khi thức dậy vào buổi sáng, xe đã sẵn sàng cho một ngày di chuyển mới mà không cần lo lắng về pin.</p>\n<p>Đây chính là yếu tố giúp xe điện trở nên “thực dụng” hơn, không còn là phương tiện phụ mà có thể thay thế hoàn toàn xe xăng trong nhiều trường hợp.</p>\n<h2><strong>Thiết kế hiện đại: Gọn gàng nhưng vẫn đầy đủ tiện nghi</strong></h2>\n<p>Bên cạnh hiệu năng, thiết kế của Victoria Viral Pro cũng là điểm cộng lớn. Với kích thước gọn gàng, xe dễ dàng di chuyển trong các khu vực đông đúc, phù hợp với đặc thù giao thông tại các thành phố lớn.</p>\n<p>Chiều cao yên hợp lý giúp người lái dễ dàng chống chân, đặc biệt phù hợp với vóc dáng người Việt. Sàn để chân rộng và thấp giúp việc lên xuống xe trở nên thuận tiện hơn, đồng thời mang lại cảm giác thoải mái khi di chuyển đường dài.</p>\n<p>Các chi tiết như ghế da chống nước, hệ thống đèn LED hay màn hình hiển thị đều được chăm chút kỹ lưỡng, tạo nên tổng thể hiện đại và tiện dụng.</p>\n<h2><strong>An toàn luôn là ưu tiên hàng đầu</strong></h2>\n<p>Không chỉ tập trung vào hiệu năng, Victoria Viral Pro còn được trang bị nhiều tính năng an toàn nhằm bảo vệ người sử dụng trong mọi tình huống.</p>\n<p>Hệ thống phanh đĩa trước kết hợp phanh cơ sau giúp kiểm soát tốc độ tốt hơn, đặc biệt khi cần dừng gấp. Giảm xóc thủy lực giúp xe vận hành êm ái trên nhiều loại địa hình, giảm thiểu cảm giác rung lắc.</p>\n<p>Ngoài ra, các tính năng như khóa NFC hay chế độ P dừng an toàn cũng góp phần nâng cao trải nghiệm sử dụng, giúp người dùng cảm thấy yên tâm hơn khi điều khiển xe.</p>\n<h2><strong>Hiệu năng vận hành: Mạnh mẽ và ổn định trong mọi điều kiện</strong></h2>\n<p>Được trang bị động cơ 1000W, Victoria Viral Pro mang lại khả năng vận hành mạnh mẽ, phù hợp với cả đường bằng và đường dốc. Tốc độ tối đa 55km/h giúp xe dễ dàng hòa nhập với dòng giao thông đô thị mà không bị “tụt lại phía sau”.</p>\n<p>Khả năng leo dốc tốt và tải trọng cao cũng là điểm cộng lớn, đặc biệt với những gia đình có nhu cầu chở thêm người hoặc hàng hóa. Điều này giúp xe không chỉ phục vụ cá nhân, mà còn đáp ứng được nhiều mục đích sử dụng khác nhau.</p>\n<h2><strong>Tiện ích thông minh: Nhỏ nhưng “đáng tiền”, nâng tầm trải nghiệm mỗi ngày</strong></h2>\n<p>Không chỉ dừng lại ở hiệu năng hay thiết kế, Victoria Viral Pro còn được trang bị nhiều tiện ích thông minh giúp việc sử dụng hàng ngày trở nên dễ dàng và thoải mái hơn. Đây là những chi tiết có thể không quá nổi bật khi nhìn qua, nhưng lại tạo nên sự khác biệt rõ rệt trong quá trình sử dụng lâu dài.</p>\n<p>Một trong những tiện ích đáng chú ý là hệ thống màn hình LED hiển thị đầy đủ thông tin như tốc độ, mức pin, quãng đường và các cảnh báo cần thiết. Nhờ đó, người dùng có thể kiểm soát tình trạng xe một cách trực quan mà không cần phải “ước lượng” như nhiều dòng xe điện đời cũ. Điều này đặc biệt hữu ích khi di chuyển đường dài, giúp bạn chủ động hơn trong việc sạc pin và lên kế hoạch hành trình.</p>\n<p>Bên cạnh đó, xe còn được trang bị cổng sạc USB tiện lợi, cho phép người dùng sạc điện thoại ngay khi đang di chuyển. Trong thời đại mà smartphone gần như là “vật bất ly thân”, chi tiết này tuy nhỏ nhưng lại cực kỳ thiết thực, особенно với những ai thường xuyên sử dụng điện thoại để định vị, làm việc hoặc liên lạc khi di chuyển.</p>\n<p>Hệ thống khóa thông minh NFC cũng là một điểm cộng lớn, giúp việc mở khóa xe trở nên nhanh chóng và hiện đại hơn. Người dùng chỉ cần một chạm là có thể khởi động xe mà không cần mang theo chìa khóa truyền thống, giảm thiểu rủi ro mất chìa và tăng tính tiện lợi trong sinh hoạt hàng ngày.</p>\n<p>Ngoài ra, cốp xe rộng rãi cũng là một yếu tố được nhiều người đánh giá cao. Với không gian đủ để chứa mũ bảo hiểm, áo mưa hoặc các vật dụng cá nhân, người dùng có thể thoải mái mang theo đồ mà không cần thêm phụ kiện bên ngoài. Điều này giúp xe giữ được vẻ ngoài gọn gàng, đồng thời tăng tính thực dụng trong nhiều tình huống.</p>\n<h2><strong>Dịch vụ hậu mãi: Yếu tố giữ chân người dùng lâu dài</strong></h2>\n<p>Một sản phẩm tốt cần đi kèm với dịch vụ tốt, và đây là điều mà Victoria đã chú trọng. Chính sách bảo hành rõ ràng, cùng hệ thống trung tâm dịch vụ rộng khắp giúp người dùng yên tâm trong quá trình sử dụng.</p>\n<p>Việc bảo hành khung, động cơ và pin theo từng thời hạn cụ thể giúp khách hàng hiểu rõ quyền lợi của mình. Đồng thời, việc có thể bảo trì tại nhiều địa điểm khác nhau giúp tiết kiệm thời gian và chi phí.</p>\n<p>Trong bối cảnh giao thông đô thị ngày càng phức tạp, việc lựa chọn một phương tiện phù hợp là điều vô cùng quan trọng. <strong>XE MÁY ĐIỆN</strong> Victoria Viral Pro không chỉ đáp ứng tốt nhu cầu di chuyển hàng ngày, mà còn mang lại sự an tâm về hiệu năng, độ bền và chi phí sử dụng.</p>\n<p>Với quãng đường lên đến 130km, thiết kế hiện đại và dịch vụ hậu mãi uy tín, đây là một trong những mẫu xe điện đáng cân nhắc nhất hiện nay. Và nếu được lựa chọn đúng nơi mua, người dùng hoàn toàn có thể yên tâm đồng hành cùng chiếc xe trong thời gian dài.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-wuyang-t2-dong-co-bosch-duc', 'Xe Máy Điện WUYANG T2 Động Cơ Bosch Đức', 'honda', '[\"xe-may-dien\"]', 18900000, 18900000, '/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-wuyang-t2-dong-co-bosch-duc-6.webp\"]', '[]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Honda\"},{\"label\":\"Xuất xứ\",\"value\":\"Nhập Khẩu 100%\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1780mm x 720mm x 1120mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"740mm\"},{\"label\":\"Lốp xe\",\"value\":\"Lốp 300-10\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đủ màu\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"Động cơ Bosch Đức 800W\"},{\"label\":\"Vận hành\",\"value\":\"Tự động\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50 - 55 km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"90kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"70 - 80 km/lần sạc\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, phanh kéo sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình 20Ah\"},{\"label\":\"Thời gian xạc điện (tối đa)\",\"value\":\"10- 12 tiếng đồng hồ\"},{\"label\":\"Vành xe\",\"value\":\"Thép đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực Phuộc sau: Lò so trụ đơn, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, sạc, chống trộm, sổ bảo hành\"}]}]', '<p>Đã từ rất lâu rồi thương hiệu Wuyang đã trở nên khá quen thuộc trên thị trường xe máy ở Việt Nam. Hôm nay, Yên Thoa xin giới thiệu đến các tín đồ xe điện của chúng ta một thiết kế mới mang tên Wuyang T2, đây là dòng xe máy chạy bằng nguồn năng lượng điện có tác dụng rất lớn trong công cuộc bảo vệ một môi trường xanh sạch đẹp bằng các phương tiện giao thông không khói. Chúng ta hãy cùng nhau tìm hiểu chi tiết về chiếc xe máy điện Wuyang T2 này nhé!</p>\n<p>Bánh xe máy điện Wuyang T2 có bánh trước được thiết kế với bộ khung vành đúc 10 inch cùng bộ lốp không săm cao cấp, giúp xe có thể duy trì thêm được vài giờ đồng hồ sau khi bị thủng lốp đột ngột giữa đường. Ngoài ra, giữa tâm bánh xe trước còn được trang bị hệ thống phanh cơ để người điều khiển linh hoạt với mọi tình huống đột xuất trên đường. Đặc biệt, bánh trước của xe máy điện Wuyang T2 còn được trang bị giảm xóc dầu cao cấp để luôn mang đến những cảm giác thoải mái nhất cho người ngồi trên xe.</p>', '<p><em>Đã từ rất lâu rồi thương hiệu&nbsp;<strong>Wuyang</strong>&nbsp;đã trở nên khá quen thuộc trên thị trường xe máy ở Việt Nam. Hôm nay,&nbsp;<strong>Yên Thoa</strong>&nbsp;xin giới thiệu đến các tín đồ xe điện của chúng ta một thiết kế mới mang tên&nbsp;<strong>Wuyang T2</strong>, đây là dòng xe máy chạy bằng nguồn năng lượng điện có tác dụng rất lớn trong công cuộc bảo vệ một môi trường xanh sạch đẹp bằng các phương tiện giao thông không khói. Chúng ta hãy cùng nhau tìm hiểu chi tiết về chiếc&nbsp;<strong>xe máy điện Wuyang T2</strong>&nbsp;này nhé!</em></p>\n<h2><strong>BÁNH XE NHỎ NHẮN NHƯNG CHỨA NHIỀU TIỆN ÍCH THÔNG MINH</strong></h2>\n<p>Bánh&nbsp;<strong>xe máy điện Wuyang T2</strong>&nbsp;có bánh trước được thiết kế với bộ khung vành đúc 10 inch cùng bộ lốp không săm cao cấp, giúp xe có thể duy trì thêm được vài giờ đồng hồ sau khi bị thủng lốp đột ngột giữa đường. Ngoài ra, giữa tâm bánh xe trước còn được trang bị hệ thống phanh cơ để người điều khiển linh hoạt với mọi tình huống đột xuất trên đường. Đặc biệt, bánh trước của xe máy điện Wuyang T2 còn được trang bị giảm xóc dầu cao cấp để luôn mang đến những cảm giác thoải mái nhất cho người ngồi trên xe.</p>\n<h2><strong>TAY LÁI ĐƠN GIẢN LINH HOẠT KHI SỬ DỤNG</strong></h2>\n<p>Được thiết kế theo xu hướng hoài cổ từ thương hiệu&nbsp;<strong>Vespa</strong>&nbsp;nổi tiếng với bộ gồm nhiều màu sắc khác nhau như xanh, đỏ, trắng, đen, hồng,…tuy nhiên&nbsp;<strong>xe máy điện Wuyang T2</strong>&nbsp;lại sở hữu phần tay lái rất gọn gàng với các chức năng khác nhau từ các phím điều khiển, đơn giản và rất dễ sử dụng.</p>\n<h2><strong>SÀN ĐỂ CHÂN MANG PHONG CÁCH XE TAY GA HIỆN ĐẠI</strong></h2>\n<p>Sàn để chân của xe máy điện&nbsp;<strong>Wuyang T2</strong>&nbsp;được đồng bộ với toàn bộ khung hợp kim thép sơn tĩnh điện cao cấp của xe nên cho dù có nhìn xe với mọi góc cạnh khác nhau thì thiết kế sàn để chân của xe thật sự rất đẹp mắt, mượt mà như những dòng xe tay ga hiện đại ngày nay. Đặc biệt, khoảng cách từ sàn để chân đến yên xe luôn được tính toán hợp lý nhất để tôn dáng và tạo cảm giác thoải mái nhất cho người điều khiển xe.</p>\n<h2><strong>YÊN XE DÀI, CỐP XE RỘNG TIỆN NGHI KHI SỬ DỤNG</strong></h2>\n<p>Yên xe được thiết kế với diện tích dài, bề mặt được bao phủ bởi lớp nệm cao su cao cấp. Đặc biệt, bên dưới chiếc yên xe khá dài là một khoảng lớn không gian trống bên trong cốp xe giúp người dùng có thể chứa nhiều vật dụng cá nhân khác nhau.</p>\n<h2><strong>ĐÈN PHA SẢN XUẤT VỚI CÔNG NGHỆ HIỆN ĐẠI</strong></h2>\n<p>Sản xuất theo công nghệ&nbsp;<strong>Philip</strong>&nbsp;với chùm sáng rộng, ánh sáng rõ nét cùng phong cách thiết kế độc đáo đã tạo nên một phong cách xe máy điện&nbsp;<strong>Wuyang T2</strong>&nbsp;không thể nhầm lẫn vào đâu được.</p>\n<h2><strong>ĐỘNG CƠ HOÀN HẢO TRÊN MỌI NẺO ĐƯỜNG</strong></h2>\n<p>Ngoài những đặc điểm nổi bật về các tính năng thì xe máy điện Wuyang T2 thật sự hoàn hảo hơn khi sở hữu động cơ Bosch của Đức với công suất 800W, vận tối đa lên đến 50km/h. Bình ắc quy 60V-20Ah giúp xe có được một quãng đường di chuyển từ 70-80km/h cho một lần sạc điện. Đặc biệt, toàn bộ hệ thống động cơ của&nbsp;<strong>xe máy điện Wuyang T2</strong>&nbsp;được sản xuất theo dây chuyền công nghệ hiện đại của Đài Loan nên được đảm bảo chống nước tuyệt đối, hạn chế thấp nhất khả năng xe bị hỏng vặt.</p>', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-xmen-motor-thai', 'Xe Máy Điện Xmen Motor Thái', 'motor-thai', '[\"xe-may-dien\"]', 15200000, 15200000, '/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-4.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-5.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-motor-thai-6.webp\"]', '[]', '[]', '[]', '', '', 1);
INSERT IGNORE INTO products (slug, name, brand, types, price, price_max, img, gallery, colors, variants, specs, short_html, html, active) VALUES ('xe-may-dien-xmen-sport-viet-thai', 'Xe Máy Điện Xmen Sport Việt Thái', 'viet-thai', '[\"xe-may-dien\"]', 14490000, 14490000, '/sites/yenthoa/img/sp/xe-may-dien-xmen-sport-viet-thai-1.webp', '[\"/sites/yenthoa/img/sp/xe-may-dien-xmen-sport-viet-thai-1.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-sport-viet-thai-2.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-sport-viet-thai-3.webp\",\"/sites/yenthoa/img/sp/xe-may-dien-xmen-sport-viet-thai-4.webp\"]', '[\"Đen\",\"đỏ\"]', '[]', '[{\"title\":\"THÔNG TIN CHUNG\",\"items\":[{\"label\":\"Hãng\",\"value\":\"Việt Thái\"},{\"label\":\"Xuất xứ\",\"value\":\"Liên Doanh\"},{\"label\":\"Bảo hành Khung xe\",\"value\":\"3 năm\"},{\"label\":\"Bảo hành Ác quy, Pin\",\"value\":\"1 năm\"},{\"label\":\"Bảo hành Pin\",\"value\":\"2 năm\"},{\"label\":\"Motor\",\"value\":\"2 năm\"}]},{\"title\":\"NGOẠI HÌNH\",\"items\":[{\"label\":\"Chiều dài x Chiều rộng x Chiều cao\",\"value\":\"1640mm x 640mm x 1200mm\"},{\"label\":\"Chiều cao yên xe\",\"value\":\"750mm\"},{\"label\":\"Đường kính bánh xe\",\"value\":\"Lốp: 476mm - Vành: 284mm\"},{\"label\":\"Mầu sắc có bán\",\"value\":\"Đen, đỏ\"}]},{\"title\":\"ĐẶC ĐIỂM\",\"items\":[{\"label\":\"Động cơ\",\"value\":\"800W\"},{\"label\":\"Vận hành\",\"value\":\"Tự động hoàn toàn\"},{\"label\":\"Vận tốc tối da\",\"value\":\"50-55km/h\"},{\"label\":\"Tải trọng\",\"value\":\"130 - 150kg\"},{\"label\":\"Trọng lượng xe\",\"value\":\"85kg\"},{\"label\":\"Quãng đường di chuyển\",\"value\":\"70 - 80 km/lần sạc\"},{\"label\":\"Phanh trước/sau\",\"value\":\"Phanh đĩa trước, phanh kéo sau\"},{\"label\":\"Loại acquy\",\"value\":\"5 bình acquy 20Ah\"},{\"label\":\"Vành xe\",\"value\":\"Hợp kim đúc\"},{\"label\":\"Lốp\",\"value\":\"Lốp không săm\"},{\"label\":\"Giảm Xóc\",\"value\":\"Phuộc trước: Ống lồng, giảm chấn thủy lực. Phuộc sau: Lò so kép, giảm chấn thủy lực\"},{\"label\":\"Phụ kiện đi kèm theo xe\",\"value\":\"Gương, chống trộm, sổ bảo hành\"}]}]', '<p>Các bạn học sinh, sinh viên ơi, bạn đã sắm xe để đi học chưa? Yên Thoa đã cập nhật sản phẩm xe máy điện Xmen Sport Việt Thái 2022 siêu xịn rồi nhé! Đây là một trong những mẫu xe máy điện cực hot trong năm 2022, là phiên bản hoàn hảo cho những cái tôi cá tính. Mời bạn tham khảo kỹ hơn về sản phẩm trong bài viết này nhé.</p>\n<p>Phiên bản Xmen Sport Việt Thái gia nhập vào “biệt đội” xe điện Xmen đáng sở hữu trong năm 2022. Bật mí rằng phiên bản này không chỉ đẹp về ngoại hình mà còn có độ bền ấn tượng, phù hợp với dáng vóc nhỏ nhắn của người Việt.</p>', '<p><em>Các bạn học sinh, sinh viên ơi, bạn đã sắm xe để đi học chưa? Yên Thoa đã cập nhật sản phẩm xe máy điện Xmen Sport Việt Thái 2022 siêu xịn rồi nhé! Đây là một trong những mẫu&nbsp;xe máy điện&nbsp;cực hot trong năm 2022, là phiên bản hoàn hảo cho những cái tôi cá tính. Mời bạn tham khảo kỹ hơn về sản phẩm trong bài viết này nhé.</em></p>\n<h2><strong>1. DIỆN MẠO HẦM HỐ CỦA XE MÁY ĐIỆN XMEN SPORT VIỆT THÁI 2022</strong></h2>\n<p>Phiên bản Xmen Sport Việt Thái gia nhập vào “biệt đội” xe điện Xmen đáng sở hữu trong năm 2022. Bật mí rằng phiên bản này không chỉ đẹp về ngoại hình mà còn có độ bền ấn tượng, phù hợp với dáng vóc nhỏ nhắn của người Việt.</p>\n<h3><strong>Thiết kế cá tính góc cạnh</strong></h3>\n<p>Xe máy điện Xmen Sport Việt Thái 2022 nổi bật với thiết kế cực kỳ hầm hố với những chi tiết vuốt nhọn cực sắc sảo. Sản phẩm lần này đã được nâng cấp và cải tiến để sở hữu một diện mạo ấn tượng hơn.</p>\n<p>Chiếc xe ra mắt thị trường Việt Nam với hai phiên bản màu đen và đỏ. Đây là hai sắc độ kinh điển, luôn tạo nên hiệu ứng thị giác ấn tượng trong mọi thời kỳ. Sự kết hợp giữa những mảng màu đối lập cùng dàn tem nước tinh xảo đã mang đến vẻ ngoài hút mắt.</p>\n<p>Sự hòa hợp trong tổng thể thiết kế giúp chiếc xe này trở thành một sản phẩm đẹp không góc chết. Nhìn từ góc độ nào, ta cũng thấy rằng nó vừa mạnh mẽ nhưng vẫn thanh thoát với bố cục chặt chẽ. Từng chi tiết được lắp ráp khăng khít trên hệ thống khung thép đúc cứng chắc. Vậy nên tuy rằng chiếc xe nặng 80kg nhưng lại không hề tạo cản trở cho người sử dụng. Ta vẫn có trải nghiệm lái xe nhẹ nhàng, dễ dàng đánh lái, dắt xe.&nbsp;</p>\n<h3><strong>Kích thước vừa vặn với người Việt</strong></h3>\n<p>Phiên bản được đánh giá là đặc biệt phù hợp với học sinh, sinh viên. Thông số cụ thể như sau: chiều cao yên 750mm, chiều dài x chiều rộng x chiều cao là 1640mm x 640mm x 1200mm. Phiên bản nhỏ gọn nhưng có phần sàn để chân khá rộng, những đường cong vát trên yên xe thiết kế vô cùng hợp lý. Chính vì vậy, sản phẩm hoàn toàn phù hợp cho các bạn từ 1m5 trở lên.</p>\n<h3><strong>Cốp rộng</strong></h3>\n<p>Đã có rất nhiều khách hàng ngạc nhiên khi biết rằng xe máy điện Xmen Sport Việt Thái 2022 ẩn chứa một chiếc cốp khá rộng. Phiên bản này tuy nhỏ gọn nhưng cốp có thể chứa được mũ bảo hiểm nửa đầu cùng nhiều vật dụng khác. Cốp xe đóng mở nhẹ nhàng, chắc chắn và chống nước, chống bụi hiệu quả.&nbsp;</p>\n<p>Để ý một chút, bạn sẽ thấy tại vị trí này có một aptomat tổng. Đây là bộ phận có nhiệm vụ đảm bảo an toàn cho toàn thể hệ thống điện của sản phẩm. Khi xuất hiện dấu hiệu nguy hiểm, nó sẽ tự động ngắt nguồn.&nbsp;</p>\n<h2><strong>2. ĐÈN LED VỚI NHIỀU ƯU ĐIỂM VƯỢT TRỘI</strong></h2>\n<p>Xe máy điện Xmen Sport Việt Thái 2022 sở hữu hệ thống đèn LED tiên tiến. Công nghệ LED so với dòng bóng đèn sợi đốt truyền thống vượt trội hơn rất nhiều:</p>\n<ul>\n<li>\n<p>Tiết kiệm đến 90% lượng điện năng.</p>\n</li>\n<li>\n<p>Chất lượng ánh sáng vượt trội: sắc độ trong trẻo, không bị ố màu, không xuất hiện tình trạng nhấp nháy khiến mắt bị khó chịu.</p>\n</li>\n<li>\n<p>Tuổi thọ cao gấp 5 lần.</p>\n</li>\n<li>\n<p>Tỏa nhiệt thấp hơn.</p>\n</li>\n</ul>\n<p>Hệ thống đèn không chỉ vượt trội về chức năng mà còn được thiết kế vô cùng thẩm mỹ. Phía trước yếm xe hình chữ X thời thượng là một chiếc đèn pha siêu to dạng hình trái tim. Nó gợi cho chúng ta liên tưởng đến hình tượng Iron Man nổi tiếng trong loạt phim siêu anh hùng của Marvel. Hai bên là đèn xi nhan đối xứng dạng mũi tên với chuôi đèn chống gãy vỡ.</p>\n<p>Thiết kế đuôi đèn được bố trí hài hòa với kiểu dáng vuốt nhọn thanh thoát của sản phẩm. Nó có sự đồng bộ với dàn đèn trước cũng như tổng thể chiếc xe - trông cá tính chẳng khác gì mẫu Exciter. Đèn tuy nhỏ nhưng có khả năng phát tín hiệu hiệu quả, giúp người dùng di chuyển an toàn.</p>\n<h2><strong>3. ĐỘNG CƠ ĐIỆN TỰ ĐỘNG 800W</strong></h2>\n<p>Xe máy điện Xmen Sport Việt Thái 2022 được cải tiến về hệ thống động cơ để mang lại trải nghiệm tuyệt vời cho người sử dụng. Sẽ thật tuyệt vời khi bạn có thể vi vu lướt gió trên những cung đường cùng chiếc xe này.</p>\n<h3><strong>Động cơ mạnh mẽ</strong></h3>\n<p>Phiên bản xe điện Xmen Sport Việt Thái sở hữu động cơ 800W định danh. Khả năng làm việc của sản phẩm vô cùng ấn tượng với tốc độ max đạt tới 50km/h. Khi tăng tốc, ta chỉ cần vặn nhẹ tay ga là nó vút đi như bay, thời gian bứt phá chỉ trong nháy mắt. Có thể thấy, đây là một sản phẩm đáp ứng tốt nhu cầu đi lại của các bạn trẻ.</p>\n<p>Nâng đỡ cho tổng thể chiếc xe là hệ thống khung thép đúc cứng chắc. Hệ thống này cùng động cơ đã góp phần tạo nên khả năng làm việc khỏe và bền của sản phẩm. Chiếc xe nhỏ nhắn này có tải trọng lên đến 150kg. Điều đó đồng nghĩa nó sẵn sàng chở bạn cùng người bạn đồng hành vi vu trên mọi dặm đường.</p>\n<h3><strong>Dễ vận hành</strong></h3>\n<p>Xe Xmen Sport Việt Thái là một trong những sản phẩm dễ vận hành, phù hợp cho mọi đối tượng sử dụng. Động cơ điện làm việc tự động không cấp số, điều chỉnh bằng cách vặn tay ga và các phím chức năng nơi tay lái. Chỉ cần làm quen vài lần thì chắc chắn bạn sẽ dễ dàng làm chủ và tự tin di chuyển cùng chiếc xe này.</p>\n<h3><strong>Kháng nước chuẩn IPX7</strong></h3>\n<p>Với chiếc Xmen Sport Việt Thái 2022, bạn khỏi cần lo lắng về điều kiện thời tiết mưa gió, đường ngập. Hãng đã thiết kế động cơ và thân xe kín nước chuẩn IPX7 để sẵn sàng làm việc trong mọi điều kiện thời tiết. Các chi tiết như đồng hồ tay ga các cụm công tắc cũng đều được thiết kế rất tỉ mỉ đảm bảo khả năng chống nước tốt đi mưa thoải mái không hề gặp tình trạng chập hay lỗi phát sinh.</p>\n<p>Ngoài ra, bạn cũng có thể dễ dàng quan sát các thông số của xe thông qua mặt đồng hồ điện tử nhỏ gọn trên xe. Đồng hồ cho phép hiển thị vận tốc, mức pin còn trên xe, xi nhan và pha/cos...Bạn có thể dễ dàng làm chủ tình hình xe khi di chuyển.</p>\n<h2><strong>4. ẮC QUY CẢI TIẾN</strong></h2>\n<p>Một chiếc xe mạnh mẽ sẽ chẳng thể làm nên kỳ tích nếu thiếu đi hệ thống tích trữ năng lượng hiệu quả. Hiện nay, phiên bản Xmen Sport Việt Thái đã được tích hợp công nghệ ắc quy cải tiến với 5 bình 20Ah. Khả năng di chuyển 70km/ 1 lần sạc chắc chắn sẽ giúp bạn hài lòng.</p>\n<p>Thời gian sạc trung bình của xe là khoảng 10-12 tiếng. Sản phẩm có đi kèm bộ sạc chuẩn chính hãng với độ an toàn cao. Bộ sạc này cũng có chức năng tự động ngắt điện khi ắc quy đã đủ năng lượng. Đây là vấn đề quan trọng giúp hạn chế tối đa nguy cơ cháy nổ, chập điện trong quá trình sử dụng.</p>\n<h2><strong>5. HỆ THỐNG PHANH VÀ GIẢM XÓC HIỆN ĐẠI</strong></h2>\n<p>Xe máy điện Xmen Sport Việt Thái 2022 mang lại trải nghiệm mượt mà, an toàn trên mọi hình trình nhờ vào hệ thống phanh và giảm xóc tiên tiến. Sẽ thật thiếu sót nếu không giới thiệu tính năng vượt trội này đến với quý khách.</p>\n<h3><strong>Phanh đĩa kết hợp với phanh cơ</strong></h3>\n<p>Xmen Sport Việt Thái là chiếc xe được trang bị phanh đĩa trước kết hợp phanh cơ sau. Hiện nay hầu hết các phương tiện cao cấp đều ưu tiên sử dụng phanh đĩa để tăng tính an toàn trong quá trình làm chủ tốc độ.</p>\n<p>Ở sản phẩm, hãng đã kết hợp phanh đĩa cùng phanh cơ để tạo nên hiệu quả tương tự. Bởi động cơ vận hành 800W ở mức nhẹ nhàng, sự kết hợp này là vừa đủ. Người dùng vẫn có trải nghiệm an tâm và an toàn khi di chuyển trong mọi điều kiện. Nếu phải phanh gấp, chiếc xe vẫn giảm tốc vô cùng mượt mà, hạn chế tối đa tình trạng trượt bánh rồi đổ xe.&nbsp;</p>\n<h3><strong>Giảm xóc giảm chấn thủy lực</strong></h3>\n<p>Khi di chuyển trên chiếc xe này, người dùng luôn cảm nhận được sự thoải mái, êm ái. Đó là bởi phiên bản Xmen Sport Việt Thái được trang bị công nghệ giảm chấn thủy lực tiên tiến. Phía trước đầu xe là phuộc nhún, phía sau là lò xo trụ giảm xóc siêu hiệu quả.&nbsp;</p>\n<p>Cả hai bộ phận kết hợp một cách nhuần nhuyễn để hạn chế tối đa lực tác động từ mặt đường lên tay lái và người ngồi trên xe. Thêm vào đó, nó cũng làm tốt nhiệm vụ cân bằng trọng lượng tác động từ phía yên xe.&nbsp;</p>\n<h2><strong>6. LỐP KHÔNG SĂM, VÀNH ĐÚC CAO CẤP</strong></h2>\n<p>Xe máy điện Xmen Sport Việt Thái 2022 sở hữu thiết kế bánh xe chất lượng như những dòng xe tay ga cao cấp. Đó chính là lốp không săm và vành đúc từ hợp kim cứng cáp.</p>\n<h3><strong>Bánh xe đường kính lớn</strong></h3>\n<p>Kích thước bánh xe cụ thể như sau: Lốp: 476mm - Vành: 284mm. Có thể thấy, đây là một sự cải tiến lớn để giúp nâng cao khoảng không gian phía gầm và giúp xe di chuyển bon hơn. Ta sẽ không gặp phải tình trạng cạ gầm vào vỉa hè nữa.</p>\n<h3><strong>Lốp không săm</strong></h3>\n<p>Lốp không săm có ưu điểm vượt trội là độ bền cao, độ an toàn cao hơn so với lốp có săm truyền thống. Khi di chuyển ở tốc độ cao, lốp khó bị mài mòn và khó bị nổ bởi khả năng tản nhiệt hiệu quả. Thêm nữa là dòng lốp này có khả năng giữ áp suất khí tốt. Nếu lỡ đâm vào vật nhọn thì bạn vẫn có thể lái xe đi thêm một đoạn đường nữa trước khi khí thoát ra hoàn toàn.</p>\n<h3><strong>Vành đúc 5 chấu thời trang</strong></h3>\n<p>Nhà sản xuất quyết định sử dụng vành đúc trên chiếc xe này. Đây quả là một quyết định đúng đắn khi giúp cho chiếc xe trông mạnh mẽ đồng thời làm việc vững chãi hơn. Vành 5 chấu cắt hoa văn lạ mắt. Nó có tác dụng chịu lực tác động tốt, tăng khả năng tăng tốc của chiếc xe.</p>\n<p>Xe máy điện Xmen Sport Việt Thái 2022&nbsp;đã sẵn sàng lăn bánh, đồng hành cùng bạn trên hành trình sắp tới. Để rinh ngay về nhà, hãy tới Yên Thoa nhé. Chúng tôi tin chắc những bạn trẻ yêu thích sự cá tính, hầm hố sẽ thích mê sản phẩm này.</p>\n<h3><strong>Bên cạnh đó xe còn nhiều tiện ích nổi bật như:</strong></h3>\n<ul>\n<li>Yên xe liền khối thiết kế dài đủ để ngồi 2 người trên xe , đệm xe êm ái không gây cảm giác khó chịu khi chạy đường dài. Tải trọng của xe Xmen Sport Việt Thái 2022 lên tới 150kg nên việc chạy 2 người là khá thoải mái.</li>\n</ul>\n<ul>\n<li>Ở phía trước bạn để ý hãng có thiết kế 1 móc treo đồ cực kỳ tiện lợi bạn có thể móc nón bảo hiểm hay các túi sách nhẹ trên đó. Sàn để chân thiết kế rộng rãi mặt sàn có các gờ chống trơn trượt rất hữu ích,</li>\n<li>Bộ khoá điện tử thông minh giúp bạn mở khoá xe tự động không cần cắm chìa, chống trọm xe nâng cao tính an toàn. Bộ sạc có tính năng tự ngắt khi đầy bảo vệ acquy tốt hơn trong quá trình sử dụng.</li>\n</ul>\n&nbsp;\n<strong>Video sản phẩm:</strong>\n<br>\n<br>\n<br>\n<br>\nXe Máy Điện Xmen Sport Việt Thái Phong Cách Thể Thao Giá Siêu Rẻ 2022<br>', 1);
